CREATE OR REPLACE FUNCTION "public"."accept_invitation_atomic"("p_token" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "email" "text", "role" "text", "expires_at" timestamp with time zone, "accepted_at" timestamp with time zone, "success" boolean, "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invitation RECORD;
BEGIN
  UPDATE organization_invitations
  SET accepted_at = NOW()
  WHERE token = p_token
    AND accepted_at IS NULL
    AND expires_at > NOW()
  RETURNING 
    organization_invitations.id,
    organization_invitations.organization_id,
    organization_invitations.email,
    organization_invitations.role,
    organization_invitations.expires_at,
    organization_invitations.accepted_at
  INTO v_invitation;

  IF NOT FOUND THEN
    SELECT 
      oi.id,
      oi.organization_id,
      oi.email,
      oi.role,
      oi.expires_at,
      oi.accepted_at
    INTO v_invitation
    FROM organization_invitations oi
    WHERE oi.token = p_token;

    IF NOT FOUND THEN
      RETURN QUERY SELECT 
        NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, 
        NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ,
        false, '招待が見つかりません'::TEXT;
      RETURN;
    ELSIF v_invitation.accepted_at IS NOT NULL THEN
      RETURN QUERY SELECT 
        v_invitation.id, v_invitation.organization_id, v_invitation.email,
        v_invitation.role, v_invitation.expires_at, v_invitation.accepted_at,
        false, 'この招待は既に使用されています'::TEXT;
      RETURN;
    ELSIF v_invitation.expires_at <= NOW() THEN
      RETURN QUERY SELECT 
        v_invitation.id, v_invitation.organization_id, v_invitation.email,
        v_invitation.role, v_invitation.expires_at, v_invitation.accepted_at,
        false, '招待の有効期限が切れています'::TEXT;
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT 
    v_invitation.id,
    v_invitation.organization_id,
    v_invitation.email,
    v_invitation.role,
    v_invitation.expires_at,
    v_invitation.accepted_at,
    true,
    NULL::TEXT;
END;
$$;


ALTER FUNCTION "public"."accept_invitation_atomic"("p_token" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_clear_reservations_scenario_id"("p_scenario_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_org_id UUID;
  v_is_admin BOOLEAN;
  v_updated INTEGER;
BEGIN
  v_caller_org_id := get_user_organization_id();
  v_is_admin := is_org_admin();

  IF NOT v_is_admin AND v_caller_org_id IS NULL THEN
    RAISE EXCEPTION 'FORBIDDEN_ORG' USING ERRCODE = 'P0010';
  END IF;

  UPDATE reservations
  SET scenario_id = NULL,
      updated_at = NOW()
  WHERE scenario_id = p_scenario_id
    AND (organization_id = v_caller_org_id OR v_is_admin);

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."admin_clear_reservations_scenario_id"("p_scenario_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_reservations_by_ids"("p_reservation_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role TEXT;
  v_caller_org_id UUID;
  v_deleted_count INTEGER;
  v_reservation_numbers TEXT[];
  v_cross_org_count INTEGER;
BEGIN
  -- 呼び出し元ユーザーの確認
  v_caller_id := auth.uid();
  
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '認証が必要です');
  END IF;
  
  -- 管理者権限チェック
  SELECT role::TEXT INTO v_caller_role
  FROM users
  WHERE id = v_caller_id;
  
  IF v_caller_role NOT IN ('admin', 'license_admin') THEN
    RETURN jsonb_build_object('success', false, 'error', '管理者権限が必要です');
  END IF;

  -- ★ P0-D 修正: 組織境界チェック
  v_caller_org_id := get_user_organization_id();

  SELECT COUNT(*) INTO v_cross_org_count
  FROM reservations
  WHERE id = ANY(p_reservation_ids)
    AND organization_id IS DISTINCT FROM v_caller_org_id;

  IF v_cross_org_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', '他の組織の予約は削除できません');
  END IF;
  
  -- 削除対象の予約番号を取得（ログ用）
  SELECT ARRAY_AGG(reservation_number) INTO v_reservation_numbers
  FROM reservations
  WHERE id = ANY(p_reservation_ids)
    AND organization_id = v_caller_org_id;
  
  -- 監査ログを記録
  INSERT INTO audit_logs (
    user_id,
    action,
    resource_type,
    resource_id,
    old_values,
    new_values,
    organization_id
  )
  SELECT 
    v_caller_id,
    'reservations.bulk_delete',
    'reservations',
    id,
    row_to_json(r.*)::JSONB,
    NULL,
    v_caller_org_id
  FROM reservations r
  WHERE r.id = ANY(p_reservation_ids)
    AND r.organization_id = v_caller_org_id;
  
  -- 削除を実行（自組織のみ）
  DELETE FROM reservations
  WHERE id = ANY(p_reservation_ids)
    AND organization_id = v_caller_org_id;
  
  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'deleted_reservation_numbers', v_reservation_numbers
  );
END;
$$;


ALTER FUNCTION "public"."admin_delete_reservations_by_ids"("p_reservation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_reservations_by_schedule_event_ids"("p_schedule_event_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_event_org_id UUID;
  v_caller_org_id UUID;
  v_is_admin BOOLEAN;
  v_is_staff_or_admin BOOLEAN;
  v_distinct_orgs INTEGER;
  v_deleted INTEGER;
  v_reservation_ids UUID[];
BEGIN
  -- 空の配列チェック
  IF p_schedule_event_ids IS NULL OR array_length(p_schedule_event_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;

  -- 対象イベントの組織を確認
  SELECT COUNT(DISTINCT organization_id)
  INTO v_distinct_orgs
  FROM schedule_events
  WHERE id = ANY(p_schedule_event_ids);

  IF v_distinct_orgs IS NULL OR v_distinct_orgs = 0 THEN
    RETURN 0;
  END IF;

  -- 複数組織のイベントを同時に削除しようとしている場合はエラー
  IF v_distinct_orgs > 1 THEN
    RAISE EXCEPTION 'MULTI_ORG_NOT_ALLOWED' USING ERRCODE = 'P0102';
  END IF;

  -- 対象イベントの組織IDを取得
  SELECT organization_id
  INTO v_event_org_id
  FROM schedule_events
  WHERE id = ANY(p_schedule_event_ids)
  LIMIT 1;

  -- 呼び出し元の組織と権限を確認
  v_caller_org_id := get_user_organization_id();
  v_is_admin := is_org_admin();
  v_is_staff_or_admin := is_staff_or_admin();

  -- スタッフまたは管理者でない場合はエラー
  IF NOT v_is_staff_or_admin THEN
    RAISE EXCEPTION 'FORBIDDEN_NOT_STAFF' USING ERRCODE = 'P0010';
  END IF;

  -- 管理者でない場合は組織の一致を確認
  IF NOT v_is_admin THEN
    IF v_caller_org_id IS NULL OR v_caller_org_id IS DISTINCT FROM v_event_org_id THEN
      RAISE EXCEPTION 'FORBIDDEN_ORG' USING ERRCODE = 'P0010';
    END IF;
  END IF;

  -- 削除対象の予約IDを取得（row_security = off なので RLS なしで取得）
  SELECT ARRAY_AGG(id)
  INTO v_reservation_ids
  FROM reservations
  WHERE schedule_event_id = ANY(p_schedule_event_ids);

  -- 予約がない場合は0を返す
  IF v_reservation_ids IS NULL OR array_length(v_reservation_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;

  -- ============================================================
  -- 依存テーブルの削除（row_security = off で RLS をバイパス）
  -- ============================================================

  -- 1. coupon_usages を先に削除（循環参照対策）
  DELETE FROM coupon_usages
  WHERE reservation_id = ANY(v_reservation_ids);

  -- 2. gm_availability_responses を削除
  DELETE FROM gm_availability_responses
  WHERE reservation_id = ANY(v_reservation_ids);

  -- 3. booking_email_queue を削除（存在する場合）
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'booking_email_queue') THEN
    DELETE FROM booking_email_queue
    WHERE reservation_id = ANY(v_reservation_ids);
  END IF;

  -- 4. reservations を削除
  DELETE FROM reservations
  WHERE id = ANY(v_reservation_ids);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."admin_delete_reservations_by_schedule_event_ids"("p_schedule_event_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_reservations_by_source"("p_reservation_source" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_org_id UUID;
  v_is_admin BOOLEAN;
  v_deleted INTEGER;
BEGIN
  v_caller_org_id := get_user_organization_id();
  v_is_admin := is_org_admin();

  IF NOT v_is_admin AND v_caller_org_id IS NULL THEN
    RAISE EXCEPTION 'FORBIDDEN_ORG' USING ERRCODE = 'P0010';
  END IF;

  DELETE FROM reservations
  WHERE reservation_source = p_reservation_source
    AND (organization_id = v_caller_org_id OR v_is_admin);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


