CREATE OR REPLACE FUNCTION "public"."admin_link_staff_account"("p_actor_id" "uuid", "p_staff_id" "uuid", "p_user_id" "uuid", "p_email" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor public.users%ROWTYPE; v_staff public.staff%ROWTYPE; v_user public.users%ROWTYPE;
BEGIN
 SELECT * INTO v_actor FROM public.users WHERE id=p_actor_id;
 IF NOT FOUND OR v_actor.role NOT IN ('admin','license_admin') OR v_actor.organization_id IS NULL
   OR (v_actor.role<>'license_admin' AND EXISTS(SELECT 1 FROM public.staff WHERE user_id=p_actor_id AND status IN ('inactive','resigned'))) THEN
   RAISE EXCEPTION '管理者権限が必要です' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM public.organizations WHERE id=v_actor.organization_id FOR UPDATE;
 SELECT * INTO v_staff FROM public.staff WHERE id=p_staff_id FOR UPDATE;
 IF NOT FOUND OR v_staff.organization_id IS DISTINCT FROM v_actor.organization_id THEN
   RAISE EXCEPTION '対象スタッフが見つからないか、組織が異なります' USING ERRCODE='42501';
 END IF;
 IF p_user_id IS NOT NULL THEN
   SELECT * INTO v_user FROM public.users WHERE id=p_user_id FOR UPDATE;
   IF NOT FOUND OR (v_user.organization_id IS NOT NULL AND v_user.organization_id IS DISTINCT FROM v_staff.organization_id) THEN
     RAISE EXCEPTION '連携先が見つからないか、組織が異なります' USING ERRCODE='42501';
   END IF;
   IF EXISTS(SELECT 1 FROM public.staff WHERE user_id=p_user_id AND organization_id<>v_staff.organization_id) THEN
     RAISE EXCEPTION '他組織のスタッフとの連携を移すことはできません' USING ERRCODE='42501';
   END IF;
   UPDATE public.staff SET user_id=NULL WHERE user_id=p_user_id AND id<>p_staff_id;
 END IF;
 UPDATE public.staff SET user_id=p_user_id,email=CASE WHEN p_email IS NOT NULL THEN p_email ELSE email END
 WHERE id=p_staff_id;
 RETURN p_staff_id;
END;
$$;


ALTER FUNCTION "public"."admin_link_staff_account"("p_actor_id" "uuid", "p_staff_id" "uuid", "p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_recalculate_reservation_prices"("p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role TEXT;
  v_caller_org_id UUID;
  v_old_values JSONB;
  v_reservation RECORD;
  v_unit_price INTEGER;
  v_total_price INTEGER;
  v_final_price INTEGER;
BEGIN
  v_caller_id := auth.uid();
  
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '認証が必要です');
  END IF;
  
  SELECT role::TEXT INTO v_caller_role
  FROM users
  WHERE id = v_caller_id;
  
  IF v_caller_role NOT IN ('admin', 'staff', 'license_admin') THEN
    RETURN jsonb_build_object('success', false, 'error', '権限がありません');
  END IF;

  -- ★ P0-D 修正: 組織境界チェック
  v_caller_org_id := get_user_organization_id();
  
  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id;
  
  IF v_reservation IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '予約が見つかりません');
  END IF;

  IF v_reservation.organization_id IS DISTINCT FROM v_caller_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', '他の組織の予約は操作できません');
  END IF;
  
  v_old_values := jsonb_build_object(
    'unit_price', v_reservation.unit_price,
    'total_price', v_reservation.total_price,
    'base_price', v_reservation.base_price,
    'final_price', v_reservation.final_price,
    'participant_count', v_reservation.participant_count
  );
  
  v_unit_price := COALESCE(
    v_reservation.unit_price,
    CASE 
      WHEN v_reservation.participant_count > 0 
      THEN ROUND(v_reservation.base_price::NUMERIC / v_reservation.participant_count)
      ELSE 0
    END
  );
  
  v_total_price := v_unit_price * v_reservation.participant_count;
  v_final_price := v_total_price - COALESCE(v_reservation.discount_amount, 0);
  
  UPDATE reservations
  SET 
    unit_price = v_unit_price,
    total_price = v_total_price,
    base_price = v_total_price,
    final_price = v_final_price,
    updated_at = NOW()
  WHERE id = p_reservation_id
    AND organization_id = v_caller_org_id;
  
  INSERT INTO audit_logs (
    user_id,
    action,
    resource_type,
    resource_id,
    old_values,
    new_values,
    organization_id
  ) VALUES (
    v_caller_id,
    'reservations.recalculate_prices',
    'reservations',
    p_reservation_id,
    v_old_values,
    jsonb_build_object(
      'unit_price', v_unit_price,
      'total_price', v_total_price,
      'base_price', v_total_price,
      'final_price', v_final_price
    ),
    v_caller_org_id
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'old', v_old_values,
    'new', jsonb_build_object(
      'unit_price', v_unit_price,
      'total_price', v_total_price,
      'final_price', v_final_price
    )
  );
END;
$$;


ALTER FUNCTION "public"."admin_recalculate_reservation_prices"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_recalculate_reservation_prices"("p_reservation_id" "uuid", "p_participant_names" "text"[] DEFAULT NULL::"text"[]) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reservation_org_id UUID;
  v_caller_org_id UUID;
  v_is_admin BOOLEAN;

  v_participant_count INTEGER;
  v_unit_price INTEGER;
  v_options_price INTEGER;
  v_discount_amount INTEGER;

  v_base_price INTEGER;
  v_total_price INTEGER;
  v_final_price INTEGER;
BEGIN
  -- ロックして値を取得
  SELECT organization_id,
         participant_count,
         unit_price,
         options_price,
         discount_amount,
         base_price
  INTO v_reservation_org_id,
       v_participant_count,
       v_unit_price,
       v_options_price,
       v_discount_amount,
       v_base_price
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0100';
  END IF;

  v_caller_org_id := get_user_organization_id();
  v_is_admin := is_org_admin();

  IF NOT v_is_admin THEN
    IF v_caller_org_id IS NULL OR v_caller_org_id IS DISTINCT FROM v_reservation_org_id THEN
      RAISE EXCEPTION 'FORBIDDEN_ORG' USING ERRCODE = 'P0010';
    END IF;
  END IF;

  -- unit_price が無い場合は base_price / participant_count から推定
  IF v_unit_price IS NULL THEN
    IF v_participant_count > 0 AND v_base_price IS NOT NULL THEN
      v_unit_price := CEIL(v_base_price::numeric / v_participant_count::numeric)::integer;
    ELSE
      v_unit_price := 0;
    END IF;
  END IF;

  v_options_price := COALESCE(v_options_price, 0);
  v_discount_amount := COALESCE(v_discount_amount, 0);

  v_base_price := v_unit_price * COALESCE(v_participant_count, 0);
  v_total_price := v_base_price + v_options_price;
  v_final_price := v_total_price - v_discount_amount;

  UPDATE reservations
  SET
    participant_names = COALESCE(p_participant_names, participant_names),
    unit_price = v_unit_price,
    base_price = v_base_price,
    total_price = v_total_price,
    final_price = v_final_price,
    updated_at = NOW()
  WHERE id = p_reservation_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."admin_recalculate_reservation_prices"("p_reservation_id" "uuid", "p_participant_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_reservation_fields"("p_reservation_id" "uuid", "p_updates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role TEXT;
  v_caller_org_id UUID;
  v_reservation_org_id UUID;
  v_current_status TEXT;
  v_new_status TEXT;
  v_result JSONB;
BEGIN
  -- 呼び出し元ユーザーの確認
  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '認証が必要です');
  END IF;

  -- 管理者権限チェック
  SELECT role::TEXT, organization_id
  INTO v_caller_role, v_caller_org_id
  FROM users
  WHERE id = v_caller_id;

  IF v_caller_role NOT IN ('admin', 'staff', 'license_admin') THEN
    RETURN jsonb_build_object('success', false, 'error', '権限がありません');
  END IF;

  -- 組織境界チェック
  SELECT organization_id INTO v_reservation_org_id
  FROM reservations
  WHERE id = p_reservation_id;

  IF v_reservation_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '予約が見つかりません');
  END IF;

  -- service_role 以外は自組織の予約のみ操作可能
  IF v_caller_org_id IS DISTINCT FROM v_reservation_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', '他組織の予約は操作できません');
  END IF;

  -- 予約の現在のステータス取得（FOR UPDATE でロック）
  SELECT status INTO v_current_status
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF v_current_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', '予約が見つかりません');
  END IF;

  -- ステータス変更がある場合は遷移を検証
  IF p_updates ? 'status' THEN
    v_new_status := p_updates->>'status';

    IF v_new_status IS NOT NULL AND v_new_status != '' THEN
      IF NOT validate_reservation_status_transition(v_current_status, v_new_status) THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', format('無効なステータス遷移です: %s → %s', v_current_status, v_new_status)
        );
      END IF;
    END IF;
  END IF;

  -- 更新を実行（許可フィールドのみ）
  UPDATE reservations
  SET
    store_id = CASE
      WHEN p_updates ? 'store_id' THEN (p_updates->>'store_id')::UUID
      ELSE store_id
    END,
    display_customer_name = CASE
      WHEN p_updates ? 'display_customer_name' THEN p_updates->>'display_customer_name'
      ELSE display_customer_name
    END,
    status = CASE
      WHEN p_updates ? 'status' THEN NULLIF(p_updates->>'status', '')
      ELSE status
    END,
    payment_status = CASE
      WHEN p_updates ? 'payment_status' THEN p_updates->>'payment_status'
      ELSE payment_status
    END,
    gm_staff = CASE
      WHEN p_updates ? 'gm_staff' THEN p_updates->>'gm_staff'
      ELSE gm_staff
    END,
    assigned_staff = CASE
      WHEN p_updates ? 'assigned_staff' THEN ARRAY(SELECT jsonb_array_elements_text(p_updates->'assigned_staff'))
      ELSE assigned_staff
    END,
    participant_names = CASE
      WHEN p_updates ? 'participant_names' THEN ARRAY(SELECT jsonb_array_elements_text(p_updates->'participant_names'))
      ELSE participant_names
    END,
    scenario_id = CASE
      WHEN p_updates ? 'scenario_id' THEN (p_updates->>'scenario_id')::UUID
      ELSE scenario_id
    END,
    -- ★追加: 遅刻フラグ
    arrived_late = CASE
      WHEN p_updates ? 'arrived_late' THEN (p_updates->>'arrived_late')::boolean
      ELSE arrived_late
    END,
    updated_at = NOW()
  WHERE id = p_reservation_id;

  -- 更新後のデータを取得
  SELECT jsonb_build_object(
    'success', true,
    'reservation', row_to_json(r.*)
  ) INTO v_result
  FROM reservations r
  WHERE r.id = p_reservation_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."admin_update_reservation_fields"("p_reservation_id" "uuid", "p_updates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alert_recruitment_x_result"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE message text; kind text;
BEGIN
 IF NEW.status IN ('failed','uncertain') THEN
  NEW.first_failed_at:=COALESCE(OLD.first_failed_at,now());
  IF OLD.first_failed_at IS NULL THEN kind:='recruitment_x_failed';message:='【追加募集X告知：送信失敗】'; END IF;
  IF NEW.status='uncertain' OR NEW.attempts>=10 THEN kind:='recruitment_x_attention';message:='【追加募集X告知：運営対応依頼】投稿の有無をXで確認してください。重複防止のため自動再投稿を停止しています。'; END IF;
 ELSIF NEW.status='sent' AND OLD.first_failed_at IS NOT NULL THEN kind:='recruitment_x_recovered';message:='【追加募集X告知：投稿できました】';
 END IF;
 IF kind IS NOT NULL THEN PERFORM queue_recruitment_operation_alert(NEW.organization_id,NEW.schedule_event_id,kind,NEW.id::text,message||E'\n'||COALESCE(NEW.snapshot->>'scenario','')||E'\n通知参照: '||NEW.id::text); END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION "public"."alert_recruitment_x_result"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_coupon_to_group_member"("p_member_id" "uuid", "p_coupon_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_member RECORD;
  v_coupon RECORD;
  v_group RECORD;
  v_discount INTEGER;
  v_final_amount INTEGER;
BEGIN
  -- メンバー情報を取得
  SELECT * INTO v_member FROM public.private_group_members WHERE id = p_member_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'メンバーが見つかりません');
  END IF;

  -- グループ情報を取得
  SELECT * INTO v_group FROM public.private_groups WHERE id = v_member.group_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'グループが見つかりません');
  END IF;

  -- クーポン情報を取得・検証
  SELECT * INTO v_coupon FROM public.coupons WHERE id = p_coupon_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'クーポンが見つかりません');
  END IF;

  -- クーポンの有効性チェック
  IF v_coupon.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'このクーポンは使用できません');
  END IF;

  IF v_coupon.expires_at IS NOT NULL AND v_coupon.expires_at < NOW() THEN
    RETURN jsonb_build_object('success', false, 'error', 'クーポンの有効期限が切れています');
  END IF;

  -- 所有者チェック（ログインユーザーのクーポンか）
  IF v_coupon.customer_id IS NOT NULL AND v_member.user_id IS NOT NULL THEN
    DECLARE
      v_customer_user_id UUID;
    BEGIN
      SELECT user_id INTO v_customer_user_id FROM public.customers WHERE id = v_coupon.customer_id;
      IF v_customer_user_id != v_member.user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'このクーポンは使用できません');
      END IF;
    END;
  END IF;

  -- 割引額を計算
  v_discount := LEAST(v_coupon.discount_amount, COALESCE(v_member.payment_amount, v_group.per_person_price, 0));
  v_final_amount := GREATEST(0, COALESCE(v_member.payment_amount, v_group.per_person_price, 0) - v_discount);

  -- メンバーのクーポン情報を更新
  UPDATE public.private_group_members
  SET 
    coupon_id = p_coupon_id,
    coupon_discount = v_discount,
    final_amount = v_final_amount,
    payment_amount = COALESCE(payment_amount, v_group.per_person_price)
  WHERE id = p_member_id;

  RETURN jsonb_build_object(
    'success', true,
    'discount', v_discount,
    'final_amount', v_final_amount,
    'coupon_code', v_coupon.code
  );
END;
$$;


ALTER FUNCTION "public"."apply_coupon_to_group_member"("p_member_id" "uuid", "p_coupon_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_coupon_to_group_member"("p_member_id" "uuid", "p_coupon_id" "uuid") IS 'グループメンバーにクーポンを適用する';



CREATE OR REPLACE FUNCTION "public"."apply_for_booking_site"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_status TEXT;
BEGIN
  -- 呼び出し元の組織を取得
  SELECT organization_id INTO v_org_id
  FROM public.users
  WHERE id = auth.uid();

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'org_not_found: 組織に所属していません';
  END IF;

  -- 現在のステータスを確認
  SELECT booking_site_status INTO v_status
  FROM public.organizations
  WHERE id = v_org_id;

  IF v_status = 'approved' THEN
    RAISE EXCEPTION 'already_approved: 既に承認済みです';
  END IF;

  IF v_status = 'pending' THEN
    RAISE EXCEPTION 'already_pending: 既に申請中です';
  END IF;

  -- 申請中に更新
  UPDATE public.organizations
    SET booking_site_status = 'pending',
        updated_at = NOW()
  WHERE id = v_org_id;

  RETURN json_build_object('status', 'pending', 'org_id', v_org_id);
END;
$$;


ALTER FUNCTION "public"."apply_for_booking_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_scenario_slot_start_times"("p_hours" "jsonb", "p_times" "jsonb", "p_weekend" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE picks jsonb:='{}'::jsonb; bucket jsonb; k text; v text; opening jsonb:='{}'::jsonb; pair record;
BEGIN
 IF p_hours IS NULL OR jsonb_typeof(p_hours->'opening_hours') IS DISTINCT FROM 'object'
  OR p_times IS NULL OR jsonb_typeof(p_times) IS DISTINCT FROM 'object' THEN RETURN p_hours; END IF;
 bucket:=p_times->(CASE WHEN coalesce(p_weekend,false) THEN 'weekend' ELSE 'weekday' END);
 IF jsonb_typeof(bucket) IS DISTINCT FROM 'object' THEN RETURN p_hours; END IF;
 FOREACH k IN ARRAY ARRAY['morning','afternoon','evening'] LOOP
  v:=btrim(coalesce(bucket->>k,''));
  IF left(v,5) ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN picks:=picks||jsonb_build_object(k,left(v,5)); END IF;
 END LOOP;
 IF picks='{}'::jsonb THEN RETURN p_hours; END IF;
 FOR pair IN SELECT * FROM jsonb_each(p_hours->'opening_hours') LOOP
  opening:=opening||jsonb_build_object(pair.key,CASE WHEN jsonb_typeof(pair.value)='object'
   THEN pair.value||jsonb_build_object('slot_start_times',
     coalesce(CASE WHEN jsonb_typeof(pair.value->'slot_start_times')='object' THEN pair.value->'slot_start_times' END,'{}'::jsonb)||picks)
   ELSE pair.value END);
 END LOOP;
 RETURN jsonb_set(p_hours,'{opening_hours}',opening);
END $_$;


ALTER FUNCTION "public"."apply_scenario_slot_start_times"("p_hours" "jsonb", "p_times" "jsonb", "p_weekend" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_staff_assignment_edit"("p_org" "uuid", "p_staff" "uuid", "p_edit" "jsonb", "p_confirm" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE current_rows jsonb; incoming jsonb; old_flags jsonb; expected_flags jsonb; removed jsonb;
BEGIN
  IF jsonb_typeof(p_edit->'records') IS DISTINCT FROM 'array' OR jsonb_typeof(p_edit->'baseline') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid assignment edit' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM organization_scenarios WHERE organization_id=p_org ORDER BY scenario_master_id FOR KEY SHARE;
  PERFORM 1 FROM staff WHERE id=p_staff AND organization_id=p_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='23503'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') INTO current_rows FROM staff_scenario_assignments a WHERE organization_id=p_org AND staff_id=p_staff;
  SELECT coalesce(jsonb_agg(jsonb_build_array(r.scenario_master_id,coalesce(r.can_main_gm,false),coalesce(r.can_sub_gm,false),coalesce(r.is_experienced,false)) ORDER BY r.scenario_master_id),'[]') INTO old_flags
    FROM jsonb_to_recordset(current_rows) r(scenario_master_id uuid,can_main_gm boolean,can_sub_gm boolean,is_experienced boolean);
  SELECT coalesce(jsonb_agg(jsonb_build_array(r.scenario_master_id,r.can_main_gm,r.can_sub_gm,r.is_experienced) ORDER BY r.scenario_master_id),'[]') INTO expected_flags
    FROM jsonb_to_recordset(p_edit->'baseline') r(scenario_master_id uuid,can_main_gm boolean,can_sub_gm boolean,is_experienced boolean);
  IF old_flags IS DISTINCT FROM expected_flags THEN RAISE EXCEPTION 'Assignments changed' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_edit->'records') j WHERE
    jsonb_typeof(j->'can_main_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(j->'can_sub_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(j->'is_experienced') IS DISTINCT FROM 'boolean')
    OR (SELECT count(*) FROM jsonb_array_elements(p_edit->'records')) <> (SELECT count(DISTINCT j->>'scenarioId') FROM jsonb_array_elements(p_edit->'records') j) THEN
    RAISE EXCEPTION 'Invalid or duplicate assignment' USING ERRCODE='22023';
  END IF;
  -- 組織から外れた旧行は無変更なら保持。新規追加・変更は認めない。
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_edit->'records') j WHERE NOT EXISTS(
    SELECT 1 FROM organization_scenarios o WHERE o.organization_id=p_org AND o.scenario_master_id=(j->>'scenarioId')::uuid)
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_rows) a WHERE a->>'scenario_master_id'=j->>'scenarioId'
      AND a->'can_main_gm'=j->'can_main_gm' AND a->'can_sub_gm'=j->'can_sub_gm' AND a->'is_experienced'=j->'is_experienced')) THEN
    RAISE EXCEPTION 'Scenario unavailable' USING ERRCODE='23503';
  END IF;
  SELECT coalesce(jsonb_agg(a->>'scenario_master_id'),'[]') INTO removed FROM jsonb_array_elements(current_rows) a
    WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_edit->'records') j WHERE j->>'scenarioId'=a->>'scenario_master_id');
  IF NOT coalesce(p_confirm,false) AND (jsonb_array_length(removed)>0 OR jsonb_array_length(p_edit->'records')=0) THEN
    RAISE EXCEPTION 'Assignment decrease requires confirmation' USING ERRCODE='P0101',DETAIL=jsonb_build_object(
      'error','ASSIGNMENT_DECREASE_REJECTED','existing_count',jsonb_array_length(current_rows),
      'incoming_count',jsonb_array_length(p_edit->'records'),'removed_scenario_ids',removed,
      'removed_scenario_names',(SELECT coalesce(jsonb_agg(coalesce(o.title,r.id) ORDER BY r.ord),'[]')
        FROM jsonb_array_elements_text(removed) WITH ORDINALITY r(id,ord)
        LEFT JOIN organization_scenarios_with_master o ON o.organization_id=p_org AND o.scenario_master_id=r.id::uuid))::text;
  END IF;
  SELECT coalesce(jsonb_agg(j),'[]') INTO incoming FROM jsonb_array_elements(p_edit->'records') j WHERE EXISTS(
    SELECT 1 FROM organization_scenarios o WHERE o.organization_id=p_org AND o.scenario_master_id=(j->>'scenarioId')::uuid);
  PERFORM replace_staff_assignments_atomic(p_org,p_staff,incoming,current_rows);
END $$;


ALTER FUNCTION "public"."apply_staff_assignment_edit"("p_org" "uuid", "p_staff" "uuid", "p_edit" "jsonb", "p_confirm" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_booking_site"("p_org_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- ライセンス管理者チェック
  IF NOT public.is_license_admin() THEN
    RAISE EXCEPTION 'forbidden: ライセンス管理者のみ実行できます';
  END IF;

  UPDATE public.organizations
    SET booking_site_status = 'approved',
        plan = 'pro',
        updated_at = NOW()
  WHERE id = p_org_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_not_found: 組織が見つかりません';
  END IF;

  RETURN json_build_object('status', 'approved', 'org_id', p_org_id);
END;
$$;


ALTER FUNCTION "public"."approve_booking_site"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_private_booking"("p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $_$
DECLARE
  v_reservation RECORD;
  v_pricing public.private_booking_pricing_snapshots%ROWTYPE;
  v_priced_booking BOOLEAN := FALSE;
  v_unit_price INTEGER;
  v_total_price INTEGER;
  v_org_id UUID;
  v_caller_org_id UUID;
  v_caller_staff_id UUID;
  v_schedule_event_id UUID;
  v_existing_event_id UUID;
  v_gm_name TEXT;
  v_sub_gm_name TEXT;
  v_store_name TEXT;
  v_store_short_name TEXT;
  v_updated_count INTEGER;
  v_private_group_id UUID;
  v_gms_array TEXT[];
  v_gm_roles JSONB;
  v_calendar_date DATE;
  v_raw TEXT;
  v_candidate JSONB;
  v_candidate_date DATE;
  v_candidate_start_time TIME;
  v_candidate_end_time TIME;
  v_candidate_time_slot TEXT;
  v_schedule_time_slot TEXT;
  v_trusted_candidate_found BOOLEAN := false;
  v_requested_store_count INTEGER;
  v_candidate_ordinal BIGINT;
  v_selected_candidate_ordinal BIGINT;
  v_normalized_candidate JSONB;
  v_rebuilt_candidates JSONB := '[]'::JSONB;
  v_confirmed_candidate_datetimes JSONB;
  v_hint_time_slot TEXT;
  v_event_time_slot TEXT;
BEGIN
  SELECT *
  INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id
    AND status IN ('pending', 'pending_gm', 'gm_confirmed', 'pending_store', 'confirmed', 'cancelled')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND_OR_ALREADY_CONFIRMED' USING ERRCODE = 'P0018';
  END IF;

  v_org_id := v_reservation.organization_id;
  v_private_group_id := v_reservation.private_group_id;
  v_existing_event_id := v_reservation.schedule_event_id;

  v_caller_org_id := get_user_organization_id();
  IF auth.uid() IS NULL
     OR v_caller_org_id IS NULL
     OR v_caller_org_id IS DISTINCT FROM v_org_id
  THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0010';
  END IF;

  SELECT id INTO v_caller_staff_id
  FROM staff
  WHERE user_id = auth.uid()
    AND organization_id = v_org_id
  ORDER BY id
  LIMIT 1;

  IF NOT is_staff_or_admin()
     OR (v_caller_staff_id IS NULL AND NOT is_org_admin())
  THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0010';
  END IF;

  SELECT name INTO v_gm_name
  FROM staff
  WHERE id = p_selected_gm_id
    AND organization_id = v_org_id;

  IF v_gm_name IS NULL THEN
    RAISE EXCEPTION 'GM_NOT_FOUND' USING ERRCODE = 'P0022';
  END IF;

  v_sub_gm_name := NULL;
  IF p_selected_sub_gm_id IS NOT NULL THEN
    IF p_selected_sub_gm_id = p_selected_gm_id THEN
      RAISE EXCEPTION 'SUB_GM_SAME_AS_MAIN' USING ERRCODE = 'P0026';
    END IF;
    SELECT name INTO v_sub_gm_name
    FROM staff
    WHERE id = p_selected_sub_gm_id
      AND organization_id = v_org_id;
    IF v_sub_gm_name IS NULL THEN
      RAISE EXCEPTION 'SUB_GM_NOT_FOUND' USING ERRCODE = 'P0022';
    END IF;
  END IF;

  SELECT name, short_name
  INTO v_store_name, v_store_short_name
  FROM stores
  WHERE id = p_selected_store_id
    AND organization_id = v_org_id
    AND status = 'active';

  IF v_store_name IS NULL THEN
    RAISE EXCEPTION 'STORE_NOT_FOUND' USING ERRCODE = 'P0023';
  END IF;

  -- 希望店舗が保存されている申請では、その信頼済み集合からだけ承認する。
  v_requested_store_count := jsonb_array_length(
    COALESCE(v_reservation.candidate_datetimes->'requestedStores', '[]'::jsonb)
  );
  IF v_requested_store_count > 0 AND NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_reservation.candidate_datetimes->'requestedStores') requested
    WHERE requested->>'storeId' = p_selected_store_id::TEXT
  ) THEN
    RAISE EXCEPTION 'STORE_NOT_REQUESTED' USING ERRCODE = 'P0042';
  END IF;

  -- 承認時刻の上書き用: clientのconfirmed候補は「どの希望枠か」のヒントにだけ使う。
  -- 日付・枠の正は保存済み候補。開始・終了は p_selected_* を採用してよい。
  SELECT CASE elem->>'timeSlot'
    WHEN 'morning' THEN 'morning'
    WHEN '朝' THEN 'morning'
    WHEN '午前' THEN 'morning'
    WHEN 'afternoon' THEN 'afternoon'
    WHEN '昼' THEN 'afternoon'
    WHEN '午後' THEN 'afternoon'
    WHEN 'evening' THEN 'evening'
    WHEN '夜' THEN 'evening'
    WHEN '夜間' THEN 'evening'
    ELSE NULL
  END
  INTO v_hint_time_slot
  FROM jsonb_array_elements(
    COALESCE(p_candidate_datetimes->'candidates', '[]'::jsonb)
  ) AS elem
  WHERE elem->>'status' = 'confirmed'
  LIMIT 1;

  -- clientが送ったconfirmed状態ではなく、予約に保存済みの候補から日付・time_slotを復元する。
  FOR v_candidate, v_candidate_ordinal IN
    SELECT candidate.value, candidate.ordinality
    FROM jsonb_array_elements(
      COALESCE(v_reservation.candidate_datetimes->'candidates', '[]'::jsonb)
    ) WITH ORDINALITY AS candidate(value, ordinality)
  LOOP
    v_raw := v_candidate->>'date';
    BEGIN
      IF btrim(v_raw) ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_candidate_date := btrim(v_raw)::DATE;
      ELSE
        v_candidate_date := ((btrim(v_raw))::TIMESTAMPTZ AT TIME ZONE 'Asia/Tokyo')::DATE;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;

    BEGIN
      v_candidate_start_time := (v_candidate->>'startTime')::TIME;
      v_candidate_end_time := (v_candidate->>'endTime')::TIME;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;

    v_candidate_time_slot := CASE v_candidate->>'timeSlot'
      WHEN 'morning' THEN 'morning'
      WHEN '朝' THEN 'morning'
      WHEN '午前' THEN 'morning'
      WHEN 'afternoon' THEN 'afternoon'
      WHEN '昼' THEN 'afternoon'
      WHEN '午後' THEN 'afternoon'
      WHEN 'evening' THEN 'evening'
      WHEN '夜' THEN 'evening'
      WHEN '夜間' THEN 'evening'
      ELSE NULL
    END;

    IF v_candidate_date = p_selected_date
       AND v_candidate_time_slot IS NOT NULL
       AND (
         (
           v_candidate_start_time = p_selected_start_time
           AND v_candidate_end_time = p_selected_end_time
         )
         OR (
           v_hint_time_slot IS NOT NULL
           AND v_candidate_time_slot = v_hint_time_slot
         )
       )
    THEN
      v_selected_candidate_ordinal := v_candidate_ordinal;
      v_trusted_candidate_found := true;
      EXIT;
    END IF;
  END LOOP;

  IF NOT v_trusted_candidate_found OR v_candidate_time_slot IS NULL THEN
    RAISE EXCEPTION 'INVALID_SELECTED_CANDIDATE' USING ERRCODE = 'P0041';
  END IF;
  IF p_selected_start_time >= p_selected_end_time THEN
    RAISE EXCEPTION 'INVALID_SELECTED_CANDIDATE_TIME' USING ERRCODE = 'P0041';
  END IF;
  IF p_selected_start_time < TIME '09:00' OR p_selected_end_time > TIME '23:00' THEN
    RAISE EXCEPTION 'INVALID_SELECTED_CANDIDATE_TIME' USING ERRCODE = 'P0041';
  END IF;

  SELECT * INTO v_pricing FROM public.private_booking_pricing_snapshots
  WHERE reservation_id = p_reservation_id AND organization_id = v_org_id;
  v_priced_booking := FOUND;
  IF v_priced_booking THEN
    v_unit_price := public.calculate_booking_participation_fee(
      v_pricing.base_fee, v_pricing.participation_costs, p_selected_date, p_selected_start_time,
      v_pricing.custom_holidays ? p_selected_date::TEXT, v_pricing.pricing_date
    );
    v_total_price := v_unit_price * v_reservation.participant_count;
  END IF;

  v_event_time_slot := CASE
    WHEN EXTRACT(HOUR FROM p_selected_start_time) < 12 THEN 'morning'
    WHEN EXTRACT(HOUR FROM p_selected_start_time) <= 17 THEN 'afternoon'
    ELSE 'evening'
  END;

  -- live client互換のshapeを維持しつつ、保存済み候補だけからconfirmed状態を再構築する。
  FOR v_candidate, v_candidate_ordinal IN
    SELECT candidate.value, candidate.ordinality
    FROM jsonb_array_elements(
      COALESCE(v_reservation.candidate_datetimes->'candidates', '[]'::jsonb)
    ) WITH ORDINALITY AS candidate(value, ordinality)
  LOOP
    v_normalized_candidate := v_candidate;
    v_raw := v_candidate->>'date';
    IF v_raw IS NOT NULL THEN
      BEGIN
        IF btrim(v_raw) ~ '^\d{4}-\d{2}-\d{2}$' THEN
          v_candidate_date := btrim(v_raw)::DATE;
        ELSE
          v_candidate_date := ((btrim(v_raw))::TIMESTAMPTZ AT TIME ZONE 'Asia/Tokyo')::DATE;
        END IF;
        v_normalized_candidate := jsonb_set(
          v_normalized_candidate,
          '{date}',
          to_jsonb(v_candidate_date::TEXT),
          true
        );
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;

    v_normalized_candidate := jsonb_set(
      v_normalized_candidate,
      '{status}',
      to_jsonb(
        CASE
          WHEN v_candidate_ordinal = v_selected_candidate_ordinal THEN 'confirmed'
          ELSE 'pending'
        END
      ),
      true
    );
    IF v_candidate_ordinal = v_selected_candidate_ordinal THEN
      IF v_priced_booking THEN
        v_normalized_candidate := v_normalized_candidate || jsonb_build_object(
          'unitPrice', v_unit_price, 'totalPrice', v_total_price);
      END IF;
      v_normalized_candidate := jsonb_set(
        jsonb_set(
          v_normalized_candidate,
          '{startTime}',
          to_jsonb(to_char(p_selected_start_time, 'HH24:MI')),
          true
        ),
        '{endTime}',
        to_jsonb(to_char(p_selected_end_time, 'HH24:MI')),
        true
      );
      IF v_event_time_slot IS DISTINCT FROM v_candidate_time_slot THEN
        v_normalized_candidate := jsonb_set(
          v_normalized_candidate,
          '{timeSlot}',
          to_jsonb(
            CASE v_event_time_slot
              WHEN 'morning' THEN '午前'
              WHEN 'afternoon' THEN '午後'
              ELSE '夜'
            END
          ),
          true
        );
      END IF;
    END IF;
    v_rebuilt_candidates := v_rebuilt_candidates || jsonb_build_array(v_normalized_candidate);
  END LOOP;

  v_confirmed_candidate_datetimes := jsonb_set(
    jsonb_set(
      COALESCE(v_reservation.candidate_datetimes, '{}'::JSONB),
      '{candidates}',
      v_rebuilt_candidates,
      true
    ),
    '{confirmedStore}',
    jsonb_build_object(
      'storeId', p_selected_store_id::TEXT,
      'storeName', v_store_name,
      'storeShortName', COALESCE(v_store_short_name, v_store_name)
    ),
    true
  );

  v_calendar_date := p_selected_date;
  v_schedule_time_slot := CASE v_event_time_slot
    WHEN 'morning' THEN '朝'
    WHEN 'afternoon' THEN '昼'
    ELSE '夜'
  END;

  -- block/unblockと全公演INSERTを直列化し、検査からINSERTまで同じ状態を維持する。
  LOCK TABLE schedule_blocked_slots IN SHARE MODE;
  LOCK TABLE schedule_events IN SHARE ROW EXCLUSIVE MODE;

  IF EXISTS (
    SELECT 1
    FROM schedule_blocked_slots blocked
    WHERE blocked.organization_id = v_org_id
      AND blocked.store_id = p_selected_store_id::TEXT
      AND blocked.date = v_calendar_date
      AND blocked.time_slot = v_event_time_slot
  ) OR public.is_store_recruitment_paused(p_selected_store_id, 'private', v_calendar_date) THEN
    RAISE EXCEPTION 'PRIVATE_BOOKING_SLOT_BLOCKED:%:%', v_calendar_date, v_event_time_slot
      USING ERRCODE = 'P0040';
  END IF;

  IF v_existing_event_id IS NOT NULL THEN
    UPDATE schedule_events
    SET is_cancelled = true,
        updated_at = NOW()
    WHERE id = v_existing_event_id
      AND organization_id = v_org_id;
  END IF;

  -- メインGMの競合チェック（直接重複）
  PERFORM 1
  FROM schedule_events
  WHERE organization_id = v_org_id
    AND date = v_calendar_date
    AND is_cancelled = false
    AND v_gm_name = ANY(gms)
    AND start_time < p_selected_end_time
    AND end_time > p_selected_start_time
    AND id != COALESCE(v_existing_event_id, '00000000-0000-0000-0000-000000000000'::UUID)
  FOR UPDATE NOWAIT;

  IF FOUND THEN
    RAISE EXCEPTION 'GM_ALREADY_ASSIGNED' USING ERRCODE = 'P0025';
  END IF;

  -- サブGMの競合チェック（直接重複）
  IF v_sub_gm_name IS NOT NULL THEN
    PERFORM 1
    FROM schedule_events
    WHERE organization_id = v_org_id
      AND date = v_calendar_date
      AND is_cancelled = false
      AND v_sub_gm_name = ANY(gms)
      AND start_time < p_selected_end_time
      AND end_time > p_selected_start_time
      AND id != COALESCE(v_existing_event_id, '00000000-0000-0000-0000-000000000000'::UUID)
    FOR UPDATE NOWAIT;

    IF FOUND THEN
      RAISE EXCEPTION 'GM_ALREADY_ASSIGNED' USING ERRCODE = 'P0025';
    END IF;
  END IF;

  -- 店舗の直接重複チェック
  PERFORM 1
  FROM schedule_events
  WHERE organization_id = v_org_id
    AND date = v_calendar_date
    AND store_id = p_selected_store_id
    AND is_cancelled = false
    AND start_time < p_selected_end_time
    AND end_time > p_selected_start_time
    AND id != COALESCE(v_existing_event_id, '00000000-0000-0000-0000-000000000000'::UUID)
  FOR UPDATE NOWAIT;

  IF FOUND THEN
    RAISE EXCEPTION 'SLOT_ALREADY_OCCUPIED' USING ERRCODE = 'P0019';
  END IF;

  -- 店舗の60分インターバルチェック（設営・撤収時間の確保）
  PERFORM 1
  FROM schedule_events
  WHERE organization_id = v_org_id
    AND date BETWEEN v_calendar_date - 2 AND v_calendar_date + 2
    AND store_id = p_selected_store_id
    AND is_cancelled = false
    AND date + start_time < v_calendar_date + p_selected_end_time + CASE WHEN p_selected_end_time < p_selected_start_time THEN interval '1 day' ELSE interval '0 days' END + make_interval(mins => public.resolve_preparation_minutes(v_org_id,NULL,NULL,id))
    AND date + end_time + CASE WHEN end_time < start_time THEN interval '1 day' ELSE interval '0 days' END > v_calendar_date + p_selected_start_time - make_interval(mins => public.resolve_preparation_minutes(v_org_id,p_selected_store_id,v_reservation.scenario_master_id,NULL))
    AND id != COALESCE(v_existing_event_id, '00000000-0000-0000-0000-000000000000'::UUID)
  FOR UPDATE NOWAIT;

  IF FOUND THEN
    RAISE EXCEPTION 'INTERVAL_TOO_SHORT' USING ERRCODE = 'P0027';
  END IF;

  IF v_sub_gm_name IS NOT NULL THEN
    v_gms_array := ARRAY[v_gm_name, v_sub_gm_name];
    v_gm_roles := jsonb_build_object(v_gm_name, 'main', v_sub_gm_name, 'sub');
  ELSE
    v_gms_array := ARRAY[v_gm_name];
    v_gm_roles := '{}'::JSONB;
  END IF;

  INSERT INTO schedule_events (
    date,
    venue,
    scenario,
    scenario_master_id,
    organization_scenario_id,
    start_time,
    end_time,
    start_at,
    end_at,
    store_id,
    gms,
    gm_roles,
    is_reservation_enabled,
    status,
    category,
    organization_id,
    reservation_id,
    reservation_name,
    is_reservation_name_overwritten,
    time_slot
  ) VALUES (
    v_calendar_date,
    v_store_name,
    p_scenario_title,
    v_reservation.scenario_master_id,
    (SELECT os.id FROM public.organization_scenarios os WHERE os.organization_id=v_org_id AND os.scenario_master_id=v_reservation.scenario_master_id LIMIT 1),
    p_selected_start_time,
    p_selected_end_time,
    (v_calendar_date + p_selected_start_time)::TIMESTAMPTZ,
    (v_calendar_date + p_selected_end_time)::TIMESTAMPTZ,
    p_selected_store_id,
    v_gms_array,
    v_gm_roles,
    false,
    'confirmed',
    'private',
    v_org_id,
    p_reservation_id,
    p_customer_name,
    false,
    v_schedule_time_slot
  )
  RETURNING id INTO v_schedule_event_id;

  UPDATE reservations
  SET
    status = 'confirmed',
    unit_price = CASE WHEN v_priced_booking THEN v_unit_price ELSE unit_price END,
    base_price = CASE WHEN v_priced_booking THEN v_total_price ELSE base_price END,
    total_price = CASE WHEN v_priced_booking THEN v_total_price + COALESCE(options_price, 0) ELSE total_price END,
    final_price = CASE WHEN v_priced_booking THEN GREATEST(0, v_total_price + COALESCE(options_price, 0) - COALESCE(discount_amount, 0)) ELSE final_price END,
    gm_staff = p_selected_gm_id,
    store_id = p_selected_store_id,
    schedule_event_id = v_schedule_event_id,
    candidate_datetimes = v_confirmed_candidate_datetimes,
    requested_datetime = (v_calendar_date::TEXT || ' ' || p_selected_start_time::TEXT)::TIMESTAMP WITH TIME ZONE,
    duration = EXTRACT(EPOCH FROM (p_selected_end_time - p_selected_start_time)) / 60,
    confirmed_by = COALESCE(v_caller_staff_id, confirmed_by),
    updated_at = NOW()
  WHERE id = p_reservation_id
    AND organization_id = v_org_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> 1 THEN
    RAISE EXCEPTION 'RESERVATION_UPDATE_FAILED' USING ERRCODE = 'P0024';
  END IF;

  IF v_private_group_id IS NOT NULL THEN
    UPDATE private_groups
    SET status = 'confirmed'
    WHERE id = v_private_group_id
      AND organization_id = v_org_id;
  END IF;

  RETURN v_schedule_event_id;
END;
$_$;


ALTER FUNCTION "public"."approve_private_booking"("p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_private_booking"("p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid") IS '貸切予約承認。確定候補の日付・枠は保存済み申請から検証し、開始・終了はスタッフが承認時に上書きできる。公演の time_slot は開始時刻から再判定する。';



CREATE OR REPLACE FUNCTION "public"."approve_private_booking_with_delivery"("p_request_id" "uuid", "p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE
 r public.reservations%ROWTYPE; receipt public.private_booking_approval_requests%ROWTYPE;
 payload jsonb; result jsonb; recipient text; recipient_name text; message_id uuid;
BEGIN
 IF auth.uid() IS NULL OR p_request_id IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR public.get_user_organization_id() IS DISTINCT FROM r.organization_id
  OR NOT coalesce(public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff s WHERE s.user_id=auth.uid() AND s.organization_id=r.organization_id AND s.status='active'),false) THEN
  RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
 END IF;
 payload:=jsonb_build_object('reservation',p_reservation_id,'date',p_selected_date,'start',p_selected_start_time,'end',p_selected_end_time,
  'store',p_selected_store_id,'gm',p_selected_gm_id,'sub_gm',p_selected_sub_gm_id,'candidates',p_candidate_datetimes,'title',p_scenario_title,'customer_name',p_customer_name);
 SELECT * INTO receipt FROM public.private_booking_approval_requests WHERE id=p_request_id;
 IF FOUND THEN
  IF receipt.organization_id IS DISTINCT FROM r.organization_id OR receipt.reservation_id IS DISTINCT FROM r.id
   OR receipt.actor_id IS DISTINCT FROM auth.uid() OR receipt.request_payload IS DISTINCT FROM payload THEN
   RAISE EXCEPTION 'APPROVAL_REQUEST_CONFLICT' USING ERRCODE='22023';
  END IF;
  RETURN receipt.result||jsonb_build_object('replayed',true);
 END IF;
 result:=public.approve_private_booking_with_notice(p_reservation_id,p_selected_date,p_selected_start_time,
  p_selected_end_time,p_selected_store_id,p_selected_gm_id,p_candidate_datetimes,p_scenario_title,p_customer_name,p_selected_sub_gm_id);
 SELECT * INTO STRICT r FROM public.reservations WHERE id=p_reservation_id;
 message_id:=(result->>'survey_message_id')::uuid;
 IF result->>'survey_notice' IS NOT NULL THEN
  IF message_id IS NULL OR r.private_group_id IS NULL THEN RAISE EXCEPTION 'SURVEY_NOTICE_MISSING' USING ERRCODE='22023'; END IF;
  recipient:=nullif(btrim(r.customer_email),'');recipient_name:=coalesce(nullif(r.customer_name,''),'お客様');
  IF recipient IS NULL AND r.customer_id IS NOT NULL THEN
   SELECT nullif(btrim(c.email),''),coalesce(nullif(c.name,''),recipient_name) INTO recipient,recipient_name FROM public.customers c
    WHERE c.id=r.customer_id AND (c.organization_id=r.organization_id OR c.organization_id IS NULL);
  END IF;
  INSERT INTO public.private_group_survey_deliveries(id,organization_id,group_id,reservation_id,schedule_event_id,actor_id,source,message_id,customer_email,customer_name,subject,message_body)
  VALUES(p_request_id,r.organization_id,r.private_group_id,r.id,(result->>'schedule_event_id')::uuid,auth.uid(),'approval',message_id,recipient,coalesce(recipient_name,'お客様'),'【事前配役アンケートのご案内】',result->>'survey_notice');
  result:=result||jsonb_build_object('survey_delivery_id',p_request_id,'survey_delivery_status','pending');
 END IF;
 -- 旧ブラウザはsurvey_noticeを直接送信するため、新入口では本文を返さない。
 result:=(result-'survey_notice'-'survey_message_id')||jsonb_build_object('replayed',false);
 INSERT INTO public.private_booking_approval_requests(id,organization_id,reservation_id,actor_id,request_payload,result)
 VALUES(p_request_id,r.organization_id,r.id,auth.uid(),payload,result);
 RETURN result;
END $$;


ALTER FUNCTION "public"."approve_private_booking_with_delivery"("p_request_id" "uuid", "p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_private_booking_with_notice"("p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE event_id uuid; r record; g record; e record; settings record;
 member_id uuid; survey_message_id uuid; survey jsonb; survey_message text; survey_action text; deadline_text text := '';
BEGIN
 event_id:=public.approve_private_booking(p_reservation_id,p_selected_date,p_selected_start_time,
 p_selected_end_time,p_selected_store_id,p_selected_gm_id,p_candidate_datetimes,
 p_scenario_title,p_customer_name,p_selected_sub_gm_id);
 SELECT * INTO STRICT r FROM reservations WHERE id=p_reservation_id;
 IF r.private_group_id IS NULL THEN
   RETURN jsonb_build_object('schedule_event_id',event_id,'survey_notice',NULL);
 END IF;
 SELECT * INTO g FROM private_groups WHERE id=r.private_group_id AND organization_id=r.organization_id FOR UPDATE;
 IF NOT FOUND THEN
   RAISE EXCEPTION 'PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
 END IF;
 IF g.reservation_id IS DISTINCT FROM r.id THEN
   RAISE EXCEPTION 'PRIVATE_GROUP_RESERVATION_MISMATCH' USING ERRCODE='P0051';
 END IF;
 SELECT se.*,s.name AS store_name INTO STRICT e FROM schedule_events se
 JOIN stores s ON s.id=se.store_id AND s.organization_id=se.organization_id
 WHERE se.id=event_id AND se.organization_id=r.organization_id;
 SELECT system_msg_schedule_confirmed_title,system_msg_schedule_confirmed_body,pre_reading_notice_message
 INTO settings FROM global_settings WHERE organization_id=r.organization_id;
 SELECT m.id INTO member_id FROM private_group_members m
 WHERE m.group_id=g.id AND m.is_organizer AND m.user_id=g.organizer_id ORDER BY m.id LIMIT 1;
 INSERT INTO private_group_messages(group_id,member_id,message) VALUES(g.id,member_id,
 jsonb_build_object('type','system','action','schedule_confirmed','confirmedDate',e.date,
 'confirmedTimeSlot',COALESCE(NULLIF(e.time_slot,''),to_char(e.start_time,'HH24:MI')||'〜'||to_char(e.end_time,'HH24:MI')),
 'storeName',e.store_name,'title',COALESCE(NULLIF(settings.system_msg_schedule_confirmed_title,''),'日程が確定いたしました'),
 'body',COALESCE(NULLIF(settings.system_msg_schedule_confirmed_body,''),'ご予約ありがとうございます。当日のご来店をお待ちしております。'))::text);
 survey:=public.freeze_private_group_survey_deadline(r.organization_id,g.id);
 IF survey->>'error' IS NOT NULL THEN
   RAISE EXCEPTION 'PRIVATE_GROUP_SURVEY_CONFIGURATION_INVALID' USING ERRCODE='P0052';
 END IF;
 IF COALESCE((survey->>'survey_enabled')::boolean,false) THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(survey->'characters','[]'::jsonb)) c
             WHERE NOT COALESCE((c->>'is_npc')::boolean,false)) AND NULLIF(survey->>'survey_url','') IS NULL THEN
     survey_action:='pre_reading_notice';
     survey_message:=COALESCE(NULLIF(settings.pre_reading_notice_message,''),E'【ご確認ください】\n\nこのシナリオには事前配役アンケートがございます。\n\n公演日までに参加者全員がこのグループに参加している必要があります。まだ参加されていない方がいらっしゃいましたら、招待リンクを共有してグループへの参加をお願いいたします。\n\nご不明点がございましたら、店舗までお問い合わせください。');
   ELSE
     survey_action:='survey_notice';
     IF survey->>'survey_deadline_at' IS NOT NULL THEN
       deadline_text:=E'\n\n回答期限: '||to_char((survey->>'survey_deadline_at')::timestamptz AT TIME ZONE 'Asia/Tokyo','FMMM/FMDD')||'まで';
     END IF;
     survey_message:=E'【事前配役アンケートのご協力のお願い】\n\nこちらの公演では事前配役アンケートへのご回答をお願いしております。\n\n'||
       CASE WHEN NULLIF(survey->>'survey_url','') IS NOT NULL THEN E'次のURLからアンケートにお答えください。\n'||(survey->>'survey_url')
       ELSE '上記の「日程を確認・回答する」ボタンからアンケートにお答えください。' END||deadline_text||E'\n\nご不明点がございましたら、お気軽にお問い合わせください。';
   END IF;
   INSERT INTO private_group_messages(group_id,member_id,message) VALUES(g.id,member_id,
     jsonb_build_object('type','system','action',survey_action,'message',survey_message)::text) RETURNING id INTO survey_message_id;
 END IF;
 RETURN jsonb_build_object('schedule_event_id',event_id,'survey_notice',survey_message,'survey_message_id',survey_message_id);
END $$;


ALTER FUNCTION "public"."approve_private_booking_with_notice"("p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_private_booking_with_notifications"("p_request_id" "uuid", "p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE approval_result jsonb;
BEGIN
 approval_result:=public.approve_private_booking_with_delivery(p_request_id,p_reservation_id,p_selected_date,p_selected_start_time,
  p_selected_end_time,p_selected_store_id,p_selected_gm_id,p_candidate_datetimes,p_scenario_title,p_customer_name,p_selected_sub_gm_id);
 -- 旧版の通信再試行を、新しい通知要求と誤認しない。
 IF approval_result->>'replayed'='true' THEN RETURN approval_result; END IF;
 PERFORM public.enqueue_private_approval_deliveries(p_request_id);
 approval_result:=approval_result||jsonb_build_object('approval_delivery_queued',true);
 UPDATE public.private_booking_approval_requests AS receipt SET result=approval_result WHERE receipt.id=p_request_id;
 RETURN approval_result;
END $$;


ALTER FUNCTION "public"."approve_private_booking_with_notifications"("p_request_id" "uuid", "p_reservation_id" "uuid", "p_selected_date" "date", "p_selected_start_time" time without time zone, "p_selected_end_time" time without time zone, "p_selected_store_id" "uuid", "p_selected_gm_id" "uuid", "p_candidate_datetimes" "jsonb", "p_scenario_title" "text", "p_customer_name" "text", "p_selected_sub_gm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_customer_cancellation_policy"("p_reservation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
 r public.reservations; e public.schedule_events;
 v_type text; v_key text; v_deadline numeric; v_fees jsonb; v_rule jsonb;
 v_hours numeric; v_fee numeric := 0; v_setting jsonb;
BEGIN
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE='P0005'; END IF;
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0009'; END IF;
 IF COALESCE((public.is_org_admin() AND public.get_user_organization_id() IS NOT DISTINCT FROM r.organization_id)
   OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid() AND organization_id=r.organization_id AND status='active'),false) THEN RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=r.customer_id AND user_id=auth.uid()) THEN
   RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0009'; END IF;
 SELECT * INTO e FROM public.schedule_events WHERE id=r.schedule_event_id AND organization_id=r.organization_id FOR SHARE NOWAIT;
 IF NOT FOUND OR e.date IS NULL OR e.start_time IS NULL THEN
   RAISE EXCEPTION 'CUSTOMER_CANCELLATION_POLICY_UNAVAILABLE' USING ERRCODE='P0053'; END IF;
 v_type := CASE WHEN r.cancellation_policy_performance_type IN ('open','private') THEN r.cancellation_policy_performance_type
   WHEN r.private_group_id IS NOT NULL OR r.reservation_source='web_private'
     OR e.is_private_booking IS TRUE OR e.category='private' THEN 'private' ELSE 'open' END;
 IF r.cancellation_policy_snapshot_version=1 THEN
   IF r.cancellation_policy_store_id IS NULL OR r.cancellation_policy_performance_type IS NULL
     OR r.cancellation_policy_performance_type NOT IN ('open','private') OR r.cancellation_policy_deadline_hours IS NULL
     OR r.cancellation_policy_fee_basis IS NULL OR r.cancellation_policy_fee_basis NOT IN ('participant_total','performance_total')
     OR r.cancellation_policy_updated_at IS NULL OR jsonb_typeof(r.cancellation_policy_fees) IS DISTINCT FROM 'array' THEN
     RAISE EXCEPTION 'CUSTOMER_CANCELLATION_POLICY_UNAVAILABLE' USING ERRCODE='P0053'; END IF;
   v_deadline:=greatest(0,r.cancellation_policy_deadline_hours);
   v_fees:=r.cancellation_policy_fees;
 ELSE
   v_key:=CASE WHEN r.private_group_id IS NOT NULL OR e.is_private_booking IS TRUE OR e.category='private' THEN 'private_cancellation_deadline_hours' ELSE 'cancellation_deadline_hours' END;
   v_setting:=public.resolve_operating_setting(r.organization_id,v_key,to_jsonb(CASE WHEN v_type='private' THEN 720 ELSE 48 END),NULL,NULL,e.id)->'value';
   IF jsonb_typeof(v_setting) IS DISTINCT FROM 'number' THEN
     RAISE EXCEPTION 'CUSTOMER_CANCELLATION_POLICY_UNAVAILABLE' USING ERRCODE='P0053'; END IF;
   v_deadline:=(v_setting #>> '{}')::numeric;
   IF v_deadline<0 THEN RAISE EXCEPTION 'CUSTOMER_CANCELLATION_POLICY_UNAVAILABLE' USING ERRCODE='P0053'; END IF;
   v_fees:=CASE WHEN v_type='private' THEN '[{"hours_before":168,"fee_percentage":50,"description":"legacy"},{"hours_before":72,"fee_percentage":100,"description":"legacy"},{"hours_before":-1,"fee_percentage":100,"description":"legacy"}]'::jsonb
     ELSE '[{"hours_before":48,"fee_percentage":50,"description":"legacy"},{"hours_before":24,"fee_percentage":100,"description":"legacy"},{"hours_before":-1,"fee_percentage":100,"description":"legacy"}]'::jsonb END;
 END IF;
 -- Existing free self-cancellation semantics: zero uses the default free period.
 IF v_deadline=0 THEN v_deadline:=CASE WHEN v_type='private' THEN 720 ELSE 48 END; END IF;
 FOR v_rule IN SELECT value FROM jsonb_array_elements(v_fees) LOOP
   IF jsonb_typeof(v_rule->'hours_before') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_rule->'fee_percentage') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_rule->'description') IS DISTINCT FROM 'string' THEN
     RAISE EXCEPTION 'CUSTOMER_CANCELLATION_POLICY_UNAVAILABLE' USING ERRCODE='P0053'; END IF;
 END LOOP;
 v_hours:=extract(epoch FROM (((e.date+e.start_time) AT TIME ZONE 'Asia/Tokyo')-statement_timestamp()))/3600;
 FOR v_rule IN SELECT value FROM jsonb_array_elements(v_fees) WITH ORDINALITY AS f(value,n) ORDER BY (value->>'hours_before')::numeric DESC,n LOOP
   IF v_hours<=(v_rule->>'hours_before')::numeric THEN v_fee:=(v_rule->>'fee_percentage')::numeric; END IF;
 END LOOP;
 IF v_hours<v_deadline OR greatest(0,least(100,v_fee))<>0 THEN
   RAISE EXCEPTION 'CUSTOMER_CANCELLATION_DEADLINE_OR_FEE' USING ERRCODE='P0052'; END IF;
END $$;


ALTER FUNCTION "public"."assert_customer_cancellation_policy"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_private_booking_candidate_date"("p_org" "uuid", "p_scenario" "uuid", "p_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE days INTEGER;
BEGIN
 IF p_org IS NULL OR p_scenario IS NULL OR p_date IS NULL THEN RAISE EXCEPTION 'PRIVATE_BOOKING_CONTEXT_REQUIRED' USING ERRCODE='P0045'; END IF;
 days := public.get_effective_private_booking_deadline_days(p_org,NULL,p_scenario);
 IF p_date < (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Tokyo')::DATE + days THEN
   RAISE EXCEPTION 'PRIVATE_BOOKING_DEADLINE_PASSED' USING ERRCODE='P0045';
 END IF;
END;
$$;


