CREATE OR REPLACE FUNCTION "public"."audit_customer_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO audit_logs (
      user_id, action, table_name, record_id, old_values, new_values
    ) VALUES (
      auth.uid(),
      'CUSTOMER_CREATED',
      'customers',
      NEW.id,
      NULL,
      jsonb_build_object(
        'name', NEW.name,
        'email', NEW.email,
        'phone', NEW.phone,
        'organization_id', NEW.organization_id
      )
    );
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO audit_logs (
      user_id, action, table_name, record_id, old_values, new_values
    ) VALUES (
      auth.uid(),
      'CUSTOMER_UPDATED',
      'customers',
      NEW.id,
      jsonb_build_object(
        'name', OLD.name,
        'email', OLD.email,
        'phone', OLD.phone
      ),
      jsonb_build_object(
        'name', NEW.name,
        'email', NEW.email,
        'phone', NEW.phone
      )
    );
  END IF;
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'audit_customer_changes failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_customer_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_generic_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_action text;
  v_resource_type text;
  v_resource_id uuid;
  v_org_id uuid;
  v_old_values jsonb;
  v_new_values jsonb;
BEGIN
  v_user_id := auth.uid();
  v_resource_type := TG_TABLE_NAME;

  IF TG_OP = 'INSERT' THEN
    v_action := v_resource_type || '.create';
    v_resource_id := NEW.id;
    v_new_values := to_jsonb(NEW);
    v_old_values := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := v_resource_type || '.update';
    v_resource_id := NEW.id;
    v_old_values := to_jsonb(OLD);
    v_new_values := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN
    v_action := v_resource_type || '.delete';
    v_resource_id := OLD.id;
    v_old_values := to_jsonb(OLD);
    v_new_values := NULL;
  END IF;

  BEGIN
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
    ELSE
      v_org_id := NEW.organization_id;
    END IF;
  EXCEPTION WHEN undefined_column THEN
    v_org_id := NULL;
  END;

  INSERT INTO public.audit_logs (user_id, action, resource_type, resource_id, old_values, new_values, organization_id)
  VALUES (v_user_id, v_action, v_resource_type, v_resource_id, v_old_values, v_new_values, v_org_id);

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'audit_generic_changes failed for %: %', v_resource_type, SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."audit_generic_changes"() OWNER TO "postgres";


