CREATE OR REPLACE FUNCTION "public"."audit_reservation_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- ステータス変更をログ
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      PERFORM log_audit(
        'update_status',
        'reservation',
        NEW.id,
        jsonb_build_object('status', OLD.status),
        jsonb_build_object('status', NEW.status),
        jsonb_build_object(
          'customer_id', NEW.customer_id,
          'schedule_event_id', NEW.schedule_event_id
        )
      );
    END IF;
    
    -- 人数変更をログ
    IF OLD.participant_count IS DISTINCT FROM NEW.participant_count THEN
      PERFORM log_audit(
        'update_participant_count',
        'reservation',
        NEW.id,
        jsonb_build_object('participant_count', OLD.participant_count),
        jsonb_build_object('participant_count', NEW.participant_count),
        NULL
      );
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM log_audit(
      'delete',
      'reservation',
      OLD.id,
      jsonb_build_object(
        'status', OLD.status,
        'customer_id', OLD.customer_id,
        'schedule_event_id', OLD.schedule_event_id
      ),
      NULL,
      NULL
    );
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."audit_reservation_changes"() OWNER TO "postgres";


