CREATE OR REPLACE FUNCTION "public"."authenticate_guest_by_pin"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") RETURNS TABLE("member_id" "uuid", "guest_name" "text", "guest_email" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT result.member_id, result.guest_name, result.guest_email
 FROM public.authenticate_guest_by_pin_v2(p_group_id, p_email, p_pin) result
 WHERE NOT result.locked AND result.member_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."authenticate_guest_by_pin"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."authenticate_guest_by_pin"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") IS 'ゲストメンバーのPIN認証。PIIテーブルからaccess_pinを取得してメールアドレスとPINが一致するメンバー情報を返す';



CREATE OR REPLACE FUNCTION "public"."authenticate_guest_by_pin_v2"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") RETURNS TABLE("member_id" "uuid", "guest_name" "text", "guest_email" "text", "locked" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_member record;
  v_attempts integer;
  v_now timestamptz;
BEGIN
  IF p_group_id IS NULL OR p_email IS NULL OR length(p_email) > 320 OR p_pin IS NULL OR p_pin !~ '^[0-9]{4}$' THEN RETURN; END IF;
  SELECT pgm.id, pii.guest_name, pii.guest_email, pii.access_pin_hash,
         pii.failed_attempts, pii.locked_until
  INTO v_member
  FROM public.private_group_members pgm
  JOIN public.private_group_members_pii pii ON pii.member_id = pgm.id
  WHERE pgm.group_id = p_group_id AND pgm.user_id IS NULL
    AND lower(pii.guest_email) = lower(trim(p_email)) AND pgm.status = 'joined'
  ORDER BY pgm.id
  LIMIT 1 FOR UPDATE OF pii;
  IF NOT FOUND THEN RETURN; END IF;
  v_now := clock_timestamp();
  IF v_member.locked_until > v_now THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::text, true;
    RETURN;
  END IF;
  v_attempts := CASE WHEN v_member.locked_until IS NOT NULL THEN 0 ELSE v_member.failed_attempts END;
  IF v_member.access_pin_hash IS NOT NULL
     AND extensions.crypt(p_pin, v_member.access_pin_hash) = v_member.access_pin_hash THEN
    UPDATE public.private_group_members_pii pii SET failed_attempts = 0, locked_until = NULL,
      updated_at = v_now WHERE pii.member_id = v_member.id;
    RETURN QUERY SELECT v_member.id, v_member.guest_name, v_member.guest_email, false;
    RETURN;
  END IF;
  v_attempts := coalesce(v_attempts, 0) + 1;
  UPDATE public.private_group_members_pii pii SET failed_attempts = v_attempts,
    locked_until = CASE WHEN v_attempts >= 10 THEN v_now + interval '15 minutes' ELSE NULL END,
    updated_at = v_now WHERE pii.member_id = v_member.id;
  IF v_attempts >= 10 THEN RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::text, true; END IF;
END;
$_$;


ALTER FUNCTION "public"."authenticate_guest_by_pin_v2"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authenticate_guest_by_pin_v3"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") RETURNS TABLE("member_id" "uuid", "guest_name" "text", "guest_email" "text", "locked" boolean, "guest_token" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_result record;
BEGIN
 -- Match v2's deterministic member selection, but lock the member before its PII.
 -- Otherwise concurrent deletion can hold member -> wait PII while session FK waits member.
 PERFORM m.id FROM public.private_group_members m
 JOIN public.private_group_members_pii pii ON pii.member_id=m.id
 WHERE m.group_id=p_group_id AND m.user_id IS NULL AND m.status='joined'
 AND lower(pii.guest_email)=lower(trim(p_email))
 ORDER BY m.id LIMIT 1 FOR UPDATE OF m;
 FOR v_result IN SELECT * FROM public.authenticate_guest_by_pin_v2(p_group_id,p_email,p_pin) LOOP
  RETURN QUERY SELECT v_result.member_id,v_result.guest_name,v_result.guest_email,v_result.locked,
    CASE WHEN v_result.member_id IS NOT NULL AND NOT v_result.locked
      THEN public.issue_private_group_guest_session(v_result.member_id) ELSE NULL::text END;
 END LOOP;
END $$;


ALTER FUNCTION "public"."authenticate_guest_by_pin_v3"("p_group_id" "uuid", "p_email" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_private_group_read"("p_group_id" "uuid", "p_member_id" "uuid" DEFAULT NULL::"uuid", "p_guest_token" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text; actor_org uuid; group_org uuid; organizer uuid;
BEGIN
 SELECT organization_id,organizer_id INTO group_org,organizer FROM public.private_groups WHERE id=p_group_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'グループを閲覧できません' USING ERRCODE='42501'; END IF;
 IF actor IS NOT NULL THEN
  SELECT role::text,organization_id INTO actor_role,actor_org FROM public.users WHERE id=actor;
  IF actor_role='license_admin' THEN RETURN 'staff'; END IF;
  IF COALESCE(actor_role IN ('admin','staff') AND actor_org=group_org,false)
   AND NOT (EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org)
    AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org AND (status IS NULL OR status NOT IN ('inactive','resigned')))) THEN
   RETURN 'staff';
  END IF;
  IF organizer=actor THEN RETURN 'organizer'; END IF;
  IF EXISTS(SELECT 1 FROM public.private_group_members WHERE group_id=p_group_id AND user_id=actor AND status='joined') THEN RETURN 'member'; END IF;
 END IF;
 IF p_member_id IS NOT NULL THEN
  PERFORM public.require_private_group_member(p_group_id,p_member_id,p_guest_token);
  RETURN 'member';
 END IF;
 RAISE EXCEPTION 'グループを閲覧できません' USING ERRCODE='42501';
END $$;


ALTER FUNCTION "public"."authorize_private_group_read"("p_group_id" "uuid", "p_member_id" "uuid", "p_guest_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_booking_participation_fee"("p_base_fee" integer, "p_costs" "jsonb", "p_date" "date", "p_start_time" time without time zone, "p_custom_holiday" boolean DEFAULT false, "p_pricing_date" "date" DEFAULT ((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Tokyo'::"text"))::"date") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  slots TEXT[] := ARRAY[]::TEXT[];
  cost JSONB;
  holiday BOOLEAN := public.is_booking_calendar_holiday(p_date) OR COALESCE(p_custom_holiday,FALSE);
  fee INTEGER;
  pricing_date TEXT := p_pricing_date::TEXT;
BEGIN
  IF EXTRACT(DOW FROM p_date) IN (0,6) OR holiday THEN
    slots := array_append(slots,'weekend');
  END IF;
  IF holiday THEN slots := array_append(slots,'holiday'); END IF;
  IF p_start_time IS NOT NULL THEN
    slots := array_append(slots,CASE WHEN EXTRACT(HOUR FROM p_start_time)<12 THEN 'morning'
      WHEN EXTRACT(HOUR FROM p_start_time)<18 THEN 'afternoon' ELSE 'evening' END);
  END IF;
  slots := slots || ARRAY['normal','通常'];
  IF jsonb_typeof(p_costs)='array' THEN
    SELECT entry INTO cost
    FROM jsonb_array_elements(p_costs) WITH ORDINALITY AS c(entry,ordinal)
    WHERE COALESCE(entry->>'status','active') IN ('active','ready')
      AND (NULLIF(entry->>'startDate','') IS NULL OR entry->>'startDate' <= pricing_date)
      AND (NULLIF(entry->>'endDate','') IS NULL OR entry->>'endDate' >= pricing_date)
      AND entry->>'time_slot'=ANY(slots)
    ORDER BY array_position(slots,entry->>'time_slot'),ordinal LIMIT 1;
  END IF;
  IF cost IS NULL THEN fee := p_base_fee;
  ELSIF cost->>'type'='percentage' THEN
    fee := ROUND(p_base_fee*(1+COALESCE((cost->>'amount')::NUMERIC,0)/100))::INTEGER;
  ELSE fee := (cost->>'amount')::INTEGER;
  END IF;
  IF fee IS NULL THEN
    RAISE EXCEPTION 'SCENARIO_FEE_NOT_FOUND' USING ERRCODE='P0017';
  END IF;
  RETURN fee;
END;
$$;


ALTER FUNCTION "public"."calculate_booking_participation_fee"("p_base_fee" integer, "p_costs" "jsonb", "p_date" "date", "p_start_time" time without time zone, "p_custom_holiday" boolean, "p_pricing_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_cancellation_fee"("p_reservation_id" "uuid") RETURNS TABLE("fee_amount" integer, "fee_percentage" integer, "hours_until_event" numeric, "is_private_booking" boolean, "policy_description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "TimeZone" TO 'Asia/Tokyo'
    AS $$
DECLARE
  v_reservation RECORD;
  v_event RECORD;
  v_settings RECORD;
  v_cancellation_fees JSONB;
  v_hours_until NUMERIC;
  v_fee_percentage INTEGER := 0;
  v_fee_amount INTEGER := 0;
  v_description TEXT := '';
  v_fee RECORD;
  v_uid UUID;
  v_is_org_staff BOOLEAN := false;
  v_is_customer BOOLEAN := false;
BEGIN
  v_uid := auth.uid();

  -- 予約情報を取得
  SELECT r.*, r.is_private_booking as is_private
  INTO v_reservation
  FROM reservations r
  WHERE r.id = p_reservation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION '予約が見つかりません: %', p_reservation_id;
  END IF;

  -- 権限チェック（クロステナント防止）
  IF is_org_admin() THEN
    NULL;
  ELSE
    -- 1) 顧客本人か？
    IF v_uid IS NOT NULL AND v_reservation.customer_id IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1
        FROM customers c
        WHERE c.id = v_reservation.customer_id
          AND c.user_id = v_uid
      )
      INTO v_is_customer;
    END IF;

    -- 2) 自組織スタッフか？
    IF v_uid IS NOT NULL AND v_reservation.organization_id IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1
        FROM staff s
        WHERE s.user_id = v_uid
          AND s.status = 'active'
          AND s.organization_id = v_reservation.organization_id
      )
      INTO v_is_org_staff;
    END IF;

    IF NOT (v_is_customer OR v_is_org_staff) THEN
      RAISE EXCEPTION 'FORBIDDEN_ORG' USING ERRCODE = 'P0010';
    END IF;
  END IF;

  -- イベント情報を取得
  SELECT se.*
  INTO v_event
  FROM schedule_events se
  WHERE se.id = v_reservation.schedule_event_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'イベントが見つかりません';
  END IF;

  -- 公演開始までの時間を計算（JST明示: date + time を +09:00 として解釈）
  v_hours_until := EXTRACT(EPOCH FROM (
    (v_event.date::text || ' ' || v_event.start_time::text || '+09:00')::timestamptz - NOW()
  )) / 3600;

  -- 店舗設定を取得
  SELECT rs.*
  INTO v_settings
  FROM reservation_settings rs
  WHERE rs.store_id = v_event.store_id;

  -- 予約タイプに応じたキャンセル料設定を選択
  IF v_reservation.is_private THEN
    v_cancellation_fees := COALESCE(
      NULLIF(v_settings.private_booking_cancellation_fees, '[]'::JSONB),
      v_settings.cancellation_fees,
      '[{"hours_before": 168, "fee_percentage": 50}, {"hours_before": 72, "fee_percentage": 100}]'::JSONB
    );
  ELSE
    v_cancellation_fees := COALESCE(
      v_settings.cancellation_fees,
      '[{"hours_before": 24, "fee_percentage": 50}, {"hours_before": 0, "fee_percentage": 100}]'::JSONB
    );
  END IF;

  -- 該当するキャンセル料率を検索（hours_before が大きい順にチェック）
  FOR v_fee IN
    SELECT * FROM jsonb_to_recordset(v_cancellation_fees)
    AS x(hours_before INTEGER, fee_percentage INTEGER, description TEXT)
    ORDER BY hours_before DESC
  LOOP
    IF v_hours_until <= v_fee.hours_before THEN
      v_fee_percentage := v_fee.fee_percentage;
      v_description := COALESCE(v_fee.description, v_fee_percentage || '%');
    END IF;
  END LOOP;

  -- キャンセル料金額を計算
  v_fee_amount := ROUND((COALESCE(v_reservation.total_price, 0) * v_fee_percentage) / 100);

  RETURN QUERY SELECT
    v_fee_amount,
    v_fee_percentage,
    v_hours_until,
    v_reservation.is_private,
    v_description;
END;
$$;


ALTER FUNCTION "public"."calculate_cancellation_fee"("p_reservation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_cancellation_fee"("p_reservation_id" "uuid") IS '予約IDからキャンセル料を計算（マルチテナント: 顧客本人/自組織スタッフ/管理者のみ）。JST明示で時間計算。';



CREATE OR REPLACE FUNCTION "public"."calculate_gm_wage"("duration_minutes" integer, "wage_settings" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  wage_type TEXT;
  rounded_minutes INT;
  half_hour_units INT;
  first_rate INT;
  threshold_minutes INT;
  threshold_units INT;
  after_rate INT;
  first_part INT;
  additional_units INT;
  additional_part INT;
BEGIN
  wage_type := wage_settings->>'wage_type';
  
  -- 固定報酬の場合はgm_costsを使用（この関数では計算しない）
  IF wage_type = 'fixed' THEN
    RETURN NULL;
  END IF;
  
  -- 時給制の計算
  first_rate := (wage_settings->>'first_rate_per_30min')::INT;
  threshold_minutes := (wage_settings->>'first_threshold_minutes')::INT;
  after_rate := (wage_settings->>'after_rate_per_30min')::INT;
  
  -- 30分単位に切り上げ
  rounded_minutes := CEIL(duration_minutes / 30.0) * 30;
  half_hour_units := rounded_minutes / 30;
  threshold_units := threshold_minutes / 30;
  
  IF half_hour_units <= threshold_units THEN
    -- 閾値以内
    RETURN first_rate * half_hour_units;
  ELSE
    -- 閾値超過
    first_part := first_rate * threshold_units;
    additional_units := half_hour_units - threshold_units;
    additional_part := after_rate * additional_units;
    RETURN first_part + additional_part;
  END IF;
END;
$$;


ALTER FUNCTION "public"."calculate_gm_wage"("duration_minutes" integer, "wage_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_hourly_wage"("duration_minutes" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  rounded_minutes INT;
  half_hour_units INT;
  first_rate INT := 875;   -- 30分あたり875円
  after_rate INT := 500;    -- 5時間超: 30分あたり500円
  threshold_units INT := 10; -- 5時間 = 10単位
BEGIN
  -- 30分単位に切り上げ
  rounded_minutes := CEIL(duration_minutes / 30.0) * 30;
  half_hour_units := rounded_minutes / 30;
  
  IF half_hour_units <= threshold_units THEN
    -- 5時間以内
    RETURN first_rate * half_hour_units;
  ELSE
    -- 5時間超
    RETURN (first_rate * threshold_units) + (after_rate * (half_hour_units - threshold_units));
  END IF;
END;
$$;


ALTER FUNCTION "public"."calculate_hourly_wage"("duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_use_coupon_reservation"("p_customer" "uuid", "p_reservation" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.reservations r JOIN public.customers c ON c.id=p_customer
  WHERE r.id=p_reservation AND (r.customer_id=c.id OR EXISTS(
   SELECT 1 FROM public.private_groups g JOIN public.private_group_members m ON m.group_id=g.id
   WHERE g.reservation_id=r.id AND g.organization_id=r.organization_id AND m.user_id=c.user_id AND m.status='joined'
  ) OR EXISTS(
   SELECT 1 FROM public.staff st WHERE st.user_id=c.user_id AND st.organization_id=r.organization_id AND st.status='active'
    AND r.payment_method='staff' AND st.name=ANY(r.participant_names)
  )));
$$;


ALTER FUNCTION "public"."can_use_coupon_reservation"("p_customer" "uuid", "p_reservation" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_event_reservations"("p_event_id" "uuid", "p_reason" "text" DEFAULT '公演中止'::"text") RETURNS TABLE("cancelled_count" integer, "reservation_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cancelled_count INTEGER := 0;
  v_reservation_ids UUID[];
  v_event_org_id UUID;
BEGIN
  SELECT organization_id INTO v_event_org_id
  FROM schedule_events WHERE id = p_event_id;
  
  IF v_event_org_id IS NULL THEN
    RAISE EXCEPTION 'イベントが見つかりません: %', p_event_id;
  END IF;
  
  IF NOT (
    is_org_admin() OR 
    EXISTS (
      SELECT 1 FROM staff 
      WHERE user_id = auth.uid() 
        AND organization_id = v_event_org_id 
        AND status = 'active'
    )
  ) THEN
    RAISE EXCEPTION '権限がありません';
  END IF;
  
  SELECT ARRAY_AGG(id) INTO v_reservation_ids
  FROM reservations
  WHERE schedule_event_id = p_event_id
    AND status IN ('pending', 'confirmed', 'gm_confirmed')
    AND (is_cancelled = false OR is_cancelled IS NULL);
  
  IF v_reservation_ids IS NULL OR array_length(v_reservation_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0, ARRAY[]::UUID[];
    RETURN;
  END IF;
  
  UPDATE reservations
  SET status = 'cancelled', is_cancelled = true, cancelled_at = NOW(),
      cancellation_reason = p_reason, updated_at = NOW()
  WHERE id = ANY(v_reservation_ids);
  
  GET DIAGNOSTICS v_cancelled_count = ROW_COUNT;
  
  UPDATE schedule_events
  SET current_participants = 0, updated_at = NOW()
  WHERE id = p_event_id;
  
  RETURN QUERY SELECT v_cancelled_count, v_reservation_ids;
END;
$$;


ALTER FUNCTION "public"."cancel_event_reservations"("p_event_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_reservation_and_group_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_reservation RECORD;
  v_event_id UUID;
  v_caller_org_id UUID;
  v_actual_participants INTEGER;
  v_group RECORD;
  v_event_is_cancelled BOOLEAN;
  v_event_exists BOOLEAN := FALSE;
BEGIN
  -- 予約をロック（cancel_reservation_with_lock と同じ認可チェック）
  SELECT id, schedule_event_id, status, customer_id, organization_id, private_group_id
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND status != 'cancelled'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0005';
  END IF;

  v_event_id := v_reservation.schedule_event_id;

  -- 組織境界チェック
  v_caller_org_id := get_user_organization_id();

  IF NOT (
    -- 自分の予約（顧客として — customer_id で照合）
    EXISTS (
      SELECT 1 FROM public.customers c
      WHERE c.id = v_reservation.customer_id
        AND c.user_id = auth.uid()
    )
    OR (
      -- 同組織の admin
      is_org_admin()
      AND (v_caller_org_id IS NOT DISTINCT FROM v_reservation.organization_id)
    )
    OR (
      -- スタッフ権限
      EXISTS (
        SELECT 1 FROM staff
        WHERE user_id = auth.uid()
          AND organization_id = v_reservation.organization_id
          AND status = 'active'
      )
    )
  ) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'P0009';
  END IF;

  -- 逆順でグループをロックする申込処理と競合した場合は待たずに再試行する。
  IF v_reservation.private_group_id IS NOT NULL THEN
    SELECT * INTO v_group FROM public.private_groups
    WHERE id = v_reservation.private_group_id
      AND organization_id = v_reservation.organization_id
    FOR UPDATE NOWAIT;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
    END IF;
    IF v_group.reservation_id IS DISTINCT FROM v_reservation.id THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_RESERVATION_MISMATCH' USING ERRCODE='P0051';
    END IF;
  END IF;

  IF v_event_id IS NOT NULL THEN
    SELECT is_cancelled INTO v_event_is_cancelled FROM public.schedule_events
    WHERE id=v_event_id FOR UPDATE NOWAIT;
    v_event_exists := FOUND;
  END IF;

  PERFORM public.assert_customer_cancellation_policy(p_reservation_id);

  -- 予約ステータスを更新
  UPDATE public.reservations
  SET status = 'cancelled',
      cancelled_at = NOW(),
      cancellation_reason = p_cancellation_reason,
      updated_at = NOW()
  WHERE id = p_reservation_id;

  -- 中止公演の人数は保持し、来場済みも有効人数として数える。
  IF v_event_exists AND v_event_is_cancelled IS NOT TRUE THEN
    SELECT COALESCE(SUM(participant_count), 0) INTO v_actual_participants
    FROM public.reservations WHERE schedule_event_id=v_event_id
      AND status IN ('pending','confirmed','gm_confirmed','checked_in');
    UPDATE public.schedule_events
    SET current_participants=v_actual_participants,updated_at=NOW()
    WHERE id=v_event_id;
  END IF;

  -- 貸切グループが紐づいている場合、同一トランザクションでキャンセル
  IF v_reservation.private_group_id IS NOT NULL THEN
    UPDATE public.private_groups
    SET status = 'cancelled',
        updated_at = NOW()
    WHERE id = v_reservation.private_group_id
      AND organization_id = v_reservation.organization_id
      AND reservation_id = v_reservation.id
      AND status != 'cancelled';
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."cancel_reservation_and_group_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_reservation_and_group_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text") IS '通常キャンセル専用。予約キャンセル・在庫返却・貸切グループのキャンセルを1トランザクションで実行。
却下フロー（mark_private_group_rejected_after_booking_rejection）では使用しないこと。';



CREATE OR REPLACE FUNCTION "public"."cancel_reservation_and_group_with_notice"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE r record; title text; body text;
BEGIN
 PERFORM public.cancel_reservation_and_group_with_lock(p_reservation_id,p_customer_id,p_cancellation_reason);
 SELECT * INTO STRICT r FROM reservations WHERE id=p_reservation_id;
 IF r.private_group_id IS NOT NULL THEN
   SELECT system_msg_booking_cancelled_title,system_msg_booking_cancelled_body INTO title,body
   FROM global_settings WHERE organization_id=r.organization_id;
   INSERT INTO private_group_messages(group_id,sender_type,message) VALUES(r.private_group_id,'system',
     jsonb_build_object('type','system','action','booking_cancelled','reservationId',r.id,
       'title',coalesce(nullif(title,''),'ご予約がキャンセルされました'),
       'body',coalesce(nullif(body,''),nullif(p_cancellation_reason,''),'誠に申し訳ございませんが、やむを得ない事情によりご予約がキャンセルとなりました。'))::text);
 END IF;
 RETURN TRUE;
END $$;


ALTER FUNCTION "public"."cancel_reservation_and_group_with_notice"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_cancellation_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
BEGIN
  RETURN public.cancel_reservation_with_lock(p_reservation_id, NULL::uuid, p_cancellation_reason);
END;
$$;


ALTER FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_cancellation_reason" "text") IS '予約をキャンセル（2パラメーター版）。公演が中止済みの場合は current_participants を更新しない（中止前の人数を保持）。再集計は checked_in を含む。';



CREATE OR REPLACE FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_reservation RECORD;
  v_event_id UUID;
  v_caller_org_id UUID;
  v_actual_participants INTEGER;
  v_event_is_cancelled BOOLEAN;
  v_event_exists BOOLEAN := FALSE;
BEGIN
  -- 予約をロック
  SELECT id, schedule_event_id, status, customer_id, organization_id
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND status != 'cancelled'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0005';
  END IF;

  v_event_id := v_reservation.schedule_event_id;

  -- 組織境界チェック
  v_caller_org_id := get_user_organization_id();

  IF auth.uid() IS NULL OR NOT COALESCE((
    (
      -- 同組織の admin
      is_org_admin()
      AND (v_caller_org_id IS NOT DISTINCT FROM v_reservation.organization_id)
    )
    OR (
      -- スタッフ権限
      EXISTS (
        SELECT 1 FROM staff
        WHERE user_id = auth.uid()
          AND organization_id = v_reservation.organization_id
          AND status = 'active'
      )
    )
  ), false) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'P0009';
  END IF;

  IF v_event_id IS NOT NULL THEN
    SELECT is_cancelled INTO v_event_is_cancelled FROM public.schedule_events
    WHERE id = v_event_id FOR UPDATE NOWAIT;
    v_event_exists := FOUND;
  END IF;

  -- ステータスを更新
  UPDATE public.reservations
  SET status = 'cancelled',
      cancelled_at = NOW(),
      cancellation_reason = p_cancellation_reason,
      updated_at = NOW()
  WHERE id = p_reservation_id;

  -- NULLの旧公演も通常集計し、中止公演の人数は保持する。
  IF v_event_exists AND v_event_is_cancelled IS NOT TRUE THEN
    SELECT COALESCE(SUM(participant_count), 0)
    INTO v_actual_participants
    FROM reservations
    WHERE schedule_event_id = v_event_id
      AND status IN ('pending', 'confirmed', 'gm_confirmed', 'checked_in');

    UPDATE schedule_events
    SET current_participants = v_actual_participants,
        updated_at = NOW()
    WHERE id = v_event_id;
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_reservation_with_lock"("p_reservation_id" "uuid", "p_customer_id" "uuid", "p_cancellation_reason" "text") IS '予約をキャンセル（3パラメーター版）。公演が中止済みの場合は current_participants を更新しない（中止前の人数を保持）。再集計は checked_in を含む。';



CREATE OR REPLACE FUNCTION "public"."cancel_unrequested_private_group"("p_group_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g public.private_groups%ROWTYPE; r record;
BEGIN
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR g.organizer_id IS DISTINCT FROM auth.uid() THEN
   RAISE EXCEPTION 'このグループをキャンセルする権限がありません' USING ERRCODE='42501';
 END IF;
 IF g.status NOT IN ('gathering','date_adjusting','cancelled') OR g.status IS NULL THEN
   RAISE EXCEPTION '予約申込済みのため、グループだけをキャンセルできません。予約の取消手続きを行ってください。' USING ERRCODE='22023';
 END IF;
 -- group-first の申込と直列化。reservation-first の承認・取消とは待ち合わない。
 FOR r IN SELECT id,status,organization_id,private_group_id FROM public.reservations
   WHERE id=g.reservation_id OR private_group_id=g.id FOR SHARE NOWAIT
 LOOP
   IF r.organization_id IS DISTINCT FROM g.organization_id OR r.private_group_id IS DISTINCT FROM g.id THEN
     RAISE EXCEPTION '予約とグループの紐づきを確認できません。店舗へお問い合わせください。' USING ERRCODE='P0051';
   END IF;
   IF r.status IS DISTINCT FROM 'cancelled' THEN
     RAISE EXCEPTION '有効な予約があるため、グループだけをキャンセルできません。予約の取消手続きを行ってください。' USING ERRCODE='22023';
   END IF;
 END LOOP;
 IF g.reservation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.reservations WHERE id=g.reservation_id) THEN
   RAISE EXCEPTION '紐づく予約を確認できません。店舗へお問い合わせください。' USING ERRCODE='P0051';
 END IF;
 UPDATE public.private_groups SET status='cancelled',updated_at=now() WHERE id=g.id AND status!='cancelled';
 RETURN true;
END $$;


ALTER FUNCTION "public"."cancel_unrequested_private_group"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_reservation_schedule"("p_reservation_id" "uuid", "p_new_schedule_event_id" "uuid", "p_customer_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_event_id UUID;
  v_participant_count INTEGER;
  v_new_max_participants INTEGER;
  v_new_current_participants INTEGER;
  v_org_id UUID;
  v_reservation_customer_id UUID;
  v_new_store_id UUID;
  v_new_date DATE;
  v_new_start_time TIME;
  v_auth_customer_id UUID;
  v_is_cancelled BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0011';
  END IF;

  -- 🔒 既存予約をロック
  SELECT schedule_event_id, participant_count, organization_id, customer_id
  INTO v_old_event_id, v_participant_count, v_org_id, v_reservation_customer_id
  FROM reservations
  WHERE id = p_reservation_id
    AND status != 'cancelled'
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0007';
  END IF;
  
  -- reservation_actor_auth_v1: 旧引数は対象の照合用。
  IF p_customer_id IS NOT NULL
     AND v_reservation_customer_id IS DISTINCT FROM p_customer_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0010';
  END IF;
  -- 旧日程変更の業務権限（管理者）を維持し、対象組織と利用状態を追加確認。
  IF NOT EXISTS (
       SELECT 1 FROM public.customers
       WHERE id = v_reservation_customer_id AND user_id = auth.uid()
     ) AND NOT (
       COALESCE(public.reservation_actor_is_org_operator(v_org_id), false)
       AND public.is_org_admin()
     ) THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0010';
  END IF;

  -- 同じイベントへの変更は無視
  IF v_old_event_id = p_new_schedule_event_id THEN
    RETURN TRUE;
  END IF;
  
  -- 🔒 新旧両方のイベントをロック（デッドロック回避のためID順）
  IF v_old_event_id < p_new_schedule_event_id THEN
    PERFORM 1 FROM schedule_events WHERE id = v_old_event_id FOR UPDATE;
    PERFORM 1 FROM schedule_events WHERE id = p_new_schedule_event_id FOR UPDATE;
  ELSE
    PERFORM 1 FROM schedule_events WHERE id = p_new_schedule_event_id FOR UPDATE;
    PERFORM 1 FROM schedule_events WHERE id = v_old_event_id FOR UPDATE;
  END IF;
  
  -- 新イベントの情報と空席確認
  SELECT 
    COALESCE(max_participants, capacity, 8), 
    current_participants,
    store_id,
    date,
    start_time,
    is_cancelled
  INTO 
    v_new_max_participants, 
    v_new_current_participants,
    v_new_store_id,
    v_new_date,
    v_new_start_time,
    v_is_cancelled
  FROM schedule_events
  WHERE id = p_new_schedule_event_id
    AND organization_id = v_org_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NEW_EVENT_NOT_FOUND: 新しい公演が見つかりません' USING ERRCODE = 'P0020';
  END IF;
  
  IF v_is_cancelled THEN
    RAISE EXCEPTION 'EVENT_CANCELLED: この公演はキャンセルされています' USING ERRCODE = 'P0022';
  END IF;
  
  IF (v_new_current_participants + v_participant_count) > v_new_max_participants THEN
    RAISE EXCEPTION 'INSUFFICIENT_SEATS_IN_NEW_EVENT: 新しい公演の空席が不足しています' USING ERRCODE = 'P0021';
  END IF;
  
  -- ✅ 旧イベントから在庫を返却
  UPDATE schedule_events
  SET current_participants = GREATEST(current_participants - v_participant_count, 0)
  WHERE id = v_old_event_id;
  
  -- ✅ 新イベントで在庫を確保
  UPDATE schedule_events
  SET current_participants = current_participants + v_participant_count
  WHERE id = p_new_schedule_event_id;
  
  -- ✅ 予約を更新
  UPDATE reservations
  SET 
    schedule_event_id = p_new_schedule_event_id,
    store_id = v_new_store_id,
    requested_datetime = (v_new_date + v_new_start_time)::TIMESTAMPTZ,
    updated_at = NOW()
  WHERE id = p_reservation_id;
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."change_reservation_schedule"("p_reservation_id" "uuid", "p_new_schedule_event_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."change_reservation_schedule"("p_reservation_id" "uuid", "p_new_schedule_event_id" "uuid", "p_customer_id" "uuid") IS '予約の日程を変更（在庫をアトミックに調整）。
🔒 セキュリティ: auth.uid()から顧客を特定し、本人またはスタッフ/管理者のみ許可。
p_customer_idは互換性のため残すが内部では使用しない。';



CREATE OR REPLACE FUNCTION "public"."check_and_fix_inventory_consistency"() RETURNS TABLE("total_checked" integer, "inconsistencies_found" integer, "auto_fixed" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_checked INTEGER := 0;
  v_inconsistencies_found INTEGER := 0;
  v_auto_fixed INTEGER := 0;
  v_details JSONB := '[]'::JSONB;
  v_event_record RECORD;
  v_actual_count INTEGER;
  v_stored_count INTEGER;
  v_difference INTEGER;
  v_max_capacity INTEGER;
  v_corrected_count INTEGER;
BEGIN
  FOR v_event_record IN
    SELECT 
      se.id,
      se.date,
      se.start_time,
      se.current_participants,
      se.max_participants,
      se.capacity,
      se.organization_id,
      s.title as scenario_title,
      st.name as store_name
    FROM schedule_events se
    LEFT JOIN scenarios s ON se.scenario_id = s.id
    LEFT JOIN stores st ON se.store_id = st.id
    WHERE se.date >= CURRENT_DATE - INTERVAL '30 days'
      AND se.date <= CURRENT_DATE + INTERVAL '90 days'
      AND se.is_cancelled = false
    ORDER BY se.date DESC
  LOOP
    v_total_checked := v_total_checked + 1;
    
    SELECT COALESCE(SUM(participant_count), 0)
    INTO v_actual_count
    FROM reservations
    WHERE schedule_event_id = v_event_record.id
      AND status IN ('pending', 'confirmed', 'gm_confirmed');
    
    v_stored_count := COALESCE(v_event_record.current_participants, 0);
    v_difference := v_stored_count - v_actual_count;
    
    v_max_capacity := COALESCE(v_event_record.max_participants, v_event_record.capacity);
    v_corrected_count := LEAST(v_actual_count, v_max_capacity);
    
    IF v_difference <> 0 THEN
      v_inconsistencies_found := v_inconsistencies_found + 1;
      
      v_details := v_details || jsonb_build_object(
        'event_id', v_event_record.id,
        'date', v_event_record.date,
        'start_time', v_event_record.start_time,
        'scenario_title', v_event_record.scenario_title,
        'store_name', v_event_record.store_name,
        'stored_count', v_stored_count,
        'actual_count', v_actual_count,
        'corrected_count', v_corrected_count,
        'max_capacity', v_max_capacity,
        'difference', v_difference,
        'is_overbooked', v_actual_count > v_max_capacity,
        'organization_id', v_event_record.organization_id
      );
      
      UPDATE schedule_events
      SET current_participants = v_corrected_count,
          updated_at = NOW()
      WHERE id = v_event_record.id;
      
      v_auto_fixed := v_auto_fixed + 1;
      
      IF v_actual_count > v_max_capacity THEN
        RAISE NOTICE 'オーバーブッキング検出: event_id=%, actual=%, max=%, corrected=%',
          v_event_record.id, v_actual_count, v_max_capacity, v_corrected_count;
      ELSE
        RAISE NOTICE '不整合を修正: event_id=%, stored=%, actual=%, diff=%',
          v_event_record.id, v_stored_count, v_actual_count, v_difference;
      END IF;
    END IF;
  END LOOP;
  
  RETURN QUERY SELECT 
    v_total_checked,
    v_inconsistencies_found,
    v_auto_fixed,
    v_details;
END;
$$;


ALTER FUNCTION "public"."check_and_fix_inventory_consistency"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_fix_inventory_consistency"() IS '在庫整合性をチェックし、不整合があれば自動修正する関数。
過去30日から未来90日の非キャンセル公演を対象とする。
ステータス条件: pending, confirmed, gm_confirmed（他RPC関数と統一）
定員チェック・オーバーブッキング検出機能付き。';



CREATE OR REPLACE FUNCTION "public"."check_and_fix_inventory_consistency"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("total_checked" integer, "inconsistencies_found" integer, "auto_fixed" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_checked INTEGER := 0;
  v_inconsistencies_found INTEGER := 0;
  v_auto_fixed INTEGER := 0;
  v_details JSONB := '[]'::JSONB;
  v_event_record RECORD;
  v_actual_count INTEGER;
  v_stored_count INTEGER;
  v_difference INTEGER;
  v_max_capacity INTEGER;
  v_corrected_count INTEGER;
  v_is_service_role BOOLEAN := (COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role');
  v_is_admin BOOLEAN := is_org_admin();
  v_can_cross_tenant BOOLEAN := FALSE;
BEGIN
  v_can_cross_tenant := v_is_service_role OR v_is_admin;

  -- 🔒 認可: admin/service_role 以外は organization_id 必須 + メンバーのみ
  IF NOT v_can_cross_tenant THEN
    IF p_organization_id IS NULL THEN
      RAISE EXCEPTION 'organization_id_required' USING ERRCODE = 'P0001';
    END IF;
    IF NOT is_organization_member(p_organization_id) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  -- 対象: 過去30日〜未来90日（非キャンセル）
  FOR v_event_record IN
    SELECT 
      se.id,
      se.date,
      se.start_time,
      se.current_participants,
      se.max_participants,
      se.capacity,
      se.organization_id,
      s.title as scenario_title,
      st.name as store_name
    FROM schedule_events se
    LEFT JOIN scenarios s ON se.scenario_id = s.id
    LEFT JOIN stores st ON se.store_id = st.id
    WHERE se.date >= CURRENT_DATE - INTERVAL '30 days'
      AND se.date <= CURRENT_DATE + INTERVAL '90 days'
      AND se.is_cancelled = false
      AND (
        p_organization_id IS NULL
        OR se.organization_id = p_organization_id
      )
    ORDER BY se.date DESC
  LOOP
    v_total_checked := v_total_checked + 1;

    -- 実際の予約数（他RPCと同条件）
    SELECT COALESCE(SUM(participant_count), 0)
    INTO v_actual_count
    FROM reservations
    WHERE schedule_event_id = v_event_record.id
      AND status IN ('pending', 'confirmed', 'gm_confirmed');

    v_stored_count := COALESCE(v_event_record.current_participants, 0);
    v_difference := v_stored_count - v_actual_count;

    v_max_capacity := COALESCE(v_event_record.max_participants, v_event_record.capacity);
    v_corrected_count := LEAST(v_actual_count, v_max_capacity);

    IF v_difference <> 0 THEN
      v_inconsistencies_found := v_inconsistencies_found + 1;

      v_details := v_details || jsonb_build_array(
        jsonb_build_object(
          'event_id', v_event_record.id,
          'date', v_event_record.date,
          'start_time', v_event_record.start_time,
          'scenario_title', v_event_record.scenario_title,
          'store_name', v_event_record.store_name,
          'stored_count', v_stored_count,
          'actual_count', v_actual_count,
          'corrected_count', v_corrected_count,
          'max_capacity', v_max_capacity,
          'difference', v_difference,
          'is_overbooked', v_actual_count > v_max_capacity,
          'organization_id', CASE WHEN v_can_cross_tenant THEN v_event_record.organization_id ELSE NULL END
        )
      );

      UPDATE schedule_events
      SET current_participants = v_corrected_count,
          updated_at = NOW()
      WHERE id = v_event_record.id;

      v_auto_fixed := v_auto_fixed + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_total_checked, v_inconsistencies_found, v_auto_fixed, v_details;
END;
$$;


ALTER FUNCTION "public"."check_and_fix_inventory_consistency"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_fix_inventory_consistency"("p_organization_id" "uuid") IS '在庫整合性をチェックし、不整合があれば自動修正する。
一般呼び出しは p_organization_id 必須（自組織のみ）。
admin/service_role は p_organization_id NULL で全組織対象。';



CREATE OR REPLACE FUNCTION "public"."check_email_registered"("p_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  needle TEXT := lower(trim(p_email));
BEGIN
  IF needle IS NULL OR needle = '' THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.customers c
    WHERE c.email IS NOT NULL AND lower(c.email) = needle
    LIMIT 1
  )
  OR EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.email IS NOT NULL AND lower(u.email) = needle
    LIMIT 1
  );
END;
$$;


ALTER FUNCTION "public"."check_email_registered"("p_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_email_registered"("p_email" "text") IS '新規登録ガード: メールが「顧客として Auth 済み」または public.users にあるか。user_id 未設定の顧客メールのみでは false（初回マジックリンク可）';



CREATE OR REPLACE FUNCTION "public"."check_email_registration_status"("p_email" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  needle TEXT := lower(trim(p_email));
  auth_user RECORD;
BEGIN
  IF needle IS NULL OR needle = '' THEN
    RETURN 'not_registered';
  END IF;

  -- auth.users をチェック
  SELECT id, email_confirmed_at
  INTO auth_user
  FROM auth.users
  WHERE lower(email) = needle
  LIMIT 1;

  IF auth_user.id IS NOT NULL THEN
    IF auth_user.email_confirmed_at IS NOT NULL THEN
      RETURN 'confirmed';
    ELSE
      RETURN 'pending_confirmation';
    END IF;
  END IF;

  -- public.users もチェック（スタッフ等）
  IF EXISTS (
    SELECT 1 FROM public.users WHERE lower(email) = needle LIMIT 1
  ) THEN
    RETURN 'confirmed';
  END IF;

  -- customers で user_id がある場合もチェック
  IF EXISTS (
    SELECT 1 FROM public.customers 
    WHERE lower(trim(email)) = needle AND user_id IS NOT NULL 
    LIMIT 1
  ) THEN
    RETURN 'confirmed';
  END IF;

  RETURN 'not_registered';
END;
$$;


ALTER FUNCTION "public"."check_email_registration_status"("p_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_email_registration_status"("p_email" "text") IS 'メール登録状態を返す: not_registered / pending_confirmation / confirmed';



CREATE OR REPLACE FUNCTION "public"."check_member_exists"("p_group_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_guest_email" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
