CREATE OR REPLACE FUNCTION "public"."claim_organization_as_admin"("p_org_id" "uuid", "p_admin_name" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT public.claim_organization_as_admin_v2(p_org_id,p_admin_name,NULL);
$$;


ALTER FUNCTION "public"."claim_organization_as_admin"("p_org_id" "uuid", "p_admin_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_organization_as_admin_v2"("p_org_id" "uuid", "p_admin_name" "text", "p_claim_token" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id   UUID := auth.uid();
  v_email     TEXT;
  v_org_slug  TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated: ログインが必要です';
  END IF;

  -- 組織の存在確認
  SELECT slug INTO v_org_slug
  FROM public.organizations
  WHERE id = p_org_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_not_found: 指定された組織が見つかりません';
  END IF;

  -- 既に別の組織に所属していないか確認
  IF EXISTS (
    SELECT 1 FROM public.users
    WHERE id = v_user_id
      AND organization_id IS NOT NULL
      AND organization_id != p_org_id
  ) THEN
    RAISE EXCEPTION 'already_in_org: このアカウントは既に別の組織に所属しています';
  END IF;

  -- メールアドレスを取得
  SELECT email INTO v_email FROM auth.users WHERE id = v_user_id;
  PERFORM public.consume_organization_signup_claim(p_org_id,p_claim_token,v_user_id,v_email);

  IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=v_user_id) THEN RAISE EXCEPTION 'アカウント情報が見つかりません' USING ERRCODE='42501'; END IF;
  -- users レコードを admin に昇格・組織紐付け
  UPDATE public.users
  SET
    role            = 'admin',
    organization_id = p_org_id,
    updated_at      = NOW()
  WHERE id = v_user_id;

  -- staff レコードを作成（未作成の場合のみ）
  INSERT INTO public.staff (
    name, email, user_id, organization_id,
    role, status, stores, ng_days,
    want_to_learn, available_scenarios, availability,
    experience, special_scenarios
  ) VALUES (
    COALESCE(NULLIF(trim(p_admin_name), ''), split_part(v_email, '@', 1)),
    v_email,
    v_user_id,
    p_org_id,
    ARRAY['管理者']::TEXT[],
    'active',
    '{}', '{}', '{}', '{}', '{}', 0, '{}'
  )
  ON CONFLICT (user_id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    role            = EXCLUDED.role,
    updated_at      = NOW();

  RETURN json_build_object(
    'org_id',   p_org_id,
    'org_slug', v_org_slug
  );
END;
$$;


ALTER FUNCTION "public"."claim_organization_as_admin_v2"("p_org_id" "uuid", "p_admin_name" "text", "p_claim_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_performance_confirmation_email"("p_schedule_event_id" "uuid", "p_to_email" "text", "p_organization_id" "uuid", "p_subject" "text", "p_body_html" "text", "p_body_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  -- 2-1. 送信前に放置された古い queued 行を failed に倒し、送信権を解放する。
  --      (Edge Function がクラッシュ/タイムアウトして sent/failed 更新に到達しなかったケース)
  UPDATE public.email_logs
     SET status = 'failed',
         error_message = COALESCE(error_message, 'stale queued claim released')
   WHERE email_type = 'performance_confirmation'
     AND schedule_event_id = p_schedule_event_id
     AND lower(to_email) = lower(p_to_email)
     AND status = 'queued'
     AND created_at < now() - interval '15 minutes';

  -- 2-2. queued を1行 INSERT して claim する。ユニーク制約に衝突したら
  --      別 run が送信権を保持済み(送信中 or 送信済み)なので NULL を返す。
  BEGIN
    INSERT INTO public.email_logs (
      organization_id, schedule_event_id, email_type,
      to_email, subject, body_html, body_text, provider, status
    ) VALUES (
      p_organization_id, p_schedule_event_id, 'performance_confirmation',
      p_to_email, p_subject, p_body_html, p_body_text, 'resend', 'queued'
    )
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      v_id := NULL;
  END;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."claim_performance_confirmation_email"("p_schedule_event_id" "uuid", "p_to_email" "text", "p_organization_id" "uuid", "p_subject" "text", "p_body_html" "text", "p_body_text" "text") OWNER TO "postgres";

