    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "recruitment_x_posts_kind_check" CHECK (("kind" = ANY (ARRAY['extension'::"text", 'confirmed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "recruitment_x_posts_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'sending'::"text", 'sent'::"text", 'failed'::"text", 'uncertain'::"text", 'expired'::"text"])))
);


