CREATE OR REPLACE FUNCTION "public"."claim_recruitment_x_posts"("p_org" "uuid") RETURNS SETOF "public"."recruitment_x_posts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 -- 通信結果不明の投稿は再投稿せず、運営へ照合を依頼する。
 UPDATE recruitment_x_posts SET status='uncertain',last_error='送信処理の結果が不明です。X上の投稿を確認してください。',updated_at=now() WHERE organization_id=p_org AND status='sending' AND lease_until<now();
 RETURN QUERY WITH candidates AS(SELECT j.id FROM recruitment_x_posts j JOIN performance_recruitment_policies p ON p.organization_id=j.organization_id
 WHERE j.organization_id=p_org AND p.x_enabled AND p.one_seat_enabled AND p.x_username='queens_waltz' AND j.status IN ('pending','failed') AND j.attempts<10 AND j.next_attempt_at<=now()
 ORDER BY j.created_at,j.kind='extension' DESC LIMIT 5 FOR UPDATE OF j SKIP LOCKED)
 UPDATE recruitment_x_posts j SET status='sending',attempts=attempts+1,lease_until=now()+interval '2 minutes',updated_at=now() FROM candidates c WHERE j.id=c.id RETURNING j.*;
END $$;


ALTER FUNCTION "public"."claim_recruitment_x_posts"("p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_scheduled_reminder"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_days_before" integer, "p_send_time" time without time zone) RETURNS TABLE("delivery_id" "uuid", "lease_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 IF p_days_before NOT BETWEEN 0 AND 365 OR p_days_before IS NULL OR p_send_time IS NULL THEN
  RAISE EXCEPTION 'invalid reminder schedule' USING ERRCODE='22023';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.reservations r JOIN public.schedule_events e ON e.id=r.schedule_event_id
   WHERE r.id=p_reservation_id AND r.organization_id=p_organization_id AND e.organization_id=p_organization_id
    AND e.id=p_event_id AND e.date=p_event_date AND COALESCE(e.is_cancelled,false)=false
    AND r.status IN ('confirmed','pending','gm_confirmed')) THEN
  RETURN;
 END IF;
 RETURN QUERY INSERT INTO public.scheduled_reminder_deliveries AS d
  (organization_id,reservation_id,schedule_event_id,event_date,days_before,send_time,status)
 VALUES(p_organization_id,p_reservation_id,p_event_id,p_event_date,p_days_before,p_send_time,'sending')
 ON CONFLICT(reservation_id,schedule_event_id,event_date,days_before,send_time) DO UPDATE
  SET status='sending',lease_token=gen_random_uuid(),attempted_at=now()
  WHERE (d.status='failed' OR (d.status='sending' AND d.attempted_at<now()-interval '15 minutes'))
    AND d.created_at>now()-interval '23 hours'
 RETURNING d.id,d.lease_token;
END;
$$;


ALTER FUNCTION "public"."claim_scheduled_reminder"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_days_before" integer, "p_send_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_discord_notification_queue"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  -- 7日以上前の完了済み・失敗済みエントリを削除
  DELETE FROM discord_notification_queue
  WHERE (status IN ('completed', 'failed') AND created_at < NOW() - INTERVAL '7 days')
     OR (status = 'pending' AND retry_count >= max_retries AND created_at < NOW() - INTERVAL '1 day');
  
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  
  -- 失敗扱いに更新
  UPDATE discord_notification_queue
  SET status = 'failed',
      updated_at = NOW()
  WHERE status = 'pending'
    AND retry_count >= max_retries;
  
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."cleanup_discord_notification_queue"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_discord_notification_queue"() IS '古いDiscord通知キューエントリを削除';



