CREATE OR REPLACE FUNCTION "public"."compensated_cancellation"("p_event_id" "uuid", "p_apply" boolean DEFAULT false, "p_expected" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT NULL::"text", "p_bodies" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE e public.schedule_events; c public.coupon_campaigns; v_org uuid; v_actor uuid:=auth.uid();
  v_start timestamptz; v_days integer; v_amount integer; v_count integer; v_rows jsonb;
  v_snapshot jsonb; item jsonb; v_result jsonb; v_token text; v_text text; v_exp timestamptz;
  v_store text; v_ids jsonb; v_quantity integer; v_campaigns uuid[];
BEGIN
  SELECT organization_id INTO v_org FROM public.users WHERE id=v_actor AND role IN ('admin','staff','license_admin');
  IF v_org IS NULL OR NOT (public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=v_actor AND organization_id=v_org AND status='active')) THEN
    RAISE EXCEPTION 'スタッフ権限を確認できません'; END IF;
  SELECT * INTO e FROM public.schedule_events WHERE id=p_event_id AND organization_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '公演を確認できません'; END IF;
  IF EXISTS(SELECT 1 FROM public.compensated_cancellations WHERE event_id=e.id AND organization_id=v_org) THEN
    SELECT jsonb_agg(reservation_id ORDER BY reservation_id) INTO v_ids FROM public.compensated_cancellation_notices WHERE event_id=e.id;
    RETURN jsonb_build_object('already_completed',true,'reservation_ids',v_ids);
  END IF;
  IF e.is_cancelled OR e.category NOT IN ('open','private') OR
    (e.scenario_id IS NULL AND e.scenario_master_id IS NULL AND e.organization_scenario_id IS NULL) THEN
    RAISE EXCEPTION '開催予定のマーダーミステリー公演を選択してください'; END IF;
  v_start:=coalesce(e.start_at,(e.date+e.start_time) AT TIME ZONE 'Asia/Tokyo');
  v_days:=(v_start AT TIME ZONE 'Asia/Tokyo')::date-(now() AT TIME ZONE 'Asia/Tokyo')::date;
  v_amount:=CASE WHEN v_days=0 AND v_start>=now() THEN CASE WHEN v_start-now()<=interval '2 hours' THEN 5000 ELSE 2000 END WHEN v_days=1 THEN 1000 END;
  IF v_amount IS NULL THEN RAISE EXCEPTION 'この時期の補償額は未確定です。個別に確認してください'; END IF;
  SELECT array_agg(id) INTO v_campaigns FROM public.coupon_campaigns
    WHERE organization_id=v_org AND is_active AND name LIKE '店舗都合中止のお詫び｜%'
      AND discount_type='fixed' AND discount_amount=v_amount AND coupon_expiry_months=6
      AND murder_mystery_only AND trigger_type='manual' AND max_uses_per_customer=1;
  IF cardinality(v_campaigns) IS DISTINCT FROM 1 THEN RAISE EXCEPTION '補償用クーポンを1種類に特定できません'; END IF;
  SELECT * INTO c FROM public.coupon_campaigns WHERE id=v_campaigns[1] FOR SHARE;
  PERFORM 1 FROM public.reservations WHERE schedule_event_id=e.id AND organization_id=v_org ORDER BY id FOR UPDATE;
  SELECT jsonb_agg(jsonb_build_object('id',r.id,'customer_id',r.customer_id,
    'name',coalesce(cu.name,r.customer_name),'email',coalesce(nullif(r.customer_email,''),cu.email),
    'quantity',r.participant_count,'status',r.status,'updated_at',r.updated_at,
    'reservation_number',r.reservation_number,'total_price',r.total_price,'user_id',cu.user_id) ORDER BY r.id)
  INTO v_rows FROM public.reservations r LEFT JOIN public.customers cu ON cu.id=r.customer_id
  WHERE r.schedule_event_id=e.id AND r.organization_id=v_org AND r.status<>'cancelled';
  IF v_rows IS NULL THEN RAISE EXCEPTION '参加予定の予約がありません'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(v_rows) LOOP
    IF item->>'status' NOT IN ('confirmed','gm_confirmed','checked_in') OR
      coalesce((item->>'quantity')::integer,0) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION '未確定の予約または人数を確認してください'; END IF;
    IF nullif(item->>'email','') IS NULL THEN RAISE EXCEPTION 'メールアドレス未登録の予約があります'; END IF;
    IF e.category='open' AND item->>'user_id' IS NULL THEN RAISE EXCEPTION '予約者のMMQアカウントを確認してください'; END IF;
    IF nullif(p_bodies->>(item->>'id'),'') IS NULL AND p_apply THEN RAISE EXCEPTION '全対象者のメール本文を確認してください'; END IF;
  END LOOP;
  v_snapshot:=jsonb_build_object('event_id',e.id,'category',e.category,'start',v_start,'event_updated_at',e.updated_at,
    'amount',v_amount,'campaign_id',c.id,'coupon_name',coalesce(c.display_name,c.name),'recipients',v_rows);
  IF NOT p_apply THEN RETURN jsonb_build_object('already_completed',false,'snapshot',v_snapshot); END IF;
  IF p_expected IS DISTINCT FROM v_snapshot THEN RAISE EXCEPTION '予約や補償額が変わりました。中止画面を開き直してください'; END IF;
  IF nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION '中止理由を入力してください'; END IF;
  SELECT name INTO v_store FROM public.stores WHERE id=e.store_id;
  INSERT INTO public.compensated_cancellations(event_id,organization_id,created_by,snapshot) VALUES(e.id,v_org,v_actor,v_snapshot);
  UPDATE public.schedule_events SET is_cancelled=true,cancelled_at=now(),cancellation_reason=p_reason,updated_at=now() WHERE id=e.id;
  FOR item IN SELECT value FROM jsonb_array_elements(v_rows) LOOP
    PERFORM public.cancel_reservation_with_lock((item->>'id')::uuid,(item->>'customer_id')::uuid,p_reason);
    IF e.category='private' THEN
      UPDATE public.private_groups SET status='cancelled',updated_at=now()
        WHERE id=(SELECT private_group_id FROM public.reservations WHERE id=(item->>'id')::uuid);
      v_token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
      INSERT INTO public.private_coupon_claim_links(organization_id,reservation_id,event_id,campaign_id,token,discount_amount,max_claims,created_by)
        VALUES(v_org,(item->>'id')::uuid,e.id,c.id,v_token,v_amount,(item->>'quantity')::integer,v_actor)
        RETURNING expires_at INTO v_exp;
      v_text:=format(E'■ お詫びクーポン\n%s\n参加予定のお客様1人につき1枚、各自のMMQアカウントでお受け取りください。\n受け取りURL：https://mmq.game/coupon-claim#%s\n受け取り期限：%s（発行から3か月）\nクーポンの有効期限：受け取った日から6か月。実際の期限は受け取り画面で確認できます。',coalesce(c.display_name,c.name),v_token,to_char(v_exp AT TIME ZONE 'Asia/Tokyo','YYYY/MM/DD HH24:MI'));
    ELSE
      v_result:=public.grant_representative_compensation(v_org,(item->>'id')::uuid,v_actor,false,NULL);
      v_result:=public.grant_representative_compensation(v_org,(item->>'id')::uuid,v_actor,true,v_result->'snapshot');
      v_text:=format(E'■ お詫びクーポン\n%s × %s枚を予約者様のアカウントへ付与しました。\n有効期限：%s（付与から6か月）\nマイページ：https://mmq.game/mypage',coalesce(c.display_name,c.name),item->>'quantity',to_char((v_result->>'expires_at')::timestamptz AT TIME ZONE 'Asia/Tokyo','YYYY/MM/DD HH24:MI'));
    END IF;
    v_text:=v_text||E'\n対象：マーダーミステリーの通常公演・貸切。作品制限はありません。ボードゲーム・箱開け会には利用できません。';
    INSERT INTO public.compensated_cancellation_notices(reservation_id,event_id,organization_id,compensation_text,payload)
    VALUES((item->>'id')::uuid,e.id,v_org,v_text,jsonb_build_object(
      'organizationId',v_org,'storeId',e.store_id,'reservationId',item->>'id','customerEmail',item->>'email',
      'customerName',item->>'name','scenarioTitle',e.scenario,'eventDate',e.date,'startTime',e.start_time,'endTime',e.end_time,
      'storeName',v_store,'participantCount',(item->>'quantity')::integer,'totalPrice',item->'total_price',
      'reservationNumber',item->>'reservation_number','cancelledBy','store','cancellationReason',p_reason,
      'customEmailBody',p_bodies->>(item->>'id')));
  END LOOP;
  SELECT jsonb_agg(reservation_id ORDER BY reservation_id) INTO v_ids FROM public.compensated_cancellation_notices WHERE event_id=e.id;
  RETURN jsonb_build_object('already_completed',false,'reservation_ids',v_ids);
END;
$$;


ALTER FUNCTION "public"."compensated_cancellation"("p_event_id" "uuid", "p_apply" boolean, "p_expected" "jsonb", "p_reason" "text", "p_bodies" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_private_approval_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE d public.private_booking_approval_deliveries%ROWTYPE; l public.email_logs%ROWTYPE;
BEGIN
 IF p_provider_id IS NULL OR length(btrim(p_provider_id))=0 OR p_sent_at IS NULL THEN
  RAISE EXCEPTION 'INVALID_DELIVERY_RECEIPT' USING ERRCODE='22023';
 END IF;
 SELECT * INTO d FROM public.private_booking_approval_deliveries WHERE id=p_delivery_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR d.status IS DISTINCT FROM 'sending' OR d.lease_token IS DISTINCT FROM p_lease_token OR p_lease_token IS NULL THEN
  RAISE EXCEPTION 'DELIVERY_LEASE_LOST' USING ERRCODE='40001';
 END IF;
 IF d.provider_payload IS NULL OR d.first_attempt_at IS NULL THEN
  RAISE EXCEPTION 'DELIVERY_NOT_STARTED' USING ERRCODE='22023';
 END IF;
 IF d.provider_message_id IS NOT NULL AND d.provider_message_id IS DISTINCT FROM p_provider_id THEN
  RAISE EXCEPTION 'DELIVERY_RECEIPT_CONFLICT' USING ERRCODE='22023';
 END IF;
 IF d.kind<>'gm_discord' THEN
  SELECT * INTO l FROM public.email_logs WHERE id=coalesce(d.email_log_id,d.id) FOR UPDATE NOWAIT;
  IF NOT FOUND OR l.organization_id IS DISTINCT FROM d.organization_id OR l.reservation_id IS DISTINCT FROM d.reservation_id
   OR l.to_email IS DISTINCT FROM (d.provider_payload->'to'->>0)
   OR l.subject IS DISTINCT FROM (d.provider_payload->>'subject')
   OR l.body_text IS DISTINCT FROM (d.provider_payload->>'text')
   OR l.body_html IS DISTINCT FROM (d.provider_payload->>'html')
   OR l.email_type IS DISTINCT FROM (CASE WHEN d.kind='confirmation_email' THEN 'reservation_confirmed' ELSE 'gm_notification' END)
   OR (l.provider_message_id IS NOT NULL AND l.provider_message_id IS DISTINCT FROM p_provider_id) THEN
   RAISE EXCEPTION 'DELIVERY_LOG_CONFLICT' USING ERRCODE='22023';
  END IF;
  UPDATE public.email_logs SET provider_message_id=p_provider_id,sent_at=coalesce(sent_at,p_sent_at),
   status=CASE WHEN status IN ('queued','failed') THEN 'sent' ELSE status END,error_message=NULL WHERE id=l.id;
 END IF;
 UPDATE public.private_booking_approval_deliveries SET status='sent',provider_message_id=p_provider_id,
  last_error=NULL,lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=d.id;
 RETURN true;
END $$;


ALTER FUNCTION "public"."complete_private_approval_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_private_rejection_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE v_delivery public.private_booking_rejection_deliveries%ROWTYPE;v_log public.email_logs%ROWTYPE;
BEGIN
 IF p_provider_id IS NULL OR length(btrim(p_provider_id))=0 OR p_sent_at IS NULL THEN
  RAISE EXCEPTION 'INVALID_DELIVERY_RECEIPT' USING ERRCODE='22023';
 END IF;
 SELECT * INTO v_delivery FROM public.private_booking_rejection_deliveries WHERE id=p_delivery_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR v_delivery.status IS DISTINCT FROM 'sending' OR v_delivery.lease_token IS DISTINCT FROM p_lease_token OR p_lease_token IS NULL THEN
  RAISE EXCEPTION 'DELIVERY_LEASE_LOST' USING ERRCODE='40001';
 END IF;
 SELECT * INTO v_log FROM public.email_logs WHERE id=coalesce(v_delivery.email_log_id,v_delivery.id) FOR UPDATE NOWAIT;
 IF NOT FOUND OR v_log.organization_id IS DISTINCT FROM v_delivery.organization_id
   OR v_log.reservation_id IS DISTINCT FROM v_delivery.reservation_id
   OR v_log.to_email IS DISTINCT FROM v_delivery.customer_email
   OR v_log.body_text IS DISTINCT FROM v_delivery.message_body
   OR v_log.email_type IS DISTINCT FROM 'reservation_cancelled'
   OR (v_log.provider_message_id IS NOT NULL AND v_log.provider_message_id IS DISTINCT FROM p_provider_id)
 THEN RAISE EXCEPTION 'DELIVERY_LOG_CONFLICT' USING ERRCODE='22023'; END IF;
 UPDATE public.email_logs SET provider_message_id=p_provider_id,sent_at=coalesce(sent_at,p_sent_at),
   status=CASE WHEN status IN ('queued','failed') THEN 'sent' ELSE status END,error_message=NULL
 WHERE id=v_log.id;
 UPDATE public.private_booking_rejection_deliveries SET status='sent',provider_message_id=p_provider_id,last_error=NULL,
   lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=v_delivery.id;
 RETURN true;
END; $$;


ALTER FUNCTION "public"."complete_private_rejection_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_private_survey_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE v_delivery public.private_group_survey_deliveries%ROWTYPE;v_log public.email_logs%ROWTYPE;
BEGIN
 IF p_provider_id IS NULL OR length(btrim(p_provider_id))=0 OR p_sent_at IS NULL THEN
  RAISE EXCEPTION 'INVALID_DELIVERY_RECEIPT' USING ERRCODE='22023';
 END IF;
 SELECT * INTO v_delivery FROM public.private_group_survey_deliveries WHERE id=p_delivery_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR v_delivery.status IS DISTINCT FROM 'sending' OR v_delivery.lease_token IS DISTINCT FROM p_lease_token OR p_lease_token IS NULL THEN
  RAISE EXCEPTION 'DELIVERY_LEASE_LOST' USING ERRCODE='40001';
 END IF;
 SELECT * INTO v_log FROM public.email_logs WHERE id=coalesce(v_delivery.email_log_id,v_delivery.id) FOR UPDATE NOWAIT;
 IF NOT FOUND OR v_log.organization_id IS DISTINCT FROM v_delivery.organization_id
   OR v_log.reservation_id IS DISTINCT FROM v_delivery.reservation_id
   OR v_log.to_email IS DISTINCT FROM v_delivery.customer_email
   OR v_log.body_text IS DISTINCT FROM v_delivery.message_body
   OR v_log.email_type IS DISTINCT FROM 'other'
   OR (v_log.provider_message_id IS NOT NULL AND v_log.provider_message_id IS DISTINCT FROM p_provider_id)
 THEN RAISE EXCEPTION 'DELIVERY_LOG_CONFLICT' USING ERRCODE='22023'; END IF;
 UPDATE public.email_logs SET provider_message_id=p_provider_id,sent_at=coalesce(sent_at,p_sent_at),
   status=CASE WHEN status IN ('queued','failed') THEN 'sent' ELSE status END,error_message=NULL
 WHERE id=v_log.id;
 UPDATE public.private_group_survey_deliveries SET status='sent',provider_message_id=p_provider_id,last_error=NULL,
   lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=v_delivery.id;
 RETURN true;
END; $$;


ALTER FUNCTION "public"."complete_private_survey_delivery"("p_delivery_id" "uuid", "p_lease_token" "uuid", "p_provider_id" "text", "p_sent_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_organization_signup_claim"("p_org_id" "uuid", "p_token" "text", "p_user_id" "uuid", "p_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_claim public.organization_signup_claims%ROWTYPE;
BEGIN
 PERFORM 1 FROM public.organizations WHERE id=p_org_id AND is_active=true FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION '登録対象の組織が見つかりません' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_claim FROM public.organization_signup_claims WHERE organization_id=p_org_id FOR UPDATE;
 IF NOT FOUND OR p_user_id IS NULL OR p_email IS NULL OR v_claim.email<>lower(trim(p_email))
   OR NOT (coalesce(v_claim.token_hash=extensions.digest(p_token,'sha256'),false)
       OR coalesce(v_claim.created_by=p_user_id AND auth.uid()=p_user_id,false)) THEN
   RAISE EXCEPTION '組織の登録権限を確認できません。登録画面からやり直してください' USING ERRCODE='42501';
 END IF;
 IF v_claim.consumed_at IS NOT NULL THEN
   IF v_claim.consumed_by=p_user_id AND EXISTS(SELECT 1 FROM public.users WHERE id=p_user_id AND organization_id=p_org_id AND role='admin') THEN RETURN; END IF;
   RAISE EXCEPTION 'この組織の登録手続きは完了しています' USING ERRCODE='42501';
 END IF;
 IF v_claim.expires_at<=clock_timestamp() THEN RAISE EXCEPTION '組織登録の有効期限が切れました。登録画面からやり直してください' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE organization_id=p_org_id)
   OR EXISTS(SELECT 1 FROM public.staff WHERE organization_id=p_org_id) THEN
   RAISE EXCEPTION '登録済みの組織を新規取得することはできません' USING ERRCODE='42501';
 END IF;
 UPDATE public.organization_signup_claims SET consumed_by=p_user_id,consumed_at=clock_timestamp(),consumed_transaction=txid_current() WHERE organization_id=p_org_id;
END;
$$;


ALTER FUNCTION "public"."consume_organization_signup_claim"("p_org_id" "uuid", "p_token" "text", "p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."coupon_campaigns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "discount_type" "text" DEFAULT 'fixed'::"text" NOT NULL,
    "discount_amount" integer NOT NULL,
    "max_uses_per_customer" integer DEFAULT 1 NOT NULL,
    "target_type" "text" DEFAULT 'all'::"text" NOT NULL,
    "target_ids" "uuid"[],
    "trigger_type" "text" DEFAULT 'manual'::"text" NOT NULL,
    "valid_from" timestamp with time zone,
    "valid_until" timestamp with time zone,
    "coupon_expiry_days" integer,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "usage_valid_from" timestamp with time zone,
    "usage_valid_until" timestamp with time zone,
    "max_total_grants" integer,
    "max_grants_per_customer" integer,
    "coupon_code" "text",
    "notify_on_grant" boolean DEFAULT false NOT NULL,
    "min_order_amount" integer,
    "combinable" boolean DEFAULT true NOT NULL,
    "allowed_weekdays" integer[],
    "allowed_time_slots" "text"[],
    "display_name" "text",
    "display_image_url" "text",
    "customer_terms" "text",
    "internal_memo" "text",
    "coupon_expiry_months" integer,
    "murder_mystery_only" boolean DEFAULT false NOT NULL,
    "target_store_ids" "uuid"[],
    "same_scenario_once" boolean DEFAULT true NOT NULL,
    CONSTRAINT "coupon_campaigns_discount_amount_check" CHECK (("discount_amount" > 0)),
    CONSTRAINT "coupon_campaigns_discount_type_check" CHECK (("discount_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"]))),
    CONSTRAINT "coupon_campaigns_max_uses_per_customer_check" CHECK (("max_uses_per_customer" > 0)),
    CONSTRAINT "coupon_campaigns_target_type_check" CHECK (("target_type" = ANY (ARRAY['all'::"text", 'specific_scenarios'::"text", 'specific_organization'::"text"]))),
    CONSTRAINT "coupon_campaigns_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['registration'::"text", 'manual'::"text"]))),
    CONSTRAINT "coupon_expiry_months_valid" CHECK ((("coupon_expiry_months" IS NULL) OR ((("coupon_expiry_months" >= 1) AND ("coupon_expiry_months" <= 120)) AND ("coupon_expiry_days" IS NULL) AND ("usage_valid_from" IS NULL) AND ("usage_valid_until" IS NULL))))
);


ALTER TABLE "public"."coupon_campaigns" OWNER TO "postgres";


COMMENT ON TABLE "public"."coupon_campaigns" IS 'クーポンキャンペーン定義（組織単位）';



COMMENT ON COLUMN "public"."coupon_campaigns"."usage_valid_from" IS 'クーポン使用開始日 (絶対)。NULL なら配布即時から使用可能';



COMMENT ON COLUMN "public"."coupon_campaigns"."usage_valid_until" IS 'クーポン使用期限 (絶対)。NULL なら無期限 (coupon_expiry_days があれば相対適用)';



COMMENT ON COLUMN "public"."coupon_campaigns"."max_total_grants" IS '配布数の上限（NULL=無制限）';



COMMENT ON COLUMN "public"."coupon_campaigns"."max_grants_per_customer" IS '1顧客あたりの配布数上限（NULL=無制限、デフォルトは1枚運用想定）';



COMMENT ON COLUMN "public"."coupon_campaigns"."coupon_code" IS '顧客が入力するクーポンコード（NULLなら管理者付与のみ）';



COMMENT ON COLUMN "public"."coupon_campaigns"."notify_on_grant" IS '付与時に顧客へメール通知するか';



COMMENT ON COLUMN "public"."coupon_campaigns"."min_order_amount" IS '最低利用金額（円）。NULL=制限なし';



COMMENT ON COLUMN "public"."coupon_campaigns"."combinable" IS '他クーポンとの併用可否';



COMMENT ON COLUMN "public"."coupon_campaigns"."allowed_weekdays" IS '使用可能な曜日（0=日曜 〜 6=土曜の配列）。NULL=全曜日';



COMMENT ON COLUMN "public"."coupon_campaigns"."allowed_time_slots" IS '使用可能な時間帯（朝公演/昼公演/夜公演など）。NULL=全時間帯';



COMMENT ON COLUMN "public"."coupon_campaigns"."display_name" IS '顧客向けクーポン表示名（NULLならキャンペーン名を流用）';



COMMENT ON COLUMN "public"."coupon_campaigns"."display_image_url" IS 'クーポン画像のURL（任意）';



COMMENT ON COLUMN "public"."coupon_campaigns"."customer_terms" IS '顧客向け利用条件文（細かい注意事項）';



COMMENT ON COLUMN "public"."coupon_campaigns"."internal_memo" IS '内部メモ（管理者のみ閲覧）';



COMMENT ON COLUMN "public"."coupon_campaigns"."coupon_expiry_months" IS 'Grant-relative calendar months in Asia/Tokyo; end-of-month clamps to the last day.';



COMMENT ON COLUMN "public"."coupon_campaigns"."murder_mystery_only" IS 'Only open/private performances with a registered scenario; excludes package and venue rental events.';



CREATE OR REPLACE FUNCTION "public"."coupon_campaign_rules"("p_campaign" "public"."coupon_campaigns") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
 SELECT jsonb_build_object(
  'discount_type',p_campaign.discount_type,'discount_amount',p_campaign.discount_amount,
  'target_type',p_campaign.target_type,'target_ids',p_campaign.target_ids,
  'target_store_ids',p_campaign.target_store_ids,'murder_mystery_only',p_campaign.murder_mystery_only,
  'usage_valid_from',p_campaign.usage_valid_from,'usage_valid_until',p_campaign.usage_valid_until,
  'min_order_amount',p_campaign.min_order_amount,'combinable',p_campaign.combinable,
  'allowed_weekdays',p_campaign.allowed_weekdays,'allowed_time_slots',p_campaign.allowed_time_slots,
  'same_scenario_once',p_campaign.same_scenario_once,'customer_terms',p_campaign.customer_terms);
$$;


ALTER FUNCTION "public"."coupon_campaign_rules"("p_campaign" "public"."coupon_campaigns") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."coupon_discount_for_event"("p_coupon" "uuid", "p_event" "uuid", "p_amount" integer, "p_customer" "uuid", "p_reservation" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE cc public.customer_coupons; e public.schedule_events; locked_reservation public.reservations; rules jsonb;
 prior record; scenario_key uuid; slot text; discount integer; used_amount integer:=0;
BEGIN
 -- 顧客行で直列化し、別クーポンを同時利用した場合にも併用/同作品制限を守る。
 PERFORM 1 FROM public.customers WHERE id=p_customer FOR UPDATE;
 SELECT * INTO cc FROM public.customer_coupons WHERE id=p_coupon FOR UPDATE;
 IF NOT FOUND OR cc.customer_id IS DISTINCT FROM p_customer THEN
  RAISE EXCEPTION 'クーポンが見つかりません' USING ERRCODE='P0028';
 END IF;
 IF cc.status<>'active' OR cc.uses_remaining<=0 OR (cc.expires_at IS NOT NULL AND cc.expires_at<now()) THEN
  RAISE EXCEPTION 'このクーポンは利用できません（残り回数・有効期限を確認してください）' USING ERRCODE='P0028';
 END IF;
 IF p_reservation IS NOT NULL THEN
  SELECT * INTO locked_reservation FROM public.reservations WHERE id=p_reservation FOR UPDATE;
  IF locked_reservation.id IS NULL OR locked_reservation.organization_id IS DISTINCT FROM cc.organization_id OR locked_reservation.status NOT IN ('confirmed','checked_in')
   OR NOT public.can_use_coupon_reservation(cc.customer_id,locked_reservation.id) THEN
   RAISE EXCEPTION '利用可能なご本人の予約を指定してください' USING ERRCODE='P0028';
  END IF;
  -- ロック前に取得された値は使わない。並行する人数変更・取消後の値で再判定する。
  p_amount:=locked_reservation.total_price;
  p_event:=locked_reservation.schedule_event_id;
 END IF;
 SELECT * INTO e FROM public.schedule_events WHERE id=p_event AND organization_id=cc.organization_id;
 IF NOT FOUND OR COALESCE(e.is_cancelled,false) THEN
  RAISE EXCEPTION 'この公演には利用できません' USING ERRCODE='P0028';
 END IF;
 IF p_reservation IS NULL THEN
  IF NOT (public.resolve_operating_setting(cc.organization_id,'coupon_usage_enabled','true'::jsonb,NULL,NULL,p_event)->>'value')::boolean THEN
   RAISE EXCEPTION 'この公演ではクーポンを利用できません' USING ERRCODE='P0028';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.reservations WHERE id=p_reservation AND coupon_usage_enabled_snapshot=false) THEN
   RAISE EXCEPTION 'この予約ではクーポンを利用できません' USING ERRCODE='P0028';
  END IF;
 END IF;
 rules:=cc.rules_snapshot;
 IF rules IS NULL OR p_amount IS NULL OR p_amount<=0 THEN
  RAISE EXCEPTION '利用条件または予約金額を確認できません' USING ERRCODE='P0028';
 END IF;
 IF (rules->>'usage_valid_from')::timestamptz>now() OR (rules->>'usage_valid_until')::timestamptz<now() THEN
  RAISE EXCEPTION 'クーポンの利用期間外です' USING ERRCODE='P0028';
 END IF;
 IF COALESCE((rules->>'murder_mystery_only')::boolean,false) AND NOT public.is_murder_mystery_coupon_event(e.category,
  e.scenario_master_id IS NOT NULL OR e.organization_scenario_id IS NOT NULL OR e.scenario_id IS NOT NULL) THEN
  RAISE EXCEPTION 'マーダーミステリーの通常公演・貸切のみで利用できます' USING ERRCODE='P0028';
 END IF;
 IF rules->>'target_type'='specific_organization' AND NOT COALESCE(rules->'target_ids' ? e.organization_id::text,false) THEN
  RAISE EXCEPTION '対象組織ではありません' USING ERRCODE='P0028';
 END IF;
 IF rules->>'target_type'='specific_scenarios' AND NOT (
  COALESCE(rules->'target_ids' ? e.organization_scenario_id::text,false) OR
  COALESCE(rules->'target_ids' ? e.scenario_master_id::text,false) OR
  COALESCE(rules->'target_ids' ? e.scenario_id::text,false)) THEN
  RAISE EXCEPTION '対象シナリオではありません' USING ERRCODE='P0028';
 END IF;
 IF jsonb_typeof(rules->'target_store_ids')='array' AND jsonb_array_length(rules->'target_store_ids')>0
  AND NOT COALESCE(rules->'target_store_ids' ? e.store_id::text,false) THEN
  RAISE EXCEPTION '対象店舗ではありません' USING ERRCODE='P0028';
 END IF;
 IF p_amount<COALESCE((rules->>'min_order_amount')::integer,0) THEN
  RAISE EXCEPTION '最低利用金額に達していません' USING ERRCODE='P0028';
 END IF;
 IF jsonb_typeof(rules->'allowed_weekdays')='array' AND jsonb_array_length(rules->'allowed_weekdays')>0 AND NOT
  rules->'allowed_weekdays' @> jsonb_build_array(extract(dow from e.date)::integer) THEN
  RAISE EXCEPTION '利用可能な曜日ではありません' USING ERRCODE='P0028';
 END IF;
 slot:=CASE WHEN e.time_slot IN ('朝','朝公演','午前','morning') THEN '朝'
  WHEN e.time_slot IN ('昼','昼公演','午後','afternoon') THEN '昼'
  WHEN e.time_slot IN ('夜','夜公演','夜間','evening') THEN '夜'
  WHEN e.start_time<'12:00' THEN '朝' WHEN e.start_time<'18:00' THEN '昼' ELSE '夜' END;
 IF jsonb_typeof(rules->'allowed_time_slots')='array' AND jsonb_array_length(rules->'allowed_time_slots')>0
  AND NOT (rules->'allowed_time_slots' ? slot OR rules->'allowed_time_slots' ? (slot||'公演')) THEN
  RAISE EXCEPTION '利用可能な時間帯ではありません' USING ERRCODE='P0028';
 END IF;
 IF p_reservation IS NOT NULL THEN
  SELECT COALESCE(sum(discount_amount),0)::integer INTO used_amount FROM public.coupon_usages WHERE reservation_id=p_reservation;
 END IF;
 scenario_key:=COALESCE(e.scenario_master_id,e.scenario_id,e.organization_scenario_id);
 FOR prior IN SELECT u.*,c.customer_id AS previous_customer,c.rules_snapshot AS previous_rules,
  COALESCE(se.scenario_master_id,se.scenario_id,se.organization_scenario_id) AS previous_scenario, se.scenario AS previous_title
  FROM public.coupon_usages u JOIN public.customer_coupons c ON c.id=u.customer_coupon_id
  JOIN public.reservations r ON r.id=u.reservation_id JOIN public.schedule_events se ON se.id=r.schedule_event_id
  WHERE c.customer_id=p_customer OR u.reservation_id=p_reservation
 LOOP
  IF prior.reservation_id=p_reservation THEN
   IF prior.customer_coupon_id=p_coupon THEN RAISE EXCEPTION 'この予約には使用済みです' USING ERRCODE='P0028'; END IF;
   IF NOT COALESCE((rules->>'combinable')::boolean,true) OR NOT COALESCE((prior.previous_rules->>'combinable')::boolean,true) THEN
    RAISE EXCEPTION '他のクーポンと併用できません' USING ERRCODE='P0028';
   END IF;
  ELSIF prior.previous_customer=p_customer AND ((scenario_key IS NOT NULL AND scenario_key=prior.previous_scenario) OR
   ((scenario_key IS NULL OR prior.previous_scenario IS NULL) AND NULLIF(btrim(e.scenario),'') IS NOT NULL AND btrim(e.scenario)=btrim(prior.previous_title))) AND COALESCE((rules->>'same_scenario_once')::boolean,true) THEN
   RAISE EXCEPTION 'この作品には既にクーポンをご利用済みです' USING ERRCODE='P0028';
  END IF;
 END LOOP;
 discount:=CASE rules->>'discount_type' WHEN 'fixed' THEN (rules->>'discount_amount')::integer
  WHEN 'percentage' THEN round(p_amount::numeric*(rules->>'discount_amount')::numeric/100)::integer END;
 discount:=LEAST(discount,GREATEST(p_amount-used_amount,0));
 IF discount IS NULL OR discount<=0 THEN RAISE EXCEPTION '割引できる金額がありません' USING ERRCODE='P0028'; END IF;
 RETURN discount;
END;
$$;


ALTER FUNCTION "public"."coupon_discount_for_event"("p_coupon" "uuid", "p_event" "uuid", "p_amount" integer, "p_customer" "uuid", "p_reservation" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_notification"("p_user_id" "uuid", "p_customer_id" "uuid", "p_organization_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_link" "text" DEFAULT NULL::"text", "p_related_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_related_event_id" "uuid" DEFAULT NULL::"uuid", "p_related_waitlist_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_notification_id UUID;
BEGIN
  INSERT INTO user_notifications (
    user_id,
    customer_id,
    organization_id,
    type,
    title,
    message,
    link,
    related_reservation_id,
    related_event_id,
    related_waitlist_id,
    metadata
  ) VALUES (
    p_user_id,
    p_customer_id,
    p_organization_id,
    p_type,
    p_title,
    p_message,
    p_link,
    p_related_reservation_id,
    p_related_event_id,
    p_related_waitlist_id,
    p_metadata
  )
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


ALTER FUNCTION "public"."create_notification"("p_user_id" "uuid", "p_customer_id" "uuid", "p_organization_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_link" "text", "p_related_reservation_id" "uuid", "p_related_event_id" "uuid", "p_related_waitlist_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_private_booking_request"("p_scenario_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_participant_count" integer, "p_candidate_datetimes" "jsonb", "p_notes" "text" DEFAULT NULL::"text", "p_reservation_number" "text" DEFAULT NULL::"text", "p_private_group_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_scenario_title TEXT;
  v_duration INTEGER;
  v_participation_fee NUMERIC;
  v_total_price NUMERIC;
  v_participation_costs JSONB;
  v_custom_holidays JSONB;
  v_unit_price INTEGER;
  v_pricing_date DATE := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Tokyo')::DATE;
  v_reservation_id UUID;
  v_gm_id UUID;
  v_org_id UUID;
  v_row_org_id UUID;
  v_scenario_org_count INTEGER;
  v_first_candidate JSONB;
  v_requested_datetime TIMESTAMPTZ;
  v_scenario_master_id UUID;
  -- 空き判定用
  v_cand JSONB;
  v_cand_date DATE;
  v_cand_start TIME;
  v_cand_end TIME;
  v_store_id_text TEXT;
  v_store_uuid UUID;
  v_store_available BOOLEAN;
  v_blocked_store_count INTEGER;
  v_requested_store_count INTEGER;
  v_candidate_count INTEGER;
  v_candidate_time_slot TEXT;
  v_caller_user_id UUID;
  v_customer_org_id UUID;
  v_group RECORD;
  v_group_candidate_id UUID;
  v_group_candidate_date DATE;
  v_group_candidate_time_slot TEXT;
  v_group_candidate_start TIME;
  v_group_candidate_end TIME;
  v_group_candidate_order INTEGER;
  v_store_name TEXT;
  v_store_short_name TEXT;
  v_seen_store_ids UUID[] := '{}'::UUID[];
  v_seen_group_candidate_ids UUID[] := '{}'::UUID[];
  v_trusted_candidates JSONB := '[]'::JSONB;
  v_trusted_requested_stores JSONB := '[]'::JSONB;
  v_trusted_candidate_datetimes JSONB;
  v_candidate_order INTEGER := 0;
  v_updated_count INTEGER;
  v_accepts_private_booking BOOLEAN;
  v_player_count_min INTEGER;
  v_player_count_max INTEGER;
  v_scenario_kind TEXT;
BEGIN
  -- 20260414150000 の認可境界を維持する。SECURITY DEFINERでもanon/なりすましを許可しない。
  v_caller_user_id := auth.uid();
  IF v_caller_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'P0401';
  END IF;

  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated customer is required' USING ERRCODE = 'P0401';
  END IF;

  SELECT customer.organization_id
  INTO v_customer_org_id
  FROM customers customer
  WHERE customer.id = p_customer_id
    AND customer.user_id = v_caller_user_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unauthorized: customer does not belong to authenticated user'
      USING ERRCODE = 'P0401';
  END IF;

  -- 貸切リクエストは必ずグループから申し込む（画面は送信前にグループを作る）。#834 #842
  -- 本人確認（P0401）の後に判定する。店舗の誤りと区別できるよう専用のコード P0047 を使う。
  IF p_private_group_id IS NULL THEN
    RAISE EXCEPTION '貸切リクエストはグループから申し込んでください' USING ERRCODE = 'P0047';
  END IF;

  -- ===========================================================================
  -- 組織の決定（最優先: グループの組織 = 申込ページの組織コンテキスト）
  -- ===========================================================================
  IF p_private_group_id IS NOT NULL THEN
    SELECT *
    INTO v_group
    FROM private_groups
    WHERE id = p_private_group_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_group.organizer_id IS DISTINCT FROM v_caller_user_id
       OR (
         v_customer_org_id IS NOT NULL
         AND v_group.organization_id IS DISTINCT FROM v_customer_org_id
       )
    THEN
      RAISE EXCEPTION 'Unauthorized private group'
        USING ERRCODE = 'P0401';
    END IF;

    v_org_id := v_group.organization_id;
  END IF;

  -- ===========================================================================
  -- シナリオ情報の取得
  -- 1) p_scenario_id を organization_scenarios.id（org固有ID）として検索。
  --    組織が確定済みの場合はその組織の行に限定する。
  -- ===========================================================================
  SELECT
    COALESCE(os.override_title, sm.title),
    COALESCE(os.duration, sm.official_duration),
    os.participation_fee, os.participation_costs,
    os.organization_id,
    os.scenario_master_id
  INTO
    v_scenario_title, v_duration, v_participation_fee, v_participation_costs, v_row_org_id, v_scenario_master_id
  FROM organization_scenarios os
  JOIN scenario_masters sm ON os.scenario_master_id = sm.id
  WHERE os.id = p_scenario_id
    AND (v_org_id IS NULL OR os.organization_id = v_org_id);

  IF FOUND THEN
    v_org_id := COALESCE(v_org_id, v_row_org_id);
  END IF;

  -- 2) 見つからない場合、p_scenario_id を scenario_master_id として検索（組織確定済み）
  IF v_scenario_title IS NULL AND v_org_id IS NOT NULL THEN
    SELECT
      COALESCE(os.override_title, sm.title),
      COALESCE(os.duration, sm.official_duration),
      os.participation_fee, os.participation_costs,
      os.scenario_master_id
    INTO
      v_scenario_title, v_duration, v_participation_fee, v_participation_costs, v_scenario_master_id
    FROM organization_scenarios os
    JOIN scenario_masters sm ON os.scenario_master_id = sm.id
    WHERE os.scenario_master_id = p_scenario_id
      AND os.organization_id = v_org_id
    ORDER BY os.created_at
    LIMIT 1;
  END IF;

  -- 3) 組織未確定で master_id 検索: 登録が1組織のみの場合に限り採用。
  --    複数組織に登録されている場合は不定な選択をせずエラーにする。
  IF v_scenario_title IS NULL AND v_org_id IS NULL THEN
    SELECT COUNT(DISTINCT os.organization_id) INTO v_scenario_org_count
    FROM organization_scenarios os
    WHERE os.scenario_master_id = p_scenario_id;

    IF v_scenario_org_count > 1 THEN
      RAISE EXCEPTION 'Scenario % is registered in multiple organizations; organization context (private group) is required', p_scenario_id
        USING ERRCODE = 'P0031';
    ELSIF v_scenario_org_count = 1 THEN
      SELECT
        COALESCE(os.override_title, sm.title),
        COALESCE(os.duration, sm.official_duration),
        os.participation_fee, os.participation_costs,
        os.organization_id,
        os.scenario_master_id
      INTO
        v_scenario_title, v_duration, v_participation_fee, v_participation_costs, v_row_org_id, v_scenario_master_id
      FROM organization_scenarios os
      JOIN scenario_masters sm ON os.scenario_master_id = sm.id
      WHERE os.scenario_master_id = p_scenario_id
      ORDER BY os.created_at
      LIMIT 1;

      IF FOUND THEN
        v_org_id := v_row_org_id;
      END IF;
    END IF;
  END IF;

  -- 4) organization_scenarios で見つからない場合は scenarios_v2 ビューから取得
  --    （組織はここでは確定しない — グループ由来の v_org_id のみ有効）
  IF v_scenario_title IS NULL THEN
    SELECT title, duration, participation_fee, participation_costs
    INTO v_scenario_title, v_duration, v_participation_fee, v_participation_costs
    FROM scenarios_v2
    WHERE id = p_scenario_id;

    v_scenario_master_id := p_scenario_id;
  END IF;

  -- 5) scenarios_v2 でも見つからない場合は scenario_masters のタイトルだけ取得
  IF v_scenario_title IS NULL THEN
    SELECT title, official_duration
    INTO v_scenario_title, v_duration
    FROM scenario_masters
    WHERE id = p_scenario_id;

    v_scenario_master_id := p_scenario_id;
  END IF;

  IF v_scenario_title IS NULL THEN
    RAISE EXCEPTION 'Scenario not found: %', p_scenario_id USING ERRCODE = 'P0001';
  END IF;

  -- platform customerはorganization_id=NULLを正規形とする。org固定customerだけ不一致を拒否する。
  IF v_customer_org_id IS NOT NULL
     AND v_org_id IS DISTINCT FROM v_customer_org_id
  THEN
    RAISE EXCEPTION 'Customer organization does not match booking organization'
      USING ERRCODE = 'P0401';
  END IF;

  IF p_private_group_id IS NOT NULL
     AND v_group.scenario_master_id IS NOT NULL
     AND v_group.scenario_master_id IS DISTINCT FROM v_scenario_master_id
  THEN
    RAISE EXCEPTION 'Private group scenario does not match booking scenario'
      USING ERRCODE = 'P0043';
  END IF;

  -- デフォルト値の設定
  v_duration := COALESCE(v_duration, 240);
  v_participation_fee := COALESCE(v_participation_fee, 4000);

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization not found for scenario' USING ERRCODE = 'P0026';
  END IF;

  SELECT COALESCE(os.custom_holidays, '[]'::JSONB) INTO v_custom_holidays
  FROM organization_settings os WHERE os.organization_id = v_org_id;
  v_custom_holidays := COALESCE(v_custom_holidays, '[]'::JSONB);

  -- 貸切受付OFF / 出張限定（offsite_only）は顧客リクエストを拒否する
  SELECT
    COALESCE(os.accepts_private_booking, true),
    COALESCE(os.scenario_kind, 'regular')
  INTO
    v_accepts_private_booking,
    v_scenario_kind
  FROM organization_scenarios os
  WHERE os.organization_id = v_org_id
    AND (
      os.id = p_scenario_id
      OR os.scenario_master_id = COALESCE(v_scenario_master_id, p_scenario_id)
    )
  ORDER BY
    CASE WHEN os.id = p_scenario_id THEN 0 ELSE 1 END,
    os.created_at
  LIMIT 1;

  IF FOUND AND (
    v_accepts_private_booking IS FALSE
    OR v_scenario_kind = 'offsite_only'
  ) THEN
    RAISE EXCEPTION 'PRIVATE_BOOKING_NOT_ACCEPTED' USING ERRCODE = 'P0044';
  END IF;

  -- 店舗側の不要な人数制限ではなく、導入作品の実効プレイ人数を検証する。
  SELECT COALESCE(os.override_player_count_min,sm.player_count_min),
         COALESCE(os.override_player_count_max,sm.player_count_max)
    INTO v_player_count_min,v_player_count_max
  FROM public.organization_scenarios os
  JOIN public.scenario_masters sm ON sm.id=os.scenario_master_id
  WHERE os.organization_id=v_org_id AND os.scenario_master_id=v_scenario_master_id;
  IF NOT FOUND OR v_player_count_min IS NULL OR v_player_count_max IS NULL
     OR v_player_count_min<1 OR v_player_count_max<v_player_count_min THEN
    RAISE EXCEPTION 'PRIVATE_BOOKING_PLAYER_COUNT_NOT_CONFIGURED' USING ERRCODE='P0051';
  END IF;
  IF p_participant_count IS NULL OR p_participant_count<v_player_count_min OR p_participant_count>v_player_count_max THEN
    RAISE EXCEPTION 'Participant count must be between % and %',v_player_count_min,v_player_count_max USING ERRCODE='P0025';
  END IF;

  IF jsonb_typeof(p_candidate_datetimes) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_candidate_datetimes->'requestedStores') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_candidate_datetimes->'candidates') IS DISTINCT FROM 'array'
  THEN
    RAISE EXCEPTION 'INVALID_CANDIDATE_PAYLOAD' USING ERRCODE = 'P0041';
  END IF;

  v_requested_store_count := jsonb_array_length(p_candidate_datetimes->'requestedStores');
  v_candidate_count := jsonb_array_length(p_candidate_datetimes->'candidates');
  IF v_requested_store_count = 0 OR v_candidate_count = 0 THEN
    RAISE EXCEPTION 'CANDIDATES_AND_REQUESTED_STORES_REQUIRED' USING ERRCODE = 'P0023';
  END IF;

  -- store名を含む保存payloadはDBから再構築する。group経路ではpreferred_store_idsと完全一致を必須化。
  IF p_private_group_id IS NOT NULL
     AND v_requested_store_count IS DISTINCT FROM cardinality(
       COALESCE(v_group.preferred_store_ids, '{}'::UUID[])
     )
  THEN
    RAISE EXCEPTION 'REQUESTED_STORES_DO_NOT_MATCH_PRIVATE_GROUP' USING ERRCODE = 'P0042';
  END IF;

  FOR v_store_id_text IN
    SELECT value->>'storeId'
    FROM jsonb_array_elements(p_candidate_datetimes->'requestedStores')
  LOOP
    BEGIN
      v_store_uuid := v_store_id_text::UUID;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'INVALID_REQUESTED_STORE' USING ERRCODE = 'P0042';
    END;

    IF v_store_uuid = ANY(v_seen_store_ids) THEN
      RAISE EXCEPTION 'DUPLICATE_REQUESTED_STORE' USING ERRCODE = 'P0042';
    END IF;

    IF p_private_group_id IS NOT NULL
       AND NOT (
         v_store_uuid = ANY(COALESCE(v_group.preferred_store_ids, '{}'::UUID[]))
       )
    THEN
      RAISE EXCEPTION 'REQUESTED_STORE_NOT_IN_PRIVATE_GROUP' USING ERRCODE = 'P0042';
    END IF;

    SELECT store.name, store.short_name
    INTO v_store_name, v_store_short_name
    FROM stores store
    WHERE store.id = v_store_uuid
      AND store.organization_id = v_org_id
      AND store.status = 'active';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_REQUESTED_STORE' USING ERRCODE = 'P0042';
    END IF;

    v_seen_store_ids := array_append(v_seen_store_ids, v_store_uuid);
    v_trusted_requested_stores := v_trusted_requested_stores || jsonb_build_array(
      jsonb_build_object(
        'storeId', v_store_uuid::TEXT,
        'storeName', v_store_name,
        'storeShortName', COALESCE(v_store_short_name, v_store_name)
      )
    );
  END LOOP;

  -- group経路はclient値をselectorとしてのみ使い、locked DB候補から全フィールドを復元する。
  FOR v_cand IN
    SELECT value FROM jsonb_array_elements(p_candidate_datetimes->'candidates')
  LOOP
    v_candidate_order := v_candidate_order + 1;
    BEGIN
      v_cand_date  := (v_cand->>'date')::DATE;
      v_cand_start := (v_cand->>'startTime')::TIME;
      v_cand_end   := (v_cand->>'endTime')::TIME;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_DATETIME' USING ERRCODE = 'P0041';
    END;

    IF v_cand_date IS NULL
       OR v_cand_start IS NULL
       OR v_cand_end IS NULL
       OR v_cand_start >= v_cand_end
    THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_DATETIME' USING ERRCODE = 'P0041';
    END IF;

    v_candidate_time_slot := CASE v_cand->>'timeSlot'
      WHEN 'morning' THEN 'morning'
      WHEN '朝' THEN 'morning'
      WHEN '午前' THEN 'morning'
      WHEN 'afternoon' THEN 'afternoon'
      WHEN '昼' THEN 'afternoon'
      WHEN '午後' THEN 'afternoon'
      WHEN 'evening' THEN 'evening'
      WHEN '夜' THEN 'evening'
      WHEN '夜間' THEN 'evening'
      ELSE NULL
    END;
    IF v_candidate_time_slot IS NULL THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_TIME_SLOT' USING ERRCODE = 'P0041';
    END IF;

    IF p_private_group_id IS NOT NULL THEN
      SELECT
        candidate.id,
        candidate.date,
        candidate.time_slot,
        candidate.start_time::TIME,
        candidate.end_time::TIME,
        candidate.order_num
      INTO
        v_group_candidate_id,
        v_group_candidate_date,
        v_group_candidate_time_slot,
        v_group_candidate_start,
        v_group_candidate_end,
        v_group_candidate_order
      FROM private_group_candidate_dates candidate
      WHERE candidate.group_id = p_private_group_id
        AND candidate.status IS DISTINCT FROM 'rejected'
        AND candidate.date = v_cand_date
        AND candidate.start_time::TIME = v_cand_start
        AND CASE candidate.time_slot
          WHEN 'morning' THEN 'morning'
          WHEN '朝' THEN 'morning'
          WHEN '午前' THEN 'morning'
          WHEN 'afternoon' THEN 'afternoon'
          WHEN '昼' THEN 'afternoon'
          WHEN '午後' THEN 'afternoon'
          WHEN 'evening' THEN 'evening'
          WHEN '夜' THEN 'evening'
          WHEN '夜間' THEN 'evening'
          ELSE NULL
        END = v_candidate_time_slot
      ORDER BY candidate.order_num, candidate.id
      LIMIT 1
      FOR SHARE;

      IF NOT FOUND OR v_group_candidate_id = ANY(v_seen_group_candidate_ids) THEN
        RAISE EXCEPTION 'CANDIDATE_NOT_IN_PRIVATE_GROUP' USING ERRCODE = 'P0041';
      END IF;

      v_seen_group_candidate_ids := array_append(
        v_seen_group_candidate_ids,
        v_group_candidate_id
      );
      v_cand_date := v_group_candidate_date;
      v_cand_start := v_group_candidate_start;
      v_cand_end := v_group_candidate_end;
      v_candidate_time_slot := CASE v_group_candidate_time_slot
        WHEN 'morning' THEN 'morning'
        WHEN '朝' THEN 'morning'
        WHEN '午前' THEN 'morning'
        WHEN 'afternoon' THEN 'afternoon'
        WHEN '昼' THEN 'afternoon'
        WHEN '午後' THEN 'afternoon'
        WHEN 'evening' THEN 'evening'
        WHEN '夜' THEN 'evening'
        WHEN '夜間' THEN 'evening'
        ELSE NULL
      END;
      v_candidate_order := v_group_candidate_order;
    END IF;

    v_unit_price := public.calculate_booking_participation_fee(
      v_participation_fee::INTEGER, v_participation_costs, v_cand_date, v_cand_start,
      v_custom_holidays ? v_cand_date::TEXT, v_pricing_date
    );

    v_trusted_candidates := v_trusted_candidates || jsonb_build_array(
      jsonb_build_object(
        'order', v_candidate_order,
        'date', v_cand_date::TEXT,
        'timeSlot', CASE v_candidate_time_slot
          WHEN 'morning' THEN '午前'
          WHEN 'afternoon' THEN '午後'
          ELSE '夜間'
        END,
        'startTime', to_char(v_cand_start, 'HH24:MI'),
        'endTime', to_char(v_cand_end, 'HH24:MI'),
        'status', 'pending',
        'unitPrice', v_unit_price,
        'totalPrice', v_unit_price * p_participant_count
      )
    );
  END LOOP;

  v_trusted_candidate_datetimes := jsonb_build_object(
    'candidates', v_trusted_candidates,
    'requestedStores', v_trusted_requested_stores
  );

  -- block/unblock・公演追加との競合を直列化し、同一transactionの最新状態で判定する。
  LOCK TABLE schedule_blocked_slots IN SHARE MODE;
  LOCK TABLE schedule_events IN SHARE MODE;

  -- =========================================================================
  -- サーバー側空き判定: 全候補がそれぞれ1店舗以上で受付可能であることを強制する。
  -- =========================================================================
  v_requested_store_count := jsonb_array_length(
    v_trusted_candidate_datetimes->'requestedStores'
  );
  v_candidate_count := jsonb_array_length(
    v_trusted_candidate_datetimes->'candidates'
  );

  FOR v_cand IN
    SELECT value FROM jsonb_array_elements(v_trusted_candidate_datetimes->'candidates')
  LOOP
    BEGIN
      v_cand_date  := (v_cand->>'date')::DATE;
      v_cand_start := (v_cand->>'startTime')::TIME;
      v_cand_end   := (v_cand->>'endTime')::TIME;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_DATETIME' USING ERRCODE = 'P0041';
    END;

    IF v_cand_date IS NULL
       OR v_cand_start IS NULL
       OR v_cand_end IS NULL
       OR v_cand_start >= v_cand_end
    THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_DATETIME' USING ERRCODE = 'P0041';
    END IF;

    v_candidate_time_slot := CASE v_cand->>'timeSlot'
      WHEN 'morning' THEN 'morning'
      WHEN '朝' THEN 'morning'
      WHEN '午前' THEN 'morning'
      WHEN 'afternoon' THEN 'afternoon'
      WHEN '昼' THEN 'afternoon'
      WHEN '午後' THEN 'afternoon'
      WHEN 'evening' THEN 'evening'
      WHEN '夜' THEN 'evening'
      WHEN '夜間' THEN 'evening'
      ELSE NULL
    END;
    IF v_candidate_time_slot IS NULL THEN
      RAISE EXCEPTION 'INVALID_CANDIDATE_TIME_SLOT' USING ERRCODE = 'P0041';
    END IF;

    v_store_available := false;
    v_blocked_store_count := 0;

    FOR v_store_id_text IN
      SELECT value->>'storeId'
      FROM jsonb_array_elements(v_trusted_candidate_datetimes->'requestedStores')
    LOOP
      v_store_uuid := v_store_id_text::UUID;

      IF EXISTS (
        SELECT 1
        FROM schedule_blocked_slots blocked
        WHERE blocked.organization_id = v_org_id
          AND blocked.store_id = v_store_uuid::TEXT
          AND blocked.date = v_cand_date
          AND blocked.time_slot = v_candidate_time_slot
      ) OR public.is_store_recruitment_paused(v_store_uuid, 'private', v_cand_date) THEN
        v_blocked_store_count := v_blocked_store_count + 1;
        CONTINUE;
      END IF;

      IF EXISTS (
        SELECT 1
        FROM schedule_events event
        WHERE event.organization_id = v_org_id
          AND event.store_id = v_store_uuid
          AND event.date BETWEEN v_cand_date - 2 AND v_cand_date + 2
          AND event.is_cancelled = false
          AND event.date + event.start_time < v_cand_date + v_cand_end + CASE WHEN v_cand_end < v_cand_start THEN interval '1 day' ELSE interval '0 days' END + make_interval(mins => public.resolve_preparation_minutes(v_org_id,NULL,NULL,event.id))
          AND event.date + event.end_time + CASE WHEN event.end_time < event.start_time THEN interval '1 day' ELSE interval '0 days' END > v_cand_date + v_cand_start - make_interval(mins => public.resolve_preparation_minutes(v_org_id,v_store_uuid,COALESCE(v_scenario_master_id,p_scenario_id),NULL))
      ) THEN
        CONTINUE;
      END IF;

      v_store_available := true;
      EXIT;
    END LOOP;

    IF NOT v_store_available THEN
      IF v_blocked_store_count = v_requested_store_count THEN
        RAISE EXCEPTION 'PRIVATE_BOOKING_SLOT_BLOCKED:%:%', v_cand_date, v_candidate_time_slot
          USING ERRCODE = 'P0040';
      END IF;
      RAISE EXCEPTION 'PRIVATE_BOOKING_CANDIDATE_CONFLICT:%:%', v_cand_date, v_candidate_time_slot
        USING ERRCODE = 'P0030';
    END IF;
  END LOOP;
  -- =========================================================================

  -- 料金計算
  v_unit_price := (v_trusted_candidate_datetimes->'candidates'->0->>'unitPrice')::INTEGER;
  v_total_price := p_participant_count * v_unit_price;

  -- 最初の候補日時を取得
  v_first_candidate := v_trusted_candidate_datetimes->'candidates'->0;
  v_requested_datetime := (
    (v_first_candidate->>'date') || 'T' ||
    COALESCE(v_first_candidate->>'startTime', '10:00') ||
    '+09:00'
  )::TIMESTAMPTZ;

  IF v_scenario_master_id IS NULL THEN
    RAISE EXCEPTION 'Scenario master not resolved: %', p_scenario_id USING ERRCODE = 'P0001';
  END IF;

  -- 予約を作成
  INSERT INTO reservations (
    title,
    reservation_number,
    scenario_id,
    scenario_master_id,
    customer_id,
    requested_datetime,
    duration,
    participant_count,
    total_price, base_price, final_price, unit_price,
    status,
    customer_notes,
    organization_id,
    customer_name,
    customer_email,
    customer_phone,
    candidate_datetimes,
    priority,
    reservation_type,
    reservation_source,
    private_group_id
  ) VALUES (
    '【貸切希望】' || v_scenario_title,
    COALESCE(p_reservation_number, 'PB-' || to_char(NOW(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 8)),
    v_scenario_master_id,
    v_scenario_master_id,
    p_customer_id,
    v_requested_datetime,
    v_duration,
    p_participant_count,
    v_total_price, v_total_price, v_total_price, v_unit_price,
    'pending',
    p_notes,
    v_org_id,
    p_customer_name,
    p_customer_email,
    p_customer_phone,
    v_trusted_candidate_datetimes,
    0,
    'private_booking',
    'web_private',
    p_private_group_id
  )
  RETURNING id INTO v_reservation_id;

  INSERT INTO public.private_booking_pricing_snapshots(
    reservation_id, organization_id, base_fee, participation_costs, custom_holidays, pricing_date
  ) VALUES (
    v_reservation_id, v_org_id, v_participation_fee::INTEGER,
    COALESCE(v_participation_costs, '[]'::JSONB), v_custom_holidays, v_pricing_date
  );

  -- private_group_id が指定されている場合、private_groups.reservation_id を更新
  IF p_private_group_id IS NOT NULL THEN
    UPDATE private_groups
    SET reservation_id = v_reservation_id,
        status = 'booking_requested',
        updated_at = NOW()
    WHERE id = p_private_group_id
      AND organization_id = v_org_id
      AND organizer_id = v_caller_user_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    IF v_updated_count <> 1 THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_UPDATE_FAILED' USING ERRCODE = 'P0043';
    END IF;
  END IF;

  -- GM確認レコードを作成（担当GMがいる場合のみ）
  -- staff_scenario_assignments から担当GMを取得
  -- ✅ v_org_id 所属のスタッフに限定（他組織GMへの pending 行生成を防ぐ）
  FOR v_gm_id IN
    SELECT ssa.staff_id
    FROM staff_scenario_assignments ssa
    JOIN staff s ON s.id = ssa.staff_id
    WHERE ssa.scenario_master_id = v_scenario_master_id
      AND ssa.organization_id = v_org_id
      AND (ssa.can_main_gm = true OR ssa.can_sub_gm = true)
      AND s.organization_id = v_org_id
      AND s.status = 'active'
  LOOP
    INSERT INTO gm_availability_responses (
      organization_id,
      reservation_id,
      staff_id,
      response_status,
      available_candidates
    ) VALUES (
      v_org_id,
      v_reservation_id,
      v_gm_id,
      'pending',
      NULL
    )
    ON CONFLICT (reservation_id, staff_id) DO NOTHING;
  END LOOP;

  RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION "public"."create_private_booking_request"("p_scenario_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_participant_count" integer, "p_candidate_datetimes" "jsonb", "p_notes" "text", "p_reservation_number" "text", "p_private_group_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_private_booking_request"("p_scenario_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_participant_count" integer, "p_candidate_datetimes" "jsonb", "p_notes" "text", "p_reservation_number" "text", "p_private_group_id" "uuid") IS '貸切予約リクエストを作成するRPC関数（organization_scenarios.override_title 対応版）';



CREATE OR REPLACE FUNCTION "public"."create_private_booking_request_with_notice"("p_scenario_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_participant_count" integer, "p_candidate_datetimes" "jsonb", "p_notes" "text" DEFAULT NULL::"text", "p_reservation_number" "text" DEFAULT NULL::"text", "p_private_group_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE reservation uuid; saved public.reservations%ROWTYPE; member uuid; title text; body text; g public.private_groups%ROWTYPE; linked_status text;
BEGIN
 IF p_private_group_id IS NOT NULL THEN
  SELECT * INTO g FROM public.private_groups WHERE id=p_private_group_id FOR UPDATE;
  IF NOT FOUND OR g.organizer_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN
   RAISE EXCEPTION 'このグループの予約を申し込む権限がありません' USING ERRCODE='42501';
  END IF;
  IF g.status IS NULL OR g.status NOT IN ('gathering','date_adjusting') THEN
   RAISE EXCEPTION '既に申込済み、確定済み、または取消済みです。画面を更新してください' USING ERRCODE='22023';
  END IF;
  IF g.reservation_id IS NOT NULL THEN
   SELECT status INTO linked_status FROM public.reservations WHERE id=g.reservation_id AND organization_id=g.organization_id FOR SHARE;
   IF linked_status IS DISTINCT FROM 'cancelled' THEN
    RAISE EXCEPTION '処理中の予約があるため再申込できません。画面を更新してください' USING ERRCODE='22023';
   END IF;
  END IF;
 END IF;
 reservation:=public.create_private_booking_request(p_scenario_id,p_customer_id,p_customer_name,p_customer_email,p_customer_phone,
  p_participant_count,p_candidate_datetimes,p_notes,p_reservation_number,p_private_group_id);
 IF p_private_group_id IS NOT NULL THEN
  SELECT * INTO STRICT saved FROM public.reservations WHERE id=reservation AND private_group_id=p_private_group_id;
  SELECT m.id INTO member FROM public.private_group_members m
   WHERE m.group_id=p_private_group_id AND m.user_id=auth.uid() AND m.is_organizer=true
   ORDER BY m.created_at,m.id LIMIT 1;
  SELECT s.system_msg_booking_requested_title,s.system_msg_booking_requested_body INTO title,body
   FROM public.global_settings s WHERE s.organization_id=saved.organization_id;
  INSERT INTO public.private_group_messages(group_id,member_id,message) VALUES(p_private_group_id,member,
   jsonb_build_object('type','system','action','booking_requested','reservationId',reservation,
    'candidateCount',jsonb_array_length(saved.candidate_datetimes->'candidates'),
    'title',coalesce(nullif(title,''),'貸切リクエストを送信しました'),
    'body',coalesce(nullif(body,''),'店舗より日程確定のご連絡をいたしますので、しばらくお待ちください。'))::text);
 END IF;
 RETURN reservation;
END $$;


ALTER FUNCTION "public"."create_private_booking_request_with_notice"("p_scenario_id" "uuid", "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_participant_count" integer, "p_candidate_datetimes" "jsonb", "p_notes" "text", "p_reservation_number" "text", "p_private_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_private_group_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_preferred_store_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_candidate_dates" "jsonb" DEFAULT '[]'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
 v_user uuid:=auth.uid(); v_group public.private_groups; v_member uuid;
 v_name text; v_settings public.global_settings; v_date jsonb; v_order bigint;
 v_custom_holidays jsonb; v_weekday_slots text[]; v_weekend_slots text[]; v_cand date; v_holiday boolean; v_allowed text[];
BEGIN
 IF v_user IS NULL THEN RAISE EXCEPTION 'ログインが必要です' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM organizations WHERE id=p_organization_id AND is_active IS TRUE) THEN
  RAISE EXCEPTION '組織情報が取得できません' USING ERRCODE='22023';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM organization_scenarios_with_master
   WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id
   AND player_count_min>=1 AND player_count_max>=player_count_min AND accepts_private_booking IS TRUE) THEN
  RAISE EXCEPTION 'この作品は現在貸切を受け付けていません' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(p_preferred_store_ids,'{}')) s(id)
   WHERE NOT EXISTS(SELECT 1 FROM stores WHERE stores.id=s.id AND organization_id=p_organization_id AND status='active')) THEN
  RAISE EXCEPTION '選択した店舗はこの組織で利用できません' USING ERRCODE='22023';
 END IF;
 IF p_candidate_dates IS NULL OR jsonb_typeof(p_candidate_dates)<>'array' THEN
  RAISE EXCEPTION '候補日時の形式が不正です' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_candidate_dates)>100 OR length(coalesce(p_name,''))>200 OR length(coalesce(p_notes,''))>10000 THEN
  RAISE EXCEPTION '入力が長すぎます' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(nullif(nickname,''),nullif(name,'')) INTO v_name FROM customers WHERE user_id=v_user ORDER BY id LIMIT 1;
 SELECT * INTO v_settings FROM global_settings WHERE organization_id=p_organization_id LIMIT 1;
 SELECT coalesce(custom_holidays,'[]'::jsonb) INTO v_custom_holidays FROM organization_settings WHERE organization_id=p_organization_id LIMIT 1;
 v_custom_holidays:=coalesce(v_custom_holidays,'[]'::jsonb);
 SELECT private_booking_time_slots,private_booking_time_slots_weekend INTO v_weekday_slots,v_weekend_slots
   FROM organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id LIMIT 1;
 INSERT INTO private_groups(organization_id,scenario_master_id,organizer_id,name,invite_code,status,preferred_store_ids,notes)
 VALUES(p_organization_id,p_scenario_master_id,v_user,nullif(trim(p_name),''),encode(extensions.gen_random_bytes(16),'hex'),'gathering',coalesce(p_preferred_store_ids,'{}'),p_notes)
 RETURNING * INTO v_group;
 INSERT INTO private_group_members(group_id,user_id,guest_name,is_organizer,status,joined_at)
 VALUES(v_group.id,v_user,coalesce(v_name,'主催者'),true,'joined',clock_timestamp()) RETURNING id INTO v_member;
 FOR v_date,v_order IN SELECT value,ordinality FROM jsonb_array_elements(p_candidate_dates) WITH ORDINALITY LOOP
  IF jsonb_typeof(v_date)<>'object' OR coalesce(v_date->>'time_slot','') NOT IN ('午前','午後','夜間')
    OR coalesce(v_date->>'start_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR coalesce(v_date->>'end_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
   RAISE EXCEPTION '候補日時の形式が不正です' USING ERRCODE='22023';
  END IF;
  -- 作品の貸切受付枠（平日・土日祝は別々。未設定は全枠受付）。候補追加時の判定と同じ。
  v_cand:=(v_date->>'date')::date;
  v_holiday:=extract(dow FROM v_cand) IN (0,6) OR public.is_booking_calendar_holiday(v_cand) OR coalesce(v_custom_holidays ? v_cand::text,false);
  v_allowed:=CASE WHEN v_holiday THEN v_weekend_slots ELSE v_weekday_slots END;
  IF coalesce(cardinality(v_allowed),0)>0 AND NOT EXISTS(
   SELECT 1 FROM unnest(v_allowed) value WHERE value=ANY(CASE v_date->>'time_slot'
    WHEN '午前' THEN ARRAY['午前','朝公演','朝'] WHEN '午後' THEN ARRAY['午後','昼公演','昼'] ELSE ARRAY['夜','夜公演'] END)
  ) THEN RAISE EXCEPTION 'この作品では選択できない時間帯です' USING ERRCODE='22023'; END IF;
  INSERT INTO private_group_candidate_dates(group_id,date,time_slot,start_time,end_time,order_num)
  VALUES(v_group.id,(v_date->>'date')::date,v_date->>'time_slot',v_date->>'start_time',v_date->>'end_time',coalesce((v_date->>'order_num')::integer,v_order::integer));
 END LOOP;
 INSERT INTO private_group_messages(group_id,member_id,message) VALUES(v_group.id,v_member,jsonb_build_object(
  'type','system','action','group_created','organizerName',coalesce(v_name,'主催者'),
  'title',coalesce(nullif(v_settings.system_msg_group_created_title,''),'貸切リクエストグループを作成しました'),
  'body',coalesce(nullif(v_settings.system_msg_group_created_body,''),'招待リンクを共有して、参加メンバーを招待してください。'),
  'note',coalesce(nullif(v_settings.system_msg_group_created_note,''),'※ 全員を招待していなくても日程確定は可能ですが、当日は参加人数全員でお越しください。'))::text);
 RETURN to_jsonb(v_group);
END $_$;


ALTER FUNCTION "public"."create_private_group_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid", "p_name" "text", "p_preferred_store_ids" "uuid"[], "p_candidate_dates" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_reservation_with_lock"("p_schedule_event_id" "uuid", "p_participant_count" integer, "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_notes" "text" DEFAULT NULL::"text", "p_how_found" "text" DEFAULT NULL::"text", "p_reservation_number" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN create_reservation_with_lock_v2(
    p_schedule_event_id,
    p_participant_count,
    p_customer_id,
    p_customer_name,
    p_customer_email,
    p_customer_phone,
    p_notes,
    p_how_found,
    p_reservation_number,
    NULL
  );
END;
$$;


ALTER FUNCTION "public"."create_reservation_with_lock"("p_schedule_event_id" "uuid", "p_participant_count" integer, "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_notes" "text", "p_how_found" "text", "p_reservation_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_reservation_with_lock_v2"("p_schedule_event_id" "uuid", "p_participant_count" integer, "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_notes" "text" DEFAULT NULL::"text", "p_how_found" "text" DEFAULT NULL::"text", "p_reservation_number" "text" DEFAULT NULL::"text", "p_customer_coupon_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_max_participants INTEGER;
  v_current_participants INTEGER;
  v_available_seats INTEGER;
  v_reservation_id UUID;

  v_event_org_id UUID;
  v_scenario_id UUID;
  v_org_scenario_id UUID;
  v_store_id UUID;
  v_date DATE;
  v_start_time TIME;
  v_duration INTEGER;
  v_title TEXT;

  v_customer_user_id UUID;
  v_customer_org_id UUID;
  v_caller_org_id UUID;
  v_is_admin BOOLEAN;
  v_is_staff BOOLEAN;

  v_participation_fee INTEGER;
  v_participation_costs JSONB;
  v_custom_holiday BOOLEAN;

  v_unit_price INTEGER;
  v_total_price INTEGER;
  v_discount_amount INTEGER := 0;
  v_final_price INTEGER;
  v_requested_datetime TIMESTAMP;
  v_reservation_number TEXT;

  v_coupon RECORD;
  v_campaign RECORD;
  v_coupon_usage_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0011';
  END IF;

  IF p_participant_count <= 0 THEN
    RAISE EXCEPTION 'INVALID_PARTICIPANT_COUNT' USING ERRCODE = 'P0001';
  END IF;

  SELECT organization_id,
         scenario_id,
         organization_scenario_id,
         store_id,
         date,
         start_time,
         COALESCE(max_participants, capacity, 8)
  INTO v_event_org_id, v_scenario_id, v_org_scenario_id, v_store_id, v_date, v_start_time, v_max_participants
  FROM schedule_events
  WHERE id = p_schedule_event_id
    AND is_cancelled = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EVENT_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- reservation_actor_auth_v1: 引数ではなくJWTの本人／対象組織の業務権限で判定。
  v_caller_org_id := public.get_user_organization_id();
  v_is_admin := COALESCE(public.reservation_actor_is_org_operator(v_event_org_id), false);
  v_is_staff := v_is_admin;

  -- 店舗の公演募集停止期間中は、お客様からの予約を受け付けない（スタッフの手入力は従来どおり可）
  IF NOT (v_is_admin OR v_is_staff)
     AND public.is_store_recruitment_paused(v_store_id, 'performance', v_date) THEN
    RAISE EXCEPTION 'RECRUITMENT_PAUSED' USING ERRCODE = 'P0046';
  END IF;

  IF p_customer_id IS NULL THEN
    IF NOT (v_is_admin OR v_is_staff) THEN
      RAISE EXCEPTION 'FORBIDDEN_STAFF_ONLY' USING ERRCODE = 'P0013';
    END IF;
    v_customer_user_id := NULL;
    v_customer_org_id := v_event_org_id;
  ELSE
    SELECT user_id, organization_id
    INTO v_customer_user_id, v_customer_org_id
    FROM public.customers
    WHERE id = p_customer_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CUSTOMER_NOT_FOUND' USING ERRCODE = 'P0009';
    END IF;

    IF v_customer_user_id IS DISTINCT FROM auth.uid()
       AND NOT (v_is_admin OR v_is_staff) THEN
      RAISE EXCEPTION 'FORBIDDEN_CUSTOMER' USING ERRCODE = 'P0011';
    END IF;

    -- 本人の共通顧客は旧organization_idの有無を問わず組織横断で利用できる。
    -- 他人を代理する業務操作では、組織付き顧客は対象公演と同じ組織に限る。
    IF v_customer_org_id IS NOT NULL
       AND v_customer_org_id IS DISTINCT FROM v_event_org_id
       AND v_customer_user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'CUSTOMER_ORG_MISMATCH' USING ERRCODE = 'P0012';
    END IF;
  END IF;

  SELECT COALESCE(SUM(participant_count), 0)
  INTO v_current_participants
  FROM reservations
  WHERE schedule_event_id = p_schedule_event_id
    AND status IN ('pending', 'confirmed', 'gm_confirmed', 'checked_in');

  v_available_seats := v_max_participants - v_current_participants;

  IF v_available_seats <= 0 THEN
    RAISE EXCEPTION 'SOLD_OUT' USING ERRCODE = 'P0003';
  END IF;

  IF p_participant_count > v_available_seats THEN
    RAISE EXCEPTION 'INSUFFICIENT_SEATS' USING ERRCODE = 'P0004';
  END IF;

  IF v_org_scenario_id IS NOT NULL THEN
    SELECT
      os.participation_fee,
      os.participation_costs,
      COALESCE(os.duration, sm.official_duration),
      COALESCE(os.override_title, sm.title)
    INTO v_participation_fee, v_participation_costs, v_duration, v_title
    FROM organization_scenarios os
    JOIN scenario_masters sm ON sm.id = os.scenario_master_id
    WHERE os.id = v_org_scenario_id;
  ELSIF v_scenario_id IS NOT NULL THEN
    SELECT participation_fee, participation_costs, duration, title
    INTO v_participation_fee, v_participation_costs, v_duration, v_title
    FROM scenarios_v2
    WHERE id = v_scenario_id;

    IF NOT FOUND THEN
      SELECT participation_fee, participation_costs, duration, title
      INTO v_participation_fee, v_participation_costs, v_duration, v_title
      FROM scenarios
      WHERE id = v_scenario_id;
    END IF;
  END IF;

  IF v_participation_fee IS NULL AND v_title IS NULL THEN
    RAISE EXCEPTION 'SCENARIO_NOT_FOUND' USING ERRCODE = 'P0017';
  END IF;

  SELECT COALESCE(bool_or(COALESCE(os.custom_holidays, '[]'::JSONB) ? v_date::TEXT), FALSE)
  INTO v_custom_holiday
  FROM organization_settings os
  WHERE os.organization_id = v_event_org_id;

  v_unit_price := public.calculate_booking_participation_fee(
    v_participation_fee, v_participation_costs, v_date, v_start_time, v_custom_holiday
  );

  v_total_price := v_unit_price * p_participant_count;

  IF p_customer_coupon_id IS NOT NULL THEN
    v_discount_amount := public.coupon_discount_for_event(
      p_customer_coupon_id, p_schedule_event_id, v_total_price, p_customer_id, NULL);
  END IF;

  v_final_price := v_total_price - v_discount_amount;
  v_requested_datetime := (v_date + v_start_time)::TIMESTAMP;

  IF p_reservation_number IS NULL OR length(trim(p_reservation_number)) = 0 THEN
    v_reservation_number := to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(random()::text), 1, 4));
  ELSE
    v_reservation_number := p_reservation_number;
  END IF;

  INSERT INTO reservations (
    schedule_event_id,
    scenario_id,
    store_id,
    customer_id,
    customer_name,
    customer_email,
    customer_phone,
    requested_datetime,
    duration,
    participant_count,
    participant_names,
    base_price,
    options_price,
    total_price,
    discount_amount,
    final_price,
    unit_price,
    payment_method,
    payment_status,
    status,
    customer_notes,
    reservation_number,
    created_by,
    organization_id,
    title
  ) VALUES (
    p_schedule_event_id,
    COALESCE(v_scenario_id, v_org_scenario_id),
    v_store_id,
    p_customer_id,
    p_customer_name,
    p_customer_email,
    p_customer_phone,
    v_requested_datetime,
    v_duration,
    p_participant_count,
    ARRAY[]::text[],
    v_total_price,
    0,
    v_total_price,
    v_discount_amount,
    v_final_price,
    v_unit_price,
    CASE WHEN p_customer_id IS NULL THEN 'staff' ELSE 'onsite' END,
    'pending',
    'confirmed',
    p_notes,
    v_reservation_number,
    auth.uid(),
    v_event_org_id,
    COALESCE(v_title, '')
  )
  RETURNING id INTO v_reservation_id;

  IF p_customer_coupon_id IS NOT NULL AND v_discount_amount > 0 THEN
    INSERT INTO coupon_usages (
      customer_coupon_id,
      reservation_id,
      discount_amount
    ) VALUES (
      p_customer_coupon_id,
      v_reservation_id,
      v_discount_amount
    )
    RETURNING id INTO v_coupon_usage_id;

    UPDATE reservations SET coupon_usage_id = v_coupon_usage_id WHERE id = v_reservation_id;

  END IF;

  -- current_participants は reservations INSERT 後の recalc トリガーが絶対値で再計算する。
  -- checked_in を含まない手動 += はトリガー結果を過小上書きするため削除。

  RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION "public"."create_reservation_with_lock_v2"("p_schedule_event_id" "uuid", "p_participant_count" integer, "p_customer_id" "uuid", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_notes" "text", "p_how_found" "text", "p_reservation_number" "text", "p_customer_coupon_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_organization_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_id UUID;
BEGIN
  -- まず users テーブルから取得（高速）
  SELECT organization_id INTO org_id
  FROM users
  WHERE id = auth.uid();
  
  IF org_id IS NOT NULL THEN
    RETURN org_id;
  END IF;
  
  -- フォールバック: staff テーブルから取得
  SELECT organization_id INTO org_id
  FROM staff
  WHERE user_id = auth.uid()
  LIMIT 1;
  
  RETURN org_id;
END;
$$;


ALTER FUNCTION "public"."current_organization_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_has_org_connection"("p_customer_id" "uuid", "p_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM reservations
    WHERE customer_id = p_customer_id
      AND organization_id = p_org_id
  )
  OR EXISTS (
    SELECT 1
    FROM private_groups pg
    JOIN private_group_members pgm ON pgm.group_id = pg.id
    JOIN customers c ON c.id = p_customer_id
    WHERE pg.organization_id = p_org_id
      AND c.user_id IS NOT NULL
      AND pgm.user_id = c.user_id
  )
$$;


ALTER FUNCTION "public"."customer_has_org_connection"("p_customer_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_play_history_action"("p_customer_id" "uuid", "p_action" "text" DEFAULT 'snapshot'::"text", "p_record" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor uuid := auth.uid();
  actor_role text;
  actor_org uuid;
  customer_row public.customers%ROWTYPE;
  staff_allowed boolean := false;
  own_profile boolean;
  has_contact boolean := false;
  can_edit boolean;
  affected uuid;
  result jsonb;
  master_id uuid;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'ログインが必要です' USING ERRCODE = '42501'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('snapshot','add_manual','update_manual_date','delete_manual','add_override','remove_override') THEN
    RAISE EXCEPTION '未対応の操作です' USING ERRCODE = '22023';
  END IF;
  -- Serializes the per-customer registration limit and permission check with
  -- writes. No customer data is changed by this lock.
  SELECT * INTO customer_row FROM public.customers WHERE id = p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '顧客を操作できません' USING ERRCODE = '42501'; END IF;
  SELECT role::text, organization_id INTO actor_role, actor_org FROM public.users WHERE id = actor;
  own_profile := customer_row.user_id IS NOT DISTINCT FROM actor;
  staff_allowed := COALESCE(actor_role IN ('admin','staff'),false) AND actor_org IS NOT NULL
    AND NOT (
      EXISTS (SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org)
      AND NOT EXISTS (SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org
        AND (status IS NULL OR status NOT IN ('inactive','resigned')))
    );
  IF staff_allowed THEN
    has_contact := customer_row.organization_id = actor_org
      OR public.customer_has_org_connection(p_customer_id, actor_org);
  END IF;
  IF NOT (own_profile OR COALESCE(actor_role = 'license_admin',false) OR (staff_allowed AND COALESCE(has_contact,false))) THEN
    RAISE EXCEPTION '顧客を操作できません' USING ERRCODE = '42501';
  END IF;
  -- An organization-owned profile may be readable from another organization
  -- through a booking, but that does not grant permission to change it.
  can_edit := own_profile OR COALESCE(actor_role = 'license_admin',false)
    OR (staff_allowed AND (customer_row.organization_id = actor_org
      OR (customer_row.organization_id IS NULL AND COALESCE(has_contact,false))));
  IF p_action <> 'snapshot' AND NOT can_edit THEN
    RAISE EXCEPTION 'この顧客の体験済み履歴を変更する権限がありません' USING ERRCODE = '42501';
  END IF;
  IF p_action = 'snapshot' THEN
    RETURN jsonb_build_object(
      'can_edit', can_edit,
      'manual', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id', h.id,
          'scenario_title', h.scenario_title,
          'scenario_master_id', h.scenario_master_id,
          'scenario_id', h.scenario_id,
          'played_at', h.played_at,
          'venue', h.venue
        ) ORDER BY h.created_at DESC, h.id DESC)
        FROM public.manual_play_history h WHERE h.customer_id=p_customer_id), '[]'::jsonb),
      'overrides', COALESCE((SELECT jsonb_agg(jsonb_build_object('scenario_master_id', o.scenario_master_id)
        ORDER BY o.created_at DESC, o.id DESC)
        FROM public.customer_played_overrides o WHERE o.customer_id=p_customer_id), '[]'::jsonb)
    );
  END IF;
  IF p_action = 'add_manual' THEN
    IF COALESCE(length(btrim(p_record->>'scenario_title')),0)=0 THEN
      RAISE EXCEPTION '作品名を入力してください' USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*) FROM public.manual_play_history WHERE customer_id=p_customer_id) >= 2000 THEN
      RAISE EXCEPTION '手動登録は最大2000件までです' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.manual_play_history(customer_id,scenario_title,scenario_master_id,played_at,venue,notes)
      VALUES(p_customer_id,btrim(p_record->>'scenario_title'),NULLIF(p_record->>'scenario_master_id','')::uuid,
        NULLIF(p_record->>'played_at','')::date,p_record->>'venue',p_record->>'notes')
      RETURNING to_jsonb(manual_play_history.*) INTO result;
    RETURN result;
  ELSIF p_action = 'update_manual_date' THEN
    UPDATE public.manual_play_history SET played_at=NULLIF(p_record->>'played_at','')::date,
      updated_at=now() WHERE id=(p_record->>'id')::uuid AND customer_id=p_customer_id
      RETURNING id INTO affected;
    RETURN jsonb_build_object('updated',affected IS NOT NULL);
  ELSIF p_action = 'delete_manual' THEN
    DELETE FROM public.manual_play_history WHERE id=(p_record->>'id')::uuid AND customer_id=p_customer_id RETURNING id INTO affected;
    RETURN jsonb_build_object('removed',affected IS NOT NULL);
  END IF;
  master_id := NULLIF(p_record->>'scenario_master_id','')::uuid;
  IF master_id IS NULL THEN RAISE EXCEPTION '作品IDが必要です' USING ERRCODE = '22023'; END IF;
  IF p_action = 'add_override' THEN
    INSERT INTO public.customer_played_overrides(customer_id,scenario_master_id,reason,created_by)
      VALUES(p_customer_id,master_id,p_record->>'reason',actor)
      ON CONFLICT(customer_id,scenario_master_id) DO NOTHING;
    RETURN jsonb_build_object('success',true);
  END IF;
  IF p_action = 'remove_override' THEN
    DELETE FROM public.customer_played_overrides WHERE customer_id=p_customer_id AND scenario_master_id=master_id RETURNING id INTO affected;
    RETURN jsonb_build_object('removed',affected IS NOT NULL);
  END IF;
  RAISE EXCEPTION '未対応の操作です' USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION "public"."customer_play_history_action"("p_customer_id" "uuid", "p_action" "text", "p_record" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."customer_play_history_action"("p_customer_id" "uuid", "p_action" "text", "p_record" "jsonb") IS 'Personal played history; verified owner or active CRM staff with customer contact. Snapshot returns minimal columns plus can_edit. No RLS policy changes.';



CREATE OR REPLACE FUNCTION "public"."delete_guest_member"("p_member_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_member RECORD;
BEGIN
  -- メンバーが存在し、ゲストユーザーであることを確認
  SELECT * INTO v_member 
  FROM public.private_group_members 
  WHERE id = p_member_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  
  -- ゲストユーザー（user_idがNULL）または主催者以外のみ削除可能
  IF v_member.is_organizer THEN
    RAISE EXCEPTION 'Cannot delete organizer';
  END IF;
  
  -- メンバーを削除（CASCADE設定により日程回答も削除される）
  DELETE FROM public.private_group_members
  WHERE id = p_member_id;
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."delete_guest_member"("p_member_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_guest_member"("p_member_id" "uuid") IS 'ゲストメンバーを削除する（日程回答も連動削除）';



CREATE OR REPLACE FUNCTION "public"."delete_guest_member"("p_member_id" "uuid", "p_invite_code" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_member RECORD;
BEGIN
  SELECT * INTO v_member
  FROM public.private_group_members
  WHERE id = p_member_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found' USING ERRCODE = 'P0404';
  END IF;

  IF v_member.is_organizer THEN
    RAISE EXCEPTION 'Cannot delete organizer' USING ERRCODE = 'P0400';
  END IF;

  -- --------------------------------------------------------
  -- 認証済みユーザー: 本人 or そのグループの主催者のみ
  -- --------------------------------------------------------
  IF auth.uid() IS NOT NULL THEN
    -- 本人による退出
    IF v_member.user_id = auth.uid() THEN
      NULL; -- OK

    -- グループの主催者による削除
    ELSIF EXISTS (
      SELECT 1 FROM public.private_group_members
      WHERE group_id = v_member.group_id
        AND user_id = auth.uid()
        AND is_organizer = true
    ) THEN
      NULL; -- OK

    ELSE
      RAISE EXCEPTION 'Unauthorized: not a member or organizer of this group'
        USING ERRCODE = 'P0401';
    END IF;

  -- --------------------------------------------------------
  -- 未認証ゲスト: invite_code でグループ所属を確認
  -- --------------------------------------------------------
  ELSE
    IF p_invite_code IS NULL OR p_invite_code = '' THEN
      RAISE EXCEPTION 'Invite code required for guest deletion'
        USING ERRCODE = 'P0401';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.private_groups pg
      WHERE pg.id = v_member.group_id
        AND pg.invite_code = p_invite_code
    ) THEN
      RAISE EXCEPTION 'Invalid invite code'
        USING ERRCODE = 'P0401';
    END IF;
  END IF;

  DELETE FROM public.private_group_members WHERE id = p_member_id;
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."delete_guest_member"("p_member_id" "uuid", "p_invite_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_guest_member"("p_member_id" "uuid", "p_invite_code" "text") IS 'ゲストメンバーを削除する。認証済みは本人/主催者のみ、未認証は invite_code で所属確認。';



CREATE OR REPLACE FUNCTION "public"."delete_org_scenario"("p_scenario_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_org_id UUID;
  v_user_org_id UUID;
  v_user_id UUID;
  v_title TEXT;
  v_event_count INT;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', '認証されていません');
  END IF;

  -- ユーザーの組織IDを取得
  SELECT organization_id INTO v_user_org_id
  FROM users WHERE id = v_user_id LIMIT 1;
  
  IF v_user_org_id IS NULL THEN
    SELECT organization_id INTO v_user_org_id
    FROM staff WHERE user_id = v_user_id LIMIT 1;
  END IF;
  
  -- シナリオ情報を取得
  SELECT os.organization_id, sm.title 
  INTO v_org_id, v_title
  FROM organization_scenarios os
  LEFT JOIN scenario_masters sm ON os.scenario_master_id = sm.id
  WHERE os.id = p_scenario_id;
  
  IF v_org_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'シナリオが見つかりません');
  END IF;
  
  -- 権限チェック
  IF v_user_org_id IS NULL OR (v_org_id != v_user_org_id AND NOT is_license_admin()) THEN
    RETURN json_build_object(
      'success', false, 
      'error', '権限がありません',
      'debug', json_build_object('user_id', v_user_id, 'user_org_id', v_user_org_id, 'scenario_org_id', v_org_id)
    );
  END IF;
  
  -- schedule_events の organization_scenario_id を NULL に（外部キー制約を回避）
  UPDATE schedule_events
  SET organization_scenario_id = NULL
  WHERE organization_scenario_id = p_scenario_id;
  
  GET DIAGNOSTICS v_event_count = ROW_COUNT;
  
  -- organization_scenarios を削除
  DELETE FROM organization_scenarios WHERE id = p_scenario_id;
  
  RETURN json_build_object(
    'success', true, 
    'title', v_title,
    'unlinked_events', v_event_count
  );
END;
$$;


ALTER FUNCTION "public"."delete_org_scenario"("p_scenario_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_org_scenario"("p_scenario_id" "uuid") IS '組織シナリオを削除（解除）。SECURITY DEFINER で RLS をバイパス。';



CREATE OR REPLACE FUNCTION "public"."delete_organization_scenario_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1 FROM public.organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Scenario unavailable' USING ERRCODE='23503'; END IF;
  PERFORM 1 FROM public.staff s WHERE s.organization_id=p_organization_id AND EXISTS(
    SELECT 1 FROM public.staff_scenario_assignments a WHERE a.organization_id=p_organization_id AND a.scenario_master_id=p_scenario_master_id AND a.staff_id=s.id) ORDER BY s.id FOR UPDATE;
  UPDATE public.reservations SET scenario_master_id=NULL WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id;
  UPDATE public.schedule_events SET scenario_master_id=NULL WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id;
  DELETE FROM public.staff_scenario_assignments WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id;
  DELETE FROM public.performance_kits WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id;
  DELETE FROM public.organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id;
  RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."delete_organization_scenario_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_private_booking_request_atomic"("p_reservation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_user uuid:=auth.uid(); v_org uuid; v_role text; v_group_id uuid; v_group public.private_groups; v_res public.reservations;
BEGIN
 SELECT role::text INTO v_role FROM users WHERE id=v_user;
 v_org:=public.get_user_organization_id();
 IF v_user IS NULL OR v_org IS NULL OR v_role IS NULL OR v_role NOT IN ('admin','staff','license_admin') THEN
  RAISE EXCEPTION '貸切申込を削除する権限がありません' USING ERRCODE='42501';
 END IF;
 SELECT private_group_id INTO v_group_id FROM reservations WHERE id=p_reservation_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION '対象の貸切申込が見つかりません' USING ERRCODE='42501'; END IF;
 -- Guest writes lock group first. Approval/cancellation lock reservation first,
 -- so never wait on the reservation while holding the group lock.
 IF v_group_id IS NOT NULL THEN
  SELECT * INTO v_group FROM private_groups WHERE id=v_group_id FOR UPDATE;
  IF NOT FOUND OR v_group.organization_id IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION '申込とグループの所属を確認できません' USING ERRCODE='42501';
  END IF;
 END IF;
 SELECT * INTO v_res FROM reservations WHERE id=p_reservation_id AND organization_id=v_org FOR UPDATE NOWAIT;
 IF NOT FOUND OR v_res.private_group_id IS DISTINCT FROM v_group_id THEN
  RAISE EXCEPTION '申込が変更されました。再読み込みしてください' USING ERRCODE='40001';
 END IF;
 IF v_res.reservation_source IS DISTINCT FROM 'web_private' THEN
  RAISE EXCEPTION 'この画面から削除できるのは貸切申込のみです' USING ERRCODE='22023';
 END IF;
 IF v_res.status NOT IN ('pending','cancelled') OR v_res.schedule_event_id IS NOT NULL OR v_res.event_id IS NOT NULL
  OR EXISTS(SELECT 1 FROM schedule_events WHERE reservation_id=v_res.id)
  OR coalesce(v_res.payment_status,'pending')<>'pending' THEN
  RAISE EXCEPTION '公演・支払履歴がある申込は完全削除できません。取消操作で履歴を残してください' USING ERRCODE='22023';
 END IF;
 IF v_group_id IS NOT NULL AND (v_group.reservation_id IS NOT NULL AND v_group.reservation_id<>v_res.id
  OR EXISTS(SELECT 1 FROM reservations WHERE private_group_id=v_group_id AND id<>v_res.id)) THEN
  RAISE EXCEPTION '別の予約でも使われているグループは削除できません' USING ERRCODE='22023';
 END IF;
 INSERT INTO audit_logs(user_id,organization_id,action,resource_type,resource_id,old_values)
 VALUES(v_user,v_org,'private_booking.request_delete','reservations',v_res.id,
   jsonb_build_object('reservation',to_jsonb(v_res),'group',CASE WHEN v_group_id IS NOT NULL THEN to_jsonb(v_group) END));
 -- Restrictive FKs intentionally retain billing, coupon claims, compensation and Discord history.
 -- Any failure here or during the group cascade rolls back the audit and every deletion.
 DELETE FROM reservations WHERE id=v_res.id;
 IF v_group_id IS NOT NULL THEN DELETE FROM private_groups WHERE id=v_group_id; END IF;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'この申込は別の処理で更新中です。少し待って再度お試しください' USING ERRCODE='55P03';
WHEN foreign_key_violation THEN
 RAISE EXCEPTION '請求・補償・通知などの関連履歴があるため完全削除できません。取消操作で履歴を残してください' USING ERRCODE='23503';
END $$;


ALTER FUNCTION "public"."delete_private_booking_request_atomic"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_private_group"("p_group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_group RECORD;
  v_caller_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'ログインが必要です' USING ERRCODE = 'P0001';
  END IF;

  SELECT id, organizer_id, status
  INTO v_group
  FROM private_groups
  WHERE id = p_group_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'グループが見つかりません' USING ERRCODE = 'P0002';
  END IF;

  IF v_group.organizer_id != v_caller_id THEN
    RAISE EXCEPTION '削除できるのは主催者のみです' USING ERRCODE = 'P0010';
  END IF;

  IF v_group.status NOT IN ('gathering', 'cancelled') THEN
    RAISE EXCEPTION '削除できるのは予約申請前または キャンセル済みのグループのみです' USING ERRCODE = 'P0003';
  END IF;

  -- 依存テーブルを順番に削除（CASCADE があるが明示的に削除して確実に）
  DELETE FROM private_group_date_responses WHERE group_id = p_group_id;
  DELETE FROM private_group_candidate_dates WHERE group_id = p_group_id;
  DELETE FROM private_group_messages WHERE group_id = p_group_id;
  DELETE FROM private_group_members WHERE group_id = p_group_id;
  DELETE FROM private_groups WHERE id = p_group_id;
END;
$$;


ALTER FUNCTION "public"."delete_private_group"("p_group_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_private_group"("p_group_id" "uuid") IS '主催者がグループを削除する（gathering/cancelled のみ）。SECURITY DEFINER で RLS をバイパスし一括削除。';



CREATE OR REPLACE FUNCTION "public"."dispatch_performance_recruitment_checks"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE p record; base_url text; cron_key text;
BEGIN
 SELECT value INTO base_url FROM app_config WHERE key='supabase_url';
 SELECT value INTO cron_key FROM app_config WHERE key='trigger_secret';
 IF base_url IS NULL OR cron_key IS NULL THEN RAISE EXCEPTION '募集判定の接続設定がありません'; END IF;
 FOR p IN SELECT id AS organization_id FROM organizations pol WHERE is_active
   AND (EXISTS(SELECT 1 FROM schedule_events e WHERE e.organization_id=pol.id
     AND NOT e.is_cancelled AND e.category='open'
     AND (EXISTS(SELECT 1 FROM performance_recruitment_deadlines active_deadline
       WHERE active_deadline.schedule_event_id=e.id AND active_deadline.organization_id=e.organization_id AND active_deadline.status='active')
       OR (public.get_performance_judgment_deadline(e.organization_id,e.id) <= now() AND NOT EXISTS(SELECT 1 FROM performance_cancellation_logs l WHERE l.schedule_event_id=e.id AND (l.check_type='four_hours_before' OR l.result='confirmed'))))
     AND ((e.date+e.start_time) AT TIME ZONE 'Asia/Tokyo'>now()
       OR EXISTS(SELECT 1 FROM performance_recruitment_deadlines d WHERE d.schedule_event_id=e.id AND d.status='active')))
     OR EXISTS(SELECT 1 FROM performance_recruitment_notices n WHERE n.organization_id=pol.id
       AND n.status IN ('pending','failed','sending') AND n.attempts<10 AND n.created_at>now()-interval '1 day'
       AND (n.kind<>'extension' OR (n.withdrawn_at IS NULL AND EXISTS(
         SELECT 1 FROM performance_recruitment_deadlines notice_deadline
         WHERE notice_deadline.schedule_event_id=n.schedule_event_id
           AND notice_deadline.organization_id=n.organization_id
           AND notice_deadline.cycle=n.cycle AND notice_deadline.status='active'
           AND notice_deadline.deadline>now()))))
     OR EXISTS(SELECT 1 FROM recruitment_x_posts x WHERE x.organization_id=pol.id AND x.status IN ('pending','failed','sending') AND x.attempts<10 AND x.created_at>now()-interval '1 day'))
 LOOP
   PERFORM net.http_post(url:=rtrim(base_url,'/')||'/functions/v1/check-performance-cancellation',
     headers:=jsonb_build_object('Content-Type','application/json','x-recruitment-cron-secret',cron_key,'x-cron-secret',cron_key),
     body:=jsonb_build_object('check_type','recruitment_deadline','organization_id',p.organization_id), timeout_milliseconds:=30000);
 END LOOP;
END;
$$;


ALTER FUNCTION "public"."dispatch_performance_recruitment_checks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_assignment_scenario_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1 FROM public.organization_scenarios WHERE organization_id=NEW.organization_id
    AND scenario_master_id=coalesce(NEW.scenario_master_id,NEW.scenario_id) FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Scenario unavailable for assignment' USING ERRCODE='23503'; END IF;
  RETURN NEW;
END;
$$;


