CREATE OR REPLACE FUNCTION "public"."enforce_coupon_performance_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r public.reservations; cc public.customer_coupons;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.customer_coupon_id IS DISTINCT FROM OLD.customer_coupon_id OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
   OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount THEN
   RAISE EXCEPTION '使用履歴の条件は変更できません。取消後に再利用してください' USING ERRCODE='P0028';
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO r FROM public.reservations WHERE id=NEW.reservation_id;
 SELECT * INTO cc FROM public.customer_coupons WHERE id=NEW.customer_coupon_id;
 IF r.id IS NULL OR r.organization_id IS DISTINCT FROM cc.organization_id OR r.status NOT IN ('confirmed','checked_in')
  OR NOT public.can_use_coupon_reservation(cc.customer_id,r.id) THEN
  RAISE EXCEPTION '利用可能な予約を指定してください' USING ERRCODE='P0028';
 END IF;
 NEW.discount_amount:=public.coupon_discount_for_event(cc.id,r.schedule_event_id,r.total_price,cc.customer_id,r.id);
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_coupon_performance_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_performance_recruitment_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE deadline_at timestamptz;
BEGIN
 IF NEW.status NOT IN ('pending','confirmed','gm_confirmed','checked_in') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.schedule_event_id IS NOT DISTINCT FROM OLD.schedule_event_id
   AND OLD.status IN ('pending','confirmed','gm_confirmed','checked_in') AND NEW.participant_count<=OLD.participant_count THEN RETURN NEW; END IF;
 PERFORM 1 FROM schedule_events WHERE id=NEW.schedule_event_id FOR UPDATE;
 SELECT effective_booking_deadline INTO deadline_at FROM get_performance_booking_window(NEW.schedule_event_id);
 IF deadline_at IS NOT NULL AND now()>=deadline_at THEN RAISE EXCEPTION '予約の受付期限を過ぎています' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_performance_recruitment_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_private_group_candidate_deadline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE g RECORD;
BEGIN
 IF TG_OP='UPDATE' AND NEW.date IS NOT DISTINCT FROM OLD.date AND NEW.group_id IS NOT DISTINCT FROM OLD.group_id THEN RETURN NEW; END IF;
 SELECT organization_id,COALESCE(scenario_master_id,scenario_id) AS scenario_id INTO g FROM public.private_groups WHERE id=NEW.group_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PRIVATE_GROUP_NOT_FOUND' USING ERRCODE='P0045'; END IF;
 -- Only a nested event synchronization may move an already confirmed candidate
 -- inside the new-request deadline. Direct candidate RPCs remain subject to it.
 IF TG_OP='UPDATE' AND pg_trigger_depth()>1 AND NEW.group_id=OLD.group_id AND EXISTS (
   SELECT 1 FROM public.private_groups pg JOIN public.reservations r ON r.id=pg.reservation_id
   JOIN public.schedule_events e ON e.id=r.schedule_event_id
   WHERE pg.id=NEW.group_id AND pg.status='confirmed' AND r.private_group_id=pg.id
    AND r.organization_id=pg.organization_id AND e.organization_id=pg.organization_id
    AND r.status IN ('confirmed','gm_confirmed','checked_in','completed')
    AND e.date=NEW.date AND e.start_time=NEW.start_time::time AND e.end_time=NEW.end_time::time
 ) THEN RETURN NEW; END IF;
 PERFORM public.assert_private_booking_candidate_date(g.organization_id,g.scenario_id,NEW.date);
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_private_group_candidate_deadline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_private_reservation_deadline"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE c JSONB;
BEGIN
 IF NEW.reservation_source IS DISTINCT FROM 'web_private' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.candidate_datetimes IS NOT DISTINCT FROM OLD.candidate_datetimes AND NEW.scenario_id IS NOT DISTINCT FROM OLD.scenario_id AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id AND NEW.reservation_source IS NOT DISTINCT FROM OLD.reservation_source THEN RETURN NEW; END IF;
 IF jsonb_typeof(NEW.candidate_datetimes->'candidates') IS DISTINCT FROM 'array' OR (TG_OP='INSERT' AND jsonb_array_length(NEW.candidate_datetimes->'candidates')=0) THEN
  RAISE EXCEPTION 'PRIVATE_BOOKING_CANDIDATES_REQUIRED' USING ERRCODE='P0045';
 END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(NEW.candidate_datetimes->'candidates') LOOP
  -- 受付済みの日付の承認・状態変更・候補削除は、受付締切で再拒否しない。
  IF TG_OP='UPDATE' AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
     AND NEW.scenario_id IS NOT DISTINCT FROM OLD.scenario_id
     AND NEW.reservation_source IS NOT DISTINCT FROM OLD.reservation_source
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(OLD.candidate_datetimes->'candidates','[]'::JSONB)) old_candidate WHERE old_candidate->>'date'=c->>'date') THEN CONTINUE; END IF;
  PERFORM public.assert_private_booking_candidate_date(NEW.organization_id,NEW.scenario_id,(c->>'date')::DATE);
 END LOOP;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_private_reservation_deadline"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."schedule_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "date" "date" NOT NULL,
    "venue" "text" NOT NULL,
    "scenario" "text" NOT NULL,
    "gms" "text"[] DEFAULT '{}'::"text"[],
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "category" "text" DEFAULT 'open'::"text" NOT NULL,
    "reservation_info" "text",
    "notes" "text",
    "is_cancelled" boolean DEFAULT false,
    "scenario_id" "uuid",
    "store_id" "uuid",
    "start_at" timestamp with time zone,
    "end_at" timestamp with time zone,
    "published" boolean DEFAULT true,
    "capacity" integer,
    "status" "text" DEFAULT 'scheduled'::"text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "max_participants" integer,
    "reservation_deadline_hours" integer DEFAULT 0,
    "is_reservation_enabled" boolean DEFAULT true,
    "reservation_notes" "text",
    "current_participants" integer DEFAULT 0,
    "time_slot" "text",
    "gm_roles" "jsonb" DEFAULT '{}'::"jsonb",
    "organization_id" "uuid" NOT NULL,
    "venue_rental_fee" integer DEFAULT 12000,
    "total_revenue" integer DEFAULT 0,
    "gm_cost" integer,
    "license_cost" integer DEFAULT 0,
    "participant_count" integer DEFAULT 0,
    "reservation_name" "text",
    "is_tentative" boolean DEFAULT false,
    "reservation_id" "uuid",
    "is_reservation_name_overwritten" boolean DEFAULT false,
    "is_private_request" boolean DEFAULT false,
    "organization_scenario_id" "uuid",
    "is_recruitment_extended" boolean DEFAULT false,
    "is_private_booking" boolean DEFAULT false,
    "is_extended" boolean DEFAULT false,
    "extended_at" timestamp with time zone,
    "cancellation_reason" "text",
    "cancelled_at" timestamp with time zone,
    "scenario_master_id" "uuid",
    "reservation_confirmation_template" "text",
    "private_confirm_template" "text",
    "booking_cutoff_minutes" integer,
    "gm_cancel_epoch" "uuid" DEFAULT "gen_random_uuid"(),
    CONSTRAINT "schedule_events_booking_cutoff_minutes_check" CHECK ((("booking_cutoff_minutes" >= 0) AND ("booking_cutoff_minutes" <= 1440))),
    CONSTRAINT "schedule_events_category_check" CHECK (("category" = ANY (ARRAY['open'::"text", 'private'::"text", 'gmtest'::"text", 'testplay'::"text", 'offsite'::"text", 'venue_rental'::"text", 'venue_rental_free'::"text", 'package'::"text", 'mtg'::"text", 'memo'::"text", 'unpublished'::"text", 'tentative'::"text"])))
);


ALTER TABLE "public"."schedule_events" OWNER TO "postgres";


COMMENT ON COLUMN "public"."schedule_events"."scenario_id" IS '旧シナリオID（廃止予定）。scenario_master_id を使用してください';



COMMENT ON COLUMN "public"."schedule_events"."max_participants" IS '最大参加可能人数';



COMMENT ON COLUMN "public"."schedule_events"."reservation_deadline_hours" IS '予約締め切り時間（公演開始の何時間前）。0 の場合は公演開始まで予約可。';



COMMENT ON COLUMN "public"."schedule_events"."is_reservation_enabled" IS '予約受付可能フラグ（false=予約受付停止）';



COMMENT ON COLUMN "public"."schedule_events"."reservation_notes" IS '予約時の注意事項（顧客に表示）';



COMMENT ON COLUMN "public"."schedule_events"."gm_roles" IS 'GM役割情報（JSON）';



COMMENT ON COLUMN "public"."schedule_events"."venue_rental_fee" IS '場所貸し公演料金';



COMMENT ON COLUMN "public"."schedule_events"."gm_cost" IS '保存済みGM費用。NULLは未記録（公演日時点の設定で算出）、0は明示された0円。旧データの記録根拠は別途確認し自動変換しない。';



COMMENT ON COLUMN "public"."schedule_events"."reservation_name" IS '貸切予約の予約者名。MMQ予約の場合は顧客名を、手動入力の場合は編集した値を保存';



COMMENT ON COLUMN "public"."schedule_events"."is_tentative" IS '仮状態フラグ - trueの場合は非公開扱い';



COMMENT ON COLUMN "public"."schedule_events"."reservation_id" IS '貸切リクエストの元reservation ID';



COMMENT ON COLUMN "public"."schedule_events"."is_reservation_name_overwritten" IS '予約者名が手動で上書きされたかどうか';



COMMENT ON COLUMN "public"."schedule_events"."is_private_request" IS '貸切リクエスト由来の公演かどうか';



COMMENT ON COLUMN "public"."schedule_events"."is_recruitment_extended" IS '前日チェックで過半数達成し、募集延長された公演かどうか';



COMMENT ON COLUMN "public"."schedule_events"."is_private_booking" IS '貸切公演かどうか';



COMMENT ON COLUMN "public"."schedule_events"."is_extended" IS '募集期間延長中フラグ（前日判定で過半数達成・満席未達の場合true）';



COMMENT ON COLUMN "public"."schedule_events"."extended_at" IS '募集期間延長判定日時';



COMMENT ON COLUMN "public"."schedule_events"."cancellation_reason" IS '公演中止理由（手動中止時に設定）';



COMMENT ON COLUMN "public"."schedule_events"."cancelled_at" IS '公演中止日時';



COMMENT ON COLUMN "public"."schedule_events"."reservation_confirmation_template" IS '予約確定メールの公演上書き。NULL/空なら作品上書きまたは店舗テンプレを使う';



COMMENT ON COLUMN "public"."schedule_events"."private_confirm_template" IS '貸切確定メールの公演上書き。NULL/空なら作品上書きまたは店舗テンプレを使う';



CREATE OR REPLACE FUNCTION "public"."enqueue_gm_assignment_released"("p_event" "public"."schedule_events", "p_names" "text"[], "p_kind" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE s record; v_body text; v_head text;
BEGIN
  IF p_event.organization_id IS NULL OR coalesce(cardinality(p_names),0)=0 THEN RETURN; END IF;
  v_head := CASE p_kind
    WHEN 'cancelled' THEN '公演が中止になりました。担当予定の解除をご確認ください。'
    WHEN 'deleted' THEN '公演が削除されました。担当予定の解除をご確認ください。'
    ELSE '担当が外れました。担当予定の解除をご確認ください。' END;
  v_body := v_head||chr(10)||p_event.date::text||' '||coalesce(to_char(p_event.start_time,'HH24:MI'),'')
    ||CASE WHEN p_event.end_time IS NOT NULL THEN '〜'||to_char(p_event.end_time,'HH24:MI') ELSE '' END
    ||chr(10)||'作品：'||coalesce(nullif(p_event.scenario,''),'未定')
    ||chr(10)||'会場：'||coalesce(nullif(p_event.venue,''),'未定')
    ||CASE WHEN nullif(btrim(coalesce(p_reason,'')),'') IS NOT NULL THEN chr(10)||'理由：'||btrim(p_reason) ELSE '' END;
  FOR s IN SELECT id,discord_channel_id FROM public.staff
    WHERE organization_id=p_event.organization_id AND name=ANY(p_names) AND status='active'
      AND nullif(btrim(coalesce(discord_channel_id,'')),'') IS NOT NULL
  LOOP
    INSERT INTO public.discord_notification_queue
      (organization_id,notification_type,reference_id,dedupe_key,webhook_url,message_payload,max_retries)
    VALUES (p_event.organization_id,'gm_assignment_released',p_event.id,
      p_event.id::text||':'||p_kind||':'||s.id::text||':'||txid_current()::text,
      'https://discord.com/api/v10/channels/'||btrim(s.discord_channel_id)||'/messages',
      jsonb_build_object('content',v_body,'allowed_mentions',jsonb_build_object('parse','[]'::jsonb)),3)
    ON CONFLICT (organization_id,notification_type,dedupe_key) DO NOTHING;
  END LOOP;
END $$;


ALTER FUNCTION "public"."enqueue_gm_assignment_released"("p_event" "public"."schedule_events", "p_names" "text"[], "p_kind" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_legacy_private_approval_delivery"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_kind" "text", "p_snapshot" "jsonb", "p_correction_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE r public.reservations%ROWTYPE; recipient text; delivery_key text; existing public.private_booking_approval_deliveries%ROWTYPE; new_id uuid;
BEGIN
 IF p_kind NOT IN ('confirmation_email','gm_email','gm_discord') OR p_kind IS NULL THEN
  RAISE EXCEPTION 'INVALID_DELIVERY_KIND' USING ERRCODE='22023';
 END IF;
 SELECT * INTO STRICT r FROM public.reservations WHERE id=p_reservation_id AND organization_id=p_organization_id FOR UPDATE;
 IF r.schedule_event_id IS NULL OR r.status NOT IN ('confirmed','gm_confirmed')
  OR p_snapshot->>'reservationId' IS DISTINCT FROM r.id::text
  OR p_snapshot->>'organizationId' IS DISTINCT FROM r.organization_id::text
  OR p_snapshot->>'scheduleEventId' IS DISTINCT FROM r.schedule_event_id::text THEN
  RAISE EXCEPTION 'APPROVAL_CHANGED' USING ERRCODE='55000';
 END IF;
 recipient:=CASE WHEN p_kind='confirmation_email' THEN 'customer' ELSE p_snapshot->>'gmId' END;
 IF recipient IS NULL THEN RAISE EXCEPTION 'INVALID_RECIPIENT' USING ERRCODE='22023'; END IF;
 IF p_correction_id IS NULL THEN
  SELECT * INTO existing FROM public.private_booking_approval_deliveries
   WHERE organization_id=r.organization_id AND reservation_id=r.id AND schedule_event_id=r.schedule_event_id
    AND kind=p_kind AND recipient_key=recipient AND compatibility_key IS NULL ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN RETURN existing.id; END IF;
 ELSIF p_kind<>'confirmation_email' THEN RAISE EXCEPTION 'INVALID_CORRECTION_KIND' USING ERRCODE='22023';
 END IF;
 delivery_key:=CASE WHEN p_correction_id IS NULL THEN 'legacy/'||r.schedule_event_id::text ELSE 'correction/'||p_correction_id::text END
  ||'/'||r.id::text||'/'||p_kind||'/'||recipient;
 SELECT * INTO existing FROM public.private_booking_approval_deliveries WHERE compatibility_key=delivery_key;
 IF FOUND THEN
  IF p_correction_id IS NOT NULL AND (existing.snapshot->>'emailSubject' IS DISTINCT FROM p_snapshot->>'emailSubject'
   OR existing.snapshot->>'templateOverride' IS DISTINCT FROM p_snapshot->>'templateOverride') THEN
   RAISE EXCEPTION 'CORRECTION_REQUEST_CONFLICT' USING ERRCODE='22023';
  END IF;
  RETURN existing.id;
 END IF;
 INSERT INTO public.private_booking_approval_deliveries(compatibility_key,organization_id,reservation_id,schedule_event_id,kind,recipient_key,snapshot)
 VALUES(delivery_key,r.organization_id,r.id,r.schedule_event_id,p_kind,recipient,p_snapshot) RETURNING id INTO new_id;
 IF NOT public.is_private_approval_delivery_current(new_id) THEN
  RAISE EXCEPTION 'APPROVAL_CHANGED' USING ERRCODE='55000';
 END IF;
 RETURN new_id;
END $$;


ALTER FUNCTION "public"."enqueue_legacy_private_approval_delivery"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_kind" "text", "p_snapshot" "jsonb", "p_correction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_private_approval_deliveries"("p_request_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE
 receipt public.private_booking_approval_requests%ROWTYPE;
 r public.reservations%ROWTYPE; e public.schedule_events%ROWTYPE; s public.staff%ROWTYPE;
 booking jsonb; gm_ids uuid[]; gm_id uuid; recipient text; recipient_name text; job_count integer;
 store_name text; store_address text;
 actor_staff_id uuid; actor_name text; event_snapshot jsonb;
BEGIN
 SELECT * INTO STRICT receipt FROM public.private_booking_approval_requests WHERE id=p_request_id;
 SELECT * INTO STRICT r FROM public.reservations WHERE id=receipt.reservation_id AND organization_id=receipt.organization_id;
 SELECT * INTO STRICT e FROM public.schedule_events
  WHERE id=(receipt.result->>'schedule_event_id')::uuid AND organization_id=receipt.organization_id;
 IF r.schedule_event_id IS DISTINCT FROM e.id OR e.is_cancelled IS DISTINCT FROM false
  OR r.status NOT IN ('confirmed','gm_confirmed') THEN
  RAISE EXCEPTION 'APPROVAL_NOTIFICATION_NOT_CURRENT' USING ERRCODE='22023';
 END IF;
 SELECT name,address INTO STRICT store_name,store_address FROM public.stores
  WHERE id=e.store_id AND organization_id=receipt.organization_id;
 recipient:=nullif(btrim(r.customer_email),''); recipient_name:=coalesce(nullif(r.customer_name,''),'お客様');
 IF recipient IS NULL AND r.customer_id IS NOT NULL THEN
  SELECT nullif(btrim(c.email),''),coalesce(nullif(c.name,''),recipient_name) INTO recipient,recipient_name
   FROM public.customers c WHERE c.id=r.customer_id AND (c.organization_id=r.organization_id OR c.organization_id IS NULL);
 END IF;
 booking:=jsonb_build_object(
  'reservationId',r.id,'organizationId',r.organization_id,'scheduleEventId',e.id,'storeId',e.store_id,
  'scenarioMasterId',coalesce(e.scenario_master_id,r.scenario_master_id),'scenarioTitle',coalesce(nullif(e.scenario,''),r.scenario_title,''),
  'eventDate',e.date,'startTime',e.start_time,'endTime',e.end_time,'storeName',store_name,'storeAddress',store_address,
  'customerEmail',recipient,'customerName',coalesce(recipient_name,'お客様'),'participantCount',r.participant_count,
  'totalPrice',coalesce(r.final_price,r.total_price,0),'reservationNumber',r.reservation_number,'notes',r.customer_notes,
  'groupId',r.private_group_id,'eventGms',to_jsonb(e.gms));
 INSERT INTO public.private_booking_approval_deliveries(request_id,organization_id,reservation_id,schedule_event_id,kind,recipient_key,snapshot)
 VALUES(receipt.id,r.organization_id,r.id,e.id,'confirmation_email','customer',booking);
 gm_ids:=array_remove(ARRAY[(receipt.request_payload->>'gm')::uuid,(receipt.request_payload->>'sub_gm')::uuid],NULL);
 FOR gm_id IN SELECT DISTINCT unnest(gm_ids) LOOP
  SELECT * INTO STRICT s FROM public.staff WHERE id=gm_id AND organization_id=r.organization_id AND status='active';
  IF NOT coalesce(s.name=ANY(e.gms),false) THEN RAISE EXCEPTION 'APPROVAL_GM_NOT_ASSIGNED' USING ERRCODE='22023'; END IF;
  INSERT INTO public.private_booking_approval_deliveries(request_id,organization_id,reservation_id,schedule_event_id,kind,recipient_key,snapshot)
  SELECT receipt.id,r.organization_id,r.id,e.id,kind,s.id::text,
   booking||jsonb_build_object('gmId',s.id,'gmName',s.name,'gmEmail',nullif(btrim(s.email),''),
    'gmDiscordChannelId',nullif(btrim(s.discord_channel_id),''),'gmDiscordUserId',nullif(btrim(s.discord_user_id),''))
  FROM unnest(ARRAY['gm_email','gm_discord']) AS kind;
 END LOOP;
 SELECT id,name INTO actor_staff_id,actor_name FROM public.staff
  WHERE user_id=receipt.actor_id AND organization_id=r.organization_id AND status='active';
 SELECT jsonb_object_agg(key,value) INTO event_snapshot FROM jsonb_each(to_jsonb(e))
  WHERE key IN ('id','organization_id','date','venue','store_id','scenario','scenario_master_id','gms','gm_roles',
   'start_time','end_time','category','capacity','max_participants','current_participants','notes','is_cancelled',
   'is_tentative','is_reservation_enabled','is_private_request','reservation_name','time_slot','venue_rental_fee');
 INSERT INTO public.schedule_event_history(schedule_event_id,organization_id,event_date,store_id,time_slot,
  changed_by_user_id,changed_by_staff_id,changed_by_name,action_type,new_values,notes)
 VALUES(e.id,r.organization_id,e.date,e.store_id,e.time_slot,receipt.actor_id,actor_staff_id,
  coalesce(actor_name,'管理者')||'（貸切管理）','create',event_snapshot,'貸切予約承認により作成');
 SELECT count(*) INTO job_count FROM public.private_booking_approval_deliveries WHERE request_id=receipt.id;
 RETURN job_count;
END $$;


ALTER FUNCTION "public"."enqueue_private_approval_deliveries"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_private_cancellation"("p_event" "public"."schedule_events") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE s record; v_epoch uuid; v_body text;
BEGIN
  IF p_event.organization_id IS NULL OR NOT (coalesce(p_event.is_private_booking,false) OR p_event.category='private') THEN RETURN; END IF;
  v_epoch := coalesce(p_event.gm_cancel_epoch,p_event.id);
  v_body := format('貸切公演がキャンセルされました。担当予定の解除をご確認ください。%s%s %s〜%s%s作品：%s%s会場：%s',
    chr(10),p_event.date,to_char(p_event.start_time,'HH24:MI'),to_char(p_event.end_time,'HH24:MI'),
    chr(10),p_event.scenario,chr(10),p_event.venue);
  FOR s IN SELECT id,name,discord_channel_id FROM public.staff
    WHERE organization_id=p_event.organization_id AND name=ANY(p_event.gms)
  LOOP
    INSERT INTO public.discord_notification_queue
      (organization_id,notification_type,reference_id,dedupe_key,webhook_url,message_payload,max_retries)
    VALUES (p_event.organization_id,'private_cancellation',NULL,
      p_event.id::text||':'||v_epoch::text||':'||s.id::text,
      CASE WHEN nullif(trim(s.discord_channel_id),'') IS NOT NULL THEN 'https://discord.com/api/v10/channels/'||trim(s.discord_channel_id)||'/messages' ELSE '' END,
      jsonb_build_object('content',v_body,'staff_id',s.id,'event_id',p_event.id,'epoch',v_epoch,'allowed_mentions',jsonb_build_object('parse','[]'::jsonb)),3)
    ON CONFLICT (organization_id,notification_type,dedupe_key) DO NOTHING;
  END LOOP;
END $$;


ALTER FUNCTION "public"."enqueue_private_cancellation"("p_event" "public"."schedule_events") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_recruitment_x_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.status=OLD.status AND NEW.cycle=OLD.cycle THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM performance_recruitment_policies WHERE organization_id=NEW.organization_id AND one_seat_enabled AND x_enabled AND x_username='queens_waltz') THEN RETURN NEW; END IF;
 INSERT INTO recruitment_x_posts(organization_id,schedule_event_id,cycle,kind,snapshot)
 VALUES(NEW.organization_id,NEW.schedule_event_id,NEW.cycle,CASE NEW.status WHEN 'active' THEN 'extension' ELSE NEW.status END,recruitment_event_snapshot(NEW.organization_id,NEW.schedule_event_id)) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;


ALTER FUNCTION "public"."enqueue_recruitment_x_post"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_and_lock_waitlist_entries"("p_schedule_event_id" "uuid", "p_freed_seats" integer) RETURNS TABLE("id" "uuid", "customer_name" "text", "customer_email" "text", "participant_count" integer, "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_remaining_seats INTEGER;
  v_expires_at TIMESTAMPTZ;
  v_entry RECORD;
BEGIN
  v_remaining_seats := p_freed_seats;
  v_expires_at := NOW() + INTERVAL '24 hours';

  -- FOR UPDATE SKIP LOCKEDで他のトランザクションと競合しないようにロック
  FOR v_entry IN
    SELECT w.id, w.customer_name, w.customer_email, w.participant_count, w.status, w.created_at
    FROM waitlist w
    WHERE w.schedule_event_id = p_schedule_event_id
      AND w.status = 'waiting'
    ORDER BY w.created_at ASC
    FOR UPDATE SKIP LOCKED
  LOOP
    -- 残席がある間だけ処理
    IF v_remaining_seats > 0 THEN
      -- ステータスを即座に更新（他のトランザクションから見えないようにする）
      UPDATE waitlist
      SET status = 'notified',
          notified_at = NOW(),
          expires_at = v_expires_at
      WHERE waitlist.id = v_entry.id;

      v_remaining_seats := v_remaining_seats - v_entry.participant_count;

      -- 結果を返す
      id := v_entry.id;
      customer_name := v_entry.customer_name;
      customer_email := v_entry.customer_email;
      participant_count := v_entry.participant_count;
      status := 'notified';  -- 更新後のステータス
      created_at := v_entry.created_at;
      RETURN NEXT;
    END IF;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."fetch_and_lock_waitlist_entries"("p_schedule_event_id" "uuid", "p_freed_seats" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fetch_and_lock_waitlist_entries"("p_schedule_event_id" "uuid", "p_freed_seats" integer) IS 'キャンセル待ちエントリをアトミックに取得・ロック・更新する。競合を防止。';



CREATE OR REPLACE FUNCTION "public"."fn_sync_reservations_scenario_ids"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.scenario_master_id IS NOT NULL AND NEW.scenario_id IS NULL THEN
      NEW.scenario_id := NEW.scenario_master_id;
    ELSIF NEW.scenario_id IS NOT NULL AND NEW.scenario_master_id IS NULL THEN
      IF EXISTS (SELECT 1 FROM public.scenario_masters WHERE id = NEW.scenario_id) THEN
        NEW.scenario_master_id := NEW.scenario_id;
      END IF;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.scenario_master_id IS DISTINCT FROM OLD.scenario_master_id THEN
      NEW.scenario_id := NEW.scenario_master_id;
    ELSIF NEW.scenario_id IS DISTINCT FROM OLD.scenario_id THEN
      IF EXISTS (SELECT 1 FROM public.scenario_masters WHERE id = NEW.scenario_id) THEN
        NEW.scenario_master_id := NEW.scenario_id;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


