CREATE OR REPLACE FUNCTION "public"."get_effective_private_booking_deadline_days"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_organization_slug" "text" DEFAULT NULL::"text", "p_scenario_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org UUID;
  common_days INTEGER;
  custom_days INTEGER;
BEGIN
  SELECT id INTO org FROM public.organizations
  WHERE (p_organization_id IS NULL OR id = p_organization_id)
    AND (p_organization_slug IS NULL OR slug = p_organization_slug)
    AND (p_organization_id IS NOT NULL OR p_organization_slug IS NOT NULL);
  IF org IS NULL THEN RETURN 14; END IF;
  SELECT private_booking_deadline_days INTO common_days FROM public.global_settings WHERE organization_id = org;
  common_days := COALESCE(common_days, 14);
  IF p_scenario_id IS NOT NULL THEN
    SELECT os.private_booking_deadline_days INTO custom_days
    FROM public.organization_scenarios os
    WHERE os.organization_id = org
      AND (os.scenario_master_id = p_scenario_id OR os.id = p_scenario_id
        OR os.scenario_master_id = (SELECT s.scenario_master_id FROM public.scenarios s WHERE s.id = p_scenario_id AND s.organization_id = org));
    IF NOT FOUND THEN RAISE EXCEPTION 'SCENARIO_NOT_FOUND'; END IF;
    RETURN COALESCE(custom_days, common_days);
  END IF;
  -- 作品未選択の入口は、個別設定で受付可能な作品を隠さない。
  -- 作品選択後に必ずその作品の締切で再判定する。
  SELECT MIN(COALESCE(private_booking_deadline_days, common_days)) INTO custom_days
  FROM public.organization_scenarios WHERE organization_id = org AND org_status = 'available';
  RETURN COALESCE(custom_days, common_days);
END;
$$;


ALTER FUNCTION "public"."get_effective_private_booking_deadline_days"("p_organization_id" "uuid", "p_organization_slug" "text", "p_scenario_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_template"("p_organization_id" "uuid", "p_template_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_templates JSONB;
  v_value TEXT;
BEGIN
  -- 組織のテンプレートを取得
  SELECT email_templates INTO v_templates
  FROM organization_settings
  WHERE organization_id = p_organization_id;
  
  IF v_templates IS NULL THEN
    v_templates := '{}'::JSONB;
  END IF;
  
  -- キーに対応する値を取得
  v_value := v_templates ->> p_template_key;
  
  -- デフォルト値
  IF v_value IS NULL THEN
    CASE p_template_key
      WHEN 'greeting' THEN
        v_value := 'いつもご利用いただきありがとうございます。';
      WHEN 'signature' THEN
        v_value := 'MMQ予約システム';
      WHEN 'footer' THEN
        v_value := '※このメールは自動送信されています。';
      ELSE
        v_value := '';
    END CASE;
  END IF;
  
  RETURN v_value;
END;
$$;


ALTER FUNCTION "public"."get_email_template"("p_organization_id" "uuid", "p_template_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_email_template"("p_organization_id" "uuid", "p_template_key" "text") IS '組織のメールテンプレートを取得。未設定時はデフォルト値を返す。';



CREATE OR REPLACE FUNCTION "public"."get_event_staff_participations"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_org uuid:=public.get_user_organization_id(); v_links jsonb; v_options jsonb; v_event public.schedule_events;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role::text IN ('admin','staff','license_admin'))
 OR NOT EXISTS(SELECT 1 FROM public.schedule_events WHERE id=p_event_id AND organization_id=v_org) THEN
  RAISE EXCEPTION 'この公演のスタッフ参加を確認する権限がありません' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_event FROM public.schedule_events WHERE id=p_event_id AND organization_id=v_org FOR SHARE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('staff_id',l.staff_id,'mode',l.mode,'reservation_id',l.reservation_id,
  'needs_confirmation',coalesce(r.id IS NULL OR r.schedule_event_id IS DISTINCT FROM l.event_id OR r.organization_id IS DISTINCT FROM l.organization_id
   OR r.status NOT IN ('pending','confirmed','gm_confirmed','checked_in') OR r.participant_count<1
   OR (l.mode='included' AND r.participant_count<(SELECT count(*) FROM public.event_staff_participations x WHERE x.reservation_id=l.reservation_id AND x.mode='included'))
   OR (l.mode='additional' AND (r.reservation_source IS DISTINCT FROM 'staff_entry' OR r.participant_count<>1 OR r.payment_method IS DISTINCT FROM 'staff' OR r.customer_id IS NOT NULL OR coalesce(r.base_price,0)<>0 OR coalesce(r.options_price,0)<>0 OR coalesce(r.discount_amount,0)<>0 OR coalesce(r.total_price,0)<>0 OR coalesce(r.final_price,0)<>0)),true)) ORDER BY l.staff_id),'[]') INTO v_links
 FROM public.event_staff_participations l LEFT JOIN public.reservations r ON r.id=l.reservation_id
 WHERE l.event_id=p_event_id AND l.organization_id=v_org;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'label',coalesce(nullif(r.customer_name,''),array_to_string(r.participant_names,'・'),r.reservation_number),
 'participant_count',r.participant_count,'reservation_number',r.reservation_number) ORDER BY r.created_at,r.id),'[]') INTO v_options
 FROM public.reservations r WHERE r.schedule_event_id=p_event_id AND r.organization_id=v_org AND r.status IN ('pending','confirmed','gm_confirmed','checked_in')
 AND r.participant_count>0 AND NOT EXISTS(SELECT 1 FROM public.event_staff_participations l WHERE l.reservation_id=r.id AND l.mode='additional');
 RETURN jsonb_build_object('entries',v_links,'reservations',v_options,'assignment',jsonb_build_object('gms',coalesce(v_event.gms,ARRAY[]::text[]),'gm_roles',coalesce(v_event.gm_roles,'{}'::jsonb)));
END $$;


