CREATE OR REPLACE FUNCTION "public"."get_performance_booking_window"("p_event_id" "uuid") RETURNS TABLE("judgment_deadline" timestamp with time zone, "judgment_status" "text", "booking_deadline" timestamp with time zone, "effective_booking_deadline" timestamp with time zone, "override_minutes" integer, "default_minutes" integer, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 WITH settings AS (
  SELECT e.id,e.updated_at,e.booking_cutoff_minutes,
    public.get_performance_judgment_deadline(e.organization_id,e.id) AS initial_judgment_deadline,
    (e.date+e.start_time) AT TIME ZONE 'Asia/Tokyo' AS starts_at,
    COALESCE(os.booking_cutoff_minutes,common.booking_cutoff_minutes,0) AS default_minutes,
    d.deadline,d.status,
    EXISTS(SELECT 1 FROM performance_cancellation_logs l WHERE l.schedule_event_id=e.id AND l.organization_id=e.organization_id AND l.result='confirmed') AS was_confirmed
  FROM schedule_events e
  LEFT JOIN global_settings common ON common.organization_id=e.organization_id
  LEFT JOIN LATERAL (
    SELECT sc.booking_cutoff_minutes FROM organization_scenarios sc
    WHERE sc.organization_id=e.organization_id AND
      ((e.organization_scenario_id IS NOT NULL AND sc.id=e.organization_scenario_id)
       OR (e.organization_scenario_id IS NULL AND sc.scenario_master_id=COALESCE(e.scenario_master_id,e.scenario_id)))
    LIMIT 1
  ) os ON true
  LEFT JOIN performance_recruitment_deadlines d ON d.schedule_event_id=e.id AND d.organization_id=e.organization_id
  WHERE e.id=p_event_id AND e.category='open' AND NOT e.is_cancelled
 ), resolved AS (
  SELECT *,starts_at-make_interval(mins=>COALESCE(booking_cutoff_minutes,default_minutes)) AS cutoff FROM settings
 )
 SELECT COALESCE(deadline,initial_judgment_deadline),
   COALESCE(status,CASE WHEN was_confirmed THEN 'confirmed' ELSE 'pending' END),cutoff,
   CASE WHEN status='active' THEN deadline ELSE cutoff END,booking_cutoff_minutes,default_minutes,updated_at
 FROM resolved;
$$;


ALTER FUNCTION "public"."get_performance_booking_window"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_performance_judgment_deadline"("p_organization_id" "uuid", "p_event_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE e record; fixed_deadline timestamptz;
BEGIN
 SELECT organization_id,date,start_time INTO e FROM schedule_events WHERE id=p_event_id AND organization_id=p_organization_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'event not found' USING ERRCODE='42501'; END IF;
 SELECT deadline_at INTO fixed_deadline FROM performance_judgment_deadlines WHERE schedule_event_id=p_event_id AND organization_id=p_organization_id;
 RETURN COALESCE(fixed_deadline,((e.date+e.start_time) AT TIME ZONE 'Asia/Tokyo') - make_interval(mins=>(public.resolve_operating_setting(p_organization_id,'judgment_minutes_before','240'::jsonb,NULL,NULL,p_event_id)->>'value')::integer));
END $$;


ALTER FUNCTION "public"."get_performance_judgment_deadline"("p_organization_id" "uuid", "p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_performance_recruitment_deadline"("p_event_id" "uuid") RETURNS TABLE("deadline" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT d.deadline FROM performance_recruitment_deadlines d JOIN schedule_events e ON e.id=d.schedule_event_id AND e.organization_id=d.organization_id
 WHERE e.id=p_event_id AND e.category='open' AND NOT e.is_cancelled AND d.status='active';
$$;


ALTER FUNCTION "public"."get_performance_recruitment_deadline"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_booking_approval_deliveries"("p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE r public.reservations%ROWTYPE; deliveries jsonb;
BEGIN
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation_id;
 IF auth.uid() IS NULL OR NOT FOUND OR public.get_user_organization_id() IS DISTINCT FROM r.organization_id
  OR NOT coalesce(public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff s
   WHERE s.user_id=auth.uid() AND s.organization_id=r.organization_id AND s.status='active'),false) THEN
  RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'kind',d.kind,'status',d.status,
  'recipient_name',CASE WHEN d.kind='confirmation_email' THEN 'お客様' ELSE d.snapshot->>'gmName' END,
  'last_error',d.last_error,'created_at',d.created_at,'updated_at',d.updated_at)
  ORDER BY d.created_at,d.kind,d.id),'[]'::jsonb) INTO deliveries
 FROM public.private_booking_approval_deliveries d WHERE d.reservation_id=r.id AND d.organization_id=r.organization_id
  AND d.schedule_event_id=r.schedule_event_id;
 RETURN jsonb_build_object('reservation_id',r.id,'deliveries',deliveries);
END $$;


ALTER FUNCTION "public"."get_private_booking_approval_deliveries"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_booking_approval_delivery_status"("p_reservation_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_reservation_ids IS NULL OR cardinality(p_reservation_ids)>100 THEN
  RAISE EXCEPTION 'INVALID_RESERVATION_IDS' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(jsonb_agg(public.get_private_booking_approval_deliveries(id)),'[]'::jsonb) INTO result
 FROM (SELECT DISTINCT unnest(p_reservation_ids) AS id) ids;
 RETURN result;
END $$;


