  SELECT public.get_effective_private_booking_deadline_days(p_organization_id, p_organization_slug, NULL);
$$;


ALTER FUNCTION "public"."get_private_booking_deadline_days"("p_organization_id" "uuid", "p_organization_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_booking_delivery_history"("p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE r public.reservations%ROWTYPE; result jsonb;
BEGIN
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation_id;
 IF auth.uid() IS NULL OR NOT FOUND OR public.get_user_organization_id() IS DISTINCT FROM r.organization_id
  OR NOT coalesce(public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
   AND organization_id=r.organization_id AND status='active'),false) THEN
  RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.created_at DESC,d.id),'[]'::jsonb) INTO result FROM (
  SELECT 'approval' AS delivery_kind,id,kind AS channel,status,snapshot->>'gmName' AS recipient_name,created_at,updated_at,last_error,
   status='failed' AND first_attempt_at IS NULL AND provider_message_id IS NULL AND public.is_private_approval_delivery_current(id) AS can_retry,
   status IN ('uncertain','superseded','failed') AND first_attempt_at IS NOT NULL AS can_reconcile,
   status='uncertain' AND first_attempt_at IS NULL AND preparation_attempted_at IS NOT NULL AND provider_payload IS NULL AND kind='confirmation_email' AND provider_message_id IS NULL AND public.is_private_approval_delivery_current(id) AS can_resume_preparation
  FROM public.private_booking_approval_deliveries WHERE reservation_id=r.id AND organization_id=r.organization_id
  UNION ALL
  SELECT 'survey',id,'survey_email',status,'お客様',created_at,updated_at,last_error,
   status='failed' AND first_attempt_at IS NULL AND provider_message_id IS NULL
    AND r.status IN ('confirmed','gm_confirmed','checked_in','completed')
    AND r.schedule_event_id IS NOT DISTINCT FROM schedule_event_id
    AND EXISTS(SELECT 1 FROM public.private_groups g WHERE g.id=group_id AND g.reservation_id=r.id AND g.organization_id=r.organization_id AND g.status='confirmed'),status IN ('uncertain','superseded','failed') AND first_attempt_at IS NOT NULL,false
  FROM public.private_group_survey_deliveries WHERE reservation_id=r.id AND organization_id=r.organization_id
  UNION ALL
  SELECT 'rejection',id,'rejection_email',status,'お客様',created_at,updated_at,last_error,
   status='failed' AND first_attempt_at IS NULL AND provider_message_id IS NULL
    AND r.status='cancelled' AND r.cancelled_at IS NOT DISTINCT FROM cancelled_at
    AND r.cancellation_reason='貸切リクエストを却下しました'
    AND (r.private_group_id IS NULL OR EXISTS(SELECT 1 FROM public.private_groups g WHERE g.id=r.private_group_id AND g.reservation_id=r.id AND g.organization_id=r.organization_id AND g.status='date_adjusting')),status IN ('uncertain','superseded','failed') AND first_attempt_at IS NOT NULL,false
  FROM public.private_booking_rejection_deliveries WHERE reservation_id=r.id AND organization_id=r.organization_id
 ) d;
 RETURN jsonb_build_object('organization_id',r.organization_id,'deliveries',result);
END $$;


ALTER FUNCTION "public"."get_private_booking_delivery_history"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_group_reservation_info"() RETURNS TABLE("reservation_id" "uuid", "schedule_event_id" "uuid", "reservation_status" "text", "group_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.id                AS reservation_id,
    r.schedule_event_id,
    r.status            AS reservation_status,
    pg.status           AS group_status
  FROM public.private_group_members pgm
  JOIN public.private_groups        pg  ON pg.id          = pgm.group_id
  JOIN public.reservations          r   ON r.id           = pg.reservation_id
  WHERE pgm.user_id        = auth.uid()
    AND pgm.status         = 'joined'
    AND pg.reservation_id  IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."get_private_group_reservation_info"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_group_schedules"("p_group_ids" "uuid"[]) RETURNS TABLE("group_id" "uuid", "requested_datetime" "text", "store_id" "uuid", "store_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pg.id::uuid AS group_id,
    r.requested_datetime::text,
    r.store_id::uuid,
    s.name::text AS store_name
  FROM private_groups pg
  JOIN reservations r ON r.id = pg.reservation_id
  LEFT JOIN stores s ON s.id = r.store_id
  WHERE pg.id = ANY(p_group_ids)
    AND (
      -- グループメンバー（参加済み）
      EXISTS (
        SELECT 1 FROM private_group_members pgm
        WHERE pgm.group_id = pg.id
          AND pgm.user_id = auth.uid()
          AND pgm.status = 'joined'
      )
      -- スタッフ・管理者
      OR pg.organization_id = get_user_organization_id()
      OR is_org_admin()
    );
END;
$$;


ALTER FUNCTION "public"."get_private_group_schedules"("p_group_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_private_group_schedules"("p_group_ids" "uuid"[]) IS '貸切グループの確定スケジュール（requested_datetime, store_id, store_name）を返す。グループメンバーが主催者の reservation を直接参照できない RLS 制約を回避するための SECURITY DEFINER 関数。';



CREATE OR REPLACE FUNCTION "public"."get_private_group_survey_deliveries"("p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g public.private_groups%ROWTYPE; history jsonb;
BEGIN
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id;
 IF auth.uid() IS NULL OR NOT FOUND OR NOT coalesce((public.is_org_admin() AND public.get_user_organization_id()=g.organization_id)
  OR EXISTS(SELECT 1 FROM public.staff s WHERE s.user_id=auth.uid() AND s.organization_id=g.organization_id AND s.status='active'),false) THEN
  RAISE EXCEPTION '通知履歴を表示する権限がありません' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.created_at DESC,d.id),'[]'::jsonb) INTO history FROM (
  SELECT id,status,source,created_at,last_error FROM public.private_group_survey_deliveries
  WHERE group_id=g.id AND organization_id=g.organization_id AND reservation_id=g.reservation_id
  ORDER BY created_at DESC,id LIMIT 10
 ) d;
 RETURN jsonb_build_object('reservation_id',g.reservation_id,'deliveries',history,
 'has_unresolved',EXISTS(SELECT 1 FROM public.private_group_survey_deliveries d JOIN public.reservations r ON r.id=g.reservation_id
  WHERE d.group_id=g.id AND d.organization_id=g.organization_id AND d.reservation_id=g.reservation_id
   AND d.schedule_event_id=r.schedule_event_id AND d.status IN ('pending','sending','uncertain')));
END $$;


ALTER FUNCTION "public"."get_private_group_survey_deliveries"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_group_survey_settings"("p_organization_id" "uuid", "p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE g record; sc record; r record; result jsonb; k text; deadline timestamptz; resolved_scenario uuid;
BEGIN
 SELECT * INTO g FROM private_groups WHERE id=p_group_id AND organization_id=p_organization_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'group not found' USING ERRCODE='42501'; END IF;
 SELECT id,characters INTO sc FROM organization_scenarios
 WHERE organization_id=p_organization_id AND (scenario_master_id=g.scenario_master_id OR id=g.scenario_master_id)
 ORDER BY (scenario_master_id=g.scenario_master_id) DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('error','scenario_not_found','survey_enabled',false); END IF;
 SELECT CASE WHEN booking.schedule_event_id IS NOT NULL THEN e.store_id ELSE booking.store_id END AS store_id,booking.schedule_event_id,e.date AS performance_date,e.organization_scenario_id,COALESCE(e.scenario_master_id,e.scenario_id) AS event_master_id INTO r FROM reservations booking
 LEFT JOIN schedule_events e ON e.id=booking.schedule_event_id AND e.organization_id=booking.organization_id
 WHERE ((g.reservation_id IS NOT NULL AND booking.id=g.reservation_id AND booking.private_group_id=p_group_id)
     OR (g.reservation_id IS NULL AND booking.private_group_id=p_group_id)) AND booking.organization_id=p_organization_id
   AND booking.status IN ('confirmed','gm_confirmed','checked_in','completed')
 ORDER BY booking.created_at DESC,booking.id LIMIT 1;
 resolved_scenario:=sc.id;
 IF r.schedule_event_id IS NOT NULL THEN
   resolved_scenario:=r.organization_scenario_id;
   IF resolved_scenario IS NULL AND r.event_master_id IS NOT NULL THEN
     SELECT id INTO resolved_scenario FROM organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=r.event_master_id;
   END IF;
   IF resolved_scenario IS NOT NULL THEN
     SELECT id,characters INTO sc FROM organization_scenarios WHERE id=resolved_scenario AND organization_id=p_organization_id;
   END IF;
 END IF;
 result:=jsonb_build_object('org_scenario_id',sc.id,'characters',COALESCE(sc.characters,'[]'::jsonb));
 FOREACH k IN ARRAY ARRAY['survey_enabled','survey_deadline_days','survey_url'] LOOP
   result:=result||jsonb_build_object(k,public.resolve_operating_setting(p_organization_id,k,'null'::jsonb,r.store_id,resolved_scenario,r.schedule_event_id)->'value');
 END LOOP;
 SELECT deadline_at INTO deadline FROM private_group_survey_deadlines WHERE group_id=p_group_id AND organization_id=p_organization_id;
 IF deadline IS NULL AND r.performance_date IS NOT NULL THEN
   SELECT public.parse_announced_survey_deadline(m.message,r.performance_date) INTO deadline
   FROM private_group_messages m WHERE m.group_id=p_group_id
     AND (m.message ~ '"action"[[:space:]]*:[[:space:]]*"(survey_notice|pre_reading_notice)"')
     AND public.parse_announced_survey_deadline(m.message,r.performance_date) IS NOT NULL
   ORDER BY m.created_at,m.id LIMIT 1;
 END IF;
 IF deadline IS NULL AND r.performance_date IS NOT NULL THEN
   deadline:=((r.performance_date-(result->>'survey_deadline_days')::integer)+time '23:59:59.999') AT TIME ZONE 'Asia/Tokyo';
 END IF;
 RETURN result||jsonb_build_object('survey_deadline_at',deadline);
END $$;


ALTER FUNCTION "public"."get_private_group_survey_settings"("p_organization_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_private_groups_survey_settings"("p_organization_id" "uuid", "p_group_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 IF cardinality(p_group_ids)>100 OR EXISTS(SELECT 1 FROM unnest(p_group_ids) AS requested(group_id)
   WHERE NOT EXISTS(SELECT 1 FROM private_groups g WHERE g.id=requested.group_id AND g.organization_id=p_organization_id)) THEN
   RAISE EXCEPTION 'group not found' USING ERRCODE='42501';
 END IF;
 RETURN COALESCE((SELECT jsonb_object_agg(id,public.get_private_group_survey_settings(p_organization_id,id)) FROM unnest(p_group_ids) id),'{}'::jsonb);
END $$;


