CREATE OR REPLACE FUNCTION "public"."get_private_rejection_delivery_status"("p_reservation_ids" "uuid"[]) RETURNS TABLE("reservation_id" "uuid", "status" "text", "attempt_count" integer, "last_error" "text", "updated_at" timestamp with time zone, "can_retry" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF coalesce(cardinality(p_reservation_ids),0)>100 THEN RAISE EXCEPTION 'TOO_MANY_RESERVATIONS' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT d.reservation_id,d.status,d.attempt_count,d.last_error,d.updated_at,(d.status='failed' AND d.first_attempt_at IS NULL)
  FROM public.private_booking_rejection_deliveries d
  JOIN public.reservations r ON r.id=d.reservation_id AND r.organization_id=d.organization_id AND r.cancelled_at=d.cancelled_at
  WHERE d.reservation_id=ANY(p_reservation_ids) AND r.status='cancelled'
    AND COALESCE((public.is_org_admin() AND public.get_user_organization_id()=d.organization_id)
      OR EXISTS(SELECT 1 FROM public.staff s WHERE s.user_id=auth.uid() AND s.organization_id=d.organization_id AND s.status='active'),false);
END; $$;


ALTER FUNCTION "public"."get_private_rejection_delivery_status"("p_reservation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_available_scenario_keys"() RETURNS TABLE("organization_id" "uuid", "scenario_master_id" "uuid", "org_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT os.organization_id, os.scenario_master_id, os.org_status::TEXT
  FROM public.organization_scenarios os
  JOIN public.scenario_masters sm ON sm.id = os.scenario_master_id
  WHERE sm.master_status = 'approved'
    AND os.org_status IN ('available', 'coming_soon');
$$;


