CREATE OR REPLACE FUNCTION "public"."get_public_payment_settings"("p_organization_slug" "text", "p_event_id" "uuid") RETURNS TABLE("payment_method_label" "text", "payment_method_description" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT o.id INTO v_org FROM public.organizations o
    JOIN public.schedule_events e ON e.organization_id = o.id AND e.id = p_event_id
    JOIN public.stores s ON s.id = e.store_id AND s.organization_id = o.id AND s.status = 'active'
    WHERE o.slug = p_organization_slug AND o.is_active = true AND o.booking_site_status = 'approved'
      AND COALESCE(e.is_cancelled, false) = false;
  IF v_org IS NULL THEN RETURN; END IF;
  RETURN QUERY SELECT
    public.resolve_operating_setting(v_org, 'payment_method_label', to_jsonb('現地決済'::text), NULL, NULL, p_event_id)->>'value',
    public.resolve_operating_setting(v_org, 'payment_method_description', to_jsonb('ご来店時にお支払いください'::text), NULL, NULL, p_event_id)->>'value';
END;
$$;


ALTER FUNCTION "public"."get_public_payment_settings"("p_organization_slug" "text", "p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_performance_judgment"("p_organization_slug" "text", "p_store_id" "uuid" DEFAULT NULL::"uuid", "p_scenario_master_id" "uuid" DEFAULT NULL::"uuid", "p_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("store_id" "uuid", "judgment_minutes" integer, "extension_enabled" boolean, "target_mode" "text", "target_value" integer, "extension_deadline_minutes" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org uuid; v_master uuid := p_scenario_master_id; v_event_store uuid; v_event_os uuid; v_event_at timestamptz;
  v_os public.organization_scenarios%ROWTYPE;
  v_one_seat boolean; v_pol_missing integer; v_enabled boolean; v_mode text; v_value integer; v_deadline integer;
  v_saved_deadline timestamptz; v_saved_missing integer;
BEGIN
  SELECT o.id INTO v_org FROM public.organizations o
    WHERE o.slug=p_organization_slug AND o.is_active IS TRUE AND o.booking_site_status='approved';
  IF v_org IS NULL THEN RETURN; END IF;
  IF p_event_id IS NOT NULL THEN
    SELECT se.store_id, se.organization_scenario_id, coalesce(se.scenario_master_id,se.scenario_id),
        (se.date::text||' '||se.start_time::text||'+09:00')::timestamptz
      INTO v_event_store, v_event_os, v_master, v_event_at
      FROM public.schedule_events se WHERE se.id=p_event_id AND se.organization_id=v_org;
    IF NOT FOUND THEN RETURN; END IF;
    SELECT rd.deadline, rd.max_missing_participants INTO v_saved_deadline, v_saved_missing
      FROM public.performance_recruitment_deadlines rd WHERE rd.schedule_event_id=p_event_id AND rd.organization_id=v_org;
  END IF;
  IF v_event_os IS NOT NULL THEN
    SELECT * INTO v_os FROM public.organization_scenarios os WHERE os.organization_id=v_org AND os.id=v_event_os;
  ELSIF v_master IS NOT NULL THEN
    SELECT * INTO v_os FROM public.organization_scenarios os WHERE os.organization_id=v_org AND os.scenario_master_id=v_master LIMIT 1;
  END IF;
  SELECT p.one_seat_enabled, p.max_missing_participants INTO v_one_seat, v_pol_missing FROM public.performance_recruitment_policies p WHERE p.organization_id=v_org;
  SELECT c.enabled, c.mode, c.value, c.deadline_minutes INTO v_enabled, v_mode, v_value, v_deadline FROM public.organization_recruitment_settings c WHERE c.organization_id=v_org;
  RETURN QUERY
  SELECT b.sid, b.jm,
    CASE WHEN b.saved THEN true ELSE b.en AND b.dm < b.jm END,
    CASE WHEN b.saved AND v_saved_missing IS NOT NULL THEN 'count' ELSE b.tm END,
    CASE WHEN b.saved AND v_saved_missing IS NOT NULL THEN v_saved_missing ELSE b.tv END,
    CASE WHEN b.saved THEN greatest(0, floor(extract(epoch FROM (v_event_at - v_saved_deadline))/60))::integer ELSE b.dm END
  FROM (
    SELECT s.id AS sid,
      (CASE WHEN p_event_id IS NOT NULL AND s.id=v_event_store
        THEN public.resolve_operating_setting(v_org,'judgment_minutes_before','240'::jsonb,NULL,NULL,p_event_id)
        ELSE public.resolve_operating_setting(v_org,'judgment_minutes_before','240'::jsonb,s.id,v_os.id,NULL) END->>'value')::integer AS jm,
      coalesce(v_one_seat,false) AND CASE WHEN v_os.recruitment_enabled_source='custom' THEN coalesce(v_os.recruitment_extension_enabled,false) ELSE coalesce(v_enabled,true) END AS en,
      CASE WHEN v_os.recruitment_target_source='custom' THEN v_os.recruitment_target_mode ELSE coalesce(v_mode,'count') END AS tm,
      CASE WHEN v_os.recruitment_target_source='custom' THEN v_os.recruitment_target_value ELSE coalesce(v_value,v_os.recruitment_max_missing,v_pol_missing,2) END AS tv,
      CASE WHEN v_os.recruitment_deadline_source='custom' THEN v_os.recruitment_deadline_minutes ELSE coalesce(v_deadline,90) END AS dm,
      (p_event_id IS NOT NULL AND s.id=v_event_store AND v_saved_deadline IS NOT NULL) AS saved
    FROM public.stores s
    WHERE s.organization_id=v_org AND s.status='active' AND (p_store_id IS NULL OR s.id=p_store_id)
  ) b;
END $$;


ALTER FUNCTION "public"."get_public_performance_judgment"("p_organization_slug" "text", "p_store_id" "uuid", "p_scenario_master_id" "uuid", "p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_preparation_context"("p_organization_id" "uuid", "p_scenario_lookup_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE store_values jsonb; event_values jsonb;
BEGIN
 IF p_start_date IS NULL OR p_end_date IS NULL OR p_end_date<p_start_date OR p_end_date-p_start_date>180 THEN
   RAISE EXCEPTION 'INVALID_AVAILABILITY_RANGE' USING ERRCODE='P0041';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM organizations WHERE id=p_organization_id AND is_active AND booking_site_status='approved') THEN
   RAISE EXCEPTION 'organization not found' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM organization_scenarios WHERE organization_id=p_organization_id
    AND (id=p_scenario_lookup_id OR scenario_master_id=p_scenario_lookup_id)) THEN
   RAISE EXCEPTION 'scenario not found' USING ERRCODE='42501';
 END IF;
 SELECT COALESCE(jsonb_object_agg(s.id,public.resolve_preparation_minutes(p_organization_id,s.id,p_scenario_lookup_id,NULL)),'{}'::jsonb)
 INTO store_values FROM stores s WHERE s.organization_id=p_organization_id AND s.status='active';
 SELECT COALESCE(jsonb_object_agg(e.id,public.resolve_preparation_minutes(p_organization_id,NULL,NULL,e.id)),'{}'::jsonb)
 INTO event_values FROM schedule_events e JOIN stores s ON s.id=e.store_id AND s.organization_id=e.organization_id
 WHERE e.organization_id=p_organization_id AND NOT e.is_cancelled AND s.status='active' AND e.date BETWEEN p_start_date - 2 AND p_end_date + 2;
 RETURN jsonb_build_object('stores',store_values,'events',event_values);
END $$;


ALTER FUNCTION "public"."get_public_preparation_context"("p_organization_id" "uuid", "p_scenario_lookup_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_private_booking_availability"("p_organization_id" "uuid", "p_store_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("date" "date", "store_id" "uuid", "time_slot" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_organization_id IS NULL
     OR p_start_date IS NULL
     OR p_end_date IS NULL
     OR p_start_date > p_end_date
     OR p_end_date - p_start_date > 180
  THEN
    RAISE EXCEPTION 'INVALID_AVAILABILITY_RANGE' USING ERRCODE = 'P0041';
  END IF;

  IF COALESCE(array_length(p_store_ids, 1), 0) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    blocked.date,
    store.id,
    blocked.time_slot
  FROM public.schedule_blocked_slots blocked
  JOIN public.organizations organization
    ON organization.id = blocked.organization_id
   AND organization.is_active = TRUE
  JOIN public.stores store
    ON store.id::TEXT = blocked.store_id
   AND store.organization_id = blocked.organization_id
  WHERE blocked.organization_id = p_organization_id
    AND store.id = ANY(p_store_ids)
    AND store.status = 'active'
    AND blocked.date BETWEEN p_start_date AND p_end_date
    AND blocked.time_slot IN ('morning', 'afternoon', 'evening')
  UNION
  -- 店舗の貸切募集停止期間（QW-20260909-011）: 期間内の日は朝・昼・夜すべて停止として返す
  SELECT
    day::DATE,
    store.id,
    slot.time_slot
  FROM public.store_recruitment_pauses pause
  JOIN public.organizations organization
    ON organization.id = pause.organization_id
   AND organization.is_active = TRUE
  JOIN public.stores store
    ON store.id = pause.store_id
   AND store.organization_id = pause.organization_id
  CROSS JOIN LATERAL generate_series(
    GREATEST(p_start_date, COALESCE(pause.starts_on, p_start_date)),
    LEAST(p_end_date, COALESCE(pause.ends_on, p_end_date)),
    INTERVAL '1 day'
  ) AS day
  CROSS JOIN (VALUES ('morning'), ('afternoon'), ('evening')) AS slot(time_slot)
  WHERE pause.organization_id = p_organization_id
    AND pause.pause_type = 'private'
    AND store.id = ANY(p_store_ids)
    AND store.status = 'active'
  ORDER BY 1, 2, 3;
END;
$$;


ALTER FUNCTION "public"."get_public_private_booking_availability"("p_organization_id" "uuid", "p_store_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_schedule_events"("p_organization_id" "uuid", "p_from_date" "date" DEFAULT NULL::"date", "p_to_date" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "date" "date", "start_time" time without time zone, "end_time" time without time zone, "store_id" "uuid", "scenario_master_id" "uuid", "title" "text", "max_participants" integer, "category" "text", "is_cancelled" boolean, "is_private_booking" boolean, "organization_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
