    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    u.id AS user_id,
    (COALESCE(
      c.nickname::text,
      c.name::text,
      u.display_name::text,
      split_part(u.email, '@', 1)
    )) AS display_name
  FROM users u
  LEFT JOIN customers c ON c.user_id = u.id
  WHERE u.id = ANY(user_ids);
END;
$$;


