CREATE OR REPLACE FUNCTION "public"."gm_assignment_released_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_today date := (now() AT TIME ZONE 'Asia/Tokyo')::date; v_private boolean; v_removed text[];
BEGIN
  IF TG_OP='DELETE' THEN
    v_private := coalesce(OLD.is_private_booking,false) OR OLD.category='private';
    IF OLD.is_cancelled IS NOT TRUE AND NOT v_private AND OLD.date>=v_today THEN
      PERFORM public.enqueue_gm_assignment_released(OLD,OLD.gms,'deleted',NULL);
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.date<v_today AND OLD.date<v_today THEN RETURN NEW; END IF;
  v_private := coalesce(NEW.is_private_booking,false) OR NEW.category='private';
  -- スタッフの中止（中止日時が入る）。自動の中止判定は中止日時を入れない。
  IF OLD.is_cancelled IS NOT TRUE AND NEW.is_cancelled IS TRUE THEN
    IF NOT v_private AND NEW.cancelled_at IS NOT NULL AND NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at THEN
      PERFORM public.enqueue_gm_assignment_released(OLD,OLD.gms,'cancelled',NEW.cancellation_reason);
    END IF;
    RETURN NEW;
  END IF;
  -- 中止されていない公演で GM が外れた
  IF NEW.is_cancelled IS NOT TRUE AND OLD.gms IS DISTINCT FROM NEW.gms THEN
    SELECT coalesce(array_agg(DISTINCT btrim(n)),'{}') INTO v_removed
      FROM unnest(coalesce(OLD.gms,'{}')) n
      WHERE nullif(btrim(n),'') IS NOT NULL AND NOT (btrim(n)=ANY(coalesce(NEW.gms,'{}')));
    IF cardinality(v_removed)>0 THEN
      PERFORM public.enqueue_gm_assignment_released(NEW,v_removed,'gm_changed',NULL);
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."gm_assignment_released_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_registration_coupons"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign              RECORD;
  v_expires_at            TIMESTAMPTZ;
  v_existing_coupon_count INTEGER;
BEGIN
  -- プラットフォーム顧客（organization_id IS NULL）はスキップ
  -- クーポン付与は org 固有なので、guest 顧客（organization_id IS NOT NULL）のみ対象
  IF NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- メールアドレスがない場合はスキップ
  IF NEW.email IS NULL OR NEW.email = '' THEN
    RETURN NEW;
  END IF;

  FOR v_campaign IN
    SELECT *
    FROM public.coupon_campaigns
    WHERE trigger_type = 'registration'
      AND is_active = true
      AND (valid_from IS NULL OR valid_from <= now())
      AND (valid_until IS NULL OR valid_until >= now())
      AND organization_id = NEW.organization_id
  LOOP
    SELECT COUNT(*) INTO v_existing_coupon_count
    FROM public.customer_coupons cc
    INNER JOIN public.customers c ON c.id = cc.customer_id
    WHERE cc.campaign_id = v_campaign.id
      AND c.id <> NEW.id
      AND NEW.email IS NOT NULL
      AND NEW.email <> ''
      AND c.email = NEW.email;

    IF v_existing_coupon_count > 0 THEN
      RAISE NOTICE 'クーポン付与スキップ: メール % は既にキャンペーン % のクーポンを所持', NEW.email, v_campaign.name;
      CONTINUE;
    END IF;

    IF v_campaign.coupon_expiry_days IS NOT NULL THEN
      v_expires_at := now() + (v_campaign.coupon_expiry_days || ' days')::INTERVAL;
    ELSE
      v_expires_at := NULL;
    END IF;

    INSERT INTO public.customer_coupons (
      campaign_id, customer_id, organization_id, uses_remaining, expires_at, status
    ) VALUES (
      v_campaign.id,
      NEW.id,
      v_campaign.organization_id,
      v_campaign.max_uses_per_customer,
      v_expires_at,
      'active'
    )
    ON CONFLICT (campaign_id, customer_id) DO NOTHING;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."grant_registration_coupons"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grant_registration_coupons"() IS '新規顧客登録時に自動でクーポンを付与（同一メールアドレスでの重複付与を防止、電話番号チェックは廃止）';



CREATE OR REPLACE FUNCTION "public"."grant_representative_compensation"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_actor" "uuid", "p_apply" boolean DEFAULT false, "p_expected" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE r public.reservations; e public.schedule_events; c public.coupon_campaigns;
  g public.representative_compensation_grants; v_start timestamptz; v_days integer;
  v_amount integer; v_count integer; v_snapshot jsonb; v_ids uuid[] := '{}';
  v_id uuid; v_name text; v_exp timestamptz;
BEGIN
  SELECT * INTO r FROM public.reservations
    WHERE id=p_reservation_id AND organization_id=p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '予約を確認できません'; END IF;
  SELECT * INTO g FROM public.representative_compensation_grants
    WHERE organization_id=p_organization_id AND reservation_id=r.id;
  IF FOUND THEN
    RETURN jsonb_build_object('already_granted',true,'coupon_ids',g.coupon_ids,'quantity',g.quantity);
  END IF;
  SELECT * INTO e FROM public.schedule_events WHERE id=r.schedule_event_id FOR SHARE;
  IF e.id IS NULL OR e.organization_id IS DISTINCT FROM p_organization_id
    OR e.is_cancelled IS DISTINCT FROM true OR e.category IS DISTINCT FROM 'open'
    OR (e.scenario_id IS NULL AND e.scenario_master_id IS NULL AND e.organization_scenario_id IS NULL) THEN
    RAISE EXCEPTION '中止済みの通常マーダーミステリー公演を選択してください';
  END IF;
  IF r.status NOT IN ('confirmed','cancelled','checked_in') OR
    r.cancelled_at < e.cancelled_at OR e.cancelled_at IS NULL THEN
    RAISE EXCEPTION '中止前に取り消された予約、未確定の予約は対象にできません';
  END IF;
  IF r.participant_count IS NULL OR r.participant_count NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION '予約人数を確認してください'; END IF;
  SELECT name INTO v_name FROM public.customers WHERE id=r.customer_id AND user_id IS NOT NULL;
  IF NOT FOUND THEN RAISE EXCEPTION '代表者のMMQアカウントを確認してください'; END IF;
  v_start := coalesce(e.start_at,(e.date + e.start_time) AT TIME ZONE 'Asia/Tokyo');
  IF v_start IS NULL OR e.cancelled_at>v_start THEN RAISE EXCEPTION '中止日時を個別に確認してください'; END IF;
  v_days := (v_start AT TIME ZONE 'Asia/Tokyo')::date - (e.cancelled_at AT TIME ZONE 'Asia/Tokyo')::date;
  v_amount := CASE WHEN v_days=0 THEN CASE WHEN v_start-e.cancelled_at<=interval '2 hours' THEN 5000 ELSE 2000 END
    WHEN v_days=1 THEN 1000 END;
  IF v_amount IS NULL THEN RAISE EXCEPTION '補償額を個別に確認してください'; END IF;
  SELECT count(*) INTO v_count FROM public.coupon_campaigns WHERE organization_id=p_organization_id
    AND is_active AND name LIKE '店舗都合中止のお詫び｜%'
    AND discount_type='fixed' AND discount_amount=v_amount AND coupon_expiry_months=6
    AND murder_mystery_only AND trigger_type='manual' AND max_uses_per_customer=1;
  IF v_count<>1 THEN RAISE EXCEPTION '補償用クーポンを1種類に特定できません'; END IF;
  SELECT * INTO c FROM public.coupon_campaigns WHERE organization_id=p_organization_id
    AND is_active AND name LIKE '店舗都合中止のお詫び｜%'
    AND discount_type='fixed' AND discount_amount=v_amount AND coupon_expiry_months=6
    AND murder_mystery_only AND trigger_type='manual' AND max_uses_per_customer=1 FOR SHARE;
  v_snapshot := jsonb_build_object('reservation_id',r.id,'customer_id',r.customer_id,
    'quantity',r.participant_count,'event_id',e.id,'start',v_start,'cancelled_at',e.cancelled_at,
    'campaign_id',c.id,'amount',v_amount,'customer_name',v_name,'coupon_name',coalesce(c.display_name,c.name));
  IF NOT p_apply THEN RETURN jsonb_build_object('already_granted',false,'snapshot',v_snapshot); END IF;
  IF p_expected IS DISTINCT FROM v_snapshot THEN RAISE EXCEPTION '対象の情報が変わりました。確認画面を開き直してください'; END IF;
  FOR i IN 1..r.participant_count LOOP
    INSERT INTO public.customer_coupons(campaign_id,customer_id,organization_id,uses_remaining,status)
      VALUES(c.id,r.customer_id,p_organization_id,1,'active') RETURNING id,expires_at INTO v_id,v_exp;
    v_ids := array_append(v_ids,v_id);
  END LOOP;
  INSERT INTO public.representative_compensation_grants(organization_id,reservation_id,customer_id,
    campaign_id,coupon_ids,quantity,snapshot,created_by)
    VALUES(p_organization_id,r.id,r.customer_id,c.id,v_ids,r.participant_count,v_snapshot,p_actor);
  RETURN jsonb_build_object('already_granted',false,'coupon_ids',v_ids,'quantity',r.participant_count,'expires_at',v_exp);
END;
$$;


ALTER FUNCTION "public"."grant_representative_compensation"("p_organization_id" "uuid", "p_reservation_id" "uuid", "p_actor" "uuid", "p_apply" boolean, "p_expected" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_new_reservation_event_alias"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  event_organization uuid;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.event_id IS NOT DISTINCT FROM OLD.event_id THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NEW.event_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.schedule_event_id IS NULL OR NEW.schedule_event_id <> NEW.event_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = '旧公演参照の新規設定には正本公演との一致が必要です';
  END IF;
  SELECT organization_id INTO event_organization
    FROM public.schedule_events WHERE id = NEW.event_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = '参照先公演が存在しません';
  END IF;
  IF NEW.organization_id IS NULL OR event_organization IS NULL
      OR NEW.organization_id <> event_organization THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = '旧公演参照の新規設定には同一組織が必要です';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_new_reservation_event_alias"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_private_group_browser_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row jsonb; v_group uuid; v_manager text; v_owner boolean; v_message jsonb; v_cap integer;
BEGIN
 -- Definer RPCs validate their own actor. Ordinary browser writes run as anon/authenticated.
 IF current_user NOT IN ('anon','authenticated') THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 IF auth.uid() IS NULL THEN RAISE EXCEPTION '本人確認が必要です。招待ページから入り直してください' USING ERRCODE='42501'; END IF;
 v_row:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 v_group:=(v_row->>'group_id')::uuid;
 IF TG_OP='UPDATE' AND (NEW.group_id IS DISTINCT FROM OLD.group_id OR NEW.id IS DISTINCT FROM OLD.id) THEN
  RAISE EXCEPTION '所属先・識別子を変更できません' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM private_groups WHERE id=v_group FOR UPDATE;
 v_manager:=public.private_group_actor_role(v_group);
 IF TG_TABLE_NAME='private_group_members' THEN
  IF TG_OP<>'DELETE' AND NEW.status='joined' THEN
   SELECT s.player_count_max INTO v_cap FROM private_groups g JOIN organization_scenarios_with_master s ON s.organization_id=g.organization_id AND s.scenario_master_id=g.scenario_master_id WHERE g.id=v_group;
   IF v_cap IS NULL OR (SELECT count(*) FROM private_group_members WHERE group_id=v_group AND status='joined' AND id<>NEW.id)>=v_cap THEN
    RAISE EXCEPTION '参加人数が上限に達しています' USING ERRCODE='23514';
   END IF;
  END IF;
  IF TG_OP='INSERT' THEN
   -- The only direct insert left is the creator becoming the organizer. Joins use the atomic RPC.
   IF NOT EXISTS(SELECT 1 FROM private_groups WHERE id=v_group AND organizer_id=auth.uid()) OR NEW.user_id IS DISTINCT FROM auth.uid() OR NOT NEW.is_organizer
    OR EXISTS(SELECT 1 FROM private_group_members WHERE group_id=v_group AND is_organizer)
    OR NEW.coupon_id IS NOT NULL OR coalesce(NEW.coupon_discount,0)<>0 OR NEW.payment_status='paid' THEN
    RAISE EXCEPTION '招待ページから参加してください' USING ERRCODE='42501';
   END IF;
  ELSIF TG_OP='UPDATE' THEN
   IF v_manager IS DISTINCT FROM 'staff' THEN RAISE EXCEPTION '参加者情報の変更権限がありません' USING ERRCODE='42501'; END IF;
   IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.is_organizer IS DISTINCT FROM OLD.is_organizer THEN RAISE EXCEPTION '本人情報を変更できません' USING ERRCODE='42501'; END IF;
  ELSE
   IF (OLD.is_organizer AND v_manager IS DISTINCT FROM 'staff') OR (v_manager IS NULL AND OLD.user_id IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION '退出・削除の権限がありません' USING ERRCODE='42501'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='private_group_candidate_dates' THEN
  IF v_manager IS NULL THEN RAISE EXCEPTION '候補日を変更する権限がありません' USING ERRCODE='42501'; END IF;
 ELSE
  SELECT EXISTS(SELECT 1 FROM private_group_members WHERE id=(v_row->>'member_id')::uuid AND group_id=v_group AND user_id=auth.uid() AND status='joined') INTO v_owner;
  IF TG_OP='UPDATE' AND NEW.member_id IS DISTINCT FROM OLD.member_id THEN RAISE EXCEPTION '回答者・送信者を変更できません' USING ERRCODE='42501'; END IF;
  IF NOT v_owner AND v_manager IS NULL THEN RAISE EXCEPTION '本人の参加情報が必要です' USING ERRCODE='42501'; END IF;
  IF TG_TABLE_NAME='private_group_date_responses' THEN
   IF TG_OP<>'DELETE' AND NOT v_owner THEN RAISE EXCEPTION '本人の日程回答だけ変更できます' USING ERRCODE='42501'; END IF;
   IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM private_group_candidate_dates WHERE id=NEW.candidate_date_id AND group_id=v_group) THEN RAISE EXCEPTION '別グループの日程には回答できません' USING ERRCODE='42501'; END IF;
  ELSIF TG_TABLE_NAME='private_group_messages' THEN
   IF TG_OP<>'DELETE' AND v_manager IS NULL AND NEW.message ~ '^\s*\{' THEN
    BEGIN
     v_message:=NEW.message::jsonb;
     IF v_message->>'type'='system' THEN RAISE EXCEPTION 'システム通知として送信できません' USING ERRCODE='42501'; END IF;
    EXCEPTION WHEN invalid_text_representation THEN NULL;
    END;
   END IF;
   IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM private_group_members WHERE id=NEW.member_id AND group_id=v_group) AND NEW.member_id IS NOT NULL THEN RAISE EXCEPTION '別グループの送信者です' USING ERRCODE='42501'; END IF;
  ELSIF TG_TABLE_NAME='private_group_survey_responses' THEN
   IF TG_OP<>'DELETE' AND NOT v_owner AND v_manager IS DISTINCT FROM 'staff' THEN RAISE EXCEPTION '本人の回答だけ変更できます' USING ERRCODE='42501'; END IF;
   IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM private_group_members WHERE id=NEW.member_id AND group_id=v_group) THEN RAISE EXCEPTION '別グループの回答者です' USING ERRCODE='42501'; END IF;
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


ALTER FUNCTION "public"."guard_private_group_browser_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_staff_account_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid; v_actor public.users%ROWTYPE; v_target public.users%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.user_id,NEW.organization_id,NEW.role,NEW.status)
   IS NOT DISTINCT FROM (OLD.user_id,OLD.organization_id,OLD.role,OLD.status) THEN RETURN NEW; END IF;
 v_org := CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
 IF TG_OP='UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
   RAISE EXCEPTION 'スタッフを別の組織へ移動することはできません' USING ERRCODE='42501';
 END IF;
 IF coalesce(auth.role(),'') <> 'service_role'
   AND NOT (auth.uid() IS NULL AND session_user IN ('postgres','supabase_admin','supabase_auth_admin') AND current_setting('role') IN ('none','postgres','supabase_admin','supabase_auth_admin')) THEN
   SELECT * INTO v_actor FROM public.users WHERE id=auth.uid();
   IF NOT FOUND OR v_actor.organization_id IS DISTINCT FROM v_org OR v_actor.role NOT IN ('admin','license_admin')
      OR (v_actor.role <> 'license_admin' AND EXISTS(SELECT 1 FROM public.staff WHERE user_id=v_actor.id AND status IN ('inactive','resigned'))) THEN
     RAISE EXCEPTION 'スタッフの連携・役割・利用状態の変更には管理者権限が必要です' USING ERRCODE='42501';
   END IF;
 END IF;
 IF TG_OP<>'DELETE' AND NEW.user_id IS NOT NULL THEN
   SELECT * INTO v_target FROM public.users WHERE id=NEW.user_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION '連携先のユーザーが見つかりません' USING ERRCODE='23503'; END IF;
   IF v_target.organization_id IS NOT NULL AND v_target.organization_id IS DISTINCT FROM v_org THEN
     RAISE EXCEPTION '他組織のユーザーを連携することはできません' USING ERRCODE='42501';
   END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_staff_account_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_staff_derived_user_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_staff public.staff%ROWTYPE; v_expected public.app_role;
BEGIN
 IF NEW.role<>'license_admin' THEN
   IF NEW.role='admin' AND NEW.id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=NEW.id)
      AND EXISTS(SELECT 1 FROM public.organization_signup_claims WHERE organization_id=NEW.organization_id AND consumed_by=NEW.id AND consumed_transaction=txid_current()) THEN RETURN NEW; END IF;
   IF NEW.role='customer' AND (EXISTS(SELECT 1 FROM public.staff WHERE user_id=NEW.id AND status IN('inactive','resigned'))
      OR (EXISTS(SELECT 1 FROM public.staff_account_access WHERE user_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=NEW.id))) THEN NEW.organization_id:=NULL; END IF;
 END IF;
 IF NEW.role IS NOT DISTINCT FROM OLD.role OR NEW.role='license_admin' THEN RETURN NEW; END IF;
 SELECT * INTO v_staff FROM public.staff WHERE user_id=NEW.id;
 IF NOT FOUND THEN
   IF NEW.role IN ('staff','admin') AND EXISTS(SELECT 1 FROM public.staff_account_access WHERE user_id=NEW.id) THEN
     RAISE EXCEPTION '解除済みアカウントの業務権限を再開するにはスタッフを再連携してください' USING ERRCODE='42501';
   END IF;
   RETURN NEW;
 END IF;
 v_expected:=CASE WHEN v_staff.status IN ('inactive','resigned') THEN 'customer'::public.app_role
   WHEN coalesce(v_staff.role,'{}'::text[]) && ARRAY['admin','管理者'] THEN 'admin'::public.app_role ELSE 'staff'::public.app_role END;
 IF NEW.role IS DISTINCT FROM v_expected THEN
   RAISE EXCEPTION '連携済みアカウントの権限はスタッフの役割・利用状態から変更してください' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_staff_derived_user_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role       app_role := 'customer';
  v_org_id     UUID;
  v_name       TEXT;
  v_phone      TEXT;
  v_prefecture TEXT;
  v_birth_date DATE;
BEGIN
  -- Self-supplied metadata never grants staff/license permissions.
  v_name       := NULLIF(trim(COALESCE(NEW.raw_user_meta_data->>'admin_name', '')), '');
  v_phone      := NULLIF(trim(COALESCE(NEW.raw_user_meta_data->>'admin_phone', '')), '');
  v_prefecture := NULLIF(trim(COALESCE(NEW.raw_user_meta_data->>'admin_prefecture', '')), '');

  BEGIN
    v_birth_date := NULLIF(trim(COALESCE(NEW.raw_user_meta_data->>'admin_birth_date', '')), '')::DATE;
  EXCEPTION WHEN OTHERS THEN
    v_birth_date := NULL;
  END;

  IF NEW.raw_user_meta_data->>'invited_as'='admin' THEN
    v_org_id:=(NEW.raw_user_meta_data->>'organization_id')::uuid;
    PERFORM public.consume_organization_signup_claim(v_org_id,NEW.raw_user_meta_data->>'organization_claim_token',NEW.id,NEW.email);
    v_role:='admin';
  END IF;

  INSERT INTO public.users (id, email, role, organization_id, created_at, updated_at)
  VALUES (NEW.id, NEW.email, v_role, v_org_id, NOW(), NOW())
  ON CONFLICT (id) DO UPDATE SET
    role            = EXCLUDED.role,
    organization_id = COALESCE(EXCLUDED.organization_id, users.organization_id),
    updated_at      = NOW();

  IF v_role = 'admin' AND v_org_id IS NOT NULL THEN
    INSERT INTO public.staff (
      name, email, phone, user_id, organization_id, role, status,
      stores, ng_days, want_to_learn, available_scenarios,
      availability, experience, special_scenarios
    ) VALUES (
      COALESCE(v_name, split_part(NEW.email, '@', 1)),
      NEW.email,
      v_phone,
      NEW.id,
      v_org_id,
      ARRAY['管理者']::TEXT[],
      'active',
      '{}'::TEXT[], '{}'::TEXT[], '{}'::TEXT[], '{}'::TEXT[],
      '{}'::TEXT[], 0, '{}'::TEXT[]
    )
    ON CONFLICT (user_id) DO NOTHING;

    -- customers INSERT を独立サブブロックで隔離。
    -- ここでの失敗は users / staff INSERT を巻き戻さない。
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM public.customers
        WHERE organization_id = v_org_id
          AND lower(email) = lower(NEW.email)
      ) THEN
        INSERT INTO public.customers (
          user_id, organization_id, name, email, phone,
          prefecture, birth_date,
          notification_settings,
          created_at, updated_at
        ) VALUES (
          NEW.id, v_org_id,
          COALESCE(v_name, split_part(NEW.email, '@', 1)),
          NEW.email,
          v_phone,
          v_prefecture,
          v_birth_date,
          jsonb_build_object(
            'email_notifications',    true,
            'reminder_notifications', true,
            'campaign_notifications', false
          ),
          NOW(), NOW()
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'handle_new_user: optional customer profile could not be created';
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_organization_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.organization_settings (organization_id)
  VALUES (NEW.id)
  ON CONFLICT (organization_id) DO NOTHING;

  INSERT INTO public.global_settings (organization_id)
  VALUES (NEW.id)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.stores (name, short_name, status, capacity, rooms, color, is_temporary, temporary_dates, organization_id, address, phone_number, email, opening_date, manager_name)
  VALUES
    ('臨時会場1', '臨時1', 'active', 8, 1, '#9E9E9E', true, '[]', NEW.id, '', '', '', CURRENT_DATE, ''),
    ('臨時会場2', '臨時2', 'active', 8, 1, '#9E9E9E', true, '[]', NEW.id, '', '', '', CURRENT_DATE, ''),
    ('臨時会場3', '臨時3', 'active', 8, 1, '#9E9E9E', true, '[]', NEW.id, '', '', '', CURRENT_DATE, ''),
    ('臨時会場4', '臨時4', 'active', 8, 1, '#9E9E9E', true, '[]', NEW.id, '', '', '', CURRENT_DATE, ''),
    ('臨時会場5', '臨時5', 'active', 8, 1, '#9E9E9E', true, '[]', NEW.id, '', '', '', CURRENT_DATE, '')
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


