CREATE OR REPLACE FUNCTION "public"."issue_private_group_guest_session"("p_member_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_token text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM private_group_members WHERE id=p_member_id AND user_id IS NULL AND status='joined') THEN
  RAISE EXCEPTION 'Guest member not found' USING ERRCODE='42501';
 END IF;
 v_token:=encode(extensions.gen_random_bytes(32),'hex');
 DELETE FROM private_group_guest_sessions WHERE member_id=p_member_id AND expires_at<=clock_timestamp();
 INSERT INTO private_group_guest_sessions(token_hash,member_id,expires_at)
 VALUES(encode(extensions.digest(v_token,'sha256'),'hex'),p_member_id,clock_timestamp()+interval '30 days');
 RETURN v_token;
END $$;


ALTER FUNCTION "public"."issue_private_group_guest_session"("p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_private_group"("p_invite_code" "text", "p_guest_name" "text" DEFAULT NULL::"text", "p_guest_email" "text" DEFAULT NULL::"text", "p_guest_phone" "text" DEFAULT NULL::"text", "p_pin" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE v_group record; v_member public.private_group_members; v_user uuid:=auth.uid(); v_email text:=lower(trim(p_guest_email)); v_cap integer; v_min integer; v_name text:=nullif(trim(p_guest_name),''); v_token text;
BEGIN
 SELECT * INTO v_group FROM private_groups WHERE invite_code=p_invite_code FOR UPDATE;
 IF NOT FOUND OR v_group.status='cancelled' THEN RAISE EXCEPTION 'この招待では参加できません' USING ERRCODE='22023'; END IF;
 IF v_user IS NULL AND (v_name IS NULL OR v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(v_email)>320 OR p_pin IS NULL OR p_pin !~ '^[0-9]{4}$') THEN
  RAISE EXCEPTION '名前・メールアドレス・4桁のPINが必要です' USING ERRCODE='22023';
 END IF;
 IF length(coalesce(v_name,''))>200 OR length(coalesce(p_guest_phone,''))>50 THEN RAISE EXCEPTION '入力が長すぎます' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM private_group_members m LEFT JOIN private_group_members_pii pii ON pii.member_id=m.id
  WHERE m.group_id=v_group.id AND m.status='joined' AND ((v_user IS NOT NULL AND m.user_id=v_user) OR (v_user IS NULL AND lower(trim(pii.guest_email))=v_email))) THEN
  RAISE EXCEPTION '既にグループに参加しています。PIN認証から入り直してください' USING ERRCODE='23505';
 END IF;
 SELECT player_count_min,player_count_max INTO v_min,v_cap FROM organization_scenarios_with_master
 WHERE organization_id=v_group.organization_id AND scenario_master_id=v_group.scenario_master_id;
 IF v_cap IS NULL OR v_min IS NULL OR v_min<1 OR v_cap<v_min THEN
  RAISE EXCEPTION '作品の参加人数を確認できません。店舗にお問い合わせください' USING ERRCODE='22023';
 END IF;
 IF (SELECT count(*) FROM private_group_members WHERE group_id=v_group.id AND status='joined')>=v_cap THEN
  RAISE EXCEPTION '参加人数が上限（%名）に達しています',v_cap USING ERRCODE='23514';
 END IF;
 IF v_user IS NOT NULL THEN
  SELECT coalesce(nullif(nickname,''),nullif(name,'')) INTO v_name FROM customers WHERE user_id=v_user ORDER BY id LIMIT 1;
 END IF;
 INSERT INTO private_group_members(group_id,user_id,guest_name,guest_email,guest_phone,is_organizer,status,joined_at)
 VALUES(v_group.id,v_user,coalesce(v_name,'メンバー'),CASE WHEN v_user IS NULL THEN v_email END,CASE WHEN v_user IS NULL THEN p_guest_phone END,false,'joined',clock_timestamp()) RETURNING * INTO v_member;
 IF v_user IS NULL THEN
  PERFORM public.save_guest_access_pin(v_member.id,p_pin);
  v_token:=public.issue_private_group_guest_session(v_member.id);
 END IF;
 INSERT INTO private_group_messages(group_id,member_id,message) VALUES(v_group.id,v_member.id,
  jsonb_build_object('type','system','action','member_joined','memberName',coalesce(v_name,'メンバー'),'memberId',v_member.id)::text);
 RETURN jsonb_build_object('member',to_jsonb(v_member),'guest_token',v_token);
END $_$;


ALTER FUNCTION "public"."join_private_group"("p_invite_code" "text", "p_guest_name" "text", "p_guest_email" "text", "p_guest_phone" "text", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_current_user_to_customer"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_email       text;
  v_role        app_role;
  v_customer_id uuid;
  v_dup_id      uuid;
  v_match_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;  -- 未ログイン
  END IF;

  -- 本人の検証済みメールを auth.users から取得
  SELECT lower(email) INTO v_email
  FROM auth.users
  WHERE id = v_uid;

  IF v_email IS NULL THEN
    RETURN NULL;
  END IF;

  -- 同一メールの紐付け/統合処理を直列化（複数タブ/デバイスからの並行呼び出し対策 #341）。
  -- トランザクション終了時に自動解放される。異なるメールはロックが競合しない。
  PERFORM pg_advisory_xact_lock(hashtextextended(v_email, 0));

  -- 呼び出しユーザー自身の role（staff/admin/license_admin が自分用の customer 行を
  -- 誤って組織から外さないためのガード。20260521030000 と同じ条件）
  SELECT role INTO v_role
  FROM public.users
  WHERE id = v_uid;

  -- 既に本人の顧客行が紐付いている場合（冪等）。同一メールの未紐付け重複行が「ちょうど1件」
  -- だけ残っていれば、その行の予約・プレイ履歴等を本人行へ統合してから重複行を削除する。
  SELECT id INTO v_customer_id
  FROM public.customers
  WHERE user_id = v_uid
  LIMIT 1;
  IF v_customer_id IS NOT NULL THEN
    SELECT count(*) INTO v_match_count
    FROM public.customers
    WHERE user_id IS NULL
      AND lower(email) = v_email;

    IF v_match_count = 1 THEN
      SELECT id INTO v_dup_id
      FROM public.customers
      WHERE user_id IS NULL
        AND lower(email) = v_email
      LIMIT 1;

      -- reservations（ON DELETE RESTRICT なので先に付け替え）
      UPDATE public.reservations SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- customer_org_stats（PK: customer_id, organization_id）
      INSERT INTO public.customer_org_stats (customer_id, organization_id, notes, visit_count, total_spent, last_visit)
      SELECT v_customer_id, organization_id, notes, visit_count, total_spent, last_visit
      FROM public.customer_org_stats
      WHERE customer_id = v_dup_id
      ON CONFLICT (customer_id, organization_id) DO NOTHING;

      -- scenario_likes (UNIQUE: customer_id, scenario_id)
      DELETE FROM public.scenario_likes
      WHERE customer_id = v_dup_id
        AND scenario_id IN (SELECT scenario_id FROM public.scenario_likes WHERE customer_id = v_customer_id);
      UPDATE public.scenario_likes SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- scenario_ratings (UNIQUE: customer_id, scenario_master_id)
      DELETE FROM public.scenario_ratings
      WHERE customer_id = v_dup_id
        AND scenario_master_id IN (SELECT scenario_master_id FROM public.scenario_ratings WHERE customer_id = v_customer_id);
      UPDATE public.scenario_ratings SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- customer_played_overrides (UNIQUE: customer_id, scenario_master_id)
      DELETE FROM public.customer_played_overrides
      WHERE customer_id = v_dup_id
        AND scenario_master_id IN (SELECT scenario_master_id FROM public.customer_played_overrides WHERE customer_id = v_customer_id);
      UPDATE public.customer_played_overrides SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- customer_memos (UNIQUE: customer_id, organization_id)
      DELETE FROM public.customer_memos
      WHERE customer_id = v_dup_id
        AND organization_id IN (SELECT organization_id FROM public.customer_memos WHERE customer_id = v_customer_id);
      UPDATE public.customer_memos SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- ユニーク制約の無い CASCADE テーブル
      UPDATE public.customer_coupons          SET customer_id = v_customer_id WHERE customer_id = v_dup_id;
      UPDATE public.manual_play_history        SET customer_id = v_customer_id WHERE customer_id = v_dup_id;
      UPDATE public.album_character_records    SET customer_id = v_customer_id WHERE customer_id = v_dup_id;
      UPDATE public.user_notifications         SET customer_id = v_customer_id WHERE customer_id = v_dup_id;
      UPDATE public.waitlist                   SET customer_id = v_customer_id WHERE customer_id = v_dup_id;

      -- 本人行の空プロフィール欄を、統合元(重複行)の値で補完する。本人行に既に値があれば
      -- 上書きしない（本人が設定した値を優先）。ゲスト予約時に入力した氏名/ニックネーム等の
      -- 保全のため (#334 / #288)
      UPDATE public.customers dst
      SET name       = COALESCE(NULLIF(btrim(dst.name), ''),     NULLIF(btrim(src.name), ''),     dst.name),
          nickname   = COALESCE(NULLIF(btrim(dst.nickname), ''), NULLIF(btrim(src.nickname), ''), dst.nickname),
          phone      = COALESCE(NULLIF(btrim(dst.phone), ''),    NULLIF(btrim(src.phone), ''),    dst.phone),
          address    = COALESCE(NULLIF(btrim(dst.address), ''),  NULLIF(btrim(src.address), ''),  dst.address),
          line_id    = COALESCE(NULLIF(btrim(dst.line_id), ''),  NULLIF(btrim(src.line_id), ''),  dst.line_id),
          avatar_url = COALESCE(NULLIF(btrim(dst.avatar_url), ''), NULLIF(btrim(src.avatar_url), ''), dst.avatar_url),
          updated_at = NOW()
      FROM public.customers src
      WHERE dst.id = v_customer_id
        AND src.id = v_dup_id;

      -- 統合済みの重複行を削除（残る customer_org_stats 等は CASCADE で削除される）
      DELETE FROM public.customers WHERE id = v_dup_id;
    END IF;

    RETURN v_customer_id;
  END IF;

  -- 未紐付けの候補が「ちょうど1件」のときのみ紐付ける（組織横断でグローバルにチェック。
  -- 重複メール・複数組織ゲスト重複は曖昧とみなしスキップ）
  SELECT count(*) INTO v_match_count
  FROM public.customers
  WHERE user_id IS NULL
    AND lower(email) = v_email;

  IF v_match_count = 1 THEN
    UPDATE public.customers
    SET user_id = v_uid,
        organization_id = CASE WHEN v_role = 'customer' THEN NULL ELSE organization_id END,
        updated_at = NOW()
    WHERE user_id IS NULL
      AND lower(email) = v_email
    RETURNING id INTO v_customer_id;
  END IF;

  RETURN v_customer_id;  -- 照合不能・曖昧なら NULL
END;
$$;


ALTER FUNCTION "public"."link_current_user_to_customer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_survey_question_sources"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.require_survey_question_staff(p_organization_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(source) ORDER BY source.title,source.org_scenario_id),'[]'::jsonb) INTO result FROM (
  SELECT s.scenario_master_id AS id,s.id AS org_scenario_id,COALESCE(m.title,'不明なシナリオ') AS title,count(q.id) AS "questionCount"
  FROM public.organization_scenarios s LEFT JOIN public.scenario_masters m ON m.id=s.scenario_master_id
  JOIN public.org_scenario_survey_questions q ON q.org_scenario_id=s.id
  WHERE s.organization_id=p_organization_id
  GROUP BY s.id,s.scenario_master_id,m.title
 ) source;
 RETURN result;
END $$;


