CREATE OR REPLACE FUNCTION "public"."log_audit"("p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid" DEFAULT NULL::"uuid", "p_old_values" "jsonb" DEFAULT NULL::"jsonb", "p_new_values" "jsonb" DEFAULT NULL::"jsonb", "p_metadata" "jsonb" DEFAULT NULL::"jsonb", "p_ip_address" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_email TEXT;
  v_user_role TEXT;
  v_org_id UUID;
  v_log_id UUID;
BEGIN
  -- 現在のユーザー情報を取得
  v_user_id := auth.uid();
  
  IF v_user_id IS NOT NULL THEN
    SELECT email, role, organization_id
    INTO v_user_email, v_user_role, v_org_id
    FROM public.users
    WHERE id = v_user_id;
  END IF;

  -- ログを挿入
  INSERT INTO audit_logs (
    user_id,
    user_email,
    user_role,
    organization_id,
    action,
    resource_type,
    resource_id,
    old_values,
    new_values,
    metadata,
    ip_address,
    user_agent
  ) VALUES (
    v_user_id,
    v_user_email,
    v_user_role,
    v_org_id,
    p_action,
    p_resource_type,
    p_resource_id,
    p_old_values,
    p_new_values,
    p_metadata,
    p_ip_address,
    p_user_agent
  )
  RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$$;


ALTER FUNCTION "public"."log_audit"("p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_metadata" "jsonb", "p_ip_address" "text", "p_user_agent" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_audit"("p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_metadata" "jsonb", "p_ip_address" "text", "p_user_agent" "text") IS '監査ログを記録する関数';



CREATE OR REPLACE FUNCTION "public"."log_reservation_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_action TEXT;
  v_reservation_id UUID;
  v_org_id UUID;

  v_actor_user_id UUID;
  v_actor_role TEXT;
  v_actor_staff_id UUID;

  v_old JSONB;
  v_new JSONB;
  v_changes JSONB;
  v_key TEXT;
  v_old_val JSONB;
  v_new_val JSONB;
BEGIN
  v_actor_user_id := auth.uid();
  v_actor_role := NULL;
  v_actor_staff_id := NULL;

  IF v_actor_user_id IS NOT NULL THEN
    SELECT role::text INTO v_actor_role
    FROM public.users
    WHERE id = v_actor_user_id
    LIMIT 1;

    SELECT id INTO v_actor_staff_id
    FROM public.staff
    WHERE user_id = v_actor_user_id
    ORDER BY created_at NULLS LAST, id
    LIMIT 1;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_reservation_id := NEW.id;
    v_org_id := NEW.organization_id;
    v_old := NULL;
    v_new := to_jsonb(NEW);
    v_changes := '{}'::jsonb;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_reservation_id := NEW.id;
    v_org_id := NEW.organization_id;
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);

    v_changes := '{}'::jsonb;
    FOR v_key, v_new_val IN SELECT key, value FROM jsonb_each(v_new) LOOP
      v_old_val := v_old -> v_key;
      IF v_old_val IS DISTINCT FROM v_new_val THEN
        v_changes := v_changes || jsonb_build_object(
          v_key,
          jsonb_build_object('old', v_old_val, 'new', v_new_val)
        );
      END IF;
    END LOOP;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    -- DELETE時はreservation_id = NULL で記録（外部キー制約を回避）
    v_reservation_id := NULL;
    v_org_id := OLD.organization_id;
    v_old := to_jsonb(OLD);
    v_new := NULL;
    v_changes := '{}'::jsonb;
  ELSE
    RETURN NULL;
  END IF;

  IF v_org_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  INSERT INTO public.reservations_history (
    reservation_id,
    organization_id,
    changed_by_user_id,
    changed_by_staff_id,
    changed_by_role,
    action_type,
    changes,
    old_values,
    new_values
  ) VALUES (
    v_reservation_id,
    v_org_id,
    v_actor_user_id,
    v_actor_staff_id,
    v_actor_role,
    v_action,
    v_changes,
    v_old,
    v_new
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_reservation_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_private_group_rejected_after_booking_rejection"("p_reservation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    SET "lock_timeout" TO '5s'
    AS $$
DECLARE
  v_reservation record;
  v_group record;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
  END IF;

  SELECT id,organization_id,private_group_id,status INTO v_reservation
  FROM public.reservations WHERE id=p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE='P0005';
  END IF;
  IF NOT COALESCE(
    (public.is_org_admin() AND public.get_user_organization_id()=v_reservation.organization_id)
    OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
      AND organization_id=v_reservation.organization_id AND status='active'),false
  ) THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF v_reservation.status IS DISTINCT FROM 'cancelled' THEN
    RAISE EXCEPTION 'RESERVATION_NOT_CANCELLED' USING ERRCODE='22023';
  END IF;
  IF v_reservation.private_group_id IS NULL THEN RETURN; END IF;

  SELECT id,organization_id,reservation_id,status INTO v_group
  FROM public.private_groups WHERE id=v_reservation.private_group_id FOR UPDATE;
  IF NOT FOUND OR v_group.organization_id IS DISTINCT FROM v_reservation.organization_id THEN
    RAISE EXCEPTION 'PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
  END IF;
  IF v_group.reservation_id IS DISTINCT FROM v_reservation.id THEN
    RAISE EXCEPTION 'PRIVATE_GROUP_RESERVATION_MISMATCH' USING ERRCODE='P0051';
  END IF;
  -- 同じ却下の再試行で、その後に追加された候補を再び却下しない。
  IF v_group.status='date_adjusting' THEN RETURN; END IF;
  IF v_group.status IS NULL OR v_group.status NOT IN ('booking_requested','confirmed') THEN
    RAISE EXCEPTION 'PRIVATE_GROUP_NOT_AWAITING_REJECTION' USING ERRCODE='22023';
  END IF;

  PERFORM 1 FROM public.private_group_candidate_dates
  WHERE group_id=v_group.id FOR UPDATE;
  UPDATE public.private_groups SET status='date_adjusting' WHERE id=v_group.id;
  UPDATE public.private_group_candidate_dates SET status='rejected' WHERE group_id=v_group.id;
END;
$$;


ALTER FUNCTION "public"."mark_private_group_rejected_after_booking_rejection"("p_reservation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_private_group_rejected_after_booking_rejection"("p_reservation_id" "uuid") IS '同組織の管理者・有効スタッフのみ。取消済みの最新予約とグループを検証して却下後の状態・候補日を一括同期。';



