CREATE OR REPLACE FUNCTION "public"."normalize_kit_transfer_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE master_id uuid; org_scenario uuid;
BEGIN
  IF NEW.org_scenario_id IS NOT NULL THEN
    SELECT scenario_master_id,id INTO master_id,org_scenario FROM public.organization_scenarios
      WHERE id=NEW.org_scenario_id AND organization_id=NEW.organization_id FOR SHARE;
  ELSE
    SELECT scenario_master_id,id INTO master_id,org_scenario FROM public.organization_scenarios
      WHERE scenario_master_id=NEW.scenario_master_id AND organization_id=NEW.organization_id FOR SHARE;
  END IF;
  IF master_id IS NULL OR org_scenario IS NULL THEN
    RAISE EXCEPTION '移動する作品を組織内で確認できません' USING ERRCODE='23514';
  END IF;
  IF NEW.scenario_master_id IS NOT NULL AND NEW.scenario_master_id<>master_id THEN
    RAISE EXCEPTION '移動する作品の参照IDが一致しません' USING ERRCODE='23514';
  END IF;
  IF NEW.kit_number IS NULL OR NEW.kit_number<1 THEN
    RAISE EXCEPTION 'キット番号は1以上で指定してください' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=NEW.from_store_id AND organization_id=NEW.organization_id)
    OR NOT EXISTS(SELECT 1 FROM public.stores WHERE id=NEW.to_store_id AND organization_id=NEW.organization_id) THEN
    RAISE EXCEPTION '移動元・移動先は同じ組織の店舗を指定してください' USING ERRCODE='23514';
  END IF;
  NEW.scenario_master_id:=master_id;
  NEW.org_scenario_id:=org_scenario;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."normalize_kit_transfer_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_all_waitlist_entries"("p_schedule_event_id" "uuid") RETURNS TABLE("id" "uuid", "customer_name" "text", "customer_email" "text", "participant_count" integer, "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expires_at TIMESTAMPTZ;
BEGIN
  v_expires_at := NOW() + INTERVAL '24 hours';

  -- 全員のステータスを更新して返す
  RETURN QUERY
  UPDATE waitlist w
  SET 
    status = 'notified',
    notified_at = NOW(),
    expires_at = v_expires_at
  WHERE w.schedule_event_id = p_schedule_event_id
    AND w.status = 'waiting'
  RETURNING w.id, w.customer_name, w.customer_email, w.participant_count, w.status, w.created_at;
END;
$$;


ALTER FUNCTION "public"."notify_all_waitlist_entries"("p_schedule_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_all_waitlist_entries"("p_schedule_event_id" "uuid") IS 'キャンセル待ちエントリ全員に通知する。先着順ではなく一斉通知。';



CREATE OR REPLACE FUNCTION "public"."notify_on_reservation_confirmed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_customer_user_id UUID;
  v_existing_notification_id UUID;
BEGIN
  -- customer_id が NULL の場合はスキップ（スタッフ予約など）
  IF NEW.customer_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- 予約がconfirmedまたはgm_confirmedになった場合
  IF NEW.status IN ('confirmed', 'gm_confirmed') AND 
     (OLD.status IS NULL OR OLD.status NOT IN ('confirmed', 'gm_confirmed')) THEN
    
    -- 既に同じ予約に対する確定通知が存在するかチェック（重複防止）
    SELECT id INTO v_existing_notification_id
    FROM user_notifications
    WHERE related_reservation_id = NEW.id
      AND type = 'reservation_confirmed'
    LIMIT 1;
    
    -- 既存の通知がある場合はスキップ
    IF v_existing_notification_id IS NOT NULL THEN
      RETURN NEW;
    END IF;
    
    -- 顧客のuser_idを取得
    SELECT user_id INTO v_customer_user_id
    FROM customers
    WHERE id = NEW.customer_id;
    
    -- user_id も customer_id も NULL の場合はスキップ
    IF v_customer_user_id IS NULL AND NEW.customer_id IS NULL THEN
      RETURN NEW;
    END IF;
    
    -- 通知を作成
    PERFORM create_notification(
      v_customer_user_id,
      NEW.customer_id,
      NEW.organization_id,
      'reservation_confirmed',
      '予約が確定しました',
      '「' || COALESCE(NEW.title, '公演') || '」のご予約を承りました',
      '/mypage',
      NEW.id,
      NEW.schedule_event_id,
      NULL,
      jsonb_build_object('reservation_number', NEW.reservation_number)
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_on_reservation_confirmed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_on_waitlist_available"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_customer_user_id UUID;
  v_event_info RECORD;
  v_existing_notification_id UUID;
BEGIN
  -- ステータスがnotifiedに変更された場合
  IF NEW.status = 'notified' AND OLD.status != 'notified' THEN
    
    -- 既に同じキャンセル待ちに対する通知が存在するかチェック（重複防止）
    SELECT id INTO v_existing_notification_id
    FROM user_notifications
    WHERE related_waitlist_id = NEW.id
      AND type = 'waitlist_available'
    LIMIT 1;
    
    -- 既存の通知がある場合はスキップ
    IF v_existing_notification_id IS NOT NULL THEN
      RETURN NEW;
    END IF;
    
    -- 顧客のuser_idを取得
    SELECT user_id INTO v_customer_user_id
    FROM customers
    WHERE id = NEW.customer_id;
    
    -- イベント情報を取得
    SELECT scenario, date INTO v_event_info
    FROM schedule_events
    WHERE id = NEW.schedule_event_id;
    
    -- 通知を作成
    PERFORM create_notification(
      v_customer_user_id,
      NEW.customer_id,
      NEW.organization_id,
      'waitlist_available',
      'キャンセル待ちに空きが出ました',
      '「' || COALESCE(v_event_info.scenario, '公演') || '」' || COALESCE(v_event_info.date::TEXT, ''),
      '/mypage',
      NULL,
      NEW.schedule_event_id,
      NEW.id,
      '{}'::jsonb
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_on_waitlist_available"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_private_booking_discord_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_base_url       text;
  v_anon_key       text;
  v_trigger_secret text;
  v_body           jsonb;
  v_headers        jsonb;
BEGIN
  SELECT value INTO v_base_url       FROM public.app_config WHERE key = 'supabase_url';
  SELECT value INTO v_anon_key       FROM public.app_config WHERE key = 'supabase_anon_key';
  SELECT value INTO v_trigger_secret FROM public.app_config WHERE key = 'trigger_secret';

  IF v_base_url IS NULL THEN
    RAISE WARNING 'app_config.supabase_url が設定されていないため Discord 通知をスキップしました';
    RETURN NEW;
  END IF;

  v_body := jsonb_build_object(
    'type',   'INSERT',
    'table',  'reservations',
    'schema', 'public',
    'record', row_to_json(NEW)::jsonb
  );

  v_headers := jsonb_build_object(
    'Content-Type',      'application/json',
    'Authorization',     'Bearer ' || v_anon_key,
    'x-mmq-cron-secret', COALESCE(v_trigger_secret, '')
  );

  PERFORM net.http_post(
    url     := v_base_url || '/functions/v1/notify-private-booking-discord',
    body    := v_body,
    headers := v_headers
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Discord 通知エラー（予約処理は続行）: %', SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_private_booking_discord_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_recruitment_shortage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE d performance_recruitment_deadlines%ROWTYPE; s jsonb;
BEGIN
 -- 公演→予約の既存ロック順を崩さない。辞退RPCは既に公演をロックしている。
 SELECT * INTO d FROM performance_recruitment_deadlines WHERE schedule_event_id=NEW.schedule_event_id AND organization_id=NEW.organization_id AND status='active' AND deadline>now();
 IF NOT FOUND OR d.shortage_alerted_cycle=d.cycle OR EXISTS(SELECT 1 FROM schedule_events WHERE id=NEW.schedule_event_id AND is_cancelled) THEN RETURN NEW; END IF;
 s:=recruitment_event_snapshot(NEW.organization_id,NEW.schedule_event_id);
 IF (s->>'missing_participants')::int>d.max_missing_participants THEN
  PERFORM queue_recruitment_operation_alert(NEW.organization_id,NEW.schedule_event_id,'recruitment_shortage',NEW.schedule_event_id::text||':'||d.cycle,
   '【追加募集：運営確認】不足人数が設定を超えました。あと'||(s->>'missing_participants')||'人です。案内済みの期限まで募集を継続します。'||E'\n'||(s->>'date')||' '||(s->>'start_time')||' '||(s->>'scenario'));
  UPDATE performance_recruitment_deadlines SET shortage_alerted_cycle=d.cycle WHERE schedule_event_id=d.schedule_event_id AND organization_id=d.organization_id;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION "public"."notify_recruitment_shortage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."parse_announced_survey_deadline"("p_message" "text", "p_performance_date" "date") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE m text[]; d date;
BEGIN
 IF p_performance_date IS NULL THEN RETURN NULL; END IF;
 m:=regexp_match(p_message,'回答期限[:：][[:space:]]*([0-9]{1,2})月([0-9]{1,2})日');
 IF m IS NULL THEN RETURN NULL; END IF;
 d:=make_date(extract(year FROM p_performance_date)::integer,m[1]::integer,m[2]::integer);
 IF d>p_performance_date THEN d:=make_date(extract(year FROM p_performance_date)::integer-1,m[1]::integer,m[2]::integer); END IF;
 RETURN (d+time '23:59:59.999') AT TIME ZONE 'Asia/Tokyo';
EXCEPTION WHEN datetime_field_overflow THEN RETURN NULL;
END $$;


ALTER FUNCTION "public"."parse_announced_survey_deadline"("p_message" "text", "p_performance_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_booking_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_event" "uuid", "p_participants" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
 cc public.customer_coupons;
 e public.schedule_events;
 fee integer;
 costs jsonb;
 title text;
 holiday boolean;
 amount integer;
 discount integer;
BEGIN
 IF p_participants IS NULL OR p_participants < 1 OR p_participants > 100 THEN
  RAISE EXCEPTION '参加人数を確認してください' USING ERRCODE='P0028';
 END IF;
 SELECT c.* INTO cc FROM public.customer_coupons c JOIN public.customers cu ON cu.id=c.customer_id
 WHERE c.id=p_coupon AND cu.user_id=p_user;
 IF cc.id IS NULL THEN RAISE EXCEPTION 'ご本人のクーポンを指定してください' USING ERRCODE='P0028'; END IF;
 SELECT * INTO e FROM public.schedule_events WHERE id=p_event AND is_cancelled=false AND organization_id=cc.organization_id;
 IF e.id IS NULL THEN RAISE EXCEPTION '対象の公演が見つかりません' USING ERRCODE='P0028'; END IF;
 IF e.organization_scenario_id IS NOT NULL THEN
  SELECT os.participation_fee, os.participation_costs, COALESCE(os.override_title,sm.title)
  INTO fee,costs,title FROM public.organization_scenarios os JOIN public.scenario_masters sm ON sm.id=os.scenario_master_id
  WHERE os.id=e.organization_scenario_id AND os.organization_id=e.organization_id;
 ELSIF e.scenario_id IS NOT NULL THEN
  SELECT participation_fee,participation_costs,s.title INTO fee,costs,title FROM public.scenarios_v2 s WHERE id=e.scenario_id;
  IF NOT FOUND THEN
   SELECT participation_fee,participation_costs,s.title INTO fee,costs,title FROM public.scenarios s WHERE id=e.scenario_id;
  END IF;
 END IF;
 IF fee IS NULL AND title IS NULL THEN RAISE EXCEPTION '公演の料金を確認できません' USING ERRCODE='P0028'; END IF;
 SELECT COALESCE(bool_or(COALESCE(os.custom_holidays,'[]'::jsonb) ? e.date::text),false)
 INTO holiday FROM public.organization_settings os WHERE os.organization_id=e.organization_id;
 amount := public.calculate_booking_participation_fee(fee,costs,e.date,e.start_time,holiday) * p_participants;
 discount := public.coupon_discount_for_event(cc.id,e.id,amount,cc.customer_id,NULL);
 RETURN jsonb_build_object('success',true,'total_price',amount,'discount_amount',discount,'final_price',amount-discount);
END;
$$;


ALTER FUNCTION "public"."preview_booking_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_event" "uuid", "p_participants" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_customer_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_reservation" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE cc public.customer_coupons; r public.reservations;
BEGIN
 SELECT c.* INTO cc FROM public.customer_coupons c JOIN public.customers cu ON cu.id=c.customer_id
 WHERE c.id=p_coupon AND cu.user_id=p_user;
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation AND organization_id=cc.organization_id;
 IF cc.id IS NULL OR r.id IS NULL OR r.status NOT IN ('confirmed','checked_in') OR NOT public.can_use_coupon_reservation(cc.customer_id,r.id) THEN
  RAISE EXCEPTION 'ご本人の利用可能な予約を指定してください' USING ERRCODE='P0028';
 END IF;
 RETURN jsonb_build_object('success',true,'discount_amount',public.coupon_discount_for_event(cc.id,r.schedule_event_id,r.total_price,cc.customer_id,r.id));
END;
$$;


ALTER FUNCTION "public"."preview_customer_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_reservation" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_booking_store_day_slots"("p_date" "date", "p_hours" "jsonb", "p_is_holiday" boolean, "p_allow_missing" boolean) RETURNS TABLE("slot_key" "text", "start_minutes" integer, "end_minutes" integer, "closing_minutes" integer)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
 names text[]:=ARRAY['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
 dow integer:=extract(dow FROM p_date); weekend boolean;
 opening jsonb; raw_day jsonb; day_key text; pair record;
 synthetic boolean:=false; explicit_morning boolean;
 base_weekend boolean; starts jsonb; slots jsonb; opening_time text; closing_time text;
 start_value text; close_minutes integer; key text;
BEGIN
 IF p_date IS NULL THEN RETURN; END IF;
 IF coalesce(nullif(p_hours->'holidays','null'::jsonb),'[]'::jsonb) ? p_date::text
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(p_hours->'special_closed_days','null'::jsonb),'[]'::jsonb)) d WHERE d->>'date'=p_date::text)
 THEN RETURN; END IF;
 weekend:=dow IN (0,6) OR coalesce(p_is_holiday,false);
 opening:='{}'::jsonb;
 IF jsonb_typeof(p_hours->'opening_hours')='object' THEN
  FOR pair IN SELECT * FROM jsonb_each(p_hours->'opening_hours') LOOP
   IF jsonb_typeof(pair.value)='object' THEN opening:=opening||jsonb_build_object(lower(pair.key),pair.value); END IF;
  END LOOP;
 END IF;
 IF opening='{}'::jsonb THEN
  IF NOT coalesce(p_allow_missing,false) THEN RETURN; END IF;
  synthetic:=true; raw_day:='{}'::jsonb; base_weekend:=weekend; explicit_morning:=true;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(p_hours->'special_open_days','null'::jsonb),'[]'::jsonb)) d WHERE d->>'date'=p_date::text) THEN
   day_key:='sunday'; raw_day:=opening->day_key;
   IF NOT coalesce((raw_day->>'is_open')::boolean,false) THEN
    raw_day:='{}'::jsonb;
   END IF;
  ELSE
   day_key:=CASE WHEN weekend AND dow NOT IN (0,6) THEN 'sunday' ELSE names[dow+1] END;
   raw_day:=opening->day_key;
   IF weekend AND day_key='sunday' AND NOT coalesce((raw_day->>'is_open')::boolean,false)
    AND coalesce((opening->names[dow+1]->>'is_open')::boolean,false) THEN
    day_key:=names[dow+1]; raw_day:=opening->day_key;
   END IF;
   IF NOT coalesce((raw_day->>'is_open')::boolean,false) THEN RETURN; END IF;
  END IF;
  base_weekend:=day_key IN ('sunday','saturday');
  explicit_morning:=coalesce(position(':' IN raw_day->'slot_start_times'->>'morning')>0,false);
 END IF;
 starts:=CASE WHEN base_weekend THEN '{"morning":"10:00","afternoon":"14:00","evening":"19:00"}'::jsonb
  ELSE '{"morning":"10:00","afternoon":"13:00","evening":"19:00"}'::jsonb END;
 IF jsonb_typeof(raw_day->'slot_start_times')='object' THEN starts:=starts||(raw_day->'slot_start_times'); END IF;
 slots:=raw_day->'available_slots';
 IF slots IS NULL OR slots='null'::jsonb OR slots='[]'::jsonb THEN slots:='["morning","afternoon","evening"]'::jsonb; END IF;
 -- 既存画面は朝・夜を常に候補帯へ補う。休業日は上で除外済み。
 slots:=slots||'["morning","evening"]'::jsonb;
 opening_time:=CASE WHEN raw_day ? 'open_time' THEN raw_day->>'open_time' ELSE CASE WHEN base_weekend THEN '09:00' ELSE '10:00' END END;
 closing_time:=CASE WHEN raw_day ? 'close_time' THEN raw_day->>'close_time' ELSE '23:00' END;
 close_minutes:=CASE WHEN position(':' IN closing_time)>0 THEN least(1380,extract(hour FROM closing_time::time)::integer*60+extract(minute FROM closing_time::time)::integer) ELSE 1380 END;
 FOREACH key IN ARRAY ARRAY['morning','afternoon','evening'] LOOP
  IF NOT slots ? key THEN CONTINUE; END IF;
  start_value:=starts->>key;
  IF coalesce(position(':' IN start_value),0)=0 THEN
   start_value:=CASE key WHEN 'morning' THEN '10:00' WHEN 'afternoon' THEN CASE WHEN weekend THEN '14:00' ELSE '13:00' END ELSE '19:00' END;
  END IF;
  start_minutes:=extract(hour FROM start_value::time)::integer*60+extract(minute FROM start_value::time)::integer;
  IF key='morning' AND NOT synthetic AND NOT explicit_morning AND position(':' IN opening_time)>0
   AND opening_time::time<'13:00'::time THEN
   start_minutes:=extract(hour FROM opening_time::time)::integer*60+extract(minute FROM opening_time::time)::integer;
  END IF;
  end_minutes:=CASE key WHEN 'morning' THEN 780 WHEN 'afternoon' THEN 1140 ELSE close_minutes END;
  IF start_minutes<end_minutes THEN slot_key:=key; closing_minutes:=close_minutes; RETURN NEXT; END IF;
 END LOOP;
END $$;


ALTER FUNCTION "public"."private_booking_store_day_slots"("p_date" "date", "p_hours" "jsonb", "p_is_holiday" boolean, "p_allow_missing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_cancellation_event_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.is_cancelled IS NOT TRUE THEN PERFORM public.enqueue_private_cancellation(OLD); END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_cancelled IS TRUE AND NEW.is_cancelled IS NOT TRUE THEN
    UPDATE public.discord_notification_queue SET status='completed',last_error='superseded_by_restoration',updated_at=now()
      WHERE organization_id=OLD.organization_id AND notification_type='private_cancellation'
      AND dedupe_key LIKE OLD.id::text||':'||coalesce(OLD.gm_cancel_epoch,OLD.id)::text||':%'
      AND status IN ('pending','sending','failed');
    NEW.gm_cancel_epoch := gen_random_uuid();
  ELSIF OLD.is_cancelled IS NOT TRUE AND NEW.is_cancelled IS TRUE THEN
    -- 取消と同時にGM欄を空にする操作でも、解除される旧担当者へ送る。
    PERFORM public.enqueue_private_cancellation(OLD);
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."private_cancellation_event_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_cancellation_reservation_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE e public.schedule_events; v_event_id uuid; v_org_id uuid;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.reservation_source IN ('staff_entry','staff_participation') OR NEW.payment_method='staff' THEN RETURN NULL; END IF;
    v_event_id := NEW.schedule_event_id; v_org_id := NEW.organization_id;
  ELSE
    IF OLD.reservation_source IN ('staff_entry','staff_participation') OR OLD.payment_method='staff' THEN RETURN NULL; END IF;
    v_event_id := OLD.schedule_event_id; v_org_id := OLD.organization_id;
  END IF;
  IF v_event_id IS NULL THEN RETURN NULL; END IF;
  IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NULL; END IF;
  -- 公演単位に直列化し、複数予約の同時取消でも最終予約の取消を確実に検出する。
  SELECT * INTO e FROM public.schedule_events WHERE id=v_event_id AND organization_id=v_org_id FOR UPDATE;
  IF NOT FOUND OR NOT (coalesce(e.is_private_booking,false) OR e.category='private') THEN RETURN NULL; END IF;
  IF (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.status='cancelled')) AND NEW.status IN ('pending','confirmed','gm_confirmed','checked_in') THEN
    IF EXISTS (SELECT 1 FROM public.discord_notification_queue WHERE organization_id=v_org_id
      AND notification_type='private_cancellation' AND dedupe_key LIKE v_event_id::text||':'||coalesce(e.gm_cancel_epoch,e.id)::text||':%') THEN
      UPDATE public.discord_notification_queue SET status='completed',last_error='superseded_by_restoration',updated_at=now()
        WHERE organization_id=v_org_id AND notification_type='private_cancellation'
        AND dedupe_key LIKE v_event_id::text||':'||coalesce(e.gm_cancel_epoch,e.id)::text||':%'
        AND status IN ('pending','sending','failed');
      UPDATE public.schedule_events SET gm_cancel_epoch=gen_random_uuid() WHERE id=v_event_id AND organization_id=v_org_id;
    END IF;
    RETURN NULL;
  END IF;
  IF TG_OP='INSERT' THEN RETURN NULL; END IF;
  IF OLD.status='cancelled' OR (TG_OP='UPDATE' AND NEW.status<>'cancelled') THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reservations WHERE schedule_event_id=v_event_id AND organization_id=v_org_id
      AND status IN ('pending','confirmed','gm_confirmed','checked_in')
      AND coalesce(reservation_source,'') NOT IN ('staff_entry','staff_participation')
      AND coalesce(payment_method,'')<>'staff') THEN
    PERFORM public.enqueue_private_cancellation(e);
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION "public"."private_cancellation_reservation_trigger"() OWNER TO "postgres";


