CREATE OR REPLACE FUNCTION "public"."private_group_actor_role"("p_group_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_group record;
BEGIN
 IF auth.uid() IS NULL THEN RETURN NULL; END IF;
 SELECT organizer_id,organization_id INTO v_group FROM private_groups WHERE id=p_group_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM users WHERE id=auth.uid() AND role IN ('admin','staff') AND organization_id=v_group.organization_id)
 AND NOT EXISTS(SELECT 1 FROM staff WHERE user_id=auth.uid() AND status IN ('inactive','resigned')) THEN RETURN 'staff'; END IF;
 IF v_group.organizer_id=auth.uid() THEN RETURN 'organizer'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION "public"."private_group_actor_role"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_add_candidate_dates"("p_group_id" "uuid", "p_request_id" "uuid", "p_expected_scenario_id" "uuid", "p_expected_store_ids" "uuid"[], "p_candidates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
 g public.private_groups%ROWTYPE; sc record; receipt public.private_group_candidate_add_requests%ROWTYPE;
 current_stores uuid[]; expected_stores uuid[]; payload jsonb; item jsonb; ids uuid[]:='{}'; candidate_id uuid;
 candidate_date date; v_start_at timestamp; v_end_at timestamp; slot text; slot_label text;
 minutes integer; start_min integer; end_min integer; next_order integer; res_status text;
 holiday boolean; custom_holidays jsonb; valid_store boolean; author_member uuid; notice_dates jsonb:='[]';
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ログインしてください' USING ERRCODE='42501'; END IF;
 -- 他の予約処理が予約→グループ順にロックする場合は待ち合わせず再読込を促す。
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR public.private_group_actor_role(p_group_id) IS NULL THEN
  RAISE EXCEPTION '候補日を追加する権限がありません' USING ERRCODE='42501';
 END IF;
 IF p_request_id IS NULL OR p_expected_scenario_id IS NULL OR p_expected_store_ids IS NULL
  OR array_position(p_expected_store_ids,NULL) IS NOT NULL
  OR jsonb_typeof(p_candidates) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION '候補日の入力を確認してください' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_candidates) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION '候補日は1〜100件選択してください' USING ERRCODE='22023'; END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::uuid[]) INTO expected_stores FROM unnest(p_expected_store_ids) id;
 payload:=jsonb_build_object('scenario_id',p_expected_scenario_id,'store_ids',expected_stores,'candidates',p_candidates);
 SELECT * INTO receipt FROM public.private_group_candidate_add_requests WHERE request_id=p_request_id;
 IF FOUND THEN
  IF receipt.group_id IS DISTINCT FROM g.id OR receipt.actor_id IS DISTINCT FROM auth.uid() OR receipt.payload IS DISTINCT FROM payload THEN
   RAISE EXCEPTION '同じ送信番号で異なる候補日を保存できません' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('success',true,'candidate_ids',receipt.candidate_ids,'replayed',true);
 END IF;
 IF g.status NOT IN ('gathering','date_adjusting') OR g.status IS NULL THEN
  RAISE EXCEPTION '店舗の返答待ち、確定後、取消後は候補日を追加できません' USING ERRCODE='22023';
 END IF;
 IF g.reservation_id IS NOT NULL THEN
  SELECT status INTO res_status FROM public.reservations WHERE id=g.reservation_id AND organization_id=g.organization_id FOR SHARE NOWAIT;
  IF res_status IS DISTINCT FROM 'cancelled' THEN RAISE EXCEPTION '予約申請中は候補日を追加できません' USING ERRCODE='22023'; END IF;
 END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::uuid[]) INTO current_stores FROM unnest(g.preferred_store_ids) id;
 IF coalesce(g.scenario_master_id,g.scenario_id) IS DISTINCT FROM p_expected_scenario_id OR current_stores IS DISTINCT FROM expected_stores THEN
  RAISE EXCEPTION '作品または希望店舗が変更されています。画面を更新して選び直してください' USING ERRCODE='40001';
 END IF;
 IF cardinality(current_stores)=0 THEN RAISE EXCEPTION '希望店舗を選択してください' USING ERRCODE='22023'; END IF;
 SELECT s.* INTO sc FROM public.organization_scenarios_with_master s WHERE s.organization_id=g.organization_id
  AND (s.scenario_master_id=p_expected_scenario_id OR s.id=p_expected_scenario_id)
  ORDER BY (s.id=p_expected_scenario_id) DESC LIMIT 1;
 IF NOT FOUND OR coalesce(sc.duration,0)<=0 THEN RAISE EXCEPTION '作品の所要時間を確認できません' USING ERRCODE='22023'; END IF;
 SELECT coalesce(os.custom_holidays,'[]'::jsonb) INTO custom_holidays FROM public.organization_settings os WHERE os.organization_id=g.organization_id;
 SELECT coalesce(max(order_num),0)+1 INTO next_order FROM public.private_group_candidate_dates WHERE group_id=g.id;
 FOR item IN SELECT value FROM jsonb_array_elements(p_candidates) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR coalesce(item->>'date','') !~ '^\d{4}-\d{2}-\d{2}$'
   OR coalesce(item->>'start_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR coalesce(item->>'end_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR coalesce(item->>'time_slot','') NOT IN ('morning','afternoon','evening') THEN
   RAISE EXCEPTION '候補日時の形式が正しくありません' USING ERRCODE='22023';
  END IF;
  candidate_date:=(item->>'date')::date; slot:=item->>'time_slot';
  slot_label:=CASE slot WHEN 'morning' THEN '午前' WHEN 'afternoon' THEN '午後' ELSE '夜' END;
  PERFORM public.assert_private_booking_candidate_date(g.organization_id,p_expected_scenario_id,candidate_date);
  holiday:=extract(dow FROM candidate_date) IN (0,6) OR public.is_booking_calendar_holiday(candidate_date) OR coalesce(custom_holidays ? candidate_date::text,false);
  minutes:=CASE WHEN holiday AND coalesce(sc.weekend_duration,0)>0 THEN sc.weekend_duration ELSE sc.duration END;
  v_start_at:=candidate_date+(item->>'start_time')::time; v_end_at:=v_start_at+make_interval(mins=>minutes);
  IF v_end_at::date<>candidate_date OR v_end_at::time>'23:00'::time OR v_end_at::time<>(item->>'end_time')::time THEN
   RAISE EXCEPTION '公演時間が更新されているか、営業時間内に収まりません。候補日を選び直してください' USING ERRCODE='40001';
  END IF;
  IF coalesce(cardinality(CASE WHEN holiday THEN sc.private_booking_time_slots_weekend ELSE sc.private_booking_time_slots END),0)>0 AND NOT EXISTS(
   SELECT 1 FROM unnest(CASE WHEN holiday THEN sc.private_booking_time_slots_weekend ELSE sc.private_booking_time_slots END) value WHERE value=ANY(CASE slot
    WHEN 'morning' THEN ARRAY['午前','朝公演','朝'] WHEN 'afternoon' THEN ARRAY['午後','昼公演','昼'] ELSE ARRAY['夜','夜公演'] END)
  ) THEN RAISE EXCEPTION 'この作品では選択できない時間帯です' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.private_group_candidate_dates cd WHERE cd.group_id=g.id AND cd.date=candidate_date
   AND cd.status IS DISTINCT FROM 'rejected' AND cd.time_slot=ANY(CASE slot WHEN 'morning' THEN ARRAY['morning','午前','朝'] WHEN 'afternoon' THEN ARRAY['afternoon','午後','昼'] ELSE ARRAY['evening','夜','夜間'] END)) THEN
   RAISE EXCEPTION '同じ日付・時間帯の候補は既に追加されています' USING ERRCODE='23505';
  END IF;
  start_min:=extract(hour FROM v_start_at)::integer*60+extract(minute FROM v_start_at)::integer;
  end_min:=start_min+minutes;
  -- 1つの店舗で営業枠と準備時間を含む空きの両方が成立すること。他店の条件を混ぜない。
  SELECT EXISTS(
   SELECT 1 FROM public.stores s
   LEFT JOIN public.business_hours_settings h ON h.store_id=s.id AND h.organization_id=g.organization_id
   -- 作品ごとの開始時刻を店舗の開始時刻へ上書きする（画面と同じ。店舗の特別営業日は土日祝の値、#698）
   CROSS JOIN LATERAL (SELECT public.apply_scenario_slot_start_times(to_jsonb(h),sc.private_booking_slot_start_times,
     holiday OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(to_jsonb(h)->'special_open_days','null'::jsonb),'[]'::jsonb)) d WHERE d->>'date'=candidate_date::text)) AS hours) eff
   CROSS JOIN LATERAL public.private_booking_store_day_slots(candidate_date,eff.hours,holiday,cardinality(current_stores)=1) band
   CROSS JOIN LATERAL (
    SELECT coalesce(max(start_minutes) FILTER (WHERE slot_key='evening'),1140)
      - public.resolve_preparation_minutes(g.organization_id,s.id,p_expected_scenario_id,NULL) AS evening_deadline,
     coalesce(max(start_minutes) FILTER (WHERE slot_key='afternoon'),780) AS afternoon_start
    FROM public.private_booking_store_day_slots(candidate_date,eff.hours,holiday,cardinality(current_stores)=1)
   ) weekday
   WHERE s.id=ANY(current_stores) AND s.organization_id=g.organization_id AND s.status='active'
    AND s.ownership_type IS DISTINCT FROM 'office'
    AND CASE WHEN coalesce(cardinality(sc.available_stores),0)>0 THEN s.id::text=ANY(sc.available_stores) ELSE NOT coalesce(s.is_temporary,false) END
    AND band.slot_key=slot
    AND (holiday OR slot='evening'
     OR (slot='morning' AND weekday.evening_deadline-minutes<weekday.afternoon_start)
     OR (slot='afternoon' AND weekday.evening_deadline-minutes>=weekday.afternoon_start AND end_min<=weekday.evening_deadline))
    AND start_min>=CASE WHEN slot='evening' AND greatest(band.start_minutes,CASE WHEN holiday AND (sc.title LIKE '%戦塵のレガストリア%' OR sc.title LIKE '%BeatSpecter%') THEN 1170 ELSE 0 END)+minutes>1380 THEN 1380-minutes
     ELSE greatest(band.start_minutes,CASE WHEN slot='evening' AND holiday AND (sc.title LIKE '%戦塵のレガストリア%' OR sc.title LIKE '%BeatSpecter%') THEN 1170 ELSE 0 END) END
    AND start_min<band.end_minutes
    AND end_min<=band.closing_minutes
    AND NOT EXISTS(SELECT 1 FROM public.schedule_blocked_slots b WHERE b.organization_id=g.organization_id AND b.store_id=s.id::text AND b.date=candidate_date AND b.time_slot=slot)
    AND NOT EXISTS(SELECT 1 FROM public.schedule_events e WHERE e.organization_id=g.organization_id AND e.store_id=s.id AND e.is_cancelled=false
     AND e.date BETWEEN candidate_date-2 AND candidate_date+2
     AND e.date+e.start_time<v_end_at+make_interval(mins=>public.resolve_preparation_minutes(g.organization_id,NULL,NULL,e.id))
     AND e.date+e.end_time+CASE WHEN e.end_time<e.start_time THEN interval '1 day' ELSE interval '0 days' END>v_start_at-make_interval(mins=>public.resolve_preparation_minutes(g.organization_id,s.id,p_expected_scenario_id,NULL)))
  ) INTO valid_store;
  IF NOT valid_store THEN RAISE EXCEPTION '選択した候補日時は現在受付できません。空き状況を更新して選び直してください' USING ERRCODE='22023'; END IF;
  INSERT INTO public.private_group_candidate_dates(group_id,date,time_slot,start_time,end_time,order_num)
   VALUES(g.id,candidate_date,CASE WHEN slot='evening' THEN '夜間' ELSE slot_label END,item->>'start_time',item->>'end_time',next_order) RETURNING id INTO candidate_id;
  ids:=array_append(ids,candidate_id); next_order:=next_order+1;
  notice_dates:=notice_dates||jsonb_build_array(jsonb_build_object('date',candidate_date,'time_slot',slot_label));
 END LOOP;
 SELECT id INTO author_member FROM public.private_group_members WHERE group_id=g.id AND user_id=auth.uid() AND status='joined' ORDER BY id LIMIT 1;
 INSERT INTO public.private_group_messages(group_id,member_id,message) VALUES(g.id,author_member,
  jsonb_build_object('type','system','action','candidate_dates_added','count',cardinality(ids),'dates',notice_dates)::text);
 INSERT INTO public.private_group_candidate_add_requests(request_id,group_id,actor_id,payload,candidate_ids)
  VALUES(p_request_id,g.id,auth.uid(),payload,ids);
 RETURN jsonb_build_object('success',true,'candidate_ids',ids,'replayed',false);
END $_$;


ALTER FUNCTION "public"."private_group_add_candidate_dates"("p_group_id" "uuid", "p_request_id" "uuid", "p_expected_scenario_id" "uuid", "p_expected_store_ids" "uuid"[], "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_confirm_characters"("p_group_id" "uuid", "p_assignments" "jsonb", "p_expected_assignments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
 g public.private_groups%ROWTYPE;
 chars jsonb;
 assignment record;
 active_count integer;
 required_count integer;
 org_scenario_id uuid;
 message_row public.private_group_messages%ROWTYPE;
 lines text;
BEGIN
 PERFORM public.require_private_group_manager(p_group_id);
 SELECT * INTO STRICT g FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 IF p_expected_assignments IS NULL OR coalesce(g.character_assignments,'{}'::jsonb) <> p_expected_assignments THEN
  RAISE EXCEPTION '配役の希望が更新されています。読み込み直して確認してください' USING ERRCODE='40001';
 END IF;
 IF p_assignments IS NULL OR jsonb_typeof(p_assignments)<>'object' THEN
  RAISE EXCEPTION '配役を指定してください' USING ERRCODE='22023';
 END IF;
 -- 同じ組織・作品の回答先を必ず解決し、旧RPCの別組織fallbackや無保存returnを防ぐ。
 SELECT id INTO STRICT org_scenario_id FROM public.organization_scenarios
 WHERE organization_id=g.organization_id AND scenario_master_id=g.scenario_master_id FOR UPDATE;
 SELECT v.characters,v.player_count_max INTO chars,required_count FROM public.organization_scenarios_with_master v
 WHERE v.organization_id=g.organization_id AND v.scenario_master_id=g.scenario_master_id;
 IF chars IS NULL OR jsonb_typeof(chars)<>'array' OR jsonb_array_length(chars)=0 THEN
  RAISE EXCEPTION '作品のキャラクター設定を確認してください' USING ERRCODE='22023';
 END IF;
 SELECT count(*) INTO active_count FROM public.private_group_members
 WHERE group_id=g.id AND status IN ('joined','active');
 IF active_count<coalesce(nullif(required_count,0),jsonb_array_length(chars)) THEN
  RAISE EXCEPTION '作品の必要人数が揃ってから配役を確定してください' USING ERRCODE='22023';
 END IF;
 IF active_count=0 OR (SELECT count(*) FROM jsonb_object_keys(p_assignments))<>active_count THEN
  RAISE EXCEPTION '参加メンバー全員の配役を選択してください' USING ERRCODE='22023';
 END IF;
 FOR assignment IN SELECT key,value FROM jsonb_each(p_assignments) LOOP
  IF jsonb_typeof(assignment.value)<>'string'
   OR NOT EXISTS(SELECT 1 FROM public.private_group_members m WHERE m.id::text=assignment.key AND m.group_id=g.id AND m.status IN ('joined','active'))
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chars) c WHERE c->>'id'=assignment.value#>>'{}') THEN
   RAISE EXCEPTION '参加メンバーまたはキャラクターが変更されています' USING ERRCODE='22023';
  END IF;
 END LOOP;
 IF (SELECT count(DISTINCT value) FROM jsonb_each(p_assignments))<>active_count THEN
  RAISE EXCEPTION '同じキャラクターを複数人に割り当てることはできません' USING ERRCODE='22023';
 END IF;
 SELECT string_agg((CASE WHEN m.user_id IS NULL THEN coalesce(nullif(m.guest_name,''),'参加者') ELSE coalesce((SELECT nullif(c.nickname,'') FROM public.customers c WHERE c.user_id=m.user_id ORDER BY c.id LIMIT 1),'ニックネーム未設定') END)||' → '||(c->>'name')||
  CASE WHEN g.character_assignments->>m.id::text IS NOT NULL AND g.character_assignments->>m.id::text<>a.value THEN '（変更あり）' ELSE '' END,E'\n' ORDER BY m.created_at,m.id)
 INTO lines FROM public.private_group_members m
 JOIN jsonb_each_text(p_assignments) a ON a.key=m.id::text
 JOIN jsonb_array_elements(chars) c ON c->>'id'=a.value WHERE m.group_id=g.id;
 UPDATE public.private_groups SET character_assignments=p_assignments,updated_at=now() WHERE id=g.id;
 PERFORM public.upsert_character_assignments_to_survey(g.id,p_assignments);
 INSERT INTO public.private_group_messages(group_id,member_id,message)
 VALUES(g.id,NULL,jsonb_build_object('type','system','action','character_assignment','title','キャラクター配役が確定しました','body',lines,'assignments',p_assignments)::text)
 RETURNING * INTO message_row;
 RETURN to_jsonb(message_row);
END $$;


ALTER FUNCTION "public"."private_group_confirm_characters"("p_group_id" "uuid", "p_assignments" "jsonb", "p_expected_assignments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_leave"("p_group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE organizer uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ログインが必要です' USING ERRCODE='42501'; END IF;
 SELECT organizer_id INTO organizer FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'グループから退出できません' USING ERRCODE='42501'; END IF;
 IF organizer=auth.uid() OR EXISTS(SELECT 1 FROM public.private_group_members WHERE group_id=p_group_id AND user_id=auth.uid() AND is_organizer) THEN
  RAISE EXCEPTION '主催者は退出できません' USING ERRCODE='42501';
 END IF;
 -- 既存の同一user_idの複数行がある場合も、他人の行を残して本人だけを退出させる。
 DELETE FROM public.private_group_members WHERE group_id=p_group_id AND user_id=auth.uid();
END $$;


ALTER FUNCTION "public"."private_group_leave"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_member_action"("p_group_id" "uuid", "p_member_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_guest_token" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row jsonb; v_result uuid; v_message text;
BEGIN
 -- Lock the group before the member, consistently with join and future membership guards.
 PERFORM 1 FROM private_groups WHERE id=p_group_id FOR UPDATE;
 PERFORM public.require_private_group_member(p_group_id,p_member_id,p_guest_token);
 IF p_payload IS NULL OR octet_length(p_payload::text)>65536 THEN RAISE EXCEPTION '入力が長すぎます' USING ERRCODE='22023'; END IF;
 CASE p_action
 WHEN 'validate' THEN RETURN jsonb_build_object('valid',true);
 WHEN 'date_responses' THEN
  IF jsonb_typeof(p_payload)<>'array' OR jsonb_array_length(p_payload)>100 THEN RAISE EXCEPTION '日程回答が不正です' USING ERRCODE='22023'; END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload) LOOP
   IF coalesce(v_row->>'response','') NOT IN ('ok','ng','maybe') OR NOT EXISTS(SELECT 1 FROM private_group_candidate_dates WHERE id=(v_row->>'candidateDateId')::uuid AND group_id=p_group_id) THEN
    RAISE EXCEPTION '回答対象の日程が見つかりません' USING ERRCODE='22023';
   END IF;
   INSERT INTO private_group_date_responses(group_id,member_id,candidate_date_id,response)
   VALUES(p_group_id,p_member_id,(v_row->>'candidateDateId')::uuid,v_row->>'response')
   ON CONFLICT(member_id,candidate_date_id) DO UPDATE SET response=EXCLUDED.response,updated_at=clock_timestamp();
  END LOOP;
  RETURN 'true'::jsonb;
 WHEN 'message' THEN
  v_message:=trim(p_payload->>'message');
  IF v_message IS NULL OR length(v_message)=0 OR length(v_message)>5000 THEN RAISE EXCEPTION 'メッセージは1〜5000文字で入力してください' USING ERRCODE='22023'; END IF;
  -- Guest/member messages are plain text, never impersonated system announcements.
  IF v_message ~ '^\s*\{' THEN
   BEGIN
    IF (v_message::jsonb)->>'type'='system' THEN RAISE EXCEPTION 'システム通知として送信できません' USING ERRCODE='42501'; END IF;
   EXCEPTION WHEN invalid_text_representation THEN NULL;
   END;
  END IF;
  INSERT INTO private_group_messages(group_id,member_id,message) VALUES(p_group_id,p_member_id,v_message) RETURNING id INTO v_result;
  RETURN to_jsonb(v_result);
 WHEN 'survey_read' THEN RETURN public.get_survey_data_for_member(p_group_id,p_member_id);
 WHEN 'survey_write' THEN
  IF jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'アンケート回答が不正です' USING ERRCODE='22023'; END IF;
  RETURN to_jsonb(public.upsert_survey_response_for_member(p_group_id,p_member_id,p_payload));
 WHEN 'character_preference' THEN
  IF length(coalesce(p_payload->>'characterId',''))>200 THEN RAISE EXCEPTION '配役希望が不正です' USING ERRCODE='22023'; END IF;
  PERFORM public.set_character_preference(p_group_id,p_member_id::text,p_payload->>'characterId');
  RETURN 'true'::jsonb;
 WHEN 'leave' THEN
  IF EXISTS(SELECT 1 FROM private_group_members WHERE id=p_member_id AND is_organizer) THEN RAISE EXCEPTION '主催者は退出できません' USING ERRCODE='42501'; END IF;
  DELETE FROM private_group_members WHERE id=p_member_id AND group_id=p_group_id;
  RETURN 'true'::jsonb;
 ELSE RAISE EXCEPTION '未対応の操作です' USING ERRCODE='22023';
 END CASE;
END $$;


ALTER FUNCTION "public"."private_group_member_action"("p_group_id" "uuid", "p_member_id" "uuid", "p_action" "text", "p_payload" "jsonb", "p_guest_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_message_payload"("p_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 RETURN p_message::jsonb;
EXCEPTION WHEN invalid_text_representation THEN RETURN NULL;
END $$;


ALTER FUNCTION "public"."private_group_message_payload"("p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_read_list"("p_scope" "text" DEFAULT 'joined'::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100, "p_group_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text; actor_org uuid;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'ログインが必要です' USING ERRCODE='42501'; END IF;
 IF p_scope IS NULL OR p_scope NOT IN ('joined','organized','staff') OR p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN
  RAISE EXCEPTION '一覧の取得条件が正しくありません' USING ERRCODE='22023';
 END IF;
 IF p_scope='staff' THEN
  SELECT role::text,organization_id INTO actor_role,actor_org FROM public.users WHERE id=actor;
  IF p_organization_id IS NULL OR NOT (
   COALESCE(actor_role='license_admin',false) OR
   (COALESCE(actor_role IN ('admin','staff') AND actor_org=p_organization_id,false)
    AND NOT (EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org)
     AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org AND (status IS NULL OR status NOT IN ('inactive','resigned')))))
  ) THEN RAISE EXCEPTION 'この組織の一覧を閲覧できません' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(public.private_group_read_snapshot(g.id)->'group' ORDER BY g.id) FROM (
  SELECT id FROM public.private_groups pg WHERE (p_after_id IS NULL OR pg.id>p_after_id)
   AND (p_organization_id IS NULL OR pg.organization_id=p_organization_id)
   AND (p_group_ids IS NULL OR pg.id=ANY(p_group_ids))
   AND (p_scope='staff' OR (p_scope='organized' AND pg.organizer_id=actor)
    OR (p_scope='joined' AND EXISTS(SELECT 1 FROM public.private_group_members m WHERE m.group_id=pg.id AND m.user_id=actor AND m.status='joined')))
  ORDER BY pg.id LIMIT p_limit
 ) g),'[]'::jsonb);
END $$;


ALTER FUNCTION "public"."private_group_read_list"("p_scope" "text", "p_organization_id" "uuid", "p_after_id" "uuid", "p_limit" integer, "p_group_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_read_messages"("p_group_id" "uuid", "p_member_id" "uuid" DEFAULT NULL::"uuid", "p_guest_token" "text" DEFAULT NULL::"text", "p_before_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE access_level text; own_members uuid[];
BEGIN
 access_level:=public.authorize_private_group_read(p_group_id,p_member_id,p_guest_token);
 SELECT coalesce(array_agg(id),'{}'::uuid[]) INTO own_members FROM public.private_group_members
 WHERE group_id=p_group_id AND user_id=auth.uid() AND status='joined';
 IF p_member_id IS NOT NULL AND NOT (p_member_id=ANY(own_members)) THEN
  BEGIN
   PERFORM public.require_private_group_member(p_group_id,p_member_id,p_guest_token);
   own_members:=array_append(own_members,p_member_id);
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
 END IF;
 IF p_limit IS NULL OR p_limit<1 OR p_limit>500 OR (p_before_created_at IS NULL)<>(p_before_id IS NULL) THEN
  RAISE EXCEPTION '履歴の取得条件が正しくありません' USING ERRCODE='22023';
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at,m.id) FROM (
  SELECT id,group_id,member_id,message,created_at,sender_type FROM public.private_group_messages m
  WHERE group_id=p_group_id
   AND (access_level='staff' OR coalesce(public.private_group_message_payload(m.message)->>'action','')<>'individual_notice'
    OR public.private_group_message_payload(m.message)->>'target_member_id'=ANY(own_members::text[])
    OR (auth.uid() IS NOT NULL AND public.private_group_message_payload(m.message)->>'target_user_id'=auth.uid()::text))
   AND (p_before_created_at IS NULL OR (created_at,id)<(p_before_created_at,p_before_id)) ORDER BY created_at DESC,id DESC LIMIT p_limit
 ) m),'[]'::jsonb);
END $$;


ALTER FUNCTION "public"."private_group_read_messages"("p_group_id" "uuid", "p_member_id" "uuid", "p_guest_token" "text", "p_before_created_at" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_read_reservation"("p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE target uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ログインが必要です' USING ERRCODE='42501'; END IF;
 SELECT g.id INTO STRICT target FROM public.private_groups g
 JOIN public.reservations r ON r.id=g.reservation_id AND r.organization_id=g.organization_id
 WHERE r.id=p_reservation_id;
 RETURN public.private_group_read_snapshot(target);
EXCEPTION WHEN no_data_found THEN RETURN NULL;
END $$;


ALTER FUNCTION "public"."private_group_read_reservation"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_read_snapshot"("p_group_id" "uuid" DEFAULT NULL::"uuid", "p_invite_code" "text" DEFAULT NULL::"text", "p_member_id" "uuid" DEFAULT NULL::"uuid", "p_guest_token" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g public.private_groups%ROWTYPE; access_level text; invited boolean:=false;
 result jsonb; members jsonb:='[]'; dates jsonb:='[]'; scenario jsonb; actor_member uuid;
 reservation_status text; confirmed_name text; confirmed_performance jsonb;
BEGIN
 IF p_invite_code IS NOT NULL THEN
  SELECT * INTO g FROM public.private_groups WHERE invite_code=p_invite_code AND (p_group_id IS NULL OR id=p_group_id);
  invited:=FOUND;
 ELSE
  SELECT * INTO g FROM public.private_groups WHERE id=p_group_id;
 END IF;
 IF g.id IS NULL THEN RAISE EXCEPTION 'グループを閲覧できません' USING ERRCODE='42501'; END IF;
 BEGIN
  access_level:=public.authorize_private_group_read(g.id,p_member_id,p_guest_token);
 EXCEPTION WHEN insufficient_privilege THEN
  IF NOT invited THEN RAISE; END IF;
  access_level:='preview';
 END;
 IF access_level<>'preview' THEN
  SELECT id INTO actor_member FROM public.private_group_members
   WHERE group_id=g.id AND status='joined'
   AND auth.uid() IS NOT NULL AND user_id=auth.uid()
   ORDER BY id LIMIT 1;
  IF actor_member IS NULL AND p_member_id IS NOT NULL THEN
   BEGIN
    PERFORM public.require_private_group_member(g.id,p_member_id,p_guest_token);
    actor_member:=p_member_id;
   EXCEPTION WHEN insufficient_privilege THEN NULL;
   END;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'id',m.id,'group_id',m.group_id,'user_id',m.user_id,
   'guest_name',CASE WHEN m.user_id IS NULL THEN m.guest_name ELSE COALESCE((SELECT NULLIF(c.nickname,'') FROM public.customers c WHERE c.user_id=m.user_id ORDER BY c.id LIMIT 1),'ニックネーム未設定') END,
   'staff_display_name',CASE WHEN access_level='staff' THEN COALESCE((SELECT COALESCE(NULLIF(c.nickname,''),NULLIF(c.name,'')) FROM public.customers c WHERE c.user_id=m.user_id ORDER BY c.id LIMIT 1),m.guest_name,'参加者') END,
   'guest_email',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.guest_email END,
   'guest_phone',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.guest_phone END,
   'is_organizer',m.is_organizer,'status',m.status,'joined_at',m.joined_at,'created_at',m.created_at,
   'coupon_id',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.coupon_id END,
   'payment_amount',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.payment_amount END,
   'coupon_discount',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.coupon_discount END,
   'final_amount',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.final_amount END,
   'payment_status',CASE WHEN access_level IN ('staff','organizer') OR m.id=actor_member THEN m.payment_status END,
   'date_responses',COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.private_group_date_responses r WHERE r.group_id=g.id AND r.member_id=m.id),'[]'::jsonb)
  ) ORDER BY m.joined_at,m.id),'[]'::jsonb) INTO members FROM public.private_group_members m WHERE m.group_id=g.id;
  SELECT r.status,s.name INTO reservation_status,confirmed_name FROM public.reservations r LEFT JOIN public.staff s ON s.id=r.confirmed_by AND s.organization_id=g.organization_id WHERE r.id=g.reservation_id AND r.organization_id=g.organization_id;
  -- Only authorized members/staff receive the current confirmed performance.
  -- Proposed candidate rows remain immutable history for availability answers.
  SELECT jsonb_build_object('id',e.id,'date',e.date,'start_time',e.start_time,'end_time',e.end_time,
    'store_name',COALESCE(s.name,e.venue)) INTO confirmed_performance
  FROM public.reservations r JOIN public.schedule_events e ON e.id=r.schedule_event_id AND e.organization_id=g.organization_id
  LEFT JOIN public.stores s ON s.id=e.store_id AND s.organization_id=g.organization_id
  WHERE r.id=g.reservation_id AND r.organization_id=g.organization_id
    AND r.status IN ('confirmed','checked_in','completed','no_show') AND NOT COALESCE(e.is_cancelled,false);
 END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(d)||jsonb_build_object('responses',CASE WHEN access_level='preview' THEN '[]'::jsonb ELSE COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.private_group_date_responses r WHERE r.group_id=g.id AND r.candidate_date_id=d.id),'[]'::jsonb) END) ORDER BY d.order_num,d.id),'[]'::jsonb)
 INTO dates FROM public.private_group_candidate_dates d WHERE d.group_id=g.id;
 SELECT jsonb_build_object('id',s.id,'title',s.title,'key_visual_url',s.key_visual_url,'player_count_min',s.player_count_min,'player_count_max',s.player_count_max) INTO scenario FROM public.scenario_masters s WHERE s.id=g.scenario_master_id;
 IF scenario IS NOT NULL THEN
  SELECT scenario||jsonb_build_object('characters',CASE WHEN access_level='preview' THEN NULL ELSE v.characters END,'effective_player_count_min',v.player_count_min,'effective_player_count_max',v.player_count_max,'survey_enabled',COALESCE(v.survey_enabled,false)) INTO result FROM public.organization_scenarios_with_master v WHERE v.organization_id=g.organization_id AND v.scenario_master_id=g.scenario_master_id;
  scenario:=COALESCE(result,scenario);
 END IF;
 result:=jsonb_build_object('id',g.id,'organization_id',g.organization_id,'scenario_master_id',g.scenario_master_id,
  'organizer_id',CASE WHEN access_level<>'preview' THEN g.organizer_id END,
  -- グループの同組織スタッフ認可後に、幹事本人の最小表示名だけを返す。
  -- 顧客プロフィールは共通(NULL組織)もあるため所属では絞らない。
  'organizer_display_name',CASE WHEN access_level='staff' THEN COALESCE((
    SELECT COALESCE(NULLIF(c.nickname,''),NULLIF(c.name,''))
    FROM public.customers c WHERE c.user_id=g.organizer_id
    ORDER BY c.id LIMIT 1
  ),(
    SELECT NULLIF(m.guest_name,'') FROM public.private_group_members m
    WHERE m.group_id=g.id AND m.user_id=g.organizer_id
    ORDER BY m.is_organizer DESC NULLS LAST,m.id LIMIT 1
  )) END,
  'name',g.name,'invite_code',g.invite_code,'status',g.status,
  'reservation_id',CASE WHEN access_level<>'preview' THEN g.reservation_id END,'target_participant_count',g.target_participant_count,'preferred_store_ids',g.preferred_store_ids,
  'notes',CASE WHEN access_level IN ('staff','organizer') THEN g.notes END,'created_at',g.created_at,'updated_at',g.updated_at,
  'total_price',g.total_price,'per_person_price',g.per_person_price,
  'character_assignments',CASE WHEN access_level<>'preview' THEN g.character_assignments END,
  'character_assignment_method',CASE WHEN access_level<>'preview' THEN g.character_assignment_method END,
  'scenario_masters',scenario,'members',members,'candidate_dates',dates,'confirmed_performance',confirmed_performance,'confirmed_performance_access',CASE WHEN access_level='preview' THEN 'preview' ELSE 'authorized' END);
 RETURN jsonb_build_object('group',result,'access_level',access_level,'current_member_id',actor_member,'linked_reservation_status',reservation_status,'confirmed_by_name',confirmed_name);
END $$;


ALTER FUNCTION "public"."private_group_read_snapshot"("p_group_id" "uuid", "p_invite_code" "text", "p_member_id" "uuid", "p_guest_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_read_survey_responses"("p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF public.authorize_private_group_read(p_group_id)<>'staff' THEN
  RAISE EXCEPTION 'アンケート一覧を閲覧できません' USING ERRCODE='42501';
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.submitted_at,r.member_id) FROM (
  SELECT s.member_id,s.responses,s.submitted_at FROM public.private_group_survey_responses s
  JOIN public.private_group_members m ON m.id=s.member_id AND m.group_id=s.group_id
  WHERE s.group_id=p_group_id
 ) r),'[]'::jsonb);
END $$;


ALTER FUNCTION "public"."private_group_read_survey_responses"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_remove_member"("p_member_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE target_group uuid; target public.private_group_members%ROWTYPE; actor_role text;
BEGIN
 SELECT group_id INTO target_group FROM public.private_group_members WHERE id=p_member_id;
 IF target_group IS NULL THEN RAISE EXCEPTION 'メンバーを削除できません' USING ERRCODE='42501'; END IF;
 actor_role:=public.private_group_actor_role(target_group);
 IF actor_role IS NULL THEN RAISE EXCEPTION 'メンバーを削除する管理権限がありません' USING ERRCODE='42501'; END IF;
 SELECT * INTO target FROM public.private_group_members WHERE id=p_member_id AND group_id=target_group FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 IF target.is_organizer AND actor_role<>'staff' THEN RAISE EXCEPTION '主催者を削除する権限がありません' USING ERRCODE='42501'; END IF;
 DELETE FROM public.private_group_members WHERE id=target.id AND group_id=target_group;
END $$;


ALTER FUNCTION "public"."private_group_remove_member"("p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_send_individual_notice"("p_group_id" "uuid", "p_member_id" "uuid", "p_message" "text" DEFAULT ''::"text", "p_character_id" "text" DEFAULT NULL::"text", "p_attach_template" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
 g public.private_groups%ROWTYPE;
 member public.private_group_members%ROWTYPE;
 scenario record;
 character jsonb;
 template text;
 sender_name text;
 target_name text;
 body text;
 saved public.private_group_messages%ROWTYPE;
BEGIN
 IF public.private_group_actor_role(p_group_id) IS DISTINCT FROM 'staff' AND coalesce(auth.role(),'')<>'service_role' THEN
  RAISE EXCEPTION 'スタッフ権限が必要です' USING ERRCODE='42501';
 END IF;
 SELECT * INTO STRICT g FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 SELECT * INTO member FROM public.private_group_members WHERE id=p_member_id AND group_id=g.id AND status IN ('joined','active');
 IF NOT FOUND THEN RAISE EXCEPTION '宛先の参加状況が変更されています' USING ERRCODE='22023'; END IF;
 SELECT v.characters,v.individual_notice_template INTO scenario FROM public.organization_scenarios_with_master v
 WHERE v.organization_id=g.organization_id AND (v.scenario_master_id=g.scenario_master_id OR v.org_scenario_id=g.scenario_master_id)
 ORDER BY (v.scenario_master_id=g.scenario_master_id) DESC LIMIT 1;
 IF p_character_id IS NOT NULL AND p_character_id<>'' THEN
  SELECT c INTO character FROM jsonb_array_elements(coalesce(scenario.characters,'[]'::jsonb)) c WHERE c->>'id'=p_character_id;
  IF character IS NULL THEN RAISE EXCEPTION '作品のキャラクターが変更されています' USING ERRCODE='22023'; END IF;
 END IF;
 IF coalesce(p_attach_template,false) THEN
  template:=nullif(scenario.individual_notice_template,'');
  IF template IS NULL THEN SELECT individual_notice_default_body INTO template FROM public.global_settings WHERE organization_id=g.organization_id; END IF;
 END IF;
 body:=concat_ws(E'\n\n',nullif(btrim(p_message),''),nullif(template,''),nullif(character->>'survey_description',''),
  CASE WHEN nullif(character->>'url','') IS NOT NULL THEN '【'||coalesce(character->>'name','キャラクター')||E'の資料】\n'||(character->>'url') END);
 IF body='' AND character IS NULL THEN RAISE EXCEPTION 'お知らせの本文を入力してください' USING ERRCODE='22023'; END IF;
 target_name:=CASE WHEN member.user_id IS NULL THEN coalesce(nullif(member.guest_name,''),'参加者')
  ELSE coalesce((SELECT nullif(c.nickname,'') FROM public.customers c WHERE c.user_id=member.user_id ORDER BY c.id LIMIT 1),'ニックネーム未設定') END;
 SELECT name INTO sender_name FROM public.staff WHERE user_id=auth.uid() AND organization_id=g.organization_id AND (status IS NULL OR status NOT IN ('inactive','resigned')) ORDER BY id LIMIT 1;
 INSERT INTO public.private_group_messages(group_id,member_id,message) VALUES(g.id,member.id,jsonb_build_object(
  'type','system','action','individual_notice','target_member_id',member.id,'target_member_name',target_name,'target_user_id',member.user_id,
  'message',body,'character_id',character->>'id','character_name',character->>'name','character_url',character->>'url',
  'template_attached',coalesce(nullif(template,'') IS NOT NULL,false),'sent_by',sender_name)::text) RETURNING * INTO saved;
 RETURN to_jsonb(saved);
END $$;


ALTER FUNCTION "public"."private_group_send_individual_notice"("p_group_id" "uuid", "p_member_id" "uuid", "p_message" "text", "p_character_id" "text", "p_attach_template" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_set_character_method"("p_group_id" "uuid", "p_method" "text", "p_expected_method" "text", "p_expected_assignments" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g public.private_groups%ROWTYPE;org_scenario uuid;question_ids text[];
BEGIN
 PERFORM public.require_private_group_manager(p_group_id);
 SELECT * INTO STRICT g FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 IF p_method IS NOT NULL AND p_method NOT IN ('survey','self') THEN RAISE EXCEPTION '配役方法が正しくありません' USING ERRCODE='22023'; END IF;
 IF g.character_assignment_method IS DISTINCT FROM p_expected_method OR coalesce(g.character_assignments,'{}'::jsonb) IS DISTINCT FROM coalesce(p_expected_assignments,'{}'::jsonb) THEN
  RAISE EXCEPTION '配役の状態が更新されています。読み込み直して確認してください' USING ERRCODE='40001';
 END IF;
 SELECT id INTO org_scenario FROM public.organization_scenarios
 WHERE organization_id=g.organization_id AND (scenario_master_id=g.scenario_master_id OR id=g.scenario_master_id)
 ORDER BY (scenario_master_id=g.scenario_master_id) DESC LIMIT 1;
 IF org_scenario IS NULL THEN RAISE EXCEPTION '作品の設定を確認してください' USING ERRCODE='22023'; END IF;
 SELECT array_agg(id::text) INTO question_ids FROM public.org_scenario_survey_questions WHERE org_scenario_id=org_scenario AND question_type='character_selection';
 UPDATE public.private_groups SET character_assignment_method=p_method,character_assignments=NULL,updated_at=now() WHERE id=g.id;
 IF question_ids IS NOT NULL THEN
  UPDATE public.private_group_survey_responses SET responses=coalesce(responses,'{}'::jsonb)-question_ids,updated_at=now() WHERE group_id=g.id;
 END IF;
 INSERT INTO public.private_group_messages(group_id,member_id,message) VALUES(g.id,NULL,jsonb_build_object(
  'type','system','action','character_method_selected','method',p_method,
  'title',CASE WHEN p_method IS NULL THEN '配役方法を変更します' ELSE '配役方法が選択されました' END,
  'body',CASE WHEN p_method IS NULL THEN '配役とキャラクター希望をリセットしました。配役方法を選び直してください。'
   WHEN p_method='survey' THEN '「アンケート」が選択されました。' ELSE '「自分たちで決める」が選択されました。' END)::text);
END $$;


ALTER FUNCTION "public"."private_group_set_character_method"("p_group_id" "uuid", "p_method" "text", "p_expected_method" "text", "p_expected_assignments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."private_group_set_preferred_stores"("p_group_id" "uuid", "p_store_ids" "uuid"[], "p_expected_store_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g public.private_groups%ROWTYPE; allowed text[]; selected uuid[]; cd record; store uuid;
 slot text; start_at timestamp; end_at timestamp; available boolean; removed integer:=0; res_status text;
BEGIN
 IF public.private_group_actor_role(p_group_id) IS NULL THEN RAISE EXCEPTION '希望店舗を変更する権限がありません' USING ERRCODE='42501'; END IF;
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id FOR UPDATE;
 IF g.status NOT IN ('gathering','date_adjusting') THEN RAISE EXCEPTION '店舗の返答待ち、確定後、取消後は希望店舗を変更できません' USING ERRCODE='22023'; END IF;
 IF g.reservation_id IS NOT NULL THEN
  SELECT status INTO res_status FROM public.reservations WHERE id=g.reservation_id AND organization_id=g.organization_id FOR SHARE;
  IF res_status IS DISTINCT FROM 'cancelled' THEN RAISE EXCEPTION '予約申請中は希望店舗を変更できません' USING ERRCODE='22023'; END IF;
 END IF;
 IF p_expected_store_ids IS NULL OR coalesce(g.preferred_store_ids,'{}'::uuid[]) IS DISTINCT FROM p_expected_store_ids THEN
  RAISE EXCEPTION '希望店舗が変更されています。画面を更新して選び直してください' USING ERRCODE='40001';
 END IF;
 IF coalesce(cardinality(p_store_ids),0)=0 OR array_position(p_store_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION '店舗を1つ以上選択してください' USING ERRCODE='22023'; END IF;
 SELECT array_agg(DISTINCT s ORDER BY s) INTO selected FROM unnest(p_store_ids) s;
 SELECT s.available_stores INTO allowed FROM public.organization_scenarios s WHERE s.organization_id=g.organization_id
  AND (s.scenario_master_id=g.scenario_master_id OR s.id=g.scenario_master_id)
  ORDER BY (s.id=g.scenario_master_id) DESC LIMIT 1 FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION '組織内の作品設定を確認できません' USING ERRCODE='22023'; END IF;
 FOREACH store IN ARRAY selected LOOP
  PERFORM 1 FROM public.stores s WHERE s.id=store AND s.organization_id=g.organization_id AND s.status='active'
   AND s.ownership_type IS DISTINCT FROM 'office'
   AND (CASE WHEN coalesce(cardinality(allowed),0)>0 THEN store::text=ANY(allowed) ELSE NOT coalesce(s.is_temporary,false) END) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION '選択できない店舗が含まれています。店舗一覧を再読み込みしてください' USING ERRCODE='22023'; END IF;
 END LOOP;
 FOR cd IN SELECT * FROM public.private_group_candidate_dates WHERE group_id=g.id AND status IS DISTINCT FROM 'rejected' ORDER BY id FOR UPDATE LOOP
  slot:=CASE cd.time_slot WHEN 'morning' THEN 'morning' WHEN '朝' THEN 'morning' WHEN '午前' THEN 'morning' WHEN 'afternoon' THEN 'afternoon' WHEN '昼' THEN 'afternoon' WHEN '午後' THEN 'afternoon' WHEN 'evening' THEN 'evening' WHEN '夜' THEN 'evening' WHEN '夜間' THEN 'evening' END;
  IF slot IS NULL OR cd.start_time IS NULL OR cd.end_time IS NULL THEN RAISE EXCEPTION '候補日時を確認できません' USING ERRCODE='22023'; END IF;
  start_at:=cd.date+cd.start_time::time;
  end_at:=cd.date+cd.end_time::time+CASE WHEN cd.end_time::time<cd.start_time::time THEN interval '1 day' ELSE interval '0 days' END;
  IF start_at=end_at THEN RAISE EXCEPTION '候補日時を確認できません' USING ERRCODE='22023'; END IF;
  -- 全店舗を1つのSELECTの同じスナップショットで確認する。
  -- 店舗間の公演移動の前後を混ぜて「全店満席」と誤認しない。
  SELECT EXISTS(
   SELECT 1 FROM unnest(selected) AS choice(store_id)
   WHERE NOT EXISTS(SELECT 1 FROM public.schedule_blocked_slots b WHERE b.organization_id=g.organization_id AND b.store_id=choice.store_id::text AND b.date=cd.date AND b.time_slot=slot)
   AND NOT EXISTS(SELECT 1 FROM public.schedule_events e WHERE e.organization_id=g.organization_id AND e.store_id=choice.store_id AND e.is_cancelled=false
    AND e.date BETWEEN cd.date-2 AND cd.date+2
    AND e.date+e.start_time < end_at+make_interval(mins=>public.resolve_preparation_minutes(g.organization_id,NULL,NULL,e.id))
    AND e.date+e.end_time+CASE WHEN e.end_time<e.start_time THEN interval '1 day' ELSE interval '0 days' END > start_at-make_interval(mins=>public.resolve_preparation_minutes(g.organization_id,choice.store_id,g.scenario_master_id,NULL)))
  ) INTO available;
  IF NOT available THEN
   DELETE FROM public.private_group_candidate_dates WHERE id=cd.id AND group_id=g.id;
   removed:=removed+1;
  END IF;
 END LOOP;
 UPDATE public.private_groups SET preferred_store_ids=selected,updated_at=now() WHERE id=g.id;
 RETURN removed;
END $$;


ALTER FUNCTION "public"."private_group_set_preferred_stores"("p_group_id" "uuid", "p_store_ids" "uuid"[], "p_expected_store_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_discord_notification_queue"() RETURNS TABLE("processed" integer, "succeeded" integer, "failed" integer, "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_processed INTEGER := 0;
  v_succeeded INTEGER := 0;
  v_failed INTEGER := 0;
  v_details JSONB := '[]'::JSONB;
  v_notification RECORD;
BEGIN
  -- pending状態で、next_retry_atが現在時刻を過ぎているものを取得
  FOR v_notification IN
    SELECT *
    FROM discord_notification_queue
    WHERE status = 'pending'
      AND next_retry_at <= NOW()
      AND retry_count < max_retries
    ORDER BY created_at
    LIMIT 10  -- 一度に処理する最大数
    FOR UPDATE SKIP LOCKED
  LOOP
    v_processed := v_processed + 1;
    
    -- リトライカウントを増やし、次回リトライ時刻を設定
    UPDATE discord_notification_queue
    SET 
      retry_count = retry_count + 1,
      next_retry_at = NOW() + (INTERVAL '5 minutes' * (retry_count + 1)),
      updated_at = NOW()
    WHERE id = v_notification.id;
    
    v_details := v_details || jsonb_build_object(
      'id', v_notification.id,
      'notification_type', v_notification.notification_type,
      'retry_count', v_notification.retry_count + 1,
      'webhook_url', LEFT(v_notification.webhook_url, 50) || '...'
    );
  END LOOP;
  
  RETURN QUERY SELECT 
    v_processed,
    v_succeeded,
    v_failed,
    v_details;
END;
$$;


ALTER FUNCTION "public"."process_discord_notification_queue"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_discord_notification_queue"() IS 'Discord通知キューを処理し、リトライ対象を返す。実際の送信はEdge Functionで行う';



CREATE OR REPLACE FUNCTION "public"."process_waitlist_notification_queue"() RETURNS TABLE("processed_count" integer, "success_count" integer, "failed_count" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_processed INTEGER := 0;
  v_success INTEGER := 0;
  v_failed INTEGER := 0;
  v_record RECORD;
BEGIN
  -- 未処理のキューを取得（retry_count < 3）
  FOR v_record IN
    SELECT *
    FROM waitlist_notification_queue
    WHERE status IN ('pending', 'processing')
      AND retry_count < 3
      AND (last_retry_at IS NULL OR last_retry_at < NOW() - INTERVAL '5 minutes')
    ORDER BY created_at
    LIMIT 100
    FOR UPDATE SKIP LOCKED
  LOOP
    v_processed := v_processed + 1;
    
    -- ステータスを processing に更新
    UPDATE waitlist_notification_queue
    SET status = 'processing',
        retry_count = retry_count + 1,
        last_retry_at = NOW(),
        updated_at = NOW()
    WHERE id = v_record.id;
    
    -- Edge Function を呼び出し（実際の実装は外部で行う）
    -- ここでは成功とみなしてステータスを completed に更新
    -- 実際のリトライロジックは別途実装が必要
    
    -- 仮の成功処理（実際は Edge Function の結果を見る）
    UPDATE waitlist_notification_queue
    SET status = 'completed',
        updated_at = NOW()
    WHERE id = v_record.id;
    
    v_success := v_success + 1;
  END LOOP;
  
  -- 3回失敗したレコードを failed に更新
  UPDATE waitlist_notification_queue
  SET status = 'failed',
      updated_at = NOW()
  WHERE retry_count >= 3
    AND status != 'failed';
  
  SELECT v_processed, v_success, v_failed
  INTO processed_count, success_count, failed_count;
  
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."process_waitlist_notification_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_recruitment_mail_alert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_kind text; v_kinds text[]:='{}'; v_channel text; v_message text;
BEGIN
 IF NEW.status='failed' THEN
  NEW.first_failed_at:=COALESCE(OLD.first_failed_at,now());
  IF OLD.first_failed_at IS NULL THEN v_kinds:=array_append(v_kinds,'recruitment_mail_failed'); END IF;
  IF NEW.attempts>=10 THEN v_kinds:=array_append(v_kinds,'recruitment_mail_exhausted'); END IF;
 ELSIF NEW.status='sent' AND OLD.first_failed_at IS NOT NULL THEN
  v_kinds:=array_append(v_kinds,'recruitment_mail_recovered');
 ELSIF NEW.status='expired' AND OLD.first_failed_at IS NOT NULL THEN
  v_kinds:=array_append(v_kinds,'recruitment_mail_exhausted');
 END IF;
 IF cardinality(v_kinds)=0 THEN RETURN NEW; END IF;
 SELECT discord_business_channel_id INTO v_channel FROM organization_settings WHERE organization_id=NEW.organization_id;
 IF v_channel IS NULL OR v_channel !~ '^[0-9]+$' THEN RAISE EXCEPTION '開催・中止通知のDiscord送信先が未設定です'; END IF;
 FOREACH v_kind IN ARRAY v_kinds LOOP
  v_message:=CASE v_kind
   WHEN 'recruitment_mail_failed' THEN '【追加募集メール：送信失敗】自動再送を続けています。'
   WHEN 'recruitment_mail_recovered' THEN '【追加募集メール：送信できました】先ほど失敗したメールの送信処理が成功しました。'
   ELSE '【追加募集メール：運営対応依頼】自動送信を完了できませんでした。運営担当は電話やDMなど別の方法でお客様への連絡をお願いします。' END;
  v_message:=v_message||E'\n'||COALESCE(NEW.snapshot->>'date','')||' '||COALESCE(NEW.snapshot->>'start_time','')||' '||COALESCE(NEW.snapshot->>'scenario','')
   ||E'\n通知参照: '||NEW.id::text||E'\n予約参照: '||NEW.reservation_id::text;
  INSERT INTO discord_notification_queue(organization_id,webhook_url,message_payload,notification_type,reference_id,dedupe_key,max_retries,next_retry_at)
   VALUES(NEW.organization_id,'https://discord.com/api/v10/channels/'||v_channel||'/messages',
    jsonb_build_object('content',v_message,'allowed_mentions',jsonb_build_object('parse','[]'::jsonb)),v_kind,NEW.id,NEW.id::text,10,now())
   ON CONFLICT DO NOTHING;
 END LOOP;
 RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."queue_recruitment_mail_alert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_recruitment_operation_alert"("p_org" "uuid", "p_event" "uuid", "p_type" "text", "p_key" "text", "p_message" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE channel text;
BEGIN
 SELECT discord_business_channel_id INTO channel FROM organization_settings WHERE organization_id=p_org;
 IF channel IS NULL OR channel !~ '^[0-9]+$' THEN RAISE EXCEPTION '開催・中止通知のDiscord送信先が未設定です'; END IF;
 INSERT INTO discord_notification_queue(organization_id,webhook_url,message_payload,notification_type,reference_id,dedupe_key,max_retries,next_retry_at)
 VALUES(p_org,'https://discord.com/api/v10/channels/'||channel||'/messages',jsonb_build_object('content',p_message||E'\n公演参照: '||p_event::text,'allowed_mentions',jsonb_build_object('parse','[]'::jsonb)),p_type,md5(p_key)::uuid,p_key,10,now()) ON CONFLICT DO NOTHING;
END $_$;


