CREATE OR REPLACE FUNCTION "public"."read_survey_question_settings"("p_org_scenario_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE org uuid; questions jsonb;
BEGIN
 SELECT organization_id INTO org FROM public.organization_scenarios WHERE id=p_org_scenario_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'アンケート設定を取得できません' USING ERRCODE='42501'; END IF;
 PERFORM public.require_survey_question_staff(org);
 SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.order_num,q.id),'[]'::jsonb) INTO questions
 FROM public.org_scenario_survey_questions q WHERE org_scenario_id=p_org_scenario_id;
 RETURN jsonb_build_object('questions',questions,'revision',md5(questions::text));
END $$;


ALTER FUNCTION "public"."read_survey_question_settings"("p_org_scenario_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalc_current_participants_for_event"("p_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
BEGIN
  -- A subquery inside UPDATE can retain a pre-wait snapshot and overwrite a newer count.
  -- This separate statement obtains the lock first, then the next statement sees committed reservations.
  PERFORM 1 FROM public.schedule_events WHERE id=p_event_id FOR NO KEY UPDATE;
  UPDATE public.schedule_events se
  SET current_participants = coalesce((
    SELECT sum(r.participant_count) FROM public.reservations r
    WHERE r.schedule_event_id=se.id AND r.status IN ('pending','confirmed','gm_confirmed','checked_in')
  ),0)
  WHERE se.id=p_event_id;
END;
$$;


ALTER FUNCTION "public"."recalc_current_participants_for_event"("p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalc_current_participants_for_event"("p_event_id" "uuid") IS 'reservations の集計値から schedule_events.current_participants を再計算して更新する（checked_in を含む）。';



CREATE OR REPLACE FUNCTION "public"."recalc_current_participants_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE event_ids uuid[]; event_id uuid;
BEGIN
  IF TG_OP='DELETE' THEN event_ids:=ARRAY[OLD.schedule_event_id];
  ELSIF TG_OP='UPDATE' THEN event_ids:=ARRAY[OLD.schedule_event_id,NEW.schedule_event_id];
  ELSE event_ids:=ARRAY[NEW.schedule_event_id]; END IF;
  -- Moves between events take the two locks in a stable order.
  PERFORM 1 FROM public.schedule_events WHERE id=ANY(event_ids) ORDER BY id FOR NO KEY UPDATE;
  FOR event_id IN SELECT DISTINCT id FROM unnest(event_ids) id WHERE id IS NOT NULL ORDER BY id LOOP
    PERFORM public.recalc_current_participants_for_event(event_id);
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."recalc_current_participants_trigger"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalc_current_participants_trigger"() IS 'reservations の変更を契機に current_participants を再計算するトリガ関数（row_security=off）。';



CREATE OR REPLACE FUNCTION "public"."reconcile_private_delivery_receipt"("p_kind" "text", "p_delivery_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_provider_id" "text", "p_sent_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $_$
DECLARE table_name text; d jsonb; token uuid:=gen_random_uuid();
BEGIN
 table_name:=CASE p_kind WHEN 'approval' THEN 'private_booking_approval_deliveries'
  WHEN 'survey' THEN 'private_group_survey_deliveries' WHEN 'rejection' THEN 'private_booking_rejection_deliveries' END;
 IF table_name IS NULL OR p_actor_id IS NULL OR p_provider_id IS NULL OR length(btrim(p_provider_id))=0 OR p_sent_at IS NULL THEN
  RAISE EXCEPTION 'INVALID_DELIVERY_RECEIPT' USING ERRCODE='22023';
 END IF;
 EXECUTE format('SELECT to_jsonb(d) FROM public.%I d WHERE id=$1 AND organization_id=$2 FOR UPDATE NOWAIT',table_name)
  INTO d USING p_delivery_id,p_organization_id;
 IF d IS NULL THEN RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE='22023'; END IF;
 IF d->>'status'='sent' AND d->>'provider_message_id'=p_provider_id THEN RETURN true; END IF;
 IF d->>'status' NOT IN ('uncertain','failed','superseded') OR (d->>'updated_at')::timestamptz IS DISTINCT FROM p_expected_updated_at
  OR d->>'first_attempt_at' IS NULL OR d->'provider_payload' IS NULL OR d->'provider_payload'='null'::jsonb THEN
  RAISE EXCEPTION 'DELIVERY_STATE_CHANGED' USING ERRCODE='40001';
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('private-delivery-receipt:'||p_provider_id,0)) THEN
  RAISE EXCEPTION 'DELIVERY_RECEIPT_BUSY' USING ERRCODE='55P03';
 END IF;
 -- 他の配送への受付IDの使い回しは許可しない。
 IF EXISTS(SELECT 1 FROM public.private_booking_approval_deliveries WHERE provider_message_id=p_provider_id AND (p_kind<>'approval' OR id<>p_delivery_id))
  OR EXISTS(SELECT 1 FROM public.private_group_survey_deliveries WHERE provider_message_id=p_provider_id AND (p_kind<>'survey' OR id<>p_delivery_id))
  OR EXISTS(SELECT 1 FROM public.private_booking_rejection_deliveries WHERE provider_message_id=p_provider_id AND (p_kind<>'rejection' OR id<>p_delivery_id)) THEN
  RAISE EXCEPTION 'DELIVERY_RECEIPT_REUSED' USING ERRCODE='22023';
 END IF;
 EXECUTE format('UPDATE public.%I SET status=''sending'',lease_token=$2,lease_until=now()+interval ''2 minutes'' WHERE id=$1',table_name)
  USING p_delivery_id,token;
 IF p_kind='approval' THEN PERFORM public.complete_private_approval_delivery(p_delivery_id,token,p_provider_id,p_sent_at);
 ELSIF p_kind='survey' THEN PERFORM public.complete_private_survey_delivery(p_delivery_id,token,p_provider_id,p_sent_at);
 ELSE PERFORM public.complete_private_rejection_delivery(p_delivery_id,token,p_provider_id,p_sent_at); END IF;
 INSERT INTO public.private_delivery_resolutions(organization_id,delivery_kind,delivery_id,actor_id,action,previous_status,provider_message_id)
 VALUES(p_organization_id,p_kind,p_delivery_id,p_actor_id,'provider_verified',d->>'status',p_provider_id);
 RETURN true;
END $_$;


ALTER FUNCTION "public"."reconcile_private_delivery_receipt"("p_kind" "text", "p_delivery_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_provider_id" "text", "p_sent_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_recruitment_mail_alerts"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 UPDATE discord_notification_queue SET status='pending',updated_at=now()
  WHERE notification_type IN ('recruitment_mail_failed','recruitment_mail_recovered','recruitment_mail_exhausted','recruitment_shortage','recruitment_x_failed','recruitment_x_attention','recruitment_x_recovered')
   AND status='sending' AND updated_at<now()-interval '5 minutes';
 UPDATE performance_recruitment_notices SET status='failed',lease_until=NULL
  WHERE status='sending' AND attempts>=10 AND lease_until<now();
 UPDATE performance_recruitment_notices n SET status='expired',lease_until=NULL
  FROM performance_recruitment_deadlines d
  WHERE n.schedule_event_id=d.schedule_event_id AND n.organization_id=d.organization_id
   AND n.first_failed_at IS NOT NULL AND n.status IN ('pending','failed') AND n.attempts<10
   AND ((n.kind='extension' AND (d.status<>'active' OR d.deadline<=now())) OR n.created_at<=now()-interval '1 day');
END;
$$;


ALTER FUNCTION "public"."recover_recruitment_mail_alerts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recruitment_event_snapshot"("p_org" "uuid", "p_event" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT jsonb_build_object('scenario',e.scenario,'date',e.date,'start_time',e.start_time,'store_name',st.name,
 'deadline',d.deadline,'site_url',p.customer_site_url,'missing_participants',GREATEST(0,
 LEAST(COALESCE(os.override_player_count_min,m.player_count_min,legacy.player_count_min,ceil(COALESCE(os.override_player_count_max,m.player_count_max,e.max_participants,legacy.player_count_max,8)::numeric/2)::int),COALESCE(os.override_player_count_max,m.player_count_max,e.max_participants,legacy.player_count_max,8))
 - COALESCE((SELECT sum(r.participant_count) FROM reservations r WHERE r.schedule_event_id=e.id AND r.organization_id=e.organization_id AND r.status IN ('pending','confirmed','gm_confirmed','checked_in')),0)
 - (SELECT count(*) FROM jsonb_each_text(COALESCE(e.gm_roles,'{}')) staff WHERE staff.value='staff' AND NOT EXISTS(SELECT 1 FROM reservations r WHERE r.schedule_event_id=e.id AND r.organization_id=e.organization_id AND r.status IN ('pending','confirmed','gm_confirmed','checked_in') AND r.reservation_source='staff_entry' AND staff.key=ANY(r.participant_names)))))
 FROM schedule_events e JOIN performance_recruitment_deadlines d ON d.schedule_event_id=e.id AND d.organization_id=e.organization_id
 JOIN performance_recruitment_policies p ON p.organization_id=e.organization_id
 LEFT JOIN LATERAL(SELECT s.* FROM organization_scenarios s WHERE s.organization_id=e.organization_id AND ((e.organization_scenario_id IS NOT NULL AND s.id=e.organization_scenario_id) OR(e.organization_scenario_id IS NULL AND s.scenario_master_id=COALESCE(e.scenario_master_id,e.scenario_id))) LIMIT 1) os ON true
 LEFT JOIN scenario_masters m ON m.id=COALESCE(os.scenario_master_id,e.scenario_master_id)
 LEFT JOIN scenarios legacy ON legacy.id=e.scenario_id LEFT JOIN stores st ON st.id=e.store_id
 WHERE e.id=p_event AND e.organization_id=p_org;
$$;


ALTER FUNCTION "public"."recruitment_event_snapshot"("p_org" "uuid", "p_event" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recruitment_missing_limit"("p_minimum" integer, "p_mode" "text", "p_value" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
 SELECT CASE WHEN p_mode='percent' AND p_value BETWEEN 1 AND 100 THEN floor(GREATEST(p_minimum,1)::numeric*p_value/100)::integer
 WHEN p_mode='count' AND p_value BETWEEN 1 AND 20 THEN p_value ELSE NULL END;
$$;


ALTER FUNCTION "public"."recruitment_missing_limit"("p_minimum" integer, "p_mode" "text", "p_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_organization_for_signup"("p_name" "text", "p_slug" "text", "p_contact_email" "text", "p_store_name" "text" DEFAULT NULL::"text", "p_store_address" "text" DEFAULT NULL::"text", "p_store_phone" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org_id        UUID;
  v_store_name    TEXT;
  v_short_name    TEXT;
  v_token text:=encode(extensions.gen_random_bytes(32),'hex');
  v_email text:=lower(trim(p_contact_email));
BEGIN
  IF v_email IS NULL OR v_email='' OR length(v_email)>320 OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+$' THEN
    RAISE EXCEPTION '登録者のメールアドレスが必要です' USING ERRCODE='22023';
  END IF;
  IF auth.uid() IS NOT NULL AND lower(coalesce(auth.email(),''))<>v_email THEN
    RAISE EXCEPTION 'ログイン中のメールアドレスで登録してください' USING ERRCODE='42501';
  END IF;
  IF p_name IS NULL OR trim(p_name) = '' THEN
    RAISE EXCEPTION 'invalid_name: 組織名は必須です';
  END IF;

  IF p_slug IS NULL OR trim(p_slug) = '' THEN
    RAISE EXCEPTION 'invalid_slug: 識別子は必須です';
  END IF;

  IF p_slug !~ '^[a-z0-9][a-z0-9\-]{0,29}$' THEN
    RAISE EXCEPTION 'invalid_slug_format: 識別子は半角英数字とハイフンのみ使用できます';
  END IF;

  IF EXISTS (SELECT 1 FROM public.organizations WHERE slug = p_slug) THEN
    RAISE EXCEPTION 'slug_already_exists: この識別子は既に使用されています';
  END IF;

  INSERT INTO public.organizations (
    name, slug, plan, contact_email, is_active, is_license_manager, settings
  )
  VALUES (
    trim(p_name), p_slug, 'free',
    COALESCE(nullif(trim(p_contact_email), ''), NULL),
    true, false, '{}'::jsonb
  )
  RETURNING id INTO v_org_id;

  -- 代表店舗を作成（指定されていれば）
  -- ※ initialize_organization_data() トリガーが「臨時会場 1〜5」を別途作るのは継続
  IF p_store_name IS NOT NULL AND trim(p_store_name) != '' THEN
    v_store_name := trim(p_store_name);
    -- short_name は NOT NULL なので名前から作る（先頭6文字、空なら名前そのもの）
    v_short_name := COALESCE(NULLIF(left(v_store_name, 6), ''), v_store_name);

    INSERT INTO public.stores (
      name, short_name, address, phone_number,
      organization_id, status, capacity, rooms, color,
      opening_date, is_temporary,
      created_at, updated_at
    )
    VALUES (
      v_store_name,
      v_short_name,
      NULLIF(trim(COALESCE(p_store_address, '')), ''),
      NULLIF(trim(COALESCE(p_store_phone, '')), ''),
      v_org_id,
      'active',
      6,        -- capacity デフォルト
      1,        -- rooms デフォルト
      '#E60012', -- color デフォルト（テーマカラー）
      CURRENT_DATE,
      false,    -- is_temporary = false（代表店舗）
      NOW(), NOW()
    );
  END IF;

  INSERT INTO public.organization_signup_claims(organization_id,token_hash,email,created_by) VALUES(v_org_id,extensions.digest(v_token,'sha256'),v_email,auth.uid());
  RETURN json_build_object(
    'id',   v_org_id,
    'slug', p_slug,
    'name', trim(p_name),
    'claim_token',v_token
  );
END;
$_$;


ALTER FUNCTION "public"."register_organization_for_signup"("p_name" "text", "p_slug" "text", "p_contact_email" "text", "p_store_name" "text", "p_store_address" "text", "p_store_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_private_booking_with_delivery"("p_reservation_id" "uuid", "p_message_body" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
  v_event public.schedule_events%ROWTYPE;
  v_group public.private_groups%ROWTYPE;
  v_message text;
  v_notice_id uuid;
  v_cancelled_at timestamptz;
  v_existing public.private_group_messages%ROWTYPE;
  v_delivery public.private_booking_rejection_deliveries%ROWTYPE;
  v_customer_email text;
  v_customer_name text;
  v_reason constant text := '貸切リクエストを却下しました';
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF p_message_body IS NULL OR length(btrim(p_message_body))=0 OR length(p_message_body)>20000 THEN
    RAISE EXCEPTION 'INVALID_REJECTION_MESSAGE' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_reservation FROM public.reservations
  WHERE id=p_reservation_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE='P0005'; END IF;
  IF NOT COALESCE((public.is_org_admin() AND public.get_user_organization_id()=v_reservation.organization_id)
    OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
      AND organization_id=v_reservation.organization_id AND status='active'),false) THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF v_reservation.status='cancelled' AND v_reservation.cancellation_reason IS DISTINCT FROM v_reason THEN
    RAISE EXCEPTION 'RESERVATION_ALREADY_CANCELLED' USING ERRCODE='22023';
  END IF;
  -- 取消日時が同じなら再試行。再承認後の却下は新しい取消日時で別通知にする。
  v_cancelled_at := CASE WHEN v_reservation.status='cancelled' THEN v_reservation.cancelled_at ELSE now() END;
  IF v_cancelled_at IS NULL THEN
    RAISE EXCEPTION 'REJECTION_TIMESTAMP_MISSING' USING ERRCODE='22023';
  END IF;
  v_notice_id := md5(v_reservation.id::text || ':' || extract(epoch FROM v_cancelled_at)::text)::uuid;
  IF v_reservation.schedule_event_id IS NOT NULL THEN
    SELECT * INTO v_event FROM public.schedule_events WHERE id=v_reservation.schedule_event_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_event.organization_id IS DISTINCT FROM v_reservation.organization_id THEN
      RAISE EXCEPTION 'EVENT_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
    END IF;
    IF v_event.category IS DISTINCT FROM 'private' AND v_event.is_private_booking IS NOT TRUE THEN
      RAISE EXCEPTION 'EVENT_NOT_PRIVATE' USING ERRCODE='22023';
    END IF;
    -- 他の予約が残る公演を、この申込の却下だけで中止にしない。
    PERFORM 1 FROM public.reservations WHERE schedule_event_id=v_event.id AND id<>v_reservation.id
      AND status IN ('pending','confirmed','gm_confirmed','checked_in') FOR UPDATE NOWAIT;
    IF FOUND THEN RAISE EXCEPTION 'PRIVATE_EVENT_HAS_OTHER_RESERVATIONS' USING ERRCODE='22023'; END IF;
  END IF;
  IF v_reservation.private_group_id IS NULL AND v_reservation.reservation_source IS DISTINCT FROM 'web_private'
    AND v_reservation.schedule_event_id IS NULL THEN
    RAISE EXCEPTION 'RESERVATION_NOT_PRIVATE' USING ERRCODE='22023';
  END IF;
  IF v_reservation.private_group_id IS NOT NULL THEN
    SELECT * INTO v_group FROM public.private_groups WHERE id=v_reservation.private_group_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_group.organization_id IS DISTINCT FROM v_reservation.organization_id THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
    END IF;
    IF v_group.reservation_id IS DISTINCT FROM v_reservation.id THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_RESERVATION_MISMATCH' USING ERRCODE='P0051';
    END IF;
    IF v_group.status IS NULL OR v_group.status NOT IN ('booking_requested','confirmed','date_adjusting')
      OR (v_group.status='date_adjusting' AND v_reservation.status IS DISTINCT FROM 'cancelled') THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_NOT_AWAITING_REJECTION' USING ERRCODE='22023';
    END IF;
    v_message := jsonb_build_object('type','system','action','booking_rejected',
      'title','貸切リクエストが却下されました','body',p_message_body,'reservation_id',v_reservation.id,'cancelled_at_epoch',extract(epoch FROM v_cancelled_at))::text;
    -- 予約と取消日時から通知IDを固定し、同じ却下の再実行で通知を増やさない。
    -- 万一既存IDと衝突した場合は別通知を上書きせず、処理全体を拒否する。
    SELECT * INTO v_existing FROM public.private_group_messages WHERE id=v_notice_id FOR UPDATE NOWAIT;
    IF FOUND AND (v_existing.group_id IS DISTINCT FROM v_group.id
      OR v_existing.member_id IS NOT NULL OR v_existing.message IS DISTINCT FROM v_message) THEN
      RAISE EXCEPTION 'REJECTION_NOTICE_CONFLICT' USING ERRCODE='22023';
    END IF;
  END IF;
  IF v_reservation.status IS DISTINCT FROM 'cancelled' THEN
    IF public.cancel_reservation_with_lock(v_reservation.id,v_reservation.customer_id,v_reason) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'RESERVATION_CANCEL_FAILED';
    END IF;
  END IF;
  IF v_reservation.schedule_event_id IS NOT NULL AND v_event.is_cancelled IS NOT TRUE THEN
    UPDATE public.schedule_events SET is_cancelled=true,cancelled_at=now(),
      cancellation_reason=v_reason,updated_at=now() WHERE id=v_event.id;
  END IF;
  IF v_reservation.private_group_id IS NOT NULL THEN
    PERFORM public.mark_private_group_rejected_after_booking_rejection(v_reservation.id);
    INSERT INTO public.private_group_messages(id,group_id,member_id,message)
    VALUES(v_notice_id,v_group.id,NULL,v_message) ON CONFLICT(id) DO NOTHING;
    -- 事前確認後に同じIDが挿入された場合も、別内容を成功扱いにしない。
    SELECT * INTO v_existing FROM public.private_group_messages WHERE id=v_notice_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_existing.group_id IS DISTINCT FROM v_group.id
      OR v_existing.member_id IS NOT NULL OR v_existing.message IS DISTINCT FROM v_message THEN
      RAISE EXCEPTION 'REJECTION_NOTICE_CONFLICT' USING ERRCODE='22023';
    END IF;
  END IF;
  -- 再試行時は元の送信スナップショットを保持し、アドレス変更で別送信を作らない。
  SELECT * INTO v_delivery FROM public.private_booking_rejection_deliveries
    WHERE id=v_notice_id FOR UPDATE NOWAIT;
  IF FOUND THEN
    IF v_delivery.reservation_id IS DISTINCT FROM v_reservation.id
      OR v_delivery.organization_id IS DISTINCT FROM v_reservation.organization_id
      OR v_delivery.cancelled_at IS DISTINCT FROM v_cancelled_at
      OR v_delivery.message_body IS DISTINCT FROM p_message_body THEN
      RAISE EXCEPTION 'REJECTION_DELIVERY_CONFLICT' USING ERRCODE='22023';
    END IF;
  ELSE
    SELECT email,name INTO v_customer_email,v_customer_name FROM public.customers
      WHERE id=v_reservation.customer_id
        AND (organization_id=v_reservation.organization_id OR organization_id IS NULL);
    INSERT INTO public.private_booking_rejection_deliveries(
      id,reservation_id,organization_id,cancelled_at,customer_email,customer_name,scenario_title,message_body,status,last_error
    ) VALUES (
      v_notice_id,v_reservation.id,v_reservation.organization_id,v_cancelled_at,
      nullif(btrim(coalesce(nullif(v_reservation.customer_email,''),v_customer_email)),''),
      coalesce(nullif(v_reservation.customer_name,''),nullif(v_customer_name,''),'お客様'),
      coalesce(v_reservation.title,''),p_message_body,
      CASE WHEN v_reservation.status='cancelled' THEN 'uncertain' ELSE 'pending' END,
      CASE WHEN v_reservation.status='cancelled' THEN 'legacy_delivery_unconfirmed' ELSE NULL END
    );
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."reject_private_booking_with_delivery"("p_reservation_id" "uuid", "p_message_body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reject_private_booking_with_delivery"("p_reservation_id" "uuid", "p_message_body" "text") IS '同組織管理者・有効スタッフ専用。貸切予約却下、公演中止、グループ差戻し、候補却下、チャット通知とメール送信予定を一括保存。通知IDは予約IDと取消日時で固定。';



CREATE OR REPLACE FUNCTION "public"."reject_private_booking_with_notice"("p_reservation_id" "uuid", "p_message_body" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
  v_event public.schedule_events%ROWTYPE;
  v_group public.private_groups%ROWTYPE;
  v_message text;
  v_notice_id uuid;
  v_cancelled_at timestamptz;
  v_existing public.private_group_messages%ROWTYPE;
  v_reason constant text := '貸切リクエストを却下しました';
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  IF p_message_body IS NULL OR length(btrim(p_message_body))=0 OR length(p_message_body)>20000 THEN
    RAISE EXCEPTION 'INVALID_REJECTION_MESSAGE' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_reservation FROM public.reservations
  WHERE id=p_reservation_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE='P0005'; END IF;
  IF NOT COALESCE((public.is_org_admin() AND public.get_user_organization_id()=v_reservation.organization_id)
    OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
      AND organization_id=v_reservation.organization_id AND status='active'),false) THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501';
  END IF;
  IF v_reservation.status='cancelled' AND v_reservation.cancellation_reason IS DISTINCT FROM v_reason THEN
    RAISE EXCEPTION 'RESERVATION_ALREADY_CANCELLED' USING ERRCODE='22023';
  END IF;
  -- 取消日時が同じなら再試行。再承認後の却下は新しい取消日時で別通知にする。
  v_cancelled_at := CASE WHEN v_reservation.status='cancelled' THEN v_reservation.cancelled_at ELSE now() END;
  IF v_cancelled_at IS NULL THEN
    RAISE EXCEPTION 'REJECTION_TIMESTAMP_MISSING' USING ERRCODE='22023';
  END IF;
  v_notice_id := md5(v_reservation.id::text || ':' || extract(epoch FROM v_cancelled_at)::text)::uuid;
  IF v_reservation.schedule_event_id IS NOT NULL THEN
    SELECT * INTO v_event FROM public.schedule_events WHERE id=v_reservation.schedule_event_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_event.organization_id IS DISTINCT FROM v_reservation.organization_id THEN
      RAISE EXCEPTION 'EVENT_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
    END IF;
    IF v_event.category IS DISTINCT FROM 'private' AND v_event.is_private_booking IS NOT TRUE THEN
      RAISE EXCEPTION 'EVENT_NOT_PRIVATE' USING ERRCODE='22023';
    END IF;
    -- 他の予約が残る公演を、この申込の却下だけで中止にしない。
    PERFORM 1 FROM public.reservations WHERE schedule_event_id=v_event.id AND id<>v_reservation.id
      AND status IN ('pending','confirmed','gm_confirmed','checked_in') FOR UPDATE NOWAIT;
    IF FOUND THEN RAISE EXCEPTION 'PRIVATE_EVENT_HAS_OTHER_RESERVATIONS' USING ERRCODE='22023'; END IF;
  END IF;
  IF v_reservation.private_group_id IS NULL AND v_reservation.reservation_source IS DISTINCT FROM 'web_private'
    AND v_reservation.schedule_event_id IS NULL THEN
    RAISE EXCEPTION 'RESERVATION_NOT_PRIVATE' USING ERRCODE='22023';
  END IF;
  IF v_reservation.private_group_id IS NOT NULL THEN
    SELECT * INTO v_group FROM public.private_groups WHERE id=v_reservation.private_group_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_group.organization_id IS DISTINCT FROM v_reservation.organization_id THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='P0050';
    END IF;
    IF v_group.reservation_id IS DISTINCT FROM v_reservation.id THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_RESERVATION_MISMATCH' USING ERRCODE='P0051';
    END IF;
    IF v_group.status IS NULL OR v_group.status NOT IN ('booking_requested','confirmed','date_adjusting')
      OR (v_group.status='date_adjusting' AND v_reservation.status IS DISTINCT FROM 'cancelled') THEN
      RAISE EXCEPTION 'PRIVATE_GROUP_NOT_AWAITING_REJECTION' USING ERRCODE='22023';
    END IF;
    v_message := jsonb_build_object('type','system','action','booking_rejected',
      'title','貸切リクエストが却下されました','body',p_message_body,'reservation_id',v_reservation.id,'cancelled_at_epoch',extract(epoch FROM v_cancelled_at))::text;
    -- 予約と取消日時から通知IDを固定し、同じ却下の再実行で通知を増やさない。
    -- 万一既存IDと衝突した場合は別通知を上書きせず、処理全体を拒否する。
    SELECT * INTO v_existing FROM public.private_group_messages WHERE id=v_notice_id FOR UPDATE NOWAIT;
    IF FOUND AND (v_existing.group_id IS DISTINCT FROM v_group.id
      OR v_existing.member_id IS NOT NULL OR v_existing.message IS DISTINCT FROM v_message) THEN
      RAISE EXCEPTION 'REJECTION_NOTICE_CONFLICT' USING ERRCODE='22023';
    END IF;
  END IF;
  IF v_reservation.status IS DISTINCT FROM 'cancelled' THEN
    IF public.cancel_reservation_with_lock(v_reservation.id,v_reservation.customer_id,v_reason) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'RESERVATION_CANCEL_FAILED';
    END IF;
  END IF;
  IF v_reservation.schedule_event_id IS NOT NULL AND v_event.is_cancelled IS NOT TRUE THEN
    UPDATE public.schedule_events SET is_cancelled=true,cancelled_at=now(),
      cancellation_reason=v_reason,updated_at=now() WHERE id=v_event.id;
  END IF;
  IF v_reservation.private_group_id IS NOT NULL THEN
    PERFORM public.mark_private_group_rejected_after_booking_rejection(v_reservation.id);
    INSERT INTO public.private_group_messages(id,group_id,member_id,message)
    VALUES(v_notice_id,v_group.id,NULL,v_message) ON CONFLICT(id) DO NOTHING;
    -- 事前確認後に同じIDが挿入された場合も、別内容を成功扱いにしない。
    SELECT * INTO v_existing FROM public.private_group_messages WHERE id=v_notice_id FOR UPDATE NOWAIT;
    IF NOT FOUND OR v_existing.group_id IS DISTINCT FROM v_group.id
      OR v_existing.member_id IS NOT NULL OR v_existing.message IS DISTINCT FROM v_message THEN
      RAISE EXCEPTION 'REJECTION_NOTICE_CONFLICT' USING ERRCODE='22023';
    END IF;
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."reject_private_booking_with_notice"("p_reservation_id" "uuid", "p_message_body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reject_private_booking_with_notice"("p_reservation_id" "uuid", "p_message_body" "text") IS '同組織管理者・有効スタッフ専用。貸切予約却下、公演中止、グループ差戻し、候補却下、チャット通知を一括保存。通知IDは予約IDと取消日時で固定。';



CREATE OR REPLACE FUNCTION "public"."remove_coupon_from_group_member"("p_member_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_member RECORD;
  v_group RECORD;
BEGIN
  -- メンバー情報を取得
  SELECT * INTO v_member FROM public.private_group_members WHERE id = p_member_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'メンバーが見つかりません');
  END IF;

  -- グループ情報を取得
  SELECT * INTO v_group FROM public.private_groups WHERE id = v_member.group_id;

  -- クーポン情報をクリア
  UPDATE public.private_group_members
  SET 
    coupon_id = NULL,
    coupon_discount = 0,
    final_amount = COALESCE(payment_amount, v_group.per_person_price, 0)
  WHERE id = p_member_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."remove_coupon_from_group_member"("p_member_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_coupon_from_group_member"("p_member_id" "uuid") IS 'グループメンバーのクーポン適用を解除する';



CREATE OR REPLACE FUNCTION "public"."rename_event_staff_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id AND EXISTS(
    SELECT 1 FROM public.schedule_event_staff_assignments WHERE staff_id=NEW.id) THEN
    RAISE EXCEPTION '公演担当記録のあるスタッフは組織を変更できません' USING ERRCODE='23514';
  END IF;
  IF NEW.name IS DISTINCT FROM OLD.name THEN
    UPDATE public.schedule_events e SET
      gms=array_replace(e.gms,OLD.name,NEW.name),
      gm_roles=CASE WHEN coalesce(e.gm_roles,'{}'::jsonb) ? OLD.name
        THEN (e.gm_roles - OLD.name) || jsonb_build_object(NEW.name,e.gm_roles->OLD.name)
        ELSE e.gm_roles END
    WHERE e.organization_id=NEW.organization_id AND EXISTS(
      SELECT 1 FROM public.schedule_event_staff_assignments a WHERE a.event_id=e.id AND a.staff_id=NEW.id);
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."rename_event_staff_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_ai_manager_work_store"("p_organization_id" "uuid", "p_expected_revision" integer, "p_store" "jsonb", "p_updated_by" "uuid") RETURNS TABLE("result_status" "text", "current_revision" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current_revision INTEGER;
BEGIN
  IF p_expected_revision < 0
    OR COALESCE((p_store->>'schema_version')::INTEGER, 0) <> 1
    OR COALESCE(p_store->>'mode', '') <> 'PRACTICE'
    OR jsonb_typeof(p_store->'items') <> 'array'
    OR COALESCE((p_store->>'revision')::INTEGER, -1) <> p_expected_revision + 1
  THEN
    RAISE EXCEPTION 'INVALID_WORK_STORE';
  END IF;

  SELECT revision INTO v_current_revision
  FROM public.ai_manager_work_stores
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    IF p_expected_revision <> 0 THEN
      RETURN QUERY SELECT 'REVISION_CONFLICT'::TEXT, 0;
      RETURN;
    END IF;
    INSERT INTO public.ai_manager_work_stores (
      organization_id, schema_version, mode, revision, items, updated_by
    ) VALUES (
      p_organization_id, 1, 'PRACTICE', 1, p_store->'items', p_updated_by
    );
    RETURN QUERY SELECT 'UPDATED'::TEXT, 1;
    RETURN;
  END IF;

  IF v_current_revision <> p_expected_revision THEN
    RETURN QUERY SELECT 'REVISION_CONFLICT'::TEXT, v_current_revision;
    RETURN;
  END IF;

  UPDATE public.ai_manager_work_stores
  SET revision = p_expected_revision + 1,
      items = p_store->'items',
      updated_by = p_updated_by,
      updated_at = NOW()
  WHERE organization_id = p_organization_id;

  RETURN QUERY SELECT 'UPDATED'::TEXT, p_expected_revision + 1;
END;
$$;


ALTER FUNCTION "public"."replace_ai_manager_work_store"("p_organization_id" "uuid", "p_expected_revision" integer, "p_store" "jsonb", "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_scenario_assignments_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid", "p_staff_ids" "uuid"[], "p_expected" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_organization_id IS NULL OR p_scenario_master_id IS NULL OR p_staff_ids IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid assignment request' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM public.organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Scenario unavailable' USING ERRCODE='23503'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(p_staff_ids) requested(staff_id) WHERE NOT EXISTS(SELECT 1 FROM public.staff s WHERE s.id=requested.staff_id AND s.organization_id=p_organization_id)) THEN
    RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='23503';
  END IF;
  PERFORM 1 FROM public.staff s WHERE s.organization_id=p_organization_id AND
    (s.id=ANY(p_staff_ids) OR EXISTS(SELECT 1 FROM public.staff_scenario_assignments a WHERE a.organization_id=p_organization_id AND a.scenario_master_id=p_scenario_master_id AND a.staff_id=s.id)) ORDER BY s.id FOR UPDATE;
  IF public.assignment_state(p_organization_id,NULL,p_scenario_master_id) IS DISTINCT FROM public.normalize_assignment_state(p_expected) THEN
    RAISE EXCEPTION 'Assignments changed' USING ERRCODE='40001';
  END IF;
  UPDATE public.staff_scenario_assignments SET can_main_gm=false,can_sub_gm=false,is_experienced=true
    WHERE organization_id=p_organization_id AND scenario_master_id=p_scenario_master_id AND (can_main_gm OR can_sub_gm) AND NOT(staff_id=ANY(p_staff_ids));
  INSERT INTO public.staff_scenario_assignments AS target
    (organization_id,staff_id,scenario_master_id,can_main_gm,can_sub_gm,is_experienced,notes)
    SELECT p_organization_id,id,p_scenario_master_id,true,true,false,p_notes FROM (SELECT DISTINCT unnest(p_staff_ids) id) s
    ON CONFLICT(staff_id,scenario_master_id) DO UPDATE SET can_main_gm=true,can_sub_gm=true,is_experienced=false
    WHERE NOT(target.can_main_gm OR target.can_sub_gm);
  RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."replace_scenario_assignments_atomic"("p_organization_id" "uuid", "p_scenario_master_id" "uuid", "p_staff_ids" "uuid"[], "p_expected" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_staff_assignments_atomic"("p_organization_id" "uuid", "p_staff_id" "uuid", "p_assignments" "jsonb", "p_expected" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE item jsonb;
BEGIN
  IF p_organization_id IS NULL OR p_staff_id IS NULL OR jsonb_typeof(p_assignments) IS DISTINCT FROM 'array' OR jsonb_typeof(p_expected) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid assignment request' USING ERRCODE='22023';
  END IF;
  -- 削除との競合を検知するため、組織の作品を安定した順序で保持する。
  PERFORM 1 FROM public.organization_scenarios WHERE organization_id=p_organization_id ORDER BY scenario_master_id FOR KEY SHARE;
  PERFORM 1 FROM public.staff WHERE id=p_staff_id AND organization_id=p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='23503'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_assignments)) <>
     (SELECT count(DISTINCT value->>'scenarioId') FROM jsonb_array_elements(p_assignments)) THEN
    RAISE EXCEPTION 'Duplicate or missing scenario' USING ERRCODE='22023';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_assignments) LOOP
    IF jsonb_typeof(item->'can_main_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(item->'can_sub_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(item->'is_experienced') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Invalid assignment flags' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=(item->>'scenarioId')::uuid) THEN
      RAISE EXCEPTION 'Scenario unavailable' USING ERRCODE='23503';
    END IF;
  END LOOP;
  IF public.assignment_state(p_organization_id,p_staff_id,NULL) IS DISTINCT FROM public.normalize_assignment_state(p_expected) THEN
    RAISE EXCEPTION 'Assignments changed' USING ERRCODE='40001';
  END IF;

  INSERT INTO public.staff_scenario_assignments AS target
    (organization_id,staff_id,scenario_master_id,can_main_gm,can_sub_gm,is_experienced,notes,assigned_at)
  SELECT p_organization_id,p_staff_id,(j.value->>'scenarioId')::uuid,
    (j.value->>'can_main_gm')::boolean,(j.value->>'can_sub_gm')::boolean,(j.value->>'is_experienced')::boolean,
    CASE WHEN j.value ? 'notes' THEN j.value->>'notes' ELSE old.notes END,coalesce(old.assigned_at,now())
  FROM jsonb_array_elements(p_assignments) j
  LEFT JOIN public.staff_scenario_assignments old ON old.organization_id=p_organization_id AND old.staff_id=p_staff_id AND old.scenario_master_id=(j.value->>'scenarioId')::uuid
  ON CONFLICT (staff_id,scenario_master_id) DO UPDATE SET
    can_main_gm=EXCLUDED.can_main_gm,can_sub_gm=EXCLUDED.can_sub_gm,is_experienced=EXCLUDED.is_experienced,notes=EXCLUDED.notes
  WHERE ROW(target.can_main_gm,target.can_sub_gm,target.is_experienced,target.notes)
    IS DISTINCT FROM ROW(EXCLUDED.can_main_gm,EXCLUDED.can_sub_gm,EXCLUDED.is_experienced,EXCLUDED.notes);

  DELETE FROM public.staff_scenario_assignments a WHERE a.organization_id=p_organization_id AND a.staff_id=p_staff_id
    AND EXISTS(SELECT 1 FROM public.organization_scenarios o WHERE o.organization_id=p_organization_id AND o.scenario_master_id=a.scenario_master_id)
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_assignments) j WHERE (j.value->>'scenarioId')::uuid=a.scenario_master_id);
  RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."replace_staff_assignments_atomic"("p_organization_id" "uuid", "p_staff_id" "uuid", "p_assignments" "jsonb", "p_expected" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_private_group_manager"("p_group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
 IF public.private_group_actor_role(p_group_id) IS NULL AND coalesce(auth.role(),'')<>'service_role' THEN
  RAISE EXCEPTION 'このグループを管理する権限がありません' USING ERRCODE='42501';
 END IF;
END $$;


ALTER FUNCTION "public"."require_private_group_manager"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_private_group_member"("p_group_id" "uuid", "p_member_id" "uuid", "p_guest_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_user uuid;
BEGIN
 SELECT user_id INTO v_user FROM private_group_members WHERE id=p_member_id AND group_id=p_group_id AND status='joined' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION '参加情報が見つかりません。招待ページから入り直してください' USING ERRCODE='42501'; END IF;
 IF v_user IS NOT NULL AND v_user=auth.uid() THEN RETURN; END IF;
 IF v_user IS NULL AND p_guest_token IS NOT NULL AND length(p_guest_token)=64 AND EXISTS(
  SELECT 1 FROM private_group_guest_sessions WHERE member_id=p_member_id
  AND token_hash=encode(extensions.digest(p_guest_token,'sha256'),'hex') AND expires_at>clock_timestamp()
 ) THEN RETURN; END IF;
 RAISE EXCEPTION '本人確認が必要です。メールアドレスとPINで入り直してください' USING ERRCODE='42501';
END $$;


ALTER FUNCTION "public"."require_private_group_member"("p_group_id" "uuid", "p_member_id" "uuid", "p_guest_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_survey_question_staff"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text; actor_org uuid;
BEGIN
 SELECT role::text,public.get_user_organization_id() INTO actor_role,actor_org FROM public.users WHERE id=actor;
 IF actor IS NOT NULL AND actor_role='license_admin' THEN RETURN; END IF;
 IF actor IS NOT NULL AND COALESCE(actor_role IN ('admin','staff') AND actor_org=p_organization_id,false)
 AND NOT (EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org)
  AND NOT EXISTS(SELECT 1 FROM public.staff WHERE user_id=actor AND organization_id=actor_org AND (status IS NULL OR status NOT IN ('inactive','resigned')))) THEN RETURN; END IF;
 RAISE EXCEPTION 'アンケート設定を操作する権限がありません' USING ERRCODE='42501';
END $$;


ALTER FUNCTION "public"."require_survey_question_staff"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reservation_actor_is_org_operator"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- 対象組織を必須にする。退職・停止・解除は既存の所属判定を使う。
  SELECT auth.uid() IS NOT NULL
    AND p_organization_id IS NOT NULL
    AND public.get_user_organization_id() = p_organization_id
    AND (
      public.is_org_admin()
      OR EXISTS (
        SELECT 1 FROM public.staff
        WHERE user_id = auth.uid()
          AND organization_id = p_organization_id
          AND status = 'active'
      )
    );
$$;


ALTER FUNCTION "public"."reservation_actor_is_org_operator"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_ai_manager_gateway_write"("p_organization_id" "uuid", "p_operation_id" "text", "p_approval_id" "text", "p_idempotency_key" "text", "p_fingerprint" "text") RETURNS TABLE("request_id" "uuid", "reservation_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.ai_manager_gateway_requests%ROWTYPE;
  v_approval public.ai_manager_gateway_approvals%ROWTYPE;
  v_request_id UUID;
BEGIN
  SELECT * INTO v_existing
  FROM public.ai_manager_gateway_requests
  WHERE organization_id = p_organization_id
    AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.fingerprint = p_fingerprint THEN
      RETURN QUERY SELECT v_existing.id, 'DUPLICATE_WRITE_BLOCKED'::TEXT;
    ELSE
      RETURN QUERY SELECT v_existing.id, 'IDEMPOTENCY_KEY_CONFLICT'::TEXT;
    END IF;
    RETURN;
  END IF;

  SELECT * INTO v_approval
  FROM public.ai_manager_gateway_approvals
  WHERE organization_id = p_organization_id
    AND approval_id = p_approval_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, 'APPROVAL_NOT_FOUND'::TEXT;
    RETURN;
  END IF;
  IF v_approval.operation_id <> p_operation_id OR v_approval.fingerprint <> p_fingerprint THEN
    RETURN QUERY SELECT NULL::UUID, 'APPROVAL_MISMATCH'::TEXT;
    RETURN;
  END IF;
  IF v_approval.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT NULL::UUID, 'APPROVAL_REVOKED'::TEXT;
    RETURN;
  END IF;
  IF v_approval.expires_at <= NOW() THEN
    RETURN QUERY SELECT NULL::UUID, 'APPROVAL_EXPIRED'::TEXT;
    RETURN;
  END IF;
  IF v_approval.consumed_at IS NOT NULL THEN
    RETURN QUERY SELECT NULL::UUID, 'APPROVAL_ALREADY_CONSUMED'::TEXT;
    RETURN;
  END IF;

  INSERT INTO public.ai_manager_gateway_requests (
    organization_id, operation_id, approval_id, idempotency_key, fingerprint, request_status
  ) VALUES (
    p_organization_id, p_operation_id, p_approval_id, p_idempotency_key, p_fingerprint, 'accepted'
  ) RETURNING id INTO v_request_id;

  UPDATE public.ai_manager_gateway_approvals
  SET consumed_at = NOW()
  WHERE id = v_approval.id;

  RETURN QUERY SELECT v_request_id, 'RESERVED'::TEXT;
END;
$$;


ALTER FUNCTION "public"."reserve_ai_manager_gateway_write"("p_organization_id" "uuid", "p_operation_id" "text", "p_approval_id" "text", "p_idempotency_key" "text", "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_operating_setting"("p_organization_id" "uuid", "p_key" "text", "p_default" "jsonb" DEFAULT 'null'::"jsonb", "p_store_id" "uuid" DEFAULT NULL::"uuid", "p_scenario_id" "uuid" DEFAULT NULL::"uuid", "p_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store uuid := p_store_id;
  v_scenario uuid := p_scenario_id;
  v_event public.schedule_events%ROWTYPE;
  v_value jsonb := COALESCE(public.get_operating_setting_default(p_key), p_default);
  v_source text := 'default';
  v_scope text;
  v_legacy jsonb;
  v_override jsonb;
  v_candidate jsonb;
  v_keys constant text[] := ARRAY['cancellation_policy','cancellation_policy_items','cancellation_deadline_hours','cancellation_fees','cancellation_fee_basis','private_cancellation_policy','private_cancellation_policy_items','private_cancellation_deadline_hours','private_cancellation_fees','private_cancellation_fee_basis','organizer_cancel_reasons','organizer_cancel_refund_note','cancellation_judgment_rules','cancellation_notice_note','reservation_change_deadline_hours','reservation_change_note','private_reservation_change_deadline_hours','private_reservation_change_note','refund_method_note','payment_method_label','payment_method_description','company_name','company_phone','company_email','company_address','reminder_enabled','reminder_schedule','reservation_confirmation_template','cancellation_template','reminder_template','private_reminder_template','booking_change_template','private_request_template','private_confirm_template','private_rejection_template','waitlist_notify_template','waitlist_registration_template','performance_cancellation_template','performance_confirmation_template','event_cancellation_template','performance_extension_template','store_cancellation_template','private_rejection_reason','judgment_minutes_before','preparation_minutes','survey_enabled','survey_deadline_days','survey_url','coupon_usage_enabled','default_performance_duration'];
BEGIN
  IF p_key IS NULL OR NOT p_key = ANY(v_keys) THEN
    RAISE EXCEPTION 'unknown setting key' USING ERRCODE = '22023';
  END IF;
  IF p_event_id IS NOT NULL THEN
    SELECT * INTO v_event FROM public.schedule_events WHERE id = p_event_id AND organization_id = p_organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'event not found' USING ERRCODE = '42501'; END IF;
    v_store := v_event.store_id;
    v_scenario := v_event.organization_scenario_id;
    IF v_scenario IS NULL AND COALESCE(v_event.scenario_master_id,v_event.scenario_id) IS NOT NULL THEN
      SELECT id INTO v_scenario FROM public.organization_scenarios
        WHERE organization_id = p_organization_id AND scenario_master_id = COALESCE(v_event.scenario_master_id,v_event.scenario_id);
    END IF;
    IF (p_store_id IS NOT NULL AND p_store_id IS DISTINCT FROM v_store)
      OR (p_scenario_id IS NOT NULL AND p_scenario_id IS DISTINCT FROM v_scenario) THEN
      RAISE EXCEPTION 'event context mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF v_store IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.stores WHERE id = v_store AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'store not found' USING ERRCODE = '42501';
  END IF;
  IF v_scenario IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.organization_scenarios WHERE id = v_scenario AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'scenario not found' USING ERRCODE = '42501';
  END IF;
  FOREACH v_scope IN ARRAY ARRAY['organization','store','scenario','performance'] LOOP
    IF (v_scope = 'store' AND v_store IS NULL) OR (v_scope = 'scenario' AND v_scenario IS NULL)
      OR (v_scope = 'performance' AND p_event_id IS NULL) THEN CONTINUE; END IF;
    IF p_key IN ('company_name','company_phone','company_email','company_address','default_performance_duration')
      AND v_scope IN ('scenario','performance') THEN CONTINUE; END IF;
    v_legacy := NULL;
    IF v_scope = 'organization' THEN
      SELECT to_jsonb(e)->p_key INTO v_legacy FROM public.email_settings e
        WHERE e.organization_id = p_organization_id AND e.store_id IS NULL ORDER BY e.id LIMIT 1;
    ELSIF v_scope = 'store' THEN
      SELECT to_jsonb(r)->p_key INTO v_legacy FROM public.reservation_settings r
        WHERE r.organization_id = p_organization_id AND r.store_id = v_store;
      IF v_legacy IS NULL THEN
        SELECT to_jsonb(e)->p_key INTO v_legacy FROM public.email_settings e
          WHERE e.organization_id = p_organization_id AND e.store_id = v_store;
      END IF;
      IF p_key = 'default_performance_duration' THEN
        SELECT to_jsonb(p.default_duration) INTO v_legacy FROM public.performance_schedule_settings p
          WHERE p.store_id = v_store AND (p.organization_id = p_organization_id OR p.organization_id IS NULL);
      END IF;
    ELSIF v_scope = 'scenario' THEN
      IF p_key = 'preparation_minutes' THEN
        SELECT to_jsonb(60 + s.extra_preparation_time) INTO v_legacy FROM public.organization_scenarios s
          WHERE s.organization_id = p_organization_id AND s.id = v_scenario;
      ELSE
        SELECT to_jsonb(s)->p_key INTO v_legacy FROM public.organization_scenarios s
          WHERE s.organization_id = p_organization_id AND s.id = v_scenario;
      END IF;
    ELSIF v_scope = 'performance' THEN
      v_legacy := to_jsonb(v_event)->p_key;
    END IF;
    SELECT o.settings INTO v_override FROM public.operating_setting_overrides o
      WHERE o.organization_id = p_organization_id
      AND o.store_id IS NOT DISTINCT FROM (CASE WHEN v_scope = 'store' THEN v_store END)
      AND o.organization_scenario_id IS NOT DISTINCT FROM (CASE WHEN v_scope = 'scenario' THEN v_scenario END)
      AND o.schedule_event_id IS NOT DISTINCT FROM (CASE WHEN v_scope = 'performance' THEN p_event_id END);
    IF p_key IN ('company_name','company_phone','company_email','company_address','reminder_enabled','reminder_schedule','reservation_confirmation_template','cancellation_template','reminder_template','private_reminder_template','booking_change_template','private_request_template','private_confirm_template','private_rejection_template','waitlist_notify_template','waitlist_registration_template','performance_cancellation_template','performance_confirmation_template','event_cancellation_template','performance_extension_template','store_cancellation_template','private_rejection_reason')
      AND jsonb_typeof(v_legacy) = 'string' AND btrim(v_legacy #>> '{}') = '' THEN v_legacy := NULL; END IF;
    v_candidate := CASE WHEN v_override ? p_key THEN v_override->p_key ELSE v_legacy END;
    IF v_candidate IS NOT NULL AND v_candidate <> 'null'::jsonb THEN
      v_value := v_candidate;
      v_source := v_scope;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('value', v_value, 'source', v_source);
END;
$$;


ALTER FUNCTION "public"."resolve_operating_setting"("p_organization_id" "uuid", "p_key" "text", "p_default" "jsonb", "p_store_id" "uuid", "p_scenario_id" "uuid", "p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_preparation_minutes"("p_organization_id" "uuid", "p_store_id" "uuid", "p_scenario_lookup_id" "uuid", "p_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE scenario_id uuid;
BEGIN
 IF p_event_id IS NOT NULL THEN
   RETURN (public.resolve_operating_setting(p_organization_id,'preparation_minutes','60'::jsonb,NULL,NULL,p_event_id)->>'value')::integer;
 END IF;
 SELECT s.id INTO scenario_id FROM organization_scenarios s WHERE s.organization_id=p_organization_id
   AND (s.id=p_scenario_lookup_id OR s.scenario_master_id=p_scenario_lookup_id)
 ORDER BY (s.id=p_scenario_lookup_id) DESC LIMIT 1;
 RETURN (public.resolve_operating_setting(p_organization_id,'preparation_minutes','60'::jsonb,p_store_id,scenario_id,NULL)->>'value')::integer;
END $$;


ALTER FUNCTION "public"."resolve_preparation_minutes"("p_organization_id" "uuid", "p_store_id" "uuid", "p_scenario_lookup_id" "uuid", "p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_performance_recruitment"("p_token" "uuid", "p_withdraw" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT public.respond_to_performance_recruitment_v2(p_token,p_withdraw,NULL,NULL,NULL);
$$;


ALTER FUNCTION "public"."respond_to_performance_recruitment"("p_token" "uuid", "p_withdraw" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_performance_recruitment_v2"("p_token" "uuid", "p_withdraw" boolean DEFAULT false, "p_count" integer DEFAULT NULL::integer, "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_expected_count" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE n performance_recruitment_notices%ROWTYPE; d performance_recruitment_deadlines%ROWTYPE; e schedule_events%ROWTYPE; r reservations%ROWTYPE;
 w performance_recruitment_withdrawals%ROWTYPE; v_count integer; v_remaining integer; v_request uuid; v_sequence integer; v_result jsonb; v_paid boolean; v_unit integer;
BEGIN
 SELECT * INTO n FROM performance_recruitment_notices WHERE response_token=p_token AND kind='extension';
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','INVALID_LINK'); END IF;
 SELECT * INTO e FROM schedule_events WHERE id=n.schedule_event_id AND organization_id=n.organization_id FOR UPDATE;
 SELECT * INTO r FROM reservations WHERE id=n.reservation_id AND organization_id=n.organization_id AND schedule_event_id=n.schedule_event_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','INVALID_LINK'); END IF;
 SELECT * INTO n FROM performance_recruitment_notices WHERE id=n.id FOR UPDATE;
 SELECT * INTO d FROM performance_recruitment_deadlines WHERE schedule_event_id=e.id AND organization_id=e.organization_id;
 v_request:=COALESCE(p_request_id,n.id);
 IF p_withdraw THEN
  SELECT * INTO w FROM performance_recruitment_withdrawals WHERE request_id=v_request;
  IF FOUND THEN
   IF w.notice_id<>n.id OR (p_count IS NOT NULL AND w.withdrawn_count<>p_count) THEN RETURN jsonb_build_object('success',false,'error','REQUEST_CONFLICT'); END IF;
   RETURN w.result;
  END IF;
 END IF;
 IF n.withdrawn_at IS NOT NULL THEN RETURN jsonb_build_object('success',true,'status','withdrawn','participant_count',0,'cancellation_fee',0,'event',n.snapshot); END IF;
 v_paid:=COALESCE(r.payment_status,'pending') NOT IN ('pending','unpaid');
 IF p_withdraw THEN
  IF n.cycle<>d.cycle OR d.status IS DISTINCT FROM 'active' OR now()>=d.deadline OR e.is_cancelled OR r.status NOT IN ('pending','confirmed','gm_confirmed') THEN RETURN jsonb_build_object('success',false,'error','WITHDRAWAL_CLOSED'); END IF;
  IF v_paid THEN RETURN jsonb_build_object('success',false,'error','PAYMENT_REVIEW_REQUIRED'); END IF;
  IF p_expected_count IS NOT NULL AND p_expected_count<>r.participant_count THEN RETURN jsonb_build_object('success',false,'error','PARTICIPANT_COUNT_CHANGED'); END IF;
  v_count:=COALESCE(p_count,r.participant_count);
  IF v_count<1 OR v_count>r.participant_count THEN RETURN jsonb_build_object('success',false,'error','INVALID_COUNT'); END IF;
  v_remaining:=r.participant_count-v_count;
  IF v_remaining>0 AND (COALESCE(r.discount_amount,0)<>0 OR COALESCE(r.total_price,0)%r.participant_count<>0) THEN RETURN jsonb_build_object('success',false,'error','PAYMENT_REVIEW_REQUIRED'); END IF;
  v_unit:=COALESCE(r.total_price,0)/r.participant_count;
  IF v_remaining=0 THEN
   UPDATE reservations SET status='cancelled',cancelled_at=now(),cancellation_reason='追加募集の開催判断待ちによる無料辞退（キャンセル料0円）',updated_at=now() WHERE id=r.id AND organization_id=n.organization_id;
   UPDATE performance_recruitment_notices SET withdrawn_at=now() WHERE id=n.id AND organization_id=n.organization_id;
  ELSE
   UPDATE reservations SET participant_count=v_remaining,
    total_price=v_unit*v_remaining,final_price=v_unit*v_remaining,
    cancellation_reason=format('追加募集の開催判断待ちに%s名無料辞退、%s名の予約を維持',v_count,v_remaining),updated_at=now()
    WHERE id=r.id AND organization_id=n.organization_id;
  END IF;
  v_result:=jsonb_build_object('success',true,'status',CASE WHEN v_remaining=0 THEN 'withdrawn' ELSE d.status END,'participant_count',v_remaining,
    'withdrawn_count',v_count,'cancellation_fee',0,'event',n.snapshot,'can_withdraw',v_remaining>0);
  INSERT INTO performance_recruitment_withdrawals(request_id,organization_id,schedule_event_id,reservation_id,notice_id,withdrawn_count,remaining_count,result)
    VALUES(v_request,n.organization_id,e.id,r.id,n.id,v_count,v_remaining,v_result);
  SELECT count(*) INTO v_sequence FROM performance_recruitment_withdrawals WHERE notice_id=n.id AND organization_id=n.organization_id;
  INSERT INTO performance_recruitment_notices(schedule_event_id,organization_id,reservation_id,customer_email,snapshot,kind,cycle,withdrawal_sequence)
    VALUES(e.id,n.organization_id,r.id,n.customer_email,n.snapshot||jsonb_build_object('withdrawn_count',v_count,'remaining_count',v_remaining),'withdrawn',n.cycle,v_sequence);
  UPDATE schedule_events SET current_participants=(SELECT COALESCE(sum(participant_count),0) FROM reservations WHERE schedule_event_id=e.id AND organization_id=e.organization_id AND status IN ('pending','confirmed','gm_confirmed','checked_in')),updated_at=now() WHERE id=e.id AND organization_id=e.organization_id;
  RETURN v_result;
 END IF;
 RETURN jsonb_build_object('success',true,'status',d.status,'event',n.snapshot,'participant_count',r.participant_count,'payment_review_required',v_paid,
 'can_withdraw',n.cycle=d.cycle AND d.status='active' AND now()<d.deadline AND NOT e.is_cancelled AND r.status IN ('pending','confirmed','gm_confirmed'));
END;
$$;


ALTER FUNCTION "public"."respond_to_performance_recruitment_v2"("p_token" "uuid", "p_withdraw" boolean, "p_count" integer, "p_request_id" "uuid", "p_expected_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_coupon_usage"("p_organization" "uuid", "p_coupon" "uuid", "p_usage" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE cc public.customer_coupons; removed uuid;
BEGIN
 SELECT * INTO cc FROM public.customer_coupons WHERE id=p_coupon AND organization_id=p_organization;
 IF cc.id IS NULL THEN RAISE EXCEPTION 'クーポンが見つかりません' USING ERRCODE='P0028'; END IF;
 PERFORM 1 FROM public.customers WHERE id=cc.customer_id FOR UPDATE;
 PERFORM 1 FROM public.customer_coupons WHERE id=p_coupon FOR UPDATE;
 DELETE FROM public.coupon_usages WHERE id=p_usage AND customer_coupon_id=p_coupon RETURNING id INTO removed;
 IF removed IS NOT NULL THEN
  UPDATE public.customer_coupons SET uses_remaining=uses_remaining+1,
    status=CASE WHEN status='fully_used' THEN 'active' ELSE status END WHERE id=p_coupon;
 END IF;
 RETURN jsonb_build_object('success',true,'restored',removed IS NOT NULL);
END;
$$;


ALTER FUNCTION "public"."restore_coupon_usage"("p_organization" "uuid", "p_coupon" "uuid", "p_usage" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_private_approval_preparation"("p_delivery_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
DECLARE d public.private_booking_approval_deliveries%ROWTYPE; r public.reservations%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.private_booking_approval_deliveries WHERE id=p_delivery_id;
 IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.reservations WHERE id=d.reservation_id AND organization_id=d.organization_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR public.get_user_organization_id() IS DISTINCT FROM r.organization_id
  OR NOT coalesce(public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
   AND organization_id=r.organization_id AND status='active'),false) THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT d FROM public.private_booking_approval_deliveries WHERE id=p_delivery_id FOR UPDATE NOWAIT;
 IF d.status<>'uncertain' OR d.kind<>'confirmation_email' OR d.first_attempt_at IS NOT NULL
  OR d.provider_message_id IS NOT NULL OR d.provider_payload IS NOT NULL OR d.preparation_attempted_at IS NULL
  OR NOT public.is_private_approval_delivery_current(d.id) THEN
  RAISE EXCEPTION 'PREPARATION_NOT_RESUMABLE' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.private_booking_discord_rooms room
  WHERE room.organization_id=d.organization_id AND room.reservation_id=d.reservation_id AND room.schedule_event_id=d.schedule_event_id
   AND nullif(btrim(room.player_invite_url),'') IS NOT NULL AND nullif(btrim(room.spectator_invite_url),'') IS NOT NULL) THEN
  RAISE EXCEPTION 'PREPARATION_RECORD_NOT_CONFIRMED' USING ERRCODE='55000';
 END IF;
 UPDATE public.private_booking_approval_deliveries SET status='pending',attempt_count=0,next_attempt_at=now(),
  last_error=NULL,lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=d.id;
 INSERT INTO public.private_delivery_resolutions(organization_id,delivery_kind,delivery_id,actor_id,action,previous_status)
 VALUES(d.organization_id,'approval',d.id,auth.uid(),'preparation_verified','uncertain');
 RETURN true;
END $$;


ALTER FUNCTION "public"."resume_private_approval_preparation"("p_delivery_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_private_rejection_delivery"("p_reservation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE v_res public.reservations%ROWTYPE;v_delivery public.private_booking_rejection_deliveries%ROWTYPE;v_email text;v_name text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_res FROM public.reservations WHERE id=p_reservation_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE='P0005'; END IF;
  IF NOT COALESCE((public.is_org_admin() AND public.get_user_organization_id()=v_res.organization_id)
    OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid() AND organization_id=v_res.organization_id AND status='active'),false)
    THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_delivery FROM public.private_booking_rejection_deliveries
    WHERE reservation_id=v_res.id AND organization_id=v_res.organization_id AND cancelled_at=v_res.cancelled_at FOR UPDATE NOWAIT;
  IF NOT FOUND OR v_res.status IS DISTINCT FROM 'cancelled' OR v_delivery.status IS DISTINCT FROM 'failed' OR v_delivery.first_attempt_at IS NOT NULL
    THEN RAISE EXCEPTION 'DELIVERY_NOT_SAFE_TO_RETRY' USING ERRCODE='22023'; END IF;
  SELECT email,name INTO v_email,v_name FROM public.customers WHERE id=v_res.customer_id
    AND (organization_id=v_res.organization_id OR organization_id IS NULL);
  -- 送信要求を一度も出していない記録だけ、明示操作で現在の連絡先を再取得する。
  UPDATE public.email_logs SET status='failed',error_message='superseded_before_send'
    WHERE id=coalesce(v_delivery.email_log_id,v_delivery.id) AND organization_id=v_delivery.organization_id
      AND reservation_id=v_delivery.reservation_id AND status='queued'
      AND email_type='reservation_cancelled' AND body_text=v_delivery.message_body
      AND to_email IS NOT DISTINCT FROM v_delivery.customer_email;
  UPDATE public.private_booking_rejection_deliveries SET status='pending',attempt_count=0,next_attempt_at=now(),
    email_log_id=gen_random_uuid(),provider_payload=NULL,provider_account_hash=NULL,lease_token=NULL,lease_until=NULL,last_error=NULL,
    customer_email=nullif(btrim(coalesce(nullif(v_res.customer_email,''),v_email)),''),
    customer_name=coalesce(nullif(v_res.customer_name,''),nullif(v_name,''),'お客様'),updated_at=now()
    WHERE id=v_delivery.id;
  RETURN true;
END; $$;


ALTER FUNCTION "public"."retry_private_rejection_delivery"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_private_unsent_delivery"("p_kind" "text", "p_delivery_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "row_security" TO 'off'
    AS $_$
DECLARE table_name text; d jsonb; r public.reservations%ROWTYPE; s public.staff%ROWTYPE;
 recipient text; recipient_name text; new_snapshot jsonb; old_log_id uuid; new_log_id uuid:=gen_random_uuid();
BEGIN
 table_name:=CASE p_kind WHEN 'approval' THEN 'private_booking_approval_deliveries' WHEN 'survey' THEN 'private_group_survey_deliveries'
  WHEN 'rejection' THEN 'private_booking_rejection_deliveries' END;
 IF table_name IS NULL OR auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
 EXECUTE format('SELECT to_jsonb(d) FROM public.%I d WHERE id=$1',table_name) INTO d USING p_delivery_id;
 IF d IS NULL THEN RAISE EXCEPTION 'DELIVERY_NOT_FOUND' USING ERRCODE='22023'; END IF;
 SELECT * INTO r FROM public.reservations WHERE id=(d->>'reservation_id')::uuid AND organization_id=(d->>'organization_id')::uuid FOR UPDATE NOWAIT;
 IF NOT FOUND OR public.get_user_organization_id() IS DISTINCT FROM r.organization_id
  OR NOT coalesce(public.is_org_admin() OR EXISTS(SELECT 1 FROM public.staff WHERE user_id=auth.uid()
   AND organization_id=r.organization_id AND status='active'),false) THEN RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE='42501'; END IF;
 EXECUTE format('SELECT to_jsonb(d) FROM public.%I d WHERE id=$1 FOR UPDATE NOWAIT',table_name) INTO d USING p_delivery_id;
 IF d->>'status'<>'failed' OR d->>'first_attempt_at' IS NOT NULL OR d->>'provider_message_id' IS NOT NULL THEN
  RAISE EXCEPTION 'DELIVERY_NOT_PROVEN_UNSENT' USING ERRCODE='55000';
 END IF;
 IF p_kind='approval' AND NOT public.is_private_approval_delivery_current(p_delivery_id) THEN
  RAISE EXCEPTION 'APPROVAL_CHANGED' USING ERRCODE='55000';
 ELSIF p_kind='survey' AND (r.status IS NULL OR r.status NOT IN ('confirmed','gm_confirmed','checked_in','completed')
  OR r.schedule_event_id IS DISTINCT FROM (d->>'schedule_event_id')::uuid
  OR NOT EXISTS(SELECT 1 FROM public.private_groups g WHERE g.id=(d->>'group_id')::uuid AND g.reservation_id=r.id AND g.organization_id=r.organization_id AND g.status='confirmed')) THEN
  RAISE EXCEPTION 'SURVEY_RESERVATION_CHANGED' USING ERRCODE='55000';
 ELSIF p_kind='rejection' AND (r.status IS DISTINCT FROM 'cancelled' OR r.cancelled_at IS DISTINCT FROM (d->>'cancelled_at')::timestamptz
  OR r.cancellation_reason IS DISTINCT FROM '貸切リクエストを却下しました'
  OR (r.private_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.private_groups g WHERE g.id=r.private_group_id AND g.organization_id=r.organization_id AND g.reservation_id=r.id AND g.status='date_adjusting'))) THEN
  RAISE EXCEPTION 'REJECTION_CHANGED' USING ERRCODE='55000';
 END IF;
 recipient:=nullif(btrim(r.customer_email),'');recipient_name:=coalesce(nullif(r.customer_name,''),'お客様');
 IF recipient IS NULL AND r.customer_id IS NOT NULL THEN
  SELECT nullif(btrim(c.email),''),coalesce(nullif(c.name,''),recipient_name) INTO recipient,recipient_name
   FROM public.customers c WHERE c.id=r.customer_id AND (c.organization_id=r.organization_id OR c.organization_id IS NULL);
 END IF;
 IF p_kind='approval' THEN
  new_snapshot:=d->'snapshot';
  IF d->>'kind'='confirmation_email' THEN
   new_snapshot:=new_snapshot||jsonb_build_object('customerEmail',recipient,'customerName',coalesce(recipient_name,'お客様'));
  ELSE
   SELECT * INTO STRICT s FROM public.staff WHERE id=(d->>'recipient_key')::uuid AND organization_id=r.organization_id AND status='active';
   new_snapshot:=new_snapshot||jsonb_build_object('gmEmail',nullif(btrim(s.email),''),'gmDiscordChannelId',nullif(btrim(s.discord_channel_id),''),'gmDiscordUserId',nullif(btrim(s.discord_user_id),''));
  END IF;
  UPDATE public.private_booking_approval_deliveries SET snapshot=new_snapshot WHERE id=p_delivery_id;
 ELSE
  EXECUTE format('UPDATE public.%I SET customer_email=$2,customer_name=$3 WHERE id=$1',table_name) USING p_delivery_id,recipient,coalesce(recipient_name,'お客様');
 END IF;
 old_log_id:=coalesce((d->>'email_log_id')::uuid,p_delivery_id);
 UPDATE public.email_logs SET status='failed',error_message='送信開始前の失敗。設定を更新して再試行を登録済み'
  WHERE id=old_log_id AND organization_id=r.organization_id AND status='queued' AND provider_message_id IS NULL;
 EXECUTE format('UPDATE public.%I SET status=''pending'',attempt_count=0,next_attempt_at=now(),provider_payload=NULL,provider_account_hash=NULL,
  email_log_id=$2,last_error=NULL,lease_token=NULL,lease_until=NULL,updated_at=now() WHERE id=$1',table_name) USING p_delivery_id,new_log_id;
 IF p_kind='approval' THEN UPDATE public.private_booking_approval_deliveries SET provider_target=NULL WHERE id=p_delivery_id; END IF;
 INSERT INTO public.private_delivery_resolutions(organization_id,delivery_kind,delivery_id,actor_id,action,previous_status)
 VALUES(r.organization_id,p_kind,p_delivery_id,auth.uid(),'retry_unsent','failed');
 RETURN true;
END $_$;


ALTER FUNCTION "public"."retry_private_unsent_delivery"("p_kind" "text", "p_delivery_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_orphan_organization"("p_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT public.rollback_orphan_organization_v2(p_org_id,NULL);
$$;


ALTER FUNCTION "public"."rollback_orphan_organization"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_orphan_organization_v2"("p_org_id" "uuid", "p_claim_token" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_created_at  TIMESTAMPTZ;
  v_user_count  INTEGER;
  v_staff_count INTEGER;
  v_claim public.organization_signup_claims%ROWTYPE;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'invalid_arg: p_org_id is required';
  END IF;

  -- 対象組織の存在確認 + 作成時刻取得
  SELECT created_at INTO v_created_at
  FROM public.organizations
  WHERE id = p_org_id FOR UPDATE;

  IF v_created_at IS NULL THEN
    -- 既に削除済み or 存在しない → idempotent に成功扱い
    RETURN TRUE;
  END IF;

  SELECT * INTO v_claim FROM public.organization_signup_claims WHERE organization_id=p_org_id FOR UPDATE;
  IF NOT FOUND OR v_claim.consumed_at IS NOT NULL OR NOT (
      coalesce(v_claim.token_hash=extensions.digest(p_claim_token,'sha256'),false)
      OR coalesce(auth.uid() IS NOT NULL AND v_claim.created_by=auth.uid(),false)) THEN
    RAISE EXCEPTION 'この組織の登録を取り消す権限がありません' USING ERRCODE='42501';
  END IF;

  -- 安全条件 1: 作成から 10 分以内
  IF v_created_at < NOW() - INTERVAL '10 minutes' THEN
    RAISE EXCEPTION 'org_too_old: 作成から 10 分以上経過した組織は rollback できません';
  END IF;

  -- 安全条件 2: ユーザーが紐づいてない
  SELECT COUNT(*) INTO v_user_count
  FROM public.users
  WHERE organization_id = p_org_id;

  IF v_user_count > 0 THEN
    RAISE EXCEPTION 'org_has_users: ユーザーが紐づいている組織は rollback できません';
  END IF;

  -- 安全条件 3: スタッフが紐づいてない (二重保険)
  SELECT COUNT(*) INTO v_staff_count
  FROM public.staff
  WHERE organization_id = p_org_id;

  IF v_staff_count > 0 THEN
    RAISE EXCEPTION 'org_has_staff: スタッフが紐づいている組織は rollback できません';
  END IF;

  -- 削除実行 (initialize_organization_data() が作る stores / settings を順に除去)
  DELETE FROM public.stores                WHERE organization_id = p_org_id;
  DELETE FROM public.organization_settings WHERE organization_id = p_org_id;
  DELETE FROM public.global_settings       WHERE organization_id = p_org_id;
  DELETE FROM public.organizations         WHERE id = p_org_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."rollback_orphan_organization_v2"("p_org_id" "uuid", "p_claim_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_inventory_consistency_check"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start_time TIMESTAMPTZ;
  v_end_time TIMESTAMPTZ;
  v_result RECORD;
  v_execution_time_ms INTEGER;
  v_response JSONB;
  v_is_service_role BOOLEAN := (COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role');
  v_is_admin BOOLEAN := is_org_admin();
  v_can_cross_tenant BOOLEAN := FALSE;
BEGIN
  v_can_cross_tenant := v_is_service_role OR v_is_admin;

  -- 🔒 認可: admin/service_role 以外は organization_id 必須 + メンバーのみ
  IF NOT v_can_cross_tenant THEN
    IF p_organization_id IS NULL THEN
      RAISE EXCEPTION 'organization_id_required' USING ERRCODE = 'P0001';
    END IF;
    IF NOT is_organization_member(p_organization_id) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  v_start_time := clock_timestamp();

  SELECT * INTO v_result
  FROM public.check_and_fix_inventory_consistency(p_organization_id);

  v_end_time := clock_timestamp();
  v_execution_time_ms := EXTRACT(MILLISECONDS FROM (v_end_time - v_start_time))::INTEGER;

  INSERT INTO inventory_consistency_logs (
    total_checked,
    inconsistencies_found,
    auto_fixed,
    details,
    execution_time_ms
  ) VALUES (
    v_result.total_checked,
    v_result.inconsistencies_found,
    v_result.auto_fixed,
    v_result.details,
    v_execution_time_ms
  );

  v_response := jsonb_build_object(
    'success', true,
    'total_checked', v_result.total_checked,
    'inconsistencies_found', v_result.inconsistencies_found,
    'auto_fixed', v_result.auto_fixed,
    'execution_time_ms', v_execution_time_ms,
    'details', v_result.details
  );

  RETURN v_response;
END;
$$;


ALTER FUNCTION "public"."run_inventory_consistency_check"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_inventory_consistency_check"("p_organization_id" "uuid") IS '在庫整合性チェックを実行し、結果をログに記録する。
一般呼び出しは p_organization_id 必須（自組織のみ）。
admin/service_role は p_organization_id NULL で全組織対象。';



CREATE OR REPLACE FUNCTION "public"."save_gm_response_atomic"("p_org" "uuid", "p_reservation" "uuid", "p_staff" "uuid", "p_candidates" "jsonb", "p_expected_response" "jsonb", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE booking public.reservations; previous public.gm_availability_responses; saved public.gm_availability_responses; gm public.staff; indices jsonb; response_state text;
BEGIN
 SELECT * INTO booking FROM reservations WHERE id=p_reservation AND organization_id=p_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Reservation unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO gm FROM staff WHERE id=p_staff AND organization_id=p_org AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_candidates) IS DISTINCT FROM 'array' OR coalesce(booking.candidate_datetimes->'candidates','[]') IS DISTINCT FROM p_candidates THEN
   RAISE EXCEPTION 'Candidates changed' USING ERRCODE='40001';
 END IF;
 SELECT * INTO previous FROM gm_availability_responses WHERE reservation_id=p_reservation AND staff_id=p_staff FOR UPDATE;
 IF (previous.id IS NULL AND p_expected_response IS NOT NULL AND p_expected_response <> 'null') OR
    (previous.id IS NOT NULL AND (p_expected_response IS NULL OR p_expected_response='null' OR
      previous.id::text IS DISTINCT FROM p_expected_response->>'id' OR
      previous.updated_at IS DISTINCT FROM (p_expected_response->>'updated_at')::timestamptz)) THEN
   RAISE EXCEPTION 'Response changed' USING ERRCODE='40001';
 END IF;
 IF previous.id IS NOT NULL AND previous.organization_id IS DISTINCT FROM p_org THEN
   RAISE EXCEPTION 'Response organization mismatch' USING ERRCODE='42501';
 END IF;
 indices:=p_patch->'available_candidates'; response_state:=p_patch->>'response_status';
 IF jsonb_typeof(indices) IS DISTINCT FROM 'array' OR response_state IS NULL OR response_state NOT IN ('pending','available','all_unavailable') THEN
   RAISE EXCEPTION 'Invalid response' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(indices) i WHERE jsonb_typeof(i)<>'number' OR i::text !~ '^[0-9]+$') THEN
   RAISE EXCEPTION 'Invalid candidate index' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(indices) i WHERE (i::text)::numeric >= jsonb_array_length(p_candidates)) OR
    (SELECT count(*) FROM jsonb_array_elements(indices)) <> (SELECT count(DISTINCT i) FROM jsonb_array_elements(indices) i) OR
    ((response_state='available') <> (jsonb_array_length(indices)>0)) THEN
   RAISE EXCEPTION 'Invalid candidate selection' USING ERRCODE='22023';
 END IF;
 INSERT INTO gm_availability_responses(organization_id,reservation_id,staff_id,gm_name,gm_discord_id,response_status,
   available_candidates,selected_candidate_index,response_type,notes,response_history,responded_at,response_datetime,updated_at)
 VALUES(p_org,p_reservation,p_staff,gm.name,gm.discord_user_id,response_state,indices,
   CASE WHEN jsonb_array_length(indices)>0 THEN (indices->>0)::integer ELSE NULL END,
   CASE WHEN response_state='available' THEN 'available' WHEN response_state='pending' THEN NULL ELSE 'unavailable' END,
   p_patch->>'notes',coalesce(p_patch->'response_history',previous.response_history,'[]'),clock_timestamp(),clock_timestamp(),clock_timestamp())
 ON CONFLICT(reservation_id,staff_id) DO UPDATE SET
   gm_name=excluded.gm_name,gm_discord_id=excluded.gm_discord_id,response_status=excluded.response_status,
   available_candidates=excluded.available_candidates,selected_candidate_index=excluded.selected_candidate_index,
   response_type=excluded.response_type,notes=excluded.notes,response_history=excluded.response_history,
   responded_at=excluded.responded_at,response_datetime=excluded.response_datetime,updated_at=excluded.updated_at
 RETURNING * INTO saved;
 RETURN to_jsonb(saved);
END $_$;


ALTER FUNCTION "public"."save_gm_response_atomic"("p_org" "uuid", "p_reservation" "uuid", "p_staff" "uuid", "p_candidates" "jsonb", "p_expected_response" "jsonb", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_guest_access_pin"("p_member_id" "uuid", "p_pin" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE v_member record; v_pii record;
BEGIN
 IF p_pin IS NULL OR p_pin !~ '^[0-9]{4}$' THEN RAISE EXCEPTION 'PIN must contain four digits' USING ERRCODE='22023'; END IF;
 SELECT id,user_id,status INTO v_member FROM public.private_group_members WHERE id=p_member_id FOR UPDATE;
 IF NOT FOUND OR v_member.user_id IS NOT NULL OR v_member.status<>'joined' THEN
   RAISE EXCEPTION 'Guest member not found' USING ERRCODE='42501';
 END IF;
 SELECT access_pin_hash,access_pin INTO v_pii FROM public.private_group_members_pii WHERE member_id=p_member_id FOR UPDATE;
 IF FOUND AND (v_pii.access_pin_hash IS NOT NULL OR v_pii.access_pin IS NOT NULL) THEN
   RAISE EXCEPTION 'PIN is already configured. Authenticate before changing it.' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.private_group_members_pii(member_id,access_pin_hash,access_pin,failed_attempts,locked_until,updated_at)
 VALUES(p_member_id,extensions.crypt(p_pin,extensions.gen_salt('bf')),NULL,0,NULL,clock_timestamp())
 ON CONFLICT(member_id) DO UPDATE SET access_pin_hash=EXCLUDED.access_pin_hash,access_pin=NULL,
   failed_attempts=0,locked_until=NULL,updated_at=EXCLUDED.updated_at;
 RETURN true;
END;
$_$;


ALTER FUNCTION "public"."save_guest_access_pin"("p_member_id" "uuid", "p_pin" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_guest_access_pin"("p_member_id" "uuid", "p_pin" "text") IS 'ゲストメンバーのアクセスPINをPIIテーブルに保存する';



CREATE OR REPLACE FUNCTION "public"."save_operating_setting_overrides"("p_organization_id" "uuid", "p_scope" "text", "p_target_id" "uuid", "p_values" "jsonb", "p_expected_revision" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store uuid;
  v_scenario uuid;
  v_event uuid;
  v_revision bigint;
BEGIN
  IF p_values IS NULL OR jsonb_typeof(p_values) <> 'object'
    OR p_expected_revision IS NULL OR p_expected_revision < 0 THEN
    RAISE EXCEPTION 'invalid setting update' USING ERRCODE = '22023';
  END IF;
  IF p_scope = 'organization' THEN
    IF p_target_id IS DISTINCT FROM p_organization_id
      OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
      RAISE EXCEPTION 'organization not found' USING ERRCODE = '42501';
    END IF;
  ELSIF p_scope = 'store' THEN
    SELECT id INTO v_store FROM public.stores
      WHERE id = p_target_id AND organization_id = p_organization_id;
    IF v_store IS NULL THEN RAISE EXCEPTION 'store not found' USING ERRCODE = '42501'; END IF;
  ELSIF p_scope = 'scenario' THEN
    SELECT id INTO v_scenario FROM public.organization_scenarios
      WHERE id = p_target_id AND organization_id = p_organization_id;
    IF v_scenario IS NULL THEN RAISE EXCEPTION 'scenario not found' USING ERRCODE = '42501'; END IF;
  ELSIF p_scope = 'performance' THEN
    SELECT id INTO v_event FROM public.schedule_events
      WHERE id = p_target_id AND organization_id = p_organization_id;
    IF v_event IS NULL THEN RAISE EXCEPTION 'performance not found' USING ERRCODE = '42501'; END IF;
  ELSE
    RAISE EXCEPTION 'invalid setting scope' USING ERRCODE = '22023';
  END IF;

  IF p_expected_revision = 0 THEN
    INSERT INTO public.operating_setting_overrides
      (organization_id, store_id, organization_scenario_id, schedule_event_id, settings)
    VALUES (p_organization_id, v_store, v_scenario, v_event, p_values)
    ON CONFLICT (organization_id, store_id, organization_scenario_id, schedule_event_id) DO NOTHING
    RETURNING revision INTO v_revision;
  ELSE
    UPDATE public.operating_setting_overrides s
    SET settings = s.settings || p_values, revision = s.revision + 1, updated_at = now()
    WHERE s.organization_id = p_organization_id
      AND s.store_id IS NOT DISTINCT FROM v_store
      AND s.organization_scenario_id IS NOT DISTINCT FROM v_scenario
      AND s.schedule_event_id IS NOT DISTINCT FROM v_event
      AND s.revision = p_expected_revision
    RETURNING s.revision INTO v_revision;
  END IF;
  IF v_revision IS NULL THEN
    RAISE EXCEPTION 'settings changed; reload before saving' USING ERRCODE = '40001';
  END IF;
  RETURN v_revision;
END;
$$;


ALTER FUNCTION "public"."save_operating_setting_overrides"("p_organization_id" "uuid", "p_scope" "text", "p_target_id" "uuid", "p_values" "jsonb", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_organization_recruitment_settings"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_value" integer, "p_expected_updated_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE s organization_recruitment_settings%ROWTYPE; before_value jsonb; after_value jsonb;
BEGIN
 IF p_actor_id IS NULL OR recruitment_missing_limit(7,p_mode,p_value) IS NULL THEN RETURN jsonb_build_object('success',false,'error','INVALID_SETTINGS'); END IF;
 -- 初回作成も直列化し、空の設定に対する同時保存を防ぐ。
 PERFORM 1 FROM organizations WHERE id=p_organization_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','NOT_FOUND'); END IF;
 SELECT * INTO s FROM organization_recruitment_settings WHERE organization_id=p_organization_id FOR UPDATE;
 IF s.updated_at IS DISTINCT FROM p_expected_updated_at THEN RETURN jsonb_build_object('success',false,'error','CONFLICT'); END IF;
 before_value:=jsonb_build_object('mode',COALESCE(s.mode,'count'),'value',COALESCE(s.value,2));
 after_value:=jsonb_build_object('mode',p_mode,'value',p_value);
 IF before_value=after_value AND s.organization_id IS NOT NULL THEN RETURN jsonb_build_object('success',true,'unchanged',true); END IF;
 INSERT INTO organization_recruitment_settings(organization_id,mode,value) VALUES(p_organization_id,p_mode,p_value)
 ON CONFLICT(organization_id) DO UPDATE SET mode=excluded.mode,value=excluded.value,updated_at=clock_timestamp();
 INSERT INTO organization_recruitment_setting_history(organization_id,actor_id,before_settings,after_settings) VALUES(p_organization_id,p_actor_id,before_value,after_value);
 RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."save_organization_recruitment_settings"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_value" integer, "p_expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_organization_recruitment_settings_v2"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_value" integer, "p_expected_updated_at" timestamp with time zone, "p_enabled" boolean, "p_deadline_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE s organization_recruitment_settings%ROWTYPE; before_value jsonb; after_value jsonb;
BEGIN
 IF p_enabled IS NULL OR p_deadline_minutes IS NULL OR p_deadline_minutes NOT BETWEEN 1 AND 239 OR p_actor_id IS NULL OR recruitment_missing_limit(7,p_mode,p_value) IS NULL THEN RETURN jsonb_build_object('success',false,'error','INVALID_SETTINGS'); END IF;
 -- 初回作成も直列化し、空の設定に対する同時保存を防ぐ。
 PERFORM 1 FROM organizations WHERE id=p_organization_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','NOT_FOUND'); END IF;
 SELECT * INTO s FROM organization_recruitment_settings WHERE organization_id=p_organization_id FOR UPDATE;
 IF s.updated_at IS DISTINCT FROM p_expected_updated_at THEN RETURN jsonb_build_object('success',false,'error','CONFLICT'); END IF;
 before_value:=jsonb_build_object('mode',COALESCE(s.mode,'count'),'value',COALESCE(s.value,2),'enabled',COALESCE(s.enabled,true),'deadline_minutes',COALESCE(s.deadline_minutes,90));
 after_value:=jsonb_build_object('mode',p_mode,'value',p_value,'enabled',p_enabled,'deadline_minutes',p_deadline_minutes);
 IF before_value=after_value AND s.organization_id IS NOT NULL THEN RETURN jsonb_build_object('success',true,'unchanged',true); END IF;
 INSERT INTO organization_recruitment_settings(organization_id,mode,value,enabled,deadline_minutes) VALUES(p_organization_id,p_mode,p_value,p_enabled,p_deadline_minutes)
 ON CONFLICT(organization_id) DO UPDATE SET mode=excluded.mode,value=excluded.value,enabled=excluded.enabled,deadline_minutes=excluded.deadline_minutes,updated_at=clock_timestamp();
 INSERT INTO organization_recruitment_setting_history(organization_id,actor_id,before_settings,after_settings) VALUES(p_organization_id,p_actor_id,before_value,after_value);
 RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."save_organization_recruitment_settings_v2"("p_organization_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_value" integer, "p_expected_updated_at" timestamp with time zone, "p_enabled" boolean, "p_deadline_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_scenario_gm_changes_atomic"("p_org" "uuid", "p_scenario" "uuid", "p_changes" "jsonb", "p_expected" "jsonb", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE item jsonb; affected uuid[]; result jsonb; previous_ids uuid[];
BEGIN
  IF p_org IS NULL OR p_scenario IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_changes->'removed') IS DISTINCT FROM 'array' OR jsonb_typeof(p_changes->'upserts') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid GM changes' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM organization_scenarios WHERE organization_id=p_org AND scenario_master_id=p_scenario FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Scenario unavailable' USING ERRCODE='23503'; END IF;
  SELECT array_agg(id) INTO affected FROM (
    SELECT value::uuid id FROM jsonb_array_elements_text(p_changes->'removed')
    UNION SELECT (value->>'staff_id')::uuid FROM jsonb_array_elements(p_changes->'upserts')
  ) s;
  IF EXISTS(SELECT 1 FROM unnest(affected) requested(id) WHERE requested.id IS NULL OR NOT EXISTS(SELECT 1 FROM staff WHERE staff.id=requested.id AND organization_id=p_org)) THEN
    RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='23503';
  END IF;
  PERFORM 1 FROM staff WHERE organization_id=p_org AND id=ANY(affected) ORDER BY id FOR UPDATE;
  IF assignment_state(p_org,NULL,p_scenario) IS DISTINCT FROM normalize_assignment_state(p_expected) THEN
    RAISE EXCEPTION 'Assignments changed' USING ERRCODE='40001';
  END IF;
  SELECT coalesce(array_agg(staff_id),'{}') INTO previous_ids FROM staff_scenario_assignments WHERE organization_id=p_org AND scenario_master_id=p_scenario;
  UPDATE staff_scenario_assignments SET can_main_gm=false,can_sub_gm=false,is_experienced=true
    WHERE organization_id=p_org AND scenario_master_id=p_scenario AND staff_id IN (SELECT value::uuid FROM jsonb_array_elements_text(p_changes->'removed'));
  FOR item IN SELECT value FROM jsonb_array_elements(p_changes->'upserts') LOOP
    IF jsonb_typeof(item->'can_main_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(item->'can_sub_gm') IS DISTINCT FROM 'boolean' OR jsonb_typeof(item->'is_experienced') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Invalid GM flags' USING ERRCODE='22023';
    END IF;
    INSERT INTO staff_scenario_assignments AS a(organization_id,staff_id,scenario_master_id,can_main_gm,can_sub_gm,is_experienced,notes)
      VALUES(p_org,(item->>'staff_id')::uuid,p_scenario,(item->>'can_main_gm')::boolean,(item->>'can_sub_gm')::boolean,(item->>'is_experienced')::boolean,item->>'notes')
      ON CONFLICT(staff_id,scenario_master_id) DO UPDATE SET can_main_gm=excluded.can_main_gm,can_sub_gm=excluded.can_sub_gm,is_experienced=excluded.is_experienced;
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') INTO result FROM staff_scenario_assignments a WHERE organization_id=p_org AND scenario_master_id=p_scenario;
  INSERT INTO staff_scenario_assignment_history(organization_id,staff_id,scenario_master_id,action,changed_by,source)
    SELECT p_org,a.staff_id,p_scenario,'added',p_actor,'api' FROM staff_scenario_assignments a
      WHERE a.organization_id=p_org AND a.scenario_master_id=p_scenario AND NOT(a.staff_id=ANY(previous_ids));
  RETURN result;
END $$;


ALTER FUNCTION "public"."save_scenario_gm_changes_atomic"("p_org" "uuid", "p_scenario" "uuid", "p_changes" "jsonb", "p_expected" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_scenario_recruitment_settings"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_max_missing" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT public.save_scenario_recruitment_settings_v2(p_organization_id,p_master_id,p_actor_id,p_enabled,'custom','count',p_max_missing,p_deadline_minutes,p_expected_updated_at);
$$;


ALTER FUNCTION "public"."save_scenario_recruitment_settings"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_max_missing" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_scenario_recruitment_settings_v2"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_source" "text", "p_mode" "text", "p_value" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 SELECT public.save_scenario_recruitment_settings_v3(p_organization_id,p_master_id,p_actor_id,p_enabled,p_source,p_mode,p_value,p_deadline_minutes,p_expected_updated_at,'custom','custom');
$$;


ALTER FUNCTION "public"."save_scenario_recruitment_settings_v2"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_source" "text", "p_mode" "text", "p_value" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_scenario_recruitment_settings_v3"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_source" "text", "p_mode" "text", "p_value" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone, "p_enabled_source" "text", "p_deadline_source" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE s organization_scenarios%ROWTYPE; before_value jsonb; after_value jsonb;
BEGIN
 SELECT * INTO s FROM organization_scenarios WHERE organization_id=p_organization_id AND scenario_master_id=p_master_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','NOT_FOUND'); END IF;
 IF p_enabled_source='common' THEN p_enabled:=s.recruitment_extension_enabled; END IF;
 IF p_deadline_source='common' THEN p_deadline_minutes:=s.recruitment_deadline_minutes; END IF;
 IF p_source='common' THEN p_mode:=s.recruitment_target_mode; p_value:=s.recruitment_target_value; END IF;
 IF p_enabled_source IS NULL OR p_enabled_source NOT IN ('common','custom') OR p_deadline_source IS NULL OR p_deadline_source NOT IN ('common','custom') OR p_enabled IS NULL OR p_source IS NULL OR p_source NOT IN ('common','custom') OR recruitment_missing_limit(7,p_mode,p_value) IS NULL OR p_deadline_minutes IS NULL OR p_deadline_minutes NOT BETWEEN 1 AND 239 OR p_actor_id IS NULL THEN
  RETURN jsonb_build_object('success',false,'error','INVALID_SETTINGS');
 END IF;
 IF s.updated_at IS DISTINCT FROM p_expected_updated_at THEN RETURN jsonb_build_object('success',false,'error','CONFLICT'); END IF;
 before_value:=jsonb_build_object('enabled',s.recruitment_extension_enabled,'source',s.recruitment_target_source,'mode',s.recruitment_target_mode,'value',s.recruitment_target_value,'deadline_minutes',s.recruitment_deadline_minutes,'enabled_source',s.recruitment_enabled_source,'deadline_source',s.recruitment_deadline_source);
 after_value:=jsonb_build_object('enabled',p_enabled,'source',p_source,'mode',p_mode,'value',p_value,'deadline_minutes',p_deadline_minutes,'enabled_source',p_enabled_source,'deadline_source',p_deadline_source);
 IF before_value=after_value THEN RETURN jsonb_build_object('success',true,'unchanged',true); END IF;
 UPDATE organization_scenarios SET recruitment_enabled_source=p_enabled_source,recruitment_deadline_source=p_deadline_source,recruitment_extension_enabled=p_enabled,recruitment_target_source=p_source,recruitment_target_mode=p_mode,recruitment_target_value=p_value,
 recruitment_max_missing=CASE WHEN p_mode='count' THEN p_value ELSE recruitment_max_missing END,
 recruitment_deadline_minutes=p_deadline_minutes,updated_at=clock_timestamp() WHERE id=s.id AND organization_id=p_organization_id;
 INSERT INTO scenario_recruitment_setting_history(organization_id,organization_scenario_id,actor_id,before_settings,after_settings) VALUES(p_organization_id,s.id,p_actor_id,before_value,after_value);
 RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION "public"."save_scenario_recruitment_settings_v3"("p_organization_id" "uuid", "p_master_id" "uuid", "p_actor_id" "uuid", "p_enabled" boolean, "p_source" "text", "p_mode" "text", "p_value" integer, "p_deadline_minutes" integer, "p_expected_updated_at" timestamp with time zone, "p_enabled_source" "text", "p_deadline_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_staff_editor_atomic"("p_org" "uuid", "p_staff" "uuid", "p_profile" "jsonb", "p_edit" "jsonb", "p_confirm" boolean DEFAULT false, "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE target uuid:=coalesce(p_staff,gen_random_uuid()); cols text; vals text; saved public.staff; previous_ids uuid[];
BEGIN
  IF p_org IS NULL OR jsonb_typeof(p_profile) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN (
    'name','line_name','x_account','discord_user_id','discord_channel_id','role','stores','ng_days','want_to_learn',
    'notes','phone','email','user_id','availability','experience','status','avatar_url','avatar_color')) THEN
    RAISE EXCEPTION 'Invalid staff fields' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM organization_scenarios WHERE organization_id=p_org ORDER BY scenario_master_id FOR KEY SHARE;
  SELECT string_agg(format('%I',k),',' ORDER BY k),string_agg(format('r.%I',k),',' ORDER BY k) INTO cols,vals FROM jsonb_object_keys(p_profile) k;
  IF cols IS NULL THEN RAISE EXCEPTION 'Empty staff fields' USING ERRCODE='22023'; END IF;
  IF p_staff IS NULL THEN
    EXECUTE format('INSERT INTO public.staff(id,organization_id,%s) SELECT $1,$2,%s FROM jsonb_populate_record(NULL::public.staff,$3) r RETURNING *',cols,vals)
      INTO saved USING target,p_org,p_profile;
  ELSE
    PERFORM 1 FROM staff WHERE id=target AND organization_id=p_org FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='23503'; END IF;
  END IF;
  SELECT coalesce(array_agg(scenario_master_id),'{}') INTO previous_ids FROM staff_scenario_assignments WHERE organization_id=p_org AND staff_id=target;
  PERFORM apply_staff_assignment_edit(p_org,target,p_edit,p_confirm);
  INSERT INTO staff_scenario_assignment_history(organization_id,staff_id,scenario_master_id,action,changed_by,source)
    SELECT p_org,target,a.scenario_master_id,'added',p_actor,'api' FROM staff_scenario_assignments a
      WHERE a.organization_id=p_org AND a.staff_id=target AND NOT(a.scenario_master_id=ANY(previous_ids))
    UNION ALL
    SELECT p_org,target,old.id,'removed',p_actor,'api' FROM unnest(previous_ids) old(id)
      WHERE NOT EXISTS(SELECT 1 FROM staff_scenario_assignments a WHERE a.organization_id=p_org AND a.staff_id=target AND a.scenario_master_id=old.id)
      AND EXISTS(SELECT 1 FROM scenario_masters m WHERE m.id=old.id);
  IF p_staff IS NOT NULL THEN
    EXECUTE format('UPDATE public.staff s SET (%s)=(SELECT %s FROM jsonb_populate_record(NULL::public.staff,$3) r) WHERE s.id=$1 AND s.organization_id=$2 RETURNING s.*',cols,vals)
      INTO saved USING target,p_org,p_profile;
  ELSE SELECT * INTO saved FROM staff WHERE id=target AND organization_id=p_org; END IF;
  RETURN to_jsonb(saved);
END $_$;


ALTER FUNCTION "public"."save_staff_editor_atomic"("p_org" "uuid", "p_staff" "uuid", "p_profile" "jsonb", "p_edit" "jsonb", "p_confirm" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_survey_question_settings"("p_org_scenario_id" "uuid", "p_questions" "jsonb", "p_revision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE snapshot jsonb; q jsonb; option_item jsonb; ids uuid[]; question_id uuid;
BEGIN
 -- Authorize before taking any lock. The same read also verifies the scenario.
 snapshot:=public.read_survey_question_settings(p_org_scenario_id);
 IF p_questions IS NULL OR jsonb_typeof(p_questions)<>'array' THEN
  RAISE EXCEPTION '設問一覧の形式が正しくありません' USING ERRCODE='22023';
 END IF;
 -- Old clients and the character-assignment RPC still write this table directly.
 -- Exclude their writes for this short configuration transaction too. Never wait
 -- behind a live booking operation: the caller can retry after a conflict.
 LOCK TABLE public.org_scenario_survey_questions IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 snapshot:=public.read_survey_question_settings(p_org_scenario_id);
 IF p_revision IS DISTINCT FROM snapshot->>'revision' THEN
  RAISE EXCEPTION '設問が別の操作で変更されました。画面を開き直して変更内容を確認してください' USING ERRCODE='40001';
 END IF;
 ids:=ARRAY[]::uuid[];
 FOR q IN SELECT value FROM jsonb_array_elements(p_questions) LOOP
  IF jsonb_typeof(q)<>'object' OR jsonb_typeof(q->'id') IS DISTINCT FROM 'string'
   OR jsonb_typeof(q->'question_text') IS DISTINCT FROM 'string' OR btrim(q->>'question_text')=''
   OR COALESCE(q->>'question_type','') NOT IN ('text','single_choice','multiple_choice','character_selection','rating')
   OR jsonb_typeof(q->'is_required') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(q->'options') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION '設問の本文・種類・選択肢を確認してください' USING ERRCODE='22023';
  END IF;
  BEGIN question_id:=(q->>'id')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION '設問IDの形式が正しくありません' USING ERRCODE='22023'; END;
  IF question_id=ANY(ids) THEN RAISE EXCEPTION '設問IDが重複しています' USING ERRCODE='22023'; END IF;
  ids:=array_append(ids,question_id);
  IF EXISTS(SELECT 1 FROM public.org_scenario_survey_questions WHERE id=question_id AND org_scenario_id<>p_org_scenario_id) THEN
   RAISE EXCEPTION '別のシナリオの設問は更新できません' USING ERRCODE='42501';
  END IF;
  FOR option_item IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
   IF jsonb_typeof(option_item)<>'object' OR jsonb_typeof(option_item->'value') IS DISTINCT FROM 'string'
    OR jsonb_typeof(option_item->'label') IS DISTINCT FROM 'string'
    OR btrim(option_item->>'value')='' OR btrim(option_item->>'label')='' THEN
    RAISE EXCEPTION '選択肢の値と表示名を入力してください' USING ERRCODE='22023';
   END IF;
  END LOOP;
  IF (SELECT count(*)<>count(DISTINCT value->>'value') FROM jsonb_array_elements(q->'options')) THEN
   RAISE EXCEPTION '選択肢の値が重複しています' USING ERRCODE='22023';
  END IF;
  IF q->>'question_type' IN ('single_choice','multiple_choice') AND jsonb_array_length(q->'options')=0 THEN
   RAISE EXCEPTION '選択式の設問には選択肢が必要です' USING ERRCODE='22023';
  END IF;
 END LOOP;
 DELETE FROM public.org_scenario_survey_questions WHERE org_scenario_id=p_org_scenario_id AND NOT(id=ANY(ids));
 INSERT INTO public.org_scenario_survey_questions(id,org_scenario_id,question_text,question_type,options,is_required,order_num)
 SELECT (value->>'id')::uuid,p_org_scenario_id,value->>'question_text',value->>'question_type',value->'options',(value->>'is_required')::boolean,ordinality::integer
 FROM jsonb_array_elements(p_questions) WITH ORDINALITY
 ON CONFLICT(id) DO UPDATE SET question_text=EXCLUDED.question_text,question_type=EXCLUDED.question_type,options=EXCLUDED.options,is_required=EXCLUDED.is_required,order_num=EXCLUDED.order_num;
 RETURN public.read_survey_question_settings(p_org_scenario_id);
END $$;


ALTER FUNCTION "public"."save_survey_question_settings"("p_org_scenario_id" "uuid", "p_questions" "jsonb", "p_revision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_org_customers"("p_org_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_sort_by" "text" DEFAULT 'created_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_min_reservations" integer DEFAULT NULL::integer, "p_min_visits" integer DEFAULT NULL::integer, "p_min_amount" bigint DEFAULT NULL::bigint, "p_has_coupons" boolean DEFAULT NULL::boolean, "p_visit_from" "date" DEFAULT NULL::"date", "p_visit_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH all_stats AS MATERIALIZED (
 SELECT * FROM public.get_org_customers_with_stats_v2(p_org_id,p_search,NULL,0)
), filtered AS MATERIALIZED (
 SELECT * FROM all_stats s
 WHERE (p_min_reservations IS NULL OR s.reservation_count >= p_min_reservations)
 AND (p_min_visits IS NULL OR s.visit_count >= p_min_visits)
 AND (p_min_amount IS NULL OR s.reservation_amount >= p_min_amount)
 AND (p_has_coupons IS NULL OR (s.remaining_coupons > 0) = p_has_coupons)
 AND (p_visit_from IS NULL OR s.last_visit >= (p_visit_from::timestamp AT TIME ZONE 'Asia/Tokyo'))
 AND (p_visit_to IS NULL OR s.last_visit < ((p_visit_to + 1)::timestamp AT TIME ZONE 'Asia/Tokyo'))
), ordered AS (
 SELECT f.*, row_number() OVER (ORDER BY
 CASE WHEN p_sort_by = 'created_at' AND p_sort_dir = 'asc' THEN f.created_at END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'created_at' AND p_sort_dir = 'desc' THEN f.created_at END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'name' AND p_sort_dir = 'asc' THEN f.name END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'name' AND p_sort_dir = 'desc' THEN f.name END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'email' AND p_sort_dir = 'asc' THEN f.email END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'email' AND p_sort_dir = 'desc' THEN f.email END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'phone' AND p_sort_dir = 'asc' THEN f.phone END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'phone' AND p_sort_dir = 'desc' THEN f.phone END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'reservation_count' AND p_sort_dir = 'asc' THEN f.reservation_count END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'reservation_count' AND p_sort_dir = 'desc' THEN f.reservation_count END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'remaining_coupons' AND p_sort_dir = 'asc' THEN f.remaining_coupons END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'remaining_coupons' AND p_sort_dir = 'desc' THEN f.remaining_coupons END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'visit_count' AND p_sort_dir = 'asc' THEN f.visit_count END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'visit_count' AND p_sort_dir = 'desc' THEN f.visit_count END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'reservation_amount' AND p_sort_dir = 'asc' THEN f.reservation_amount END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'reservation_amount' AND p_sort_dir = 'desc' THEN f.reservation_amount END DESC NULLS LAST,
 CASE WHEN p_sort_by = 'last_visit' AND p_sort_dir = 'asc' THEN f.last_visit END ASC NULLS LAST,
 CASE WHEN p_sort_by = 'last_visit' AND p_sort_dir = 'desc' THEN f.last_visit END DESC NULLS LAST, f.created_at DESC, f.id ASC) AS position
 FROM filtered f
), page AS (
 SELECT * FROM ordered ORDER BY position
 LIMIT LEAST(GREATEST(COALESCE(p_limit,50),1),100) OFFSET GREATEST(COALESCE(p_offset,0),0)
)
SELECT jsonb_build_object('customers',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'position'-'total_count' ORDER BY p.position) FROM page p),'[]'::jsonb),
 'totalCount',(SELECT count(*) FROM filtered))
$$;


ALTER FUNCTION "public"."search_org_customers"("p_org_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer, "p_sort_by" "text", "p_sort_dir" "text", "p_min_reservations" integer, "p_min_visits" integer, "p_min_amount" bigint, "p_has_coupons" boolean, "p_visit_from" "date", "p_visit_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_private_group_survey_notice"("p_group_id" "uuid", "p_request_id" "uuid", "p_expected_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
 g public.private_groups%ROWTYPE; r public.reservations%ROWTYPE; e record;
 receipt public.private_group_survey_deliveries%ROWTYPE;
 survey jsonb; body text; action text; deadline_text text:=''; author_member uuid; notice_id uuid;
 recipient text; recipient_name text; target_org_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ログインしてください' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_expected_reservation_id IS NULL THEN RAISE EXCEPTION '通知対象を確認してください' USING ERRCODE='22023'; END IF;
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id;
 IF NOT FOUND THEN RAISE EXCEPTION '通知する権限がありません' USING ERRCODE='42501'; END IF;
 target_org_id:=g.organization_id;
 IF NOT coalesce((public.is_org_admin() AND public.get_user_organization_id()=g.organization_id)
  OR EXISTS(SELECT 1 FROM public.staff s WHERE s.user_id=auth.uid() AND s.organization_id=g.organization_id AND s.status='active'),false) THEN
  RAISE EXCEPTION '通知する権限がありません' USING ERRCODE='42501';
 END IF;
 -- 承認と同じ予約→グループの順でロックする。参照変更は後から再照合。
 SELECT * INTO r FROM public.reservations WHERE id=p_expected_reservation_id AND reservations.organization_id=g.organization_id FOR UPDATE NOWAIT;
 SELECT * INTO g FROM public.private_groups WHERE id=p_group_id AND private_groups.organization_id=target_org_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION '通知対象が変更されています' USING ERRCODE='40001'; END IF;
 SELECT * INTO receipt FROM public.private_group_survey_deliveries WHERE id=p_request_id;
 IF FOUND THEN
  IF receipt.organization_id IS DISTINCT FROM g.organization_id OR receipt.group_id IS DISTINCT FROM g.id
   OR receipt.actor_id IS DISTINCT FROM auth.uid() OR receipt.reservation_id IS DISTINCT FROM p_expected_reservation_id OR receipt.source<>'manual' THEN
   RAISE EXCEPTION '同じ送信番号で別の通知は保存できません' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('success',true,'delivery_id',receipt.id,'status',receipt.status,'replayed',true);
 END IF;
 IF g.reservation_id IS DISTINCT FROM p_expected_reservation_id OR r.id IS NULL OR r.private_group_id IS DISTINCT FROM g.id
  OR g.status IS DISTINCT FROM 'confirmed' OR r.status NOT IN ('confirmed','gm_confirmed','checked_in','completed') OR r.status IS NULL THEN
  RAISE EXCEPTION '確定済みの現在の予約だけに通知できます。画面を更新してください' USING ERRCODE='22023';
 END IF;
 SELECT * INTO e FROM public.schedule_events WHERE id=r.schedule_event_id AND schedule_events.organization_id=g.organization_id FOR SHARE NOWAIT;
 IF NOT FOUND OR e.is_cancelled IS DISTINCT FROM false THEN RAISE EXCEPTION '公演が変更または中止されています' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.private_group_survey_deliveries d WHERE d.group_id=g.id AND d.organization_id=g.organization_id
  AND d.reservation_id=r.id AND d.schedule_event_id=e.id AND d.status IN ('pending','sending','uncertain')) THEN
  RAISE EXCEPTION '送信待ち、または送信結果の確認が必要な案内があります。通知履歴を確認してください' USING ERRCODE='55000';
 END IF;
 survey:=public.freeze_private_group_survey_deadline(g.organization_id,g.id);
 IF survey->>'error' IS NOT NULL OR NOT coalesce((survey->>'survey_enabled')::boolean,false) THEN
  RAISE EXCEPTION 'この公演ではアンケートを案内できません' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(survey->'characters','[]')) c WHERE NOT coalesce((c->>'is_npc')::boolean,false))
  AND nullif(survey->>'survey_url','') IS NULL THEN
  action:='pre_reading_notice';
  SELECT nullif(pre_reading_notice_message,'') INTO body FROM public.global_settings WHERE global_settings.organization_id=g.organization_id;
  body:=coalesce(body,E'【ご確認ください】\n\nこのシナリオには事前配役アンケートがございます。\n\n公演日までに参加者全員がこのグループに参加している必要があります。まだ参加されていない方がいらっしゃいましたら、招待リンクを共有してグループへの参加をお願いいたします。\n\nご不明点がございましたら、店舗までお問い合わせください。');
 ELSE
  action:='survey_notice';
  IF survey->>'survey_deadline_at' IS NOT NULL THEN deadline_text:=E'\n\n回答期限: '||to_char((survey->>'survey_deadline_at')::timestamptz AT TIME ZONE 'Asia/Tokyo','FMMM/FMDD')||'まで'; END IF;
  body:=E'【事前配役アンケートのご協力のお願い】\n\nこちらの公演では事前配役アンケートへのご回答をお願いしております。\n\n'||
   CASE WHEN nullif(survey->>'survey_url','') IS NOT NULL THEN E'次のURLからアンケートにお答えください。\n'||(survey->>'survey_url')
   ELSE '上記の「日程を確認・回答する」ボタンからアンケートにお答えください。' END||deadline_text||E'\n\nご不明点がございましたら、お気軽にお問い合わせください。';
 END IF;
 recipient:=nullif(btrim(r.customer_email),''); recipient_name:=coalesce(nullif(r.customer_name,''),'お客様');
 IF recipient IS NULL AND r.customer_id IS NOT NULL THEN
  SELECT nullif(btrim(c.email),''),coalesce(nullif(c.name,''),recipient_name) INTO recipient,recipient_name FROM public.customers c
   WHERE c.id=r.customer_id AND (c.organization_id=g.organization_id OR c.organization_id IS NULL);
 END IF;
 SELECT m.id INTO author_member FROM public.private_group_members m WHERE m.group_id=g.id AND m.user_id=auth.uid() AND m.status='joined' ORDER BY m.id LIMIT 1;
 INSERT INTO public.private_group_messages(group_id,member_id,message) VALUES(g.id,author_member,jsonb_build_object('type','system','action',action,'message',body)::text) RETURNING id INTO notice_id;
 INSERT INTO public.private_group_survey_deliveries(id,organization_id,group_id,reservation_id,schedule_event_id,actor_id,source,message_id,customer_email,customer_name,subject,message_body)
 VALUES(p_request_id,g.organization_id,g.id,r.id,e.id,auth.uid(),'manual',notice_id,recipient,coalesce(recipient_name,'お客様'),'【事前配役アンケートのご案内】',body);
 RETURN jsonb_build_object('success',true,'delivery_id',p_request_id,'status','pending','replayed',false);
END $$;


ALTER FUNCTION "public"."send_private_group_survey_notice"("p_group_id" "uuid", "p_request_id" "uuid", "p_expected_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_staff_group_message"("p_group_id" "uuid", "p_message" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_staff_org_id UUID;
  v_group_org_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'ログインが必要です';
  END IF;
  
  -- is_staff_or_admin() ヘルパーを使用
  IF NOT public.is_staff_or_admin() THEN
    RAISE EXCEPTION 'スタッフ権限がありません';
  END IF;
  
  -- スタッフの組織IDを取得
  SELECT organization_id INTO v_staff_org_id
  FROM public.staff
  WHERE user_id = v_user_id
  LIMIT 1;
  
  IF v_staff_org_id IS NULL THEN
    RAISE EXCEPTION 'スタッフ情報が見つかりません';
  END IF;
  
  -- グループの組織IDを取得
  SELECT organization_id INTO v_group_org_id
  FROM public.private_groups
  WHERE id = p_group_id;
  
  IF v_group_org_id IS NULL THEN
    RAISE EXCEPTION 'グループが見つかりません';
  END IF;
  
  IF v_staff_org_id != v_group_org_id THEN
    RAISE EXCEPTION '他組織のグループにはメッセージを送信できません';
  END IF;
  
  INSERT INTO public.private_group_messages (group_id, message)
  VALUES (
    p_group_id,
    jsonb_build_object(
      'type', 'system',
      'action', 'staff_message',
      'title', '店舗からのお知らせ',
      'body', p_message
    )::text
  );
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."send_staff_group_message"("p_group_id" "uuid", "p_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_staff_group_message"("p_group_id" "uuid", "p_message" "text") IS 'スタッフ/管理者がグループにシステムメッセージを送信';



CREATE OR REPLACE FUNCTION "public"."set_author_organization_name"("p_author_name" "text", "p_organization_name" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  -- authorsテーブルにupsert
  INSERT INTO authors (name, license_organization_name, notes, updated_at)
  VALUES (p_author_name, p_organization_name, p_notes, NOW())
  ON CONFLICT (name)
  DO UPDATE SET
    license_organization_name = p_organization_name,
    notes = COALESCE(p_notes, authors.notes),
    updated_at = NOW()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success', true,
    'id', v_id,
    'author_name', p_author_name,
    'organization_name', p_organization_name
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$$;


ALTER FUNCTION "public"."set_author_organization_name"("p_author_name" "text", "p_organization_name" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_author_organization_name"("p_author_name" "text", "p_organization_name" "text", "p_notes" "text") IS '作者のライセンス組織名（会社名）を設定する専用RPC（RLSをバイパス）';



CREATE OR REPLACE FUNCTION "public"."set_cancelled_at_on_cancel"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'cancelled'
    AND (OLD.status IS DISTINCT FROM 'cancelled')
    AND NEW.cancelled_at IS NULL
  THEN
    NEW.cancelled_at = NOW();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_cancelled_at_on_cancel"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_character_preference"("p_group_id" "uuid", "p_member_id" "text", "p_character_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE private_groups
  SET character_assignments = coalesce(character_assignments, '{}'::jsonb) || jsonb_build_object(p_member_id, p_character_id)
  WHERE id = p_group_id;
END;
$$;


ALTER FUNCTION "public"."set_character_preference"("p_group_id" "uuid", "p_member_id" "text", "p_character_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_coupon_calendar_expiry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_months integer;
BEGIN
  SELECT coupon_expiry_months INTO v_months
  FROM public.coupon_campaigns WHERE id = NEW.campaign_id;
  IF v_months IS NOT NULL THEN
    NEW.expires_at := ((statement_timestamp() AT TIME ZONE 'Asia/Tokyo')
      + make_interval(months => v_months)) AT TIME ZONE 'Asia/Tokyo';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_coupon_calendar_expiry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_performance_recruitment_deadline"("p_organization_id" "uuid", "p_event_id" "uuid", "p_deadline" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event public.schedule_events%ROWTYPE;
  v_existing public.performance_recruitment_deadlines%ROWTYPE;
  v_start timestamptz;
  v_confirmed boolean;
BEGIN
  SELECT * INTO v_event FROM public.schedule_events
  WHERE id = p_event_id AND organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '対象の公演が見つかりません' USING ERRCODE = '22023'; END IF;
  v_start := (v_event.date + v_event.start_time) AT TIME ZONE 'Asia/Tokyo';
  IF v_event.category <> 'open' OR v_event.is_cancelled IS DISTINCT FROM false THEN
    RAISE EXCEPTION '中止していないオープン公演のみ延長できます' USING ERRCODE = '22023';
  END IF;
  IF p_deadline IS NULL OR p_deadline <= now() OR p_deadline >= v_start OR p_deadline < v_start - make_interval(mins=>(public.resolve_operating_setting(p_organization_id,'judgment_minutes_before','240'::jsonb,NULL,NULL,p_event_id)->>'value')::integer) THEN
    RAISE EXCEPTION '締切は現在より後かつ設定された最終判断時刻以降、公演開始より前を指定してください' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION '延長理由を1〜2000文字で指定してください' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_existing FROM public.performance_recruitment_deadlines WHERE schedule_event_id = p_event_id;
  IF FOUND THEN
    -- 再送は同じ結果を返す。顧客に案内した期限の黙示的な変更はしない。
    IF v_existing.status = 'active' AND v_existing.deadline = p_deadline
      AND v_existing.reason = btrim(p_reason) THEN
      RETURN jsonb_build_object('success', true, 'deadline', v_existing.deadline,
        'was_confirmed', v_existing.was_confirmed, 'replayed', true);
    END IF;
    RAISE EXCEPTION '既存の延長判断があります。期限の変更には顧客案内の再確認が必要です' USING ERRCODE = '22023';
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.performance_cancellation_logs
    WHERE schedule_event_id = p_event_id AND organization_id = p_organization_id
      AND result = 'confirmed') INTO v_confirmed;
  INSERT INTO public.performance_recruitment_deadlines
    (schedule_event_id, organization_id, deadline, reason, was_confirmed)
    VALUES (p_event_id, p_organization_id, p_deadline, btrim(p_reason), v_confirmed);
  UPDATE public.schedule_events SET is_recruitment_extended = true, updated_at = now()
    WHERE id = p_event_id AND organization_id = p_organization_id;
  RETURN jsonb_build_object('success', true, 'deadline', p_deadline,
    'was_confirmed', v_confirmed, 'replayed', false);
END;
$$;


ALTER FUNCTION "public"."set_performance_recruitment_deadline"("p_organization_id" "uuid", "p_event_id" "uuid", "p_deadline" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_reservation_cancellation_policy_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings public.reservation_settings%ROWTYPE;
  v_performance_type TEXT;
  v_is_private BOOLEAN;
  v_validate_store BOOLEAN := false;
  v_scenario uuid;
  v_prefix text;
BEGIN
  -- 新規予約と店舗/組織の変更時は、設定取得より先にtenant整合を検証する。
  -- 既存の不整合行に対する無関係な更新は互換性のため阻害しない。
  IF TG_OP = 'INSERT' THEN
    v_validate_store := true;
  ELSIF NEW.store_id IS DISTINCT FROM OLD.store_id
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    v_validate_store := true;
  END IF;

  IF v_validate_store AND NEW.store_id IS NOT NULL THEN
    PERFORM 1
    FROM public.stores s
    WHERE s.id = NEW.store_id
      AND s.organization_id = NEW.organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION '予約店舗が予約organizationに所属していません'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- 一度保存したスナップショットは、店舗や管理設定が変わっても上書きしない。
    NEW.cancellation_policy_snapshot_version := OLD.cancellation_policy_snapshot_version;
    NEW.cancellation_policy_store_id := OLD.cancellation_policy_store_id;
    NEW.cancellation_policy_performance_type := OLD.cancellation_policy_performance_type;
    NEW.cancellation_policy_deadline_hours := OLD.cancellation_policy_deadline_hours;
    NEW.cancellation_policy_fees := OLD.cancellation_policy_fees;
    NEW.cancellation_policy_fee_basis := OLD.cancellation_policy_fee_basis;
    NEW.cancellation_policy_updated_at := OLD.cancellation_policy_updated_at;

    -- migration以前の予約はNULLのまま維持する。新規貸切申込だけ、初回店舗確定時に補完する。
    IF OLD.cancellation_policy_snapshot_version IS NULL
      OR OLD.cancellation_policy_store_id IS NOT NULL
      OR NEW.store_id IS NULL THEN
      RETURN NEW;
    END IF;

    v_performance_type := OLD.cancellation_policy_performance_type;
  ELSE
    -- 呼び出し元から渡された値を信用せず、DB内の設定から必ず作り直す。
    NEW.cancellation_policy_snapshot_version := 1;
    NEW.cancellation_policy_store_id := NULL;
    NEW.cancellation_policy_deadline_hours := NULL;
    NEW.cancellation_policy_fees := NULL;
    NEW.cancellation_policy_fee_basis := NULL;
    NEW.cancellation_policy_updated_at := NULL;

    SELECT EXISTS (
      SELECT 1
      FROM public.schedule_events se
      WHERE se.id = NEW.schedule_event_id
        AND se.organization_id = NEW.organization_id
        AND (se.category = 'private' OR se.is_private_booking = true)
    ) INTO v_is_private;

    v_performance_type := CASE
      WHEN NEW.private_group_id IS NOT NULL
        OR NEW.reservation_source = 'web_private'
        OR NEW.reservation_type IN ('private', 'private_booking')
        OR v_is_private
      THEN 'private'
      ELSE 'open'
    END;
    NEW.cancellation_policy_performance_type := v_performance_type;

    -- 貸切申込は店舗未確定で作られるため、初回store_id設定時に同じtriggerで補完する。
    IF NEW.store_id IS NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT rs.*
  INTO v_settings
  FROM public.reservation_settings rs
  JOIN public.stores s
    ON s.id = rs.store_id
   AND s.organization_id = NEW.organization_id
  WHERE rs.store_id = NEW.store_id
    AND (rs.organization_id = NEW.organization_id OR rs.organization_id IS NULL)
  ORDER BY (rs.organization_id = NEW.organization_id) DESC, rs.updated_at DESC
  LIMIT 1;

  NEW.cancellation_policy_store_id := NEW.store_id;
  IF FOUND THEN
    IF v_performance_type = 'private' THEN
      NEW.cancellation_policy_deadline_hours := COALESCE(v_settings.private_cancellation_deadline_hours, 0);
      NEW.cancellation_policy_fees := COALESCE(
        v_settings.private_cancellation_fees,
        '[{"hours_before":168,"fee_percentage":50,"description":"7日前より公演価格全額の50%"},{"hours_before":72,"fee_percentage":100,"description":"3日前より公演価格全額の100%"},{"hours_before":-1,"fee_percentage":100,"description":"公演開始後・無断キャンセル100%"}]'::jsonb
      );
      NEW.cancellation_policy_fee_basis := v_settings.private_cancellation_fee_basis;
    ELSE
      NEW.cancellation_policy_deadline_hours := COALESCE(v_settings.cancellation_deadline_hours, 0);
      NEW.cancellation_policy_fees := COALESCE(
        v_settings.cancellation_fees,
        '[{"hours_before":48,"fee_percentage":50,"description":"前日より50%"},{"hours_before":24,"fee_percentage":100,"description":"当日より100%"},{"hours_before":-1,"fee_percentage":100,"description":"公演開始後・無断100%"}]'::jsonb
      );
      NEW.cancellation_policy_fee_basis := v_settings.cancellation_fee_basis;
    END IF;
    NEW.cancellation_policy_updated_at := COALESCE(v_settings.updated_at, transaction_timestamp());
  ELSE
    -- 設定行がない店舗でも予約作成を止めず、不変の既定ポリシーをその場で固定する。
    IF v_performance_type = 'private' THEN
      NEW.cancellation_policy_deadline_hours := 0;
      NEW.cancellation_policy_fees := '[{"hours_before":168,"fee_percentage":50,"description":"7日前より公演価格全額の50%"},{"hours_before":72,"fee_percentage":100,"description":"3日前より公演価格全額の100%"},{"hours_before":-1,"fee_percentage":100,"description":"公演開始後・無断キャンセル100%"}]'::jsonb;
      NEW.cancellation_policy_fee_basis := 'performance_total';
    ELSE
      NEW.cancellation_policy_deadline_hours := 0;
      NEW.cancellation_policy_fees := '[{"hours_before":48,"fee_percentage":50,"description":"前日より50%"},{"hours_before":24,"fee_percentage":100,"description":"当日より100%"},{"hours_before":-1,"fee_percentage":100,"description":"公演開始後・無断100%"}]'::jsonb;
      NEW.cancellation_policy_fee_basis := 'participant_total';
    END IF;
    NEW.cancellation_policy_updated_at := transaction_timestamp();
  END IF;

  -- 初回に条件を固定する時点だけ、組織→店舗→作品→公演の実効値を採用する。
  -- UPDATE時の既存スナップショットを返す分岐は上で維持している。
  IF NEW.schedule_event_id IS NULL THEN
    SELECT os.id INTO v_scenario FROM public.organization_scenarios os
      WHERE os.organization_id = NEW.organization_id
        AND os.scenario_master_id = NEW.scenario_master_id;
  END IF;
  v_prefix := CASE WHEN v_performance_type = 'private' THEN 'private_' ELSE '' END;
  NEW.cancellation_policy_deadline_hours := (
    public.resolve_operating_setting(NEW.organization_id, v_prefix || 'cancellation_deadline_hours',
      to_jsonb(NEW.cancellation_policy_deadline_hours), NEW.store_id, v_scenario, NEW.schedule_event_id)->>'value')::integer;
  NEW.cancellation_policy_fees := public.resolve_operating_setting(NEW.organization_id, v_prefix || 'cancellation_fees',
    NEW.cancellation_policy_fees, NEW.store_id, v_scenario, NEW.schedule_event_id)->'value';
  NEW.cancellation_policy_fee_basis := public.resolve_operating_setting(NEW.organization_id, v_prefix || 'cancellation_fee_basis',
    to_jsonb(NEW.cancellation_policy_fee_basis), NEW.store_id, v_scenario, NEW.schedule_event_id)->>'value';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_reservation_cancellation_policy_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_reservation_cancelled_by"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
BEGIN
  IF NEW.status = 'cancelled'
     AND (OLD.status IS DISTINCT FROM 'cancelled')
     AND NEW.cancelled_by IS NULL THEN
    SELECT id INTO v_staff_id
    FROM staff
    WHERE user_id = auth.uid()
      AND organization_id = NEW.organization_id
    LIMIT 1;
    IF v_staff_id IS NOT NULL THEN
      NEW.cancelled_by := v_staff_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_reservation_cancelled_by"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_reservation_change_policy_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE scenario_id uuid; is_private boolean; setting_key text; performance_start timestamptz; refresh_on_first_store boolean:=false;
BEGIN
 IF TG_OP='INSERT' THEN
  NEW.reservation_change_policy_snapshot_version:=1;
 ELSE
  NEW.reservation_change_policy_snapshot_version:=OLD.reservation_change_policy_snapshot_version;
 END IF;
 IF TG_OP='UPDATE' THEN
  -- キャンセル規定の固定マーカーを共有し、店舗の解除→再設定でも再固定しない。
  -- 旧NULLは制限なしの履歴として保持。変更期限専用マーカーまたは既存の時間数で導入後を識別する。
  refresh_on_first_store:=(OLD.reservation_change_policy_snapshot_version=1
      OR OLD.reservation_change_deadline_hours_snapshot IS NOT NULL)
    AND OLD.cancellation_policy_snapshot_version=1
    AND OLD.cancellation_policy_store_id IS NULL AND OLD.store_id IS NULL
    AND NEW.store_id IS NOT NULL AND NEW.organization_id=OLD.organization_id
    AND (OLD.private_group_id IS NOT NULL OR OLD.reservation_source='web_private'
      OR COALESCE(OLD.reservation_type IN ('private','private_booking'),false));
 END IF;
 IF TG_OP='INSERT' OR refresh_on_first_store THEN
  IF refresh_on_first_store THEN
   IF NOT EXISTS(SELECT 1 FROM stores WHERE id=NEW.store_id AND organization_id=NEW.organization_id)
     OR (NEW.schedule_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM schedule_events
       WHERE id=NEW.schedule_event_id AND organization_id=NEW.organization_id AND store_id=NEW.store_id)) THEN
    RAISE EXCEPTION 'RESERVATION_POLICY_CONTEXT_MISMATCH' USING ERRCODE='23514';
   END IF;
  END IF;
  SELECT EXISTS(SELECT 1 FROM schedule_events e WHERE e.id=NEW.schedule_event_id
    AND e.organization_id=NEW.organization_id AND (e.category='private' OR e.is_private_booking)) INTO is_private;
  is_private:=is_private OR NEW.private_group_id IS NOT NULL OR NEW.reservation_source='web_private'
    OR COALESCE(NEW.reservation_type IN ('private','private_booking'),false);
  SELECT s.id INTO scenario_id FROM organization_scenarios s WHERE s.organization_id=NEW.organization_id
    AND s.scenario_master_id=NEW.scenario_master_id LIMIT 1;
  setting_key:=CASE WHEN is_private THEN 'private_reservation_change_deadline_hours' ELSE 'reservation_change_deadline_hours' END;
  NEW.reservation_change_deadline_hours_snapshot:=(public.resolve_operating_setting(NEW.organization_id,setting_key,'null'::jsonb,NEW.store_id,scenario_id,NEW.schedule_event_id)->>'value')::integer;
 ELSE
  NEW.reservation_change_deadline_hours_snapshot:=OLD.reservation_change_deadline_hours_snapshot;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.participant_count IS DISTINCT FROM OLD.participant_count
    AND auth.uid() IS NOT NULL
    AND NOT EXISTS(SELECT 1 FROM staff WHERE user_id=auth.uid() AND organization_id=OLD.organization_id AND status='active')
    AND NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND organization_id=OLD.organization_id AND role='admin') THEN
   IF OLD.reservation_change_deadline_hours_snapshot IS NOT NULL THEN
    SELECT (e.date + e.start_time) AT TIME ZONE 'Asia/Tokyo' INTO performance_start
     FROM schedule_events e WHERE e.id=OLD.schedule_event_id AND e.organization_id=OLD.organization_id;
    performance_start:=COALESCE(performance_start,OLD.requested_datetime);
    IF performance_start IS NULL OR now() >= performance_start - make_interval(hours=>OLD.reservation_change_deadline_hours_snapshot) THEN
     RAISE EXCEPTION 'RESERVATION_CHANGE_DEADLINE_PASSED' USING ERRCODE='P0050';
    END IF;
   END IF;
   IF refresh_on_first_store AND NEW.reservation_change_deadline_hours_snapshot IS NOT NULL THEN
    SELECT (e.date + e.start_time) AT TIME ZONE 'Asia/Tokyo' INTO performance_start
     FROM schedule_events e WHERE e.id=NEW.schedule_event_id AND e.organization_id=NEW.organization_id;
    performance_start:=COALESCE(performance_start,NEW.requested_datetime);
    IF performance_start IS NULL OR now() >= performance_start - make_interval(hours=>NEW.reservation_change_deadline_hours_snapshot) THEN
     RAISE EXCEPTION 'RESERVATION_CHANGE_DEADLINE_PASSED' USING ERRCODE='P0050';
    END IF;
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION "public"."set_reservation_change_policy_snapshot"() OWNER TO "postgres";


