CREATE OR REPLACE FUNCTION "public"."settle_cancellation_billing_claim"("p_organization_id" "uuid", "p_claim_id" "uuid", "p_revision" integer, "p_entry_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_claim public.cancellation_billing_claims;
BEGIN
  SELECT * INTO v_claim FROM public.cancellation_billing_claims
    WHERE organization_id = p_organization_id AND id = p_claim_id FOR UPDATE;
  IF NOT FOUND OR v_claim.revision <> p_revision OR v_claim.data->>'paidAt' IS NOT NULL
    OR v_claim.data->'assessment'->>'status' <> 'payable'
    OR v_claim.data->>'notifiedAt' IS NULL THEN
    RETURN false;
  END IF;
  -- 配信中の未入金案内とは競合させない。送信結果不明も運営確認まで保留。
  IF EXISTS (SELECT 1 FROM public.cancellation_billing_notices
    WHERE organization_id = p_organization_id AND claim_id = p_claim_id AND status IN ('sending', 'unknown')) THEN
    RETURN false;
  END IF;
  INSERT INTO public.cancellation_billing_matches(organization_id, entry_id, claim_id)
    VALUES (p_organization_id, p_entry_id, p_claim_id);
  UPDATE public.cancellation_billing_claims
    SET data = jsonb_set(data, '{paidAt}', to_jsonb(now())), revision = revision + 1, updated_at = now()
    WHERE organization_id = p_organization_id AND id = p_claim_id;
  RETURN true;
EXCEPTION WHEN unique_violation THEN RETURN false;
END;
$$;


ALTER FUNCTION "public"."settle_cancellation_billing_claim"("p_organization_id" "uuid", "p_claim_id" "uuid", "p_revision" integer, "p_entry_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_cancellation_billing_snapshot"("p_organization_id" "uuid", "p_claim_id" "uuid", "p_revision" integer, "p_entry_id" "text", "p_snapshot" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_snapshot jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text, 908001));
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'revision',revision) ORDER BY id),'[]'::jsonb)
    INTO v_snapshot FROM public.cancellation_billing_claims WHERE organization_id=p_organization_id;
  IF p_snapshot IS NULL OR p_snapshot <> v_snapshot THEN RETURN false; END IF;
  RETURN public.settle_cancellation_billing_claim(p_organization_id,p_claim_id,p_revision,p_entry_id);
END;
$$;


ALTER FUNCTION "public"."settle_cancellation_billing_snapshot"("p_organization_id" "uuid", "p_claim_id" "uuid", "p_revision" integer, "p_entry_id" "text", "p_snapshot" "jsonb") OWNER TO "postgres";


