CREATE OR REPLACE FUNCTION "public"."submit_license_partner_monthly_report"("p_token" "text", "p_year" integer, "p_month" integer, "p_counts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_store public.license_partner_stores%ROWTYPE;
  v_item JSONB;
  v_scenario_id UUID;
  v_count INTEGER;
  v_updated INTEGER := 0;
  v_now TIMESTAMPTZ := NOW();
  v_jst_year INTEGER;
  v_jst_month INTEGER;
BEGIN
  IF p_token IS NULL OR length(p_token) < 32 THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = '28000';
  END IF;
  IF p_year IS NULL OR p_month IS NULL
     OR p_year < 2020 OR p_year > 2100
     OR p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'invalid period' USING ERRCODE = '22023';
  END IF;
  IF p_counts IS NULL OR jsonb_typeof(p_counts) <> 'array' THEN
    RAISE EXCEPTION 'invalid counts' USING ERRCODE = '22023';
  END IF;

  v_jst_year := EXTRACT(YEAR FROM (v_now AT TIME ZONE 'Asia/Tokyo'))::INTEGER;
  v_jst_month := EXTRACT(MONTH FROM (v_now AT TIME ZONE 'Asia/Tokyo'))::INTEGER;
  IF (p_year > v_jst_year) OR (p_year = v_jst_year AND p_month > v_jst_month) THEN
    RAISE EXCEPTION 'future month not allowed' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_store
    FROM public.license_partner_stores
   WHERE report_token = p_token
     AND is_active = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = '28000';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_counts)
  LOOP
    BEGIN
      v_scenario_id := (v_item->>'scenario_master_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid scenario' USING ERRCODE = '22023';
    END;

    BEGIN
      v_count := (v_item->>'performance_count')::INTEGER;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid count' USING ERRCODE = '22023';
    END;

    IF v_scenario_id IS NULL OR v_count IS NULL OR v_count < 0 THEN
      RAISE EXCEPTION 'invalid count' USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.license_partner_contracts c
      INNER JOIN public.organization_scenarios os
        ON os.scenario_master_id = c.scenario_master_id
       AND os.organization_id = c.organization_id
       AND os.scenario_type = 'managed'
       AND os.org_status = 'available'
      WHERE c.partner_store_id = v_store.id
        AND c.organization_id = v_store.organization_id
        AND c.scenario_master_id = v_scenario_id
    ) THEN
      RAISE EXCEPTION 'scenario not contracted' USING ERRCODE = '42501';
    END IF;

    INSERT INTO public.license_partner_monthly_reports (
      organization_id,
      partner_store_id,
      scenario_master_id,
      year,
      month,
      performance_count,
      submitted_at,
      submitted_via
    ) VALUES (
      v_store.organization_id,
      v_store.id,
      v_scenario_id,
      p_year,
      p_month,
      v_count,
      v_now,
      'form'
    )
    ON CONFLICT (partner_store_id, scenario_master_id, year, month)
    DO UPDATE SET
      performance_count = EXCLUDED.performance_count,
      submitted_at = EXCLUDED.submitted_at,
      submitted_via = EXCLUDED.submitted_via;

    v_updated := v_updated + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', TRUE,
    'updated_count', v_updated
  );
END;
$$;


ALTER FUNCTION "public"."submit_license_partner_monthly_report"("p_token" "text", "p_year" integer, "p_month" integer, "p_counts" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_license_partner_monthly_report"("p_token" "text", "p_year" integer, "p_month" integer, "p_counts" "jsonb") IS '契約店舗の報告トークンで、契約作品の月次回数だけを upsert する。';



CREATE OR REPLACE FUNCTION "public"."sync_assignments_to_staff"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE target uuid; targets uuid[];
BEGIN
  IF TG_OP='INSERT' THEN targets:=ARRAY[NEW.staff_id];
  ELSIF TG_OP='DELETE' THEN targets:=ARRAY[OLD.staff_id];
  ELSE targets:=ARRAY[OLD.staff_id,NEW.staff_id]; END IF;
  FOR target IN SELECT DISTINCT x FROM unnest(targets) x ORDER BY x LOOP
    PERFORM 1 FROM public.staff WHERE id=target FOR NO KEY UPDATE;
    UPDATE public.staff SET
      special_scenarios=coalesce((SELECT array_agg(DISTINCT scenario_master_id::text ORDER BY scenario_master_id::text)
        FROM public.staff_scenario_assignments WHERE staff_id=target AND (can_main_gm OR can_sub_gm)),'{}'::text[]),
      available_scenarios=coalesce((SELECT array_agg(DISTINCT scenario_master_id::text ORDER BY scenario_master_id::text)
        FROM public.staff_scenario_assignments WHERE staff_id=target AND is_experienced),'{}'::text[])
      WHERE id=target;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_assignments_to_staff"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_event_datetime_to_current_bookings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record; g record; candidate_ids uuid[];
BEGIN
 IF NEW.date IS NOT DISTINCT FROM OLD.date AND NEW.start_time IS NOT DISTINCT FROM OLD.start_time
    AND NEW.end_time IS NOT DISTINCT FROM OLD.end_time AND NEW.time_slot IS NOT DISTINCT FROM OLD.time_slot THEN RETURN NEW; END IF;
 IF NEW.organization_id IS NULL OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
  RAISE EXCEPTION 'EVENT_BOOKING_ORGANIZATION_MISMATCH' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM public.reservations WHERE schedule_event_id=NEW.id
    AND organization_id IS DISTINCT FROM NEW.organization_id) THEN
  RAISE EXCEPTION 'EVENT_BOOKING_ORGANIZATION_MISMATCH' USING ERRCODE='23514';
 END IF;
 FOR r IN SELECT id,private_group_id FROM public.reservations
   WHERE schedule_event_id=NEW.id AND organization_id=NEW.organization_id
     AND status IN ('pending','confirmed','gm_confirmed','checked_in','completed') ORDER BY id FOR UPDATE NOWAIT LOOP
  UPDATE public.reservations SET requested_datetime=(NEW.date::text||' '||NEW.start_time::text)::timestamp AT TIME ZONE 'Asia/Tokyo'
   WHERE id=r.id AND organization_id=NEW.organization_id;
  IF r.private_group_id IS NULL THEN CONTINUE; END IF;
  SELECT id,organization_id,reservation_id INTO g FROM public.private_groups WHERE id=r.private_group_id FOR UPDATE NOWAIT;
  IF NOT FOUND OR g.organization_id IS DISTINCT FROM NEW.organization_id THEN
   RAISE EXCEPTION 'EVENT_PRIVATE_GROUP_ORGANIZATION_MISMATCH' USING ERRCODE='23514';
  END IF;
  -- A superseded reservation must not rewrite the current group's candidate dates.
  IF g.reservation_id IS DISTINCT FROM r.id THEN CONTINUE; END IF;
  PERFORM c.id FROM public.private_group_candidate_dates c WHERE c.group_id=g.id
   AND c.date=OLD.date AND c.start_time::time=OLD.start_time::time AND c.status IS DISTINCT FROM 'rejected'
   ORDER BY c.id FOR UPDATE NOWAIT;
  SELECT array_agg(c.id ORDER BY c.id) INTO candidate_ids FROM public.private_group_candidate_dates c
   WHERE c.group_id=g.id AND c.date=OLD.date AND c.start_time::time=OLD.start_time::time
     AND c.status IS DISTINCT FROM 'rejected';
  IF coalesce(cardinality(candidate_ids),0)>1 THEN
   RAISE EXCEPTION 'EVENT_PRIVATE_CANDIDATE_AMBIGUOUS' USING ERRCODE='23514';
  END IF;
  -- No exact match: preserve the original proposals, never choose the first same-day row.
  IF cardinality(candidate_ids)=1 THEN
   UPDATE public.private_group_candidate_dates SET date=NEW.date,start_time=NEW.start_time::text,end_time=NEW.end_time::text,
    time_slot=CASE NEW.time_slot WHEN '朝' THEN '午前' WHEN '昼' THEN '午後' WHEN '夜' THEN '夜間' ELSE time_slot END
    WHERE id=candidate_ids[1] AND group_id=g.id;
  END IF;
 END LOOP;
 RETURN NEW;
END $$;


ALTER FUNCTION "public"."sync_event_datetime_to_current_bookings"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_event_datetime_to_current_bookings"() IS '{"rollback_candidate_update": {"anon": true, "authenticated": true}}';



CREATE OR REPLACE FUNCTION "public"."sync_event_staff_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  previous jsonb;
  prior jsonb;
  gm_name text;
  gm_id uuid;
  gm_role text;
  gm_status text;
  gm_role_confirmed boolean;
  position integer := 0;
  gm_position integer := 0;  -- 参加・見学・受付を除いた GM の配置順（役割未設定の既定値に使う）
  occurrences integer;
  role_name text;
BEGIN
  IF TG_OP='UPDATE' AND NEW.gms IS NOT DISTINCT FROM OLD.gms
    AND NEW.gm_roles IS NOT DISTINCT FROM OLD.gm_roles
    AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id
    AND EXISTS(SELECT 1 FROM public.schedule_event_staff_assignments WHERE event_id=NEW.id) THEN
    RAISE EXCEPTION '担当記録のある公演は組織を変更できません' USING ERRCODE='23514';
  END IF;
  IF NEW.gm_roles IS NOT NULL AND jsonb_typeof(NEW.gm_roles) <> 'object' THEN
    RAISE EXCEPTION '担当役割の形式が不正です' USING ERRCODE='23514';
  END IF;
  FOR role_name IN SELECT jsonb_object_keys(coalesce(NEW.gm_roles,'{}'::jsonb)) LOOP
    IF NOT (role_name = ANY(coalesce(NEW.gms,ARRAY[]::text[])))
      AND (TG_OP='INSERT' OR NOT(coalesce(OLD.gm_roles,'{}'::jsonb) ? role_name)) THEN
      RAISE EXCEPTION '担当名と役割が一致しません。最新の公演を読み込み直してください' USING ERRCODE='23514';
    END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(a)), '[]') INTO previous
    FROM public.schedule_event_staff_assignments a WHERE event_id=NEW.id;
  DELETE FROM public.schedule_event_staff_assignments WHERE event_id=NEW.id;
  FOREACH gm_name IN ARRAY coalesce(NEW.gms,ARRAY[]::text[]) LOOP
    position := position + 1;
    SELECT value INTO prior FROM jsonb_array_elements(previous)
      WHERE value->>'staff_name' IS NOT DISTINCT FROM gm_name LIMIT 1;
    SELECT count(*) INTO occurrences FROM unnest(NEW.gms) x(name) WHERE name IS NOT DISTINCT FROM gm_name;
    gm_id := NULL;
    IF occurrences > 1 THEN
      -- Previously imported duplicates may be edited without inventing identities.
      IF prior IS NULL OR prior->>'resolution_status' <> 'duplicate' THEN
        RAISE EXCEPTION '同じスタッフを重複して登録できません' USING ERRCODE='23514';
      END IF;
      gm_status := 'duplicate';
    ELSIF prior IS NOT NULL AND prior->>'resolution_status' <> 'duplicate' THEN
      gm_id := (prior->>'staff_id')::uuid;
      gm_status := CASE WHEN gm_id IS NULL THEN 'unmatched' ELSE 'resolved' END;
    ELSE
      SELECT id INTO gm_id FROM public.staff
        WHERE organization_id=NEW.organization_id AND name=gm_name FOR SHARE NOWAIT;
      IF gm_id IS NULL THEN
        RAISE EXCEPTION '担当スタッフを特定できません。最新のスタッフ一覧から選び直してください' USING ERRCODE='23514';
      END IF;
      gm_status := 'resolved';
    END IF;
    IF gm_id IS NOT NULL THEN
      -- Pre-lock before the FK insert: staff rename holds a staff lock and updates events.
      PERFORM id FROM public.staff WHERE id=gm_id AND organization_id=NEW.organization_id FOR KEY SHARE NOWAIT;
      IF NOT FOUND THEN RAISE EXCEPTION '別組織のスタッフは登録できません' USING ERRCODE='23514'; END IF;
    END IF;
    IF prior IS NULL AND gm_id IS NOT NULL THEN
      -- A rename changes the name key, not the already-resolved person's identity.
      SELECT value INTO prior FROM jsonb_array_elements(previous) WHERE value->>'staff_id'=gm_id::text LIMIT 1;
    END IF;
    -- 役割未設定の既定値は、参加・見学・受付を除いた GM の配置順で決める（売上側 salesGmCostRole と同じ規則、#734）。
    IF lower(coalesce(nullif(NEW.gm_roles->>gm_name,''),'main')) NOT IN ('staff','observer','reception') THEN
      gm_position := gm_position + 1;
    END IF;
    gm_role := coalesce(nullif(NEW.gm_roles->>gm_name,''),CASE WHEN gm_position=1 THEN 'main' ELSE 'sub' END);
    gm_role_confirmed := CASE
      WHEN nullif(NEW.gm_roles->>gm_name,'') IS NOT NULL THEN true
      WHEN prior->>'role_confirmed'='false' THEN false
      ELSE NOT EXISTS(SELECT 1 FROM jsonb_object_keys(coalesce(NEW.gm_roles,'{}'::jsonb)) key
        WHERE NOT(key=ANY(coalesce(NEW.gms,ARRAY[]::text[])))) END;
    INSERT INTO public.schedule_event_staff_assignments VALUES(NEW.id,position,NEW.organization_id,gm_id,gm_name,gm_role,gm_status,gm_role_confirmed);
  END LOOP;
  RETURN NEW;
EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION '担当スタッフが別の処理で更新中です。少し待って再度保存してください' USING ERRCODE='23514';
END $$;


ALTER FUNCTION "public"."sync_event_staff_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_event_staff_participations"("p_event_id" "uuid", "p_entries" "jsonb", "p_expected" "jsonb", "p_gms" "text"[], "p_gm_roles" "jsonb", "p_expected_staff" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_org uuid:=public.get_user_organization_id(); v_event public.schedule_events; v_current jsonb; v_entry jsonb;
 v_staff public.staff; v_res public.reservations; v_id uuid; v_name text; v_total integer; v_limit integer; v_new_count integer; v_old record; v_after jsonb; v_actor_id uuid; v_actor_name text;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role::text IN ('admin','staff','license_admin')) THEN
  RAISE EXCEPTION 'スタッフ参加を保存する権限がありません' USING ERRCODE='42501';
 END IF;
 IF jsonb_typeof(p_entries) IS DISTINCT FROM 'array' OR jsonb_typeof(p_expected) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'スタッフ参加の形式が不正です' USING ERRCODE='22023';
 END IF;
 SELECT * INTO v_event FROM public.schedule_events WHERE id=p_event_id AND organization_id=v_org FOR NO KEY UPDATE;
 IF NOT FOUND OR v_event.is_cancelled THEN RAISE EXCEPTION '保存可能な公演が見つかりません' USING ERRCODE='22023'; END IF;
 v_current:=public.get_event_staff_participations(p_event_id)->'entries';
 IF v_current IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'スタッフ参加が更新されました。公演を開き直してください' USING ERRCODE='40001'; END IF;
 IF jsonb_build_object('gms',coalesce(v_event.gms,ARRAY[]::text[]),'gm_roles',coalesce(v_event.gm_roles,'{}'::jsonb)) IS DISTINCT FROM p_expected_staff THEN
  RAISE EXCEPTION '担当スタッフが更新されました。公演を開き直してください' USING ERRCODE='40001';
 END IF;
 IF p_gms IS NULL OR jsonb_typeof(p_gm_roles) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '担当スタッフの形式が不正です' USING ERRCODE='22023'; END IF;
 UPDATE public.schedule_events SET gms=p_gms,gm_roles=p_gm_roles WHERE id=p_event_id AND organization_id=v_org;
 IF (SELECT count(*) FROM jsonb_array_elements(p_entries))<>(SELECT count(DISTINCT e->>'staff_id') FROM jsonb_array_elements(p_entries) e) THEN
  RAISE EXCEPTION '同じスタッフを重複して登録できません' USING ERRCODE='22023';
 END IF;
 -- Event roles and participant reservations are committed or rolled back together.
 IF EXISTS(SELECT 1 FROM public.schedule_event_staff_assignments a WHERE a.event_id=p_event_id AND a.role='staff'
  AND (a.staff_id IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_entries) e WHERE e->>'staff_id'=a.staff_id::text))) THEN
  RAISE EXCEPTION 'スタッフ参加ごとに予約人数内か追加席かを選択してください' USING ERRCODE='22023';
 END IF;
 -- A reservation update may already hold a row lock while waiting for the event.
 -- NOWAIT prevents reversing that order into a deadlock; the entire call rolls back.
 PERFORM 1 FROM public.reservations WHERE schedule_event_id=p_event_id ORDER BY id FOR UPDATE NOWAIT;
 FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
  SELECT * INTO v_staff FROM public.staff WHERE id=(v_entry->>'staff_id')::uuid AND organization_id=v_org;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.schedule_event_staff_assignments WHERE event_id=p_event_id AND staff_id=v_staff.id AND role='staff') THEN
   RAISE EXCEPTION '公演の参加スタッフを確認できません' USING ERRCODE='22023';
  END IF;
  IF v_entry->>'mode' NOT IN ('included','additional') OR v_entry->>'mode' IS NULL THEN
   RAISE EXCEPTION '予約人数内か追加席かを選択してください' USING ERRCODE='22023';
  END IF;
  IF v_entry->>'mode'='included' THEN
   SELECT * INTO v_res FROM public.reservations WHERE id=(v_entry->>'reservation_id')::uuid AND schedule_event_id=p_event_id AND organization_id=v_org AND status IN ('pending','confirmed','gm_confirmed','checked_in') AND participant_count>0;
   IF NOT FOUND OR EXISTS(SELECT 1 FROM public.event_staff_participations WHERE reservation_id=v_res.id AND mode='additional') THEN
    RAISE EXCEPTION '人数に含める有効な予約を選び直してください' USING ERRCODE='22023';
   END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(p_entries) e WHERE e->>'mode'='included' AND e->>'reservation_id'=v_res.id::text)>v_res.participant_count THEN
    RAISE EXCEPTION '予約人数を超えるスタッフを人数内として指定できません' USING ERRCODE='22023';
   END IF;
  ELSIF nullif(v_entry->>'reservation_id','') IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.event_staff_participations l JOIN public.reservations r ON r.id=l.reservation_id
   WHERE l.event_id=p_event_id AND l.staff_id=v_staff.id AND l.mode='additional' AND l.reservation_id=(v_entry->>'reservation_id')::uuid
    AND r.schedule_event_id=p_event_id AND r.organization_id=v_org AND r.reservation_source='staff_entry' AND r.participant_count=1
    AND r.status IN ('pending','confirmed','gm_confirmed','checked_in')) THEN
   RAISE EXCEPTION '追加席が変更されています。公演を開き直してください' USING ERRCODE='40001';
  END IF;
 END LOOP;
 -- Only explicitly linked auto-created seats may be cancelled; all legacy/manual bookings are preserved.
 FOR v_old IN SELECT * FROM public.event_staff_participations WHERE event_id=p_event_id AND mode='additional' LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_entries) e WHERE e->>'staff_id'=v_old.staff_id::text AND e->>'mode'='additional' AND e->>'reservation_id'=v_old.reservation_id::text) THEN
   UPDATE public.reservations SET status='cancelled' WHERE id=v_old.reservation_id AND schedule_event_id=p_event_id AND organization_id=v_org
    AND reservation_source='staff_entry' AND participant_count=1 AND payment_method='staff' AND customer_id IS NULL AND coalesce(base_price,0)=0 AND coalesce(options_price,0)=0 AND coalesce(discount_amount,0)=0 AND coalesce(total_price,0)=0 AND coalesce(final_price,0)=0
    AND status IN ('pending','confirmed','gm_confirmed','checked_in');
   IF NOT FOUND AND EXISTS(SELECT 1 FROM public.reservations WHERE id=v_old.reservation_id AND status<>'cancelled')
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_current) e WHERE e->>'staff_id'=v_old.staff_id::text AND (e->>'needs_confirmation')::boolean) THEN
    RAISE EXCEPTION '追加席の予約内容が変更されています。予約者一覧を確認してください' USING ERRCODE='40001';
   END IF;
  END IF;
 END LOOP;
 SELECT coalesce(sum(participant_count),0) INTO v_total FROM public.reservations WHERE schedule_event_id=p_event_id AND organization_id=v_org AND status IN ('pending','confirmed','gm_confirmed','checked_in');
 v_new_count:=(SELECT count(*) FROM jsonb_array_elements(p_entries) e WHERE e->>'mode'='additional' AND nullif(e->>'reservation_id','') IS NULL);
 v_total:=v_total+v_new_count;
 v_limit:=coalesce(nullif(v_event.max_participants,0),nullif(v_event.capacity,0));
 IF v_new_count>0 AND (v_limit IS NULL OR v_limit<1 OR v_total>v_limit) THEN
  RAISE EXCEPTION '定員%名に対して%名になるため保存できません。予約人数に含まれるスタッフは「予約人数内」を選択してください',coalesce(v_limit,0),v_total USING ERRCODE='23514';
 END IF;
 DELETE FROM public.event_staff_participations WHERE event_id=p_event_id;
 FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
  v_id:=nullif(v_entry->>'reservation_id','')::uuid;
  IF v_entry->>'mode'='additional' AND v_id IS NULL THEN
   SELECT name INTO v_name FROM public.staff WHERE id=(v_entry->>'staff_id')::uuid AND organization_id=v_org;
   INSERT INTO public.reservations(organization_id,schedule_event_id,reservation_number,title,scenario_master_id,store_id,customer_id,customer_notes,
    requested_datetime,duration,participant_count,participant_names,assigned_staff,base_price,options_price,total_price,discount_amount,final_price,payment_method,payment_status,status,reservation_source,created_by)
   VALUES(v_org,p_event_id,'STAFF-'||gen_random_uuid()::text,v_event.scenario,v_event.scenario_master_id,v_event.store_id,NULL,v_name,
    (v_event.date+v_event.start_time) AT TIME ZONE 'Asia/Tokyo',(extract(epoch FROM (v_event.end_time-v_event.start_time))/60+CASE WHEN v_event.end_time<=v_event.start_time THEN 1440 ELSE 0 END)::integer,
    1,ARRAY[v_name],ARRAY[]::text[],0,0,0,0,0,'staff','paid','confirmed','staff_entry',auth.uid()) RETURNING id INTO v_id;
  END IF;
  INSERT INTO public.event_staff_participations VALUES(p_event_id,(v_entry->>'staff_id')::uuid,v_org,v_id,v_entry->>'mode');
 END LOOP;
 v_after:=public.get_event_staff_participations(p_event_id);
 IF v_after->'entries' IS DISTINCT FROM v_current OR v_after->'assignment' IS DISTINCT FROM p_expected_staff THEN
  INSERT INTO public.audit_logs(user_id,organization_id,action,resource_type,resource_id,old_values,new_values)
  VALUES(auth.uid(),v_org,'staff_participation.sync','schedule_events',p_event_id,jsonb_build_object('entries',v_current,'assignment',p_expected_staff),v_after-'reservations');
  SELECT id,name INTO v_actor_id,v_actor_name FROM public.staff WHERE user_id=auth.uid() AND organization_id=v_org;
  INSERT INTO public.schedule_event_history(schedule_event_id,organization_id,changed_by_user_id,changed_by_staff_id,changed_by_name,action_type,changes,old_values,new_values,event_date,store_id,time_slot,notes)
  SELECT p_event_id,v_org,auth.uid(),v_actor_id,coalesce(v_actor_name,'管理者'),'update',
   jsonb_build_object('gms',jsonb_build_object('old',p_expected_staff->'gms','new',to_jsonb(p_gms)),
    'gm_roles',jsonb_build_object('old',p_expected_staff->'gm_roles','new',p_gm_roles),
    'staff_participation',jsonb_build_object('old',v_current,'new',v_after->'entries')),
   to_jsonb(v_event),to_jsonb(e),e.date,e.store_id,e.time_slot,'担当とスタッフ参加人数を一括保存'
  FROM public.schedule_events e WHERE e.id=p_event_id;
 END IF;
 RETURN v_after;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION '予約が別の操作で更新中です。変更は保存されていません。再読み込みしてください' USING ERRCODE='55P03';
END $$;


ALTER FUNCTION "public"."sync_event_staff_participations"("p_event_id" "uuid", "p_entries" "jsonb", "p_expected" "jsonb", "p_gms" "text"[], "p_gm_roles" "jsonb", "p_expected_staff" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_kit_location_on_transfer_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status='completed' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'completed') THEN
    INSERT INTO public.scenario_kit_locations(organization_id,org_scenario_id,scenario_master_id,kit_number,store_id)
    VALUES(NEW.organization_id,NEW.org_scenario_id,NEW.scenario_master_id,NEW.kit_number,NEW.to_store_id)
    ON CONFLICT(organization_id,org_scenario_id,kit_number)
    DO UPDATE SET store_id=EXCLUDED.store_id,scenario_master_id=EXCLUDED.scenario_master_id,updated_at=now();
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."sync_kit_location_on_transfer_complete"() OWNER TO "postgres";


