CREATE OR REPLACE FUNCTION "public"."sync_scenario_title_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- タイトルが変更された場合のみ処理
  IF OLD.title IS DISTINCT FROM NEW.title THEN
    UPDATE schedule_events
    SET scenario = NEW.title,
        updated_at = NOW()
    WHERE scenario_master_id = NEW.id;
    
    RAISE NOTICE 'Updated schedule_events scenario title from "%" to "%" for master_id %', 
      OLD.title, NEW.title, NEW.id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_scenario_title_to_events"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_scenario_title_to_events"() IS 'scenario_masters.title の変更を schedule_events.scenario に自動反映するトリガー関数';



CREATE OR REPLACE FUNCTION "public"."sync_staff_account_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_ids uuid[]; v_id uuid; v_user public.users%ROWTYPE; v_staff public.staff%ROWTYPE; v_role public.app_role;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.user_id,NEW.organization_id,NEW.role,NEW.status)
   IS NOT DISTINCT FROM (OLD.user_id,OLD.organization_id,OLD.role,OLD.status) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN v_ids:=ARRAY[NEW.user_id];
 ELSIF TG_OP='DELETE' THEN v_ids:=ARRAY[OLD.user_id];
 ELSE v_ids:=ARRAY[OLD.user_id,NEW.user_id]; END IF;
 FOR v_id IN SELECT DISTINCT x from unnest(v_ids) x WHERE x IS NOT NULL ORDER BY x LOOP
   SELECT * INTO v_user FROM public.users WHERE id=v_id FOR UPDATE;
   IF NOT FOUND THEN CONTINUE; END IF;
   SELECT * INTO v_staff FROM public.staff WHERE user_id=v_id;
   -- A license administrator's permission is independent of staff membership.
   IF v_user.role='license_admin' THEN
     IF v_staff.id IS NOT NULL AND v_user.organization_id IS NULL THEN
       UPDATE public.users SET organization_id=v_staff.organization_id WHERE id=v_id;
     END IF;
     CONTINUE;
   END IF;
   INSERT INTO public.staff_account_access(user_id,organization_id) VALUES(v_id,coalesce(v_staff.organization_id,v_user.organization_id,(SELECT organization_id FROM public.staff_account_access WHERE user_id=v_id),CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END)) ON CONFLICT(user_id) DO NOTHING;
   v_role := CASE WHEN v_staff.id IS NULL OR v_staff.status IN ('inactive','resigned') THEN 'customer'::public.app_role
     WHEN coalesce(v_staff.role,'{}'::text[]) && ARRAY['admin','管理者'] THEN 'admin'::public.app_role
     ELSE 'staff'::public.app_role END;
   UPDATE public.users SET role=v_role,
      organization_id=CASE WHEN v_role='customer' THEN NULL ELSE coalesce(v_staff.organization_id,v_user.organization_id) END,
      updated_at=clock_timestamp() WHERE id=v_id;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_staff_account_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_staff_to_assignments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE gm text[]; played text[];
BEGIN
  IF TG_OP='UPDATE' AND (NEW.special_scenarios,NEW.available_scenarios)
    IS NOT DISTINCT FROM (OLD.special_scenarios,OLD.available_scenarios) THEN RETURN NEW; END IF;
  SELECT coalesce(array_agg(DISTINCT scenario_master_id::text ORDER BY scenario_master_id::text)
      FILTER(WHERE can_main_gm OR can_sub_gm),'{}'::text[]),
    coalesce(array_agg(DISTINCT scenario_master_id::text ORDER BY scenario_master_id::text)
      FILTER(WHERE is_experienced),'{}'::text[])
  INTO gm,played FROM public.staff_scenario_assignments WHERE staff_id=NEW.id;
  IF coalesce(NEW.special_scenarios,'{}'::text[]) IS DISTINCT FROM gm
    OR coalesce(NEW.available_scenarios,'{}'::text[]) IS DISTINCT FROM played THEN
    RAISE EXCEPTION '担当作品・体験済み作品は担当設定から変更してください' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_staff_to_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_waitlist_retry"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_pending_count INTEGER;
  v_supabase_url TEXT;
  v_service_role_key TEXT;
BEGIN
  -- 処理待ちのキューがあるか確認
  SELECT COUNT(*) INTO v_pending_count
  FROM waitlist_notification_queue
  WHERE status = 'pending'
    AND retry_count < 3
    AND (last_retry_at IS NULL OR last_retry_at < NOW() - INTERVAL '5 minutes');
  
  IF v_pending_count = 0 THEN
    RAISE NOTICE '処理待ちキューなし';
    RETURN;
  END IF;
  
  RAISE NOTICE 'キャンセル待ちリトライ対象: %件', v_pending_count;
  
  -- Edge Function URLを設定（Supabase環境変数から取得）
  -- 注意: 実際の呼び出しはpg_netまたは外部スケジューラから行う
  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_role_key := current_setting('app.service_role_key', true);
  
  IF v_supabase_url IS NULL THEN
    RAISE NOTICE '⚠️ Supabase URL未設定。Edge Functionは外部から呼び出してください。';
    RETURN;
  END IF;
  
  -- pg_netでHTTPリクエストを送信（オプション）
  -- PERFORM extensions.http_post(
  --   v_supabase_url || '/functions/v1/process-waitlist-queue',
  --   '{}',
  --   ARRAY[
  --     extensions.http_header('Authorization', 'Bearer ' || v_service_role_key),
  --     extensions.http_header('Content-Type', 'application/json')
  --   ]
  -- );
  
  RAISE NOTICE 'キャンセル待ちリトライをトリガー（外部スケジューラ経由）';
END;
$$;


ALTER FUNCTION "public"."trigger_waitlist_retry"() OWNER TO "postgres";


