CREATE OR REPLACE FUNCTION "public"."update_customer_coupon_on_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE public.customer_coupons
  SET
    uses_remaining = GREATEST(uses_remaining - 1, 0),
    status = CASE
      WHEN uses_remaining - 1 <= 0 THEN 'fully_used'
      ELSE status
    END,
    updated_at = NOW()
  WHERE id = NEW.customer_coupon_id;

  RETURN NEW;
END;
$$;


