    "organization_id" "uuid" NOT NULL,
    "memo" "text" DEFAULT ''::"text" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."customer_memos" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_memos" IS '顧客単位の社内専用メモ。RLSで組織スタッフのみ・顧客ロールには一切見せない。(customer_id, organization_id) で1件';



CREATE OR REPLACE FUNCTION "public"."upsert_customer_memo"("p_customer_id" "uuid", "p_memo" "text") RETURNS "public"."customer_memos"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_org_id uuid := public.get_user_organization_id();
  v_row    public.customer_memos;
BEGIN
  IF v_org_id IS NULL OR NOT public.is_staff_or_admin() THEN
    RAISE EXCEPTION 'not authorized to write customer memos';
  END IF;

  INSERT INTO public.customer_memos (customer_id, organization_id, memo, created_by, updated_by)
  VALUES (p_customer_id, v_org_id, COALESCE(p_memo, ''), v_uid, v_uid)
  ON CONFLICT (customer_id, organization_id)
  DO UPDATE SET
    memo       = EXCLUDED.memo,
    updated_by = v_uid,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_customer_memo"("p_customer_id" "uuid", "p_memo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_customer_memo"("p_customer_id" "uuid", "p_memo" "text") IS '顧客単位の社内メモを自組織分で upsert。org_id はサーバー側導出、created_by は初回のみ保持。RLS(自組織+staff)を SECURITY INVOKER で適用';



CREATE OR REPLACE FUNCTION "public"."upsert_manual_external_performance"("p_organization_id" "uuid", "p_scenario_id" "uuid", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_id UUID;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users
    WHERE id = auth.uid()
    AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: organization mismatch';
  END IF;

  IF p_performance_count = 0 THEN
    DELETE FROM manual_external_performances
    WHERE organization_id = p_organization_id
      AND scenario_master_id = p_scenario_id
      AND year = p_year
      AND month = p_month;

    RETURN jsonb_build_object('action', 'deleted', 'count', 0);
  END IF;

  INSERT INTO manual_external_performances (
    organization_id,
    scenario_master_id,
    year,
    month,
    performance_count,
    updated_by,
    updated_at
  ) VALUES (
    p_organization_id,
    p_scenario_id,
    p_year,
    p_month,
    p_performance_count,
    p_updated_by,
    NOW()
  )
  ON CONFLICT (organization_id, scenario_master_id, year, month)
  DO UPDATE SET
    performance_count = EXCLUDED.performance_count,
    updated_by = EXCLUDED.updated_by,
    updated_at = NOW()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'action', 'upserted',
    'id', v_id,
    'count', p_performance_count
  );
END;
$$;


ALTER FUNCTION "public"."upsert_manual_external_performance"("p_organization_id" "uuid", "p_scenario_id" "uuid", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_manual_external_performance"("p_organization_id" "uuid", "p_scenario_id" "uuid", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid") IS '他社公演数の保存（upsert）。RLSをバイパスして確実に実行';



CREATE OR REPLACE FUNCTION "public"."upsert_manual_external_performance"("p_organization_id" "uuid", "p_scenario_id" "uuid", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid" DEFAULT NULL::"uuid", "p_performance_type" "text" DEFAULT 'normal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_existing_id UUID;
BEGIN
  SELECT id INTO v_existing_id
  FROM public.manual_external_performances
  WHERE organization_id  = p_organization_id
    AND scenario_id      = p_scenario_id
    AND year             = p_year
    AND month            = p_month
    AND performance_type = p_performance_type;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.manual_external_performances
    SET performance_count = p_performance_count,
        updated_by        = p_updated_by,
        updated_at        = now()
    WHERE id = v_existing_id;
  ELSE
    INSERT INTO public.manual_external_performances
      (organization_id, scenario_id, year, month, performance_count, updated_by, performance_type)
    VALUES
      (p_organization_id, p_scenario_id, p_year, p_month, p_performance_count, p_updated_by, p_performance_type);
  END IF;

  RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."upsert_manual_external_performance"("p_organization_id" "uuid", "p_scenario_id" "uuid", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid", "p_performance_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_manual_internal_performance_override"("p_organization_id" "uuid", "p_scenario_key" "text", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_existing_id UUID;
BEGIN
  SELECT id INTO v_existing_id
  FROM public.manual_internal_performance_overrides
  WHERE organization_id = p_organization_id
    AND scenario_key    = p_scenario_key
    AND year            = p_year
    AND month           = p_month;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.manual_internal_performance_overrides
    SET performance_count = p_performance_count,
        updated_by        = p_updated_by,
        updated_at        = now()
    WHERE id = v_existing_id;
  ELSE
    INSERT INTO public.manual_internal_performance_overrides
      (organization_id, scenario_key, year, month, performance_count, updated_by)
    VALUES
      (p_organization_id, p_scenario_key, p_year, p_month, p_performance_count, p_updated_by);
  END IF;

  RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."upsert_manual_internal_performance_override"("p_organization_id" "uuid", "p_scenario_key" "text", "p_year" integer, "p_month" integer, "p_performance_count" integer, "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_survey_response_for_member"("p_group_id" "uuid", "p_member_id" "uuid", "p_responses" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_member_exists BOOLEAN;
  v_response_id UUID;
BEGIN
  -- メンバーがグループに属しているか検証
  SELECT EXISTS(
    SELECT 1 FROM private_group_members
    WHERE id = p_member_id
      AND group_id = p_group_id
      AND status = 'joined'
  ) INTO v_member_exists;

  IF NOT v_member_exists THEN
    RAISE EXCEPTION 'Member does not belong to this group';
  END IF;

  -- UNIQUE(group_id, member_id) を利用してUPSERT
  INSERT INTO private_group_survey_responses (group_id, member_id, responses)
  VALUES (p_group_id, p_member_id, p_responses)
  ON CONFLICT (group_id, member_id) DO UPDATE
    SET responses = EXCLUDED.responses,
        updated_at = NOW()
  RETURNING id INTO v_response_id;

  RETURN v_response_id;
END;
$$;


ALTER FUNCTION "public"."upsert_survey_response_for_member"("p_group_id" "uuid", "p_member_id" "uuid", "p_responses" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_survey_response_for_member"("p_group_id" "uuid", "p_member_id" "uuid", "p_responses" "jsonb") IS 'ゲスト含むグループメンバーのアンケート回答をUPSERTするRPC。member_idがgroup_idに属することを検証する。';



CREATE OR REPLACE FUNCTION "public"."use_customer_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_reservation" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE cc public.customer_coupons; r public.reservations; uid uuid; amount integer;
BEGIN
 SELECT c.* INTO cc FROM public.customer_coupons c JOIN public.customers cu ON cu.id=c.customer_id
 WHERE c.id=p_coupon AND cu.user_id=p_user;
 IF cc.id IS NULL THEN RAISE EXCEPTION 'クーポンが見つかりません' USING ERRCODE='P0028'; END IF;
 SELECT * INTO r FROM public.reservations WHERE id=p_reservation AND organization_id=cc.organization_id;
 IF r.id IS NULL OR NOT public.can_use_coupon_reservation(cc.customer_id,r.id) THEN
  RAISE EXCEPTION 'ご本人の予約を指定してください' USING ERRCODE='P0028';
 END IF;
 PERFORM 1 FROM public.customers WHERE id=cc.customer_id FOR UPDATE;
 SELECT id,discount_amount INTO uid,amount FROM public.coupon_usages WHERE customer_coupon_id=p_coupon AND reservation_id=p_reservation LIMIT 1;
 IF uid IS NOT NULL THEN RETURN jsonb_build_object('success',true,'usage_id',uid,'discount_amount',amount,'already_used',true); END IF;
 INSERT INTO public.coupon_usages(customer_coupon_id,reservation_id,discount_amount)
 VALUES(p_coupon,p_reservation,1) RETURNING id,discount_amount INTO uid,amount;
 -- 予約後に使ったクーポンも予約の確定金額（final_price）に反映する。金額の正本は final_price（20261002160000）。
 IF COALESCE(amount,0) > 0 THEN
  UPDATE public.reservations
  SET discount_amount = COALESCE(discount_amount,0) + amount,
      final_price = GREATEST(COALESCE(final_price, total_price, 0) - amount, 0),
      updated_at = now()
  WHERE id = p_reservation;
 END IF;
 RETURN jsonb_build_object('success',true,'usage_id',uid,'discount_amount',amount);
END;
$$;


ALTER FUNCTION "public"."use_customer_coupon"("p_user" "uuid", "p_coupon" "uuid", "p_reservation" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_reservation_status_transition"("p_old_status" "text", "p_new_status" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- 同じステータスへの遷移は常に許可
  IF p_old_status = p_new_status THEN
    RETURN TRUE;
  END IF;

  -- cancelled → confirmed のみ許可（復活運用）
  IF p_old_status = 'cancelled' THEN
    IF p_new_status = 'confirmed' THEN
      RETURN TRUE;
    END IF;
    RETURN FALSE;
  END IF;

  -- 完了済みからの変更は限定的
  IF p_old_status = 'completed' THEN
    IF p_new_status IN ('cancelled', 'no_show') THEN
      RETURN TRUE;
    ELSE
      RETURN FALSE;
    END IF;
  END IF;

  -- ★追加: ノーショーからの取消（→ confirmed）を許可。それ以外は禁止
  IF p_old_status = 'no_show' THEN
    IF p_new_status = 'confirmed' THEN
      RETURN TRUE;
    END IF;
    RETURN FALSE;
  END IF;

  -- pending → confirmed, cancelled, pending_gm, gm_confirmed, checked_in
  IF p_old_status = 'pending' THEN
    IF p_new_status IN ('confirmed', 'cancelled', 'pending_gm', 'gm_confirmed', 'checked_in') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- pending_gm → confirmed, gm_confirmed, cancelled
  IF p_old_status = 'pending_gm' THEN
    IF p_new_status IN ('confirmed', 'gm_confirmed', 'cancelled') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- pending_store → confirmed, cancelled
  IF p_old_status = 'pending_store' THEN
    IF p_new_status IN ('confirmed', 'cancelled') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- gm_confirmed → confirmed, cancelled, pending_store, checked_in
  IF p_old_status = 'gm_confirmed' THEN
    IF p_new_status IN ('confirmed', 'cancelled', 'pending_store', 'checked_in') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- confirmed → completed, cancelled, no_show, checked_in
  IF p_old_status = 'confirmed' THEN
    IF p_new_status IN ('completed', 'cancelled', 'no_show', 'checked_in') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- checked_in → completed, cancelled, no_show, confirmed（★confirmed=チェックイン解除を追加）
  IF p_old_status = 'checked_in' THEN
    IF p_new_status IN ('completed', 'cancelled', 'no_show', 'confirmed') THEN
      RETURN TRUE;
    END IF;
  END IF;

  -- その他は禁止
  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."validate_reservation_status_transition"("p_old_status" "text", "p_new_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_store_travel_times_org"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.stores sa
    JOIN public.stores sb ON sb.id = NEW.store_b_id
    WHERE sa.id = NEW.store_a_id
      AND sa.organization_id = NEW.organization_id
      AND sb.organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'store_travel_times stores must belong to the same organization';
  END IF;

  RETURN NEW;
END;
$$;


