    "cancellation_policy_fee_basis" "text",
    "cancellation_policy_updated_at" timestamp with time zone,
    "reservation_change_deadline_hours_snapshot" integer,
    "coupon_usage_enabled_snapshot" boolean,
    "reservation_change_policy_snapshot_version" integer,
    CONSTRAINT "reservations_cancellation_policy_fee_basis_check" CHECK ((("cancellation_policy_fee_basis" IS NULL) OR ("cancellation_policy_fee_basis" = ANY (ARRAY['participant_total'::"text", 'performance_total'::"text"])))),
    CONSTRAINT "reservations_cancellation_policy_fees_check" CHECK ((("cancellation_policy_fees" IS NULL) OR ("jsonb_typeof"("cancellation_policy_fees") = 'array'::"text"))),
    CONSTRAINT "reservations_cancellation_policy_performance_type_check" CHECK ((("cancellation_policy_performance_type" IS NULL) OR ("cancellation_policy_performance_type" = ANY (ARRAY['open'::"text", 'private'::"text"])))),
    CONSTRAINT "reservations_cancellation_policy_snapshot_version_check" CHECK ((("cancellation_policy_snapshot_version" IS NULL) OR ("cancellation_policy_snapshot_version" = 1))),
    CONSTRAINT "reservations_reservation_change_deadline_hours_snapshot_check" CHECK (("reservation_change_deadline_hours_snapshot" >= 0)),
    CONSTRAINT "reservations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'checked_in'::"text", 'completed'::"text", 'cancelled'::"text", 'no_show'::"text", 'gm_confirmed'::"text", 'pending_gm'::"text", 'pending_store'::"text"])))
);


