    "notes" "text",
    "color" "text" DEFAULT '#3B82F6'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "fixed_costs" "jsonb" DEFAULT '[]'::"jsonb",
    "ownership_type" "text",
    "franchise_fee" integer DEFAULT 1000,
    "is_temporary" boolean DEFAULT false,
    "temporary_date" "date",
    "temporary_dates" "jsonb" DEFAULT '[]'::"jsonb",
    "organization_id" "uuid" NOT NULL,
    "display_order" integer DEFAULT 999,
    "region" "text",
    "temporary_venue_names" "jsonb" DEFAULT '{}'::"jsonb",
    "transport_allowance" integer,
    "kit_group_id" "uuid",
    "venue_cost_per_performance" integer DEFAULT 0,
    "access_info" "text",
    "kit_fixed" boolean DEFAULT false,
    "franchise_fee_type" "text" DEFAULT 'fixed'::"text" NOT NULL,
    "franchise_fee_percent" numeric(5,2),
    CONSTRAINT "stores_franchise_fee_type_check" CHECK (("franchise_fee_type" = ANY (ARRAY['fixed'::"text", 'percent'::"text"]))),
    CONSTRAINT "stores_ownership_type_check" CHECK (("ownership_type" = ANY (ARRAY['corporate'::"text", 'franchise'::"text", 'office'::"text"]))),
    CONSTRAINT "stores_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'temporarily_closed'::"text", 'closed'::"text"])))
);


ALTER TABLE "public"."stores" OWNER TO "postgres";


COMMENT ON COLUMN "public"."stores"."fixed_costs" IS '店舗の固定費（家賃、光熱費など）。JSONB配列形式';



COMMENT ON COLUMN "public"."stores"."ownership_type" IS '店舗の所有形態（直営店 or フランチャイズ or オフィス）';



COMMENT ON COLUMN "public"."stores"."franchise_fee" IS 'フランチャイズ登録手数料（円）。デフォルト1000円';



