COMMENT ON COLUMN "public"."stores"."temporary_venue_names" IS '日付ごとの臨時会場カスタム名（例: {"2025-11-01": "スペースマーケット渋谷"}）';



COMMENT ON COLUMN "public"."stores"."kit_group_id" IS 'キットグループの親店舗ID。同じ値を持つ店舗はキット移動計算で同一拠点として扱う';



COMMENT ON COLUMN "public"."stores"."venue_cost_per_performance" IS '1公演あたりの会場費（家賃按分）';



COMMENT ON COLUMN "public"."stores"."franchise_fee_type" IS 'FC料金の方式。fixed=公演1件ごとの定額（franchise_fee 円）、percent=公演売上に対する割合（franchise_fee_percent %）。既定 fixed';



COMMENT ON COLUMN "public"."stores"."franchise_fee_percent" IS 'FC料金が percent 方式のときの割合（%）。例 10.00 = 公演売上の10%。fixed 方式では未使用';



CREATE OR REPLACE VIEW "public"."customer_reservation_history" AS
 SELECT "c"."id" AS "customer_id",
    "c"."name" AS "customer_name",
    "c"."email",
    "c"."phone",
    "r"."id" AS "reservation_id",
    "r"."reservation_number",
    "r"."status" AS "reservation_status",
    "r"."requested_datetime",
    "r"."participant_count",
    "r"."final_price",
    "se"."scenario",
    "se"."venue",
    "s"."name" AS "store_name"
   FROM ((("public"."customers" "c"
     LEFT JOIN "public"."reservations" "r" ON (("r"."customer_id" = "c"."id")))
     LEFT JOIN "public"."schedule_events" "se" ON (("r"."schedule_event_id" = "se"."id")))
     LEFT JOIN "public"."stores" "s" ON ((("se"."venue")::"uuid" = "s"."id")))
  ORDER BY "r"."requested_datetime" DESC;


ALTER VIEW "public"."customer_reservation_history" OWNER TO "postgres";


