    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "deadline_minutes" integer DEFAULT 90 NOT NULL,
    CONSTRAINT "organization_recruitment_settings_check" CHECK (((("mode" = 'count'::"text") AND (("value" >= 1) AND ("value" <= 20))) OR (("mode" = 'percent'::"text") AND (("value" >= 1) AND ("value" <= 100))))),
    CONSTRAINT "organization_recruitment_settings_deadline_minutes_check" CHECK ((("deadline_minutes" >= 1) AND ("deadline_minutes" <= 239))),
    CONSTRAINT "organization_recruitment_settings_mode_check" CHECK (("mode" = ANY (ARRAY['count'::"text", 'percent'::"text"])))
);


