CREATE OR REPLACE VIEW "public"."private_group_members_full" WITH ("security_invoker"='true') AS
 SELECT "m"."id",
    "m"."group_id",
    "m"."user_id",
    "m"."is_organizer",
    "m"."status",
    "m"."joined_at",
    "m"."created_at",
    "pii"."guest_name",
    "pii"."guest_email",
    "pii"."guest_phone",
    "pii"."access_pin"
   FROM ("public"."private_group_members" "m"
     LEFT JOIN "public"."private_group_members_pii" "pii" ON (("pii"."member_id" = "m"."id")));


