CREATE TABLE IF NOT EXISTS "public"."scenarios" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "author" "text" NOT NULL,
    "duration" integer NOT NULL,
    "player_count_min" integer DEFAULT 1 NOT NULL,
    "player_count_max" integer DEFAULT 8 NOT NULL,
    "difficulty" integer DEFAULT 3,
    "available_gms" "text"[] DEFAULT '{}'::"text"[],
    "rating" numeric(2,1) DEFAULT 0.0,
    "play_count" integer DEFAULT 0,
    "status" "text" DEFAULT 'available'::"text" NOT NULL,
    "props" "jsonb" DEFAULT '[]'::"jsonb",
    "genre" "text"[] DEFAULT '{}'::"text"[],
    "production_cost" integer DEFAULT 0,
    "production_cost_items" "jsonb" DEFAULT '[]'::"jsonb",
    "participation_fee" integer DEFAULT 0,
    "notes" "text",
    "has_pre_reading" boolean DEFAULT false,
    "release_date" "date",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "gm_costs" "jsonb" DEFAULT '[]'::"jsonb",
    "license_costs" "jsonb" DEFAULT '[]'::"jsonb",
    "participation_costs" "jsonb" DEFAULT '[]'::"jsonb",
    "gm_assignments" "jsonb" DEFAULT '[]'::"jsonb",
    "license_rewards" "jsonb" DEFAULT '[]'::"jsonb",
    "license_amount" integer DEFAULT 0,
    "gm_test_license_amount" integer DEFAULT 0,
    "gm_test_participation_fee" integer DEFAULT 0,
    "gm_reward_amount" integer DEFAULT 0,
    "requires_sub_gm" boolean DEFAULT false,
    "gm_count_required" integer DEFAULT 1,
    "reading_hiragana" "text",
    "reading_katakana" "text",
    "reading_alphabet" "text",
    "key_visual_url" "text",
    "gm_hourly_wage_settings" "jsonb",
    "gm_count" integer DEFAULT 1,
    "production_costs" "jsonb" DEFAULT '[]'::"jsonb",
    "required_props" "jsonb",
    "scenario_type" "text" DEFAULT 'normal'::"text",
    "franchise_license_amount" integer DEFAULT 0,
    "franchise_gm_test_license_amount" integer DEFAULT 0,
    "available_stores" "uuid"[] DEFAULT '{}'::"uuid"[],
    "sub_gm_costs" integer DEFAULT 0,
    "organization_id" "uuid",
    "is_shared" boolean DEFAULT false,
    "author_email" "text",
    "depreciation_per_performance" integer DEFAULT 0,
    "slug" character varying(100),
    "extra_preparation_time" integer DEFAULT 0,
    "synopsis" "text",
    "gallery_images" "text"[] DEFAULT '{}'::"text"[],
    "scenario_master_id" "uuid",
    "kit_count" integer DEFAULT 1,
    "weekend_duration" integer,
    "external_license_amount" integer DEFAULT 0,
    "external_gm_test_license_amount" integer DEFAULT 0,
    "report_display_name" "text",
    "fc_receive_license_amount" integer,
    "fc_receive_gm_test_license_amount" integer,
    "fc_author_license_amount" integer,
    "fc_author_gm_test_license_amount" integer,
    "male_count" integer,
    "female_count" integer,
    "is_recommended" boolean DEFAULT false,
    "other_count" integer,
    CONSTRAINT "scenarios_difficulty_check" CHECK ((("difficulty" >= 1) AND ("difficulty" <= 5))),
    CONSTRAINT "scenarios_rating_check" CHECK ((("rating" >= 0.0) AND ("rating" <= 5.0))),
    CONSTRAINT "scenarios_scenario_type_check" CHECK (("scenario_type" = ANY (ARRAY['normal'::"text", 'managed'::"text"]))),
    CONSTRAINT "scenarios_status_check" CHECK (("status" = ANY (ARRAY['available'::"text", 'maintenance'::"text", 'retired'::"text", 'draft'::"text", 'unavailable'::"text"]))),
    CONSTRAINT "slug_format_check" CHECK ((("slug" IS NULL) OR (("slug")::"text" ~ '^[a-z0-9-]+$'::"text")))
);


ALTER TABLE "public"."scenarios" OWNER TO "postgres";


COMMENT ON COLUMN "public"."scenarios"."participation_costs" IS '時間帯別参加費設定（例: [{time_slot: "通常公演", amount: 5000, type: "fixed", status: "active"}]）';



COMMENT ON COLUMN "public"."scenarios"."license_amount" IS '通常公演：作者に支払うライセンス料（円）';



COMMENT ON COLUMN "public"."scenarios"."gm_test_license_amount" IS 'GMテスト公演：作者に支払うライセンス料（円）';



COMMENT ON COLUMN "public"."scenarios"."gm_test_participation_fee" IS 'GMテスト公演：お客様から受け取る参加費（円）';



COMMENT ON COLUMN "public"."scenarios"."gm_reward_amount" IS 'GM報酬：GMスタッフに支払う金額（円）';



COMMENT ON COLUMN "public"."scenarios"."requires_sub_gm" IS 'サブGMが必要なシナリオかどうか（2人以上のGMが必要）';



COMMENT ON COLUMN "public"."scenarios"."gm_count_required" IS '必要なGM人数（通常1、サブGM必要なら2以上）';



COMMENT ON COLUMN "public"."scenarios"."reading_katakana" IS 'カタカナ読み（例: ビービーエー、リュウネン）';



COMMENT ON COLUMN "public"."scenarios"."reading_alphabet" IS 'アルファベット読み（例: bba, ryunen）';



COMMENT ON COLUMN "public"."scenarios"."key_visual_url" IS 'シナリオのキービジュアル画像URL';



COMMENT ON COLUMN "public"."scenarios"."gm_hourly_wage_settings" IS 'GM時給設定（時給制の場合の計算パラメータ）';



COMMENT ON COLUMN "public"."scenarios"."gm_count" IS '必要GM数（公演に必要なGMの人数）';



COMMENT ON COLUMN "public"."scenarios"."production_costs" IS 'シナリオの制作費（項目別）- 例: [{"item": "キット", "amount": 30000}]';



COMMENT ON COLUMN "public"."scenarios"."required_props" IS 'シナリオに必要な小道具（項目別）- 例: [{"item": "シート", "amount": 10, "frequency": "recurring"}]';



COMMENT ON COLUMN "public"."scenarios"."scenario_type" IS 'シナリオタイプ: normal（通常シナリオ）, managed（管理シナリオ）';



COMMENT ON COLUMN "public"."scenarios"."franchise_license_amount" IS '他店用（フランチャイズ）通常公演：作者に支払うライセンス料（円）';



COMMENT ON COLUMN "public"."scenarios"."franchise_gm_test_license_amount" IS '他店用（フランチャイズ）GMテスト公演：作者に支払うライセンス料（円）';



COMMENT ON COLUMN "public"."scenarios"."available_stores" IS 'このシナリオを公演可能な店舗IDの配列。空の場合は全店舗で公演可能';



COMMENT ON COLUMN "public"."scenarios"."slug" IS 'URL用の短い識別子（英数字とハイフンのみ）';



COMMENT ON COLUMN "public"."scenarios"."scenario_master_id" IS 'マスタから引用した場合のマスタシナリオID（NULLの場合は独自作成）';



COMMENT ON COLUMN "public"."scenarios"."weekend_duration" IS '土日・祝日の公演時間（分）。NULLの場合はdurationを使用';



COMMENT ON COLUMN "public"."scenarios"."external_license_amount" IS '他社公演料：他社がMMQに支払う金額（円）。マージン = external_license_amount - franchise_license_amount';



COMMENT ON COLUMN "public"."scenarios"."external_gm_test_license_amount" IS '他社GMテスト公演料：他社がMMQに支払う金額（円）';



COMMENT ON COLUMN "public"."scenarios"."report_display_name" IS '報告用の表示名。NULLの場合はauthorを使用';



COMMENT ON COLUMN "public"."scenarios"."fc_receive_license_amount" IS 'フランチャイズ公演時：フランチャイズから受け取る金額（通常）';



COMMENT ON COLUMN "public"."scenarios"."fc_receive_gm_test_license_amount" IS 'フランチャイズ公演時：フランチャイズから受け取る金額（GMテスト）';



COMMENT ON COLUMN "public"."scenarios"."fc_author_license_amount" IS 'フランチャイズ公演時：作者に支払う金額（通常）';



COMMENT ON COLUMN "public"."scenarios"."fc_author_gm_test_license_amount" IS 'フランチャイズ公演時：作者に支払う金額（GMテスト）';



COMMENT ON COLUMN "public"."scenarios"."male_count" IS '男性プレイヤー数（NULLの場合は男女比指定なし）';



COMMENT ON COLUMN "public"."scenarios"."female_count" IS '女性プレイヤー数（NULLの場合は男女比指定なし）';



COMMENT ON COLUMN "public"."scenarios"."is_recommended" IS '管理者が設定するおすすめフラグ';



COMMENT ON COLUMN "public"."scenarios"."other_count" IS 'その他/性別不問プレイヤー数（NULLの場合は設定なし）';



CREATE OR REPLACE VIEW "public"."scenarios_v2" AS
 SELECT "os"."scenario_master_id" AS "id",
    "os"."id" AS "org_scenario_id",
    "os"."organization_id",
    "os"."scenario_master_id",
    "os"."slug",
    "os"."org_status" AS "status",
    "os"."participation_fee",
    "os"."participation_costs",
    "os"."gm_costs",
    "os"."gm_count",
    "os"."gm_assignments",
    "os"."extra_preparation_time",
    "os"."available_stores",
    "os"."available_gms",
    "os"."experienced_staff",
    "os"."license_amount",
    "os"."gm_test_license_amount",
    "os"."franchise_license_amount",
    "os"."franchise_gm_test_license_amount",
    "os"."production_cost",
    "os"."production_costs",
    "os"."depreciation_per_performance",
    "os"."play_count",
    "os"."notes",
    "os"."created_at",
    "os"."updated_at",
    COALESCE("os"."override_title", "sm"."title") AS "title",
    COALESCE("os"."override_author", "sm"."author") AS "author",
    "sm"."author_email",
    "sm"."author_id",
    COALESCE("os"."custom_key_visual_url", "sm"."key_visual_url") AS "key_visual_url",
    COALESCE("os"."custom_description", "sm"."description") AS "description",
    COALESCE("os"."custom_synopsis", "sm"."synopsis") AS "synopsis",
    COALESCE("os"."custom_caution", "sm"."caution") AS "caution",
    COALESCE("os"."override_player_count_min", "sm"."player_count_min") AS "player_count_min",
    COALESCE("os"."override_player_count_max", "sm"."player_count_max") AS "player_count_max",
    COALESCE("os"."duration", "sm"."official_duration") AS "duration",
    COALESCE("os"."override_genre", "sm"."genre") AS "genre",
    COALESCE("os"."override_difficulty", "sm"."difficulty") AS "difficulty",
    COALESCE("os"."override_has_pre_reading", "sm"."has_pre_reading") AS "has_pre_reading",
    "sm"."release_date",
    "sm"."official_site_url",
    "sm"."required_items" AS "required_props",
    "sm"."master_status",
    true AS "is_shared",
    'normal'::"text" AS "scenario_type",
    (0)::numeric AS "rating",
    1 AS "kit_count"
   FROM ("public"."organization_scenarios" "os"
     JOIN "public"."scenario_masters" "sm" ON (("sm"."id" = "os"."scenario_master_id")));


ALTER VIEW "public"."scenarios_v2" OWNER TO "postgres";


COMMENT ON VIEW "public"."scenarios_v2" IS 'scenarios テーブルの互換ビュー。organization_scenarios + scenario_masters を結合し、scenarios と同じカラム構成を提供';



