CREATE TABLE IF NOT EXISTS "public"."schedule_event_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "schedule_event_id" "uuid",
    "organization_id" "uuid" NOT NULL,
    "changed_by_user_id" "uuid",
    "changed_by_staff_id" "uuid",
    "changed_by_name" "text",
    "action_type" "text" NOT NULL,
    "changes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "old_values" "jsonb",
    "new_values" "jsonb",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "event_date" "date",
    "store_id" "uuid",
    "time_slot" "text",
    "deleted_event_scenario" "text",
    CONSTRAINT "schedule_event_history_action_type_check" CHECK (("action_type" = ANY (ARRAY['create'::"text", 'update'::"text", 'delete'::"text", 'cancel'::"text", 'restore'::"text", 'publish'::"text", 'unpublish'::"text", 'add_participant'::"text", 'remove_participant'::"text", 'move_out'::"text", 'move_in'::"text", 'copy'::"text"])))
);


ALTER TABLE "public"."schedule_event_history" OWNER TO "postgres";


COMMENT ON TABLE "public"."schedule_event_history" IS '公演スケジュールの変更履歴';



COMMENT ON COLUMN "public"."schedule_event_history"."schedule_event_id" IS '対象の公演ID';



COMMENT ON COLUMN "public"."schedule_event_history"."organization_id" IS '組織ID（マルチテナント）';



COMMENT ON COLUMN "public"."schedule_event_history"."changed_by_user_id" IS '変更者のユーザーID';



COMMENT ON COLUMN "public"."schedule_event_history"."changed_by_staff_id" IS '変更者のスタッフID';



