COMMENT ON COLUMN "public"."schedule_event_history"."action_type" IS '変更種別（create/update/delete/cancel/restore/publish/unpublish）';



COMMENT ON COLUMN "public"."schedule_event_history"."changes" IS '変更内容の差分 { field: { old: value, new: value } }';



COMMENT ON COLUMN "public"."schedule_event_history"."old_values" IS '変更前のスナップショット';



COMMENT ON COLUMN "public"."schedule_event_history"."new_values" IS '変更後のスナップショット';



COMMENT ON COLUMN "public"."schedule_event_history"."notes" IS '変更メモ';



