SET search_path = public, extensions;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('blog-covers', 'blog-covers', 't', 5242880, '{image/jpeg,image/png,image/gif,image/webp}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('character-images', 'character-images', 't', 5242880, '{image/jpeg,image/png,image/gif,image/webp}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('customer-avatars', 'customer-avatars', 't', 5242880, '{image/jpeg,image/png,image/gif,image/webp}'::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('key-visuals', 'key-visuals', 't', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('mmq-studio-assets', 'mmq-studio-assets', 'f', NULL, NULL) ON CONFLICT (id) DO NOTHING;
CREATE POLICY "Admin and staff can delete" ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'key-visuals'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['admin'::app_role, 'staff'::app_role])))))));
CREATE POLICY "Admin and staff can update" ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'key-visuals'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['admin'::app_role, 'staff'::app_role])))))));
CREATE POLICY "Admin and staff can upload" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'key-visuals'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['admin'::app_role, 'staff'::app_role])))))));
CREATE POLICY "Anyone can view avatars" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'customer-avatars'::text));
CREATE POLICY "Avatars are public" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'customer-avatars'::text));
CREATE POLICY "Public read access" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'key-visuals'::text));
CREATE POLICY "Users can delete their own avatar" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'customer-avatars'::text) AND (name ~~ ((auth.uid())::text || '_%'::text))));
CREATE POLICY "Users can update their own avatar" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'customer-avatars'::text) AND (name ~~ ((auth.uid())::text || '_%'::text))));
CREATE POLICY "Users can upload avatars" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'customer-avatars'::text) AND (auth.role() = 'authenticated'::text)));
CREATE POLICY "Users can upload their own avatar" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'customer-avatars'::text) AND ((storage.foldername(name))[1] = 'avatars'::text) AND (name ~~ ((auth.uid())::text || '_%'::text))));
CREATE POLICY blog_covers_org_admin_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'blog-covers'::text) AND ((storage.foldername(name))[1] = ( SELECT (get_user_organization_id())::text AS get_user_organization_id)) AND is_org_admin()));
CREATE POLICY blog_covers_org_admin_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'blog-covers'::text) AND ((storage.foldername(name))[1] = ( SELECT (get_user_organization_id())::text AS get_user_organization_id)) AND is_org_admin()));
CREATE POLICY blog_covers_org_admin_update ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'blog-covers'::text) AND ((storage.foldername(name))[1] = ( SELECT (get_user_organization_id())::text AS get_user_organization_id)) AND is_org_admin())) WITH CHECK (((bucket_id = 'blog-covers'::text) AND ((storage.foldername(name))[1] = ( SELECT (get_user_organization_id())::text AS get_user_organization_id)) AND is_org_admin()));
CREATE POLICY blog_covers_public_read ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'blog-covers'::text));
CREATE POLICY character_images_auth_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING ((bucket_id = 'character-images'::text));
CREATE POLICY character_images_auth_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'character-images'::text));
CREATE POLICY character_images_auth_update ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING ((bucket_id = 'character-images'::text));
CREATE POLICY character_images_public_read ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'character-images'::text));
CREATE POLICY license_admin_can_upload ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'key-visuals'::text) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['admin'::app_role, 'staff'::app_role, 'license_admin'::app_role])))))));
